async def partner_tag(user_id: int) -> str:
    """Строка «привёл — @ник» для сообщений о заказе. Пусто, если клиент обычный."""
    try:
        p = await get_partner_for_client(int(user_id))
    except Exception:
        return ""
    if not p:
        return ""
    _nm = ("@" + p["username"]) if p.get("username") else (p.get("full_name") or "")
    _nm = str(_nm).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    return (f"\n🏢 <i>Привёл: {_nm} (<code>{p['partner_id']}</code>)</i>"
            if _nm else f"\n🏢 <i>Привёл партнёр <code>{p['partner_id']}</code></i>")


async def partner_ctx(user_id: int, svc_key: str = "") -> dict | None:
    """Партнёрский контекст клиента: {partner_id, discount_pct, markup_pct}.

    None — обычный клиент, цены розничные. Ставки по конкретному сервису
    перекрывают общие проценты партнёра.
    """
    try:
        p = await get_partner_of(int(user_id))
    except Exception as _e_pc:
        logging.warning(f"partner_ctx {user_id}: {_e_pc}")
        return None
    if not p:
        return None
    _d = float(p.get("partner_discount_pct") or 0)
    _m = float(p.get("partner_markup_pct") or 0)
    if svc_key:
        try:
            _r = await get_partner_rate(int(p["partner_id"]), svc_key)
            if _r:
                _d, _m = _r
        except Exception as _e_pr:
            logging.warning(f"partner_rate {svc_key}: {_e_pr}")
    # Скидка партнёра своим клиентам: действует только при выполненном условии
    # (N дней с прихода либо первая покупка), иначе клиент платит полную цену.
    _promo, _left = 0.0, 0
    try:
        _pp = float(p.get("partner_promo_pct") or 0)
        if _pp > 0:
            _pc = await partner_promo_ctx(int(user_id), int(p["partner_id"]))
            _act, _left = partner_promo_active(
                p.get("partner_promo_mode"), int(p.get("partner_promo_days") or 0),
                _pc.get("joined"), _pc.get("orders"))
            if _act:
                _promo = _pp
    except Exception as _e_pp:
        logging.warning(f"partner promo {user_id}: {_e_pp}")
    return {"partner_id": int(p["partner_id"]), "discount_pct": _d, "markup_pct": _m,
            "promo_pct": _promo, "promo_left": _left}


async def shop_price_for(user_id: int, svc_key: str, base_price) -> int:
    """Цена тарифа ДЛЯ ЭТОГО клиента. Обычному — розница, клиенту партнёра — с наценкой.

    Единственная точка, где появляется наценка: и показ, и списание идут через
    неё, поэтому клиент не может увидеть одну цену, а заплатить другую.
    """
    try:
        _b = int(float(base_price or 0))
    except Exception:
        return 0
    if _b <= 0:
        return _b
    ctx = await partner_ctx(user_id, svc_key)
    if not ctx or ctx["markup_pct"] <= 0:
        return _b
    _full, _pay, _owner = partner_prices(_b, ctx["discount_pct"], ctx["markup_pct"],
                                         ctx.get("promo_pct") or 0)
    return _pay


async def shop_price_pair(user_id: int, svc_key: str, base_price) -> tuple[int, int, int, int]:
    """(полная_цена, цена_к_оплате, процент_скидки, осталось_дней) для показа.

    Полная и к оплате совпадают, а процент равен нулю, если партнёра нет или
    скидка неактивна. Процент берём ровно тот, что задан в панели, а не
    пересчитываем из цен: после округления пересчёт может дать 14% вместо 15%,
    а клиенту показывается обещанная величина.
    """
    try:
        _b = int(float(base_price or 0))
    except Exception:
        return 0, 0, 0, 0
    if _b <= 0:
        return _b, _b, 0, 0
    ctx = await partner_ctx(user_id, svc_key)
    if not ctx or ctx["markup_pct"] <= 0:
        return _b, _b, 0, 0
    _full, _pay, _owner = partner_prices(_b, ctx["discount_pct"], ctx["markup_pct"],
                                         ctx.get("promo_pct") or 0)
    _pct = int(round(float(ctx.get("promo_pct") or 0))) if _full > _pay else 0
    return _full, _pay, _pct, int(ctx.get("promo_left") or 0)


# ── Техработы и блокировка для HTTP-запросов из мини-аппов ──────────────
# Middleware aiogram (bot.py) видит только апдейты Telegram. Мини-апп ходит
# в aiohttp напрямую, мимо неё: заблокированный клиент с ещё живым initData
# продолжал запускать ПЛАТНЫЕ запросы к провайдеру, а включённые техработы
# на мини-апп не действовали вовсе. Внешний аудит 29.09.2026, пункт №23.
_maint_cache = {"val": "0", "ts": 0.0}


async def maintenance_on() -> bool:
    """Включён ли режим техработ. Значение из БД кэшируем на 10 секунд —
    иначе каждый тап в мини-аппе тянул бы отдельный запрос в базу.
    Этим же помощником пользуется middleware в bot.py, чтобы кэш был один
    на весь процесс и режим включался/выключался везде одновременно."""
    if _time_module.time() - _maint_cache["ts"] > 10:
        try:
            _maint_cache["val"] = await get_setting("maintenance", "0")
        except Exception:
            pass
        _maint_cache["ts"] = _time_module.time()
    return _maint_cache["val"] == "1"


def maintenance_cache_reset() -> None:
    """Сбросить кэш сразу после переключения режима из админки."""
    _maint_cache["ts"] = 0.0


async def _web_access_denied(uid, check_maintenance: bool = True):
    """Можно ли дать ход пользовательскому запросу из мини-аппа.

    Возвращает ("", "") — можно; иначе (код, текст для клиента).
    check_maintenance=False — для ВЫДАЧИ уже оплаченного (активации):
    деньги получены, и терять их из-за техработ нельзя; блокировка
    клиента при этом продолжает действовать.
    Админа шлюз не трогает никогда — иначе нечем будет чинить.
    """
    try:
        _uid = int(uid)
    except Exception:
        return "auth", "Ошибка авторизации. Перезапусти мини-приложение."
    if _uid == ADMIN_ID:
        return "", ""
    try:
        if await is_blocked(_uid):
            return "blocked", ("Доступ к боту закрыт. Если это ошибка — "
                               f"напиши @{PERSONAL_USERNAME}.")
    except Exception as _e_bl:
        # База недоступна — не запираем клиента, но след оставляем.
        logging.warning(f"_web_access_denied is_blocked uid={_uid}: {_e_bl}")
    if check_maintenance:
        try:
            if await maintenance_on():
                return "maintenance", "⚙️ Идут техработы. Загляни чуть позже 🙏"
        except Exception as _e_mt:
            logging.warning(f"_web_access_denied maintenance uid={_uid}: {_e_mt}")
    return "", ""


def _fk_body_preview(raw: str, limit: int = 200) -> str:
    """Кусок тела вебхука для сообщения владельцу: без подписи и без разметки.

    Тут было два изъяна сразу. Первый: тело вставлялось в HTML-сообщение как
    есть — одна «<» в нём отменяла всё сообщение, и алерт о неизвестном IP
    просто не приходил. Второй: в теле лежит SIGN, готовый аутентификатор
    запроса. Внешний аудит 29.09.2026, пункты №22 и №28.
    """
    import re as _re_fb, html as _h_fb
    _t = _re_fb.sub(r"(?i)(SIGN=)[^&\s]*", r"\1<скрыто>", str(raw or ""))
    _t = _re_fb.sub(r'(?i)("SIGN"\s*:\s*")[^"]*"', r'\1<скрыто>"', _t)
    return _h_fb.escape(strip_surrogates(_t[:limit]), quote=False)


def _new_webgen_id() -> str:
    """Короткий идентификатор оплаченной генерации (он же ключ в журнале)."""
    import secrets as _sec_wg
    return _sec_wg.token_urlsafe(10)


def _webgen_err_resp(err: str):
    """Один текст отказа на все четыре эндпоинта генерации."""
    _msgs = {
        "busy": "Уже запускаю — подожди пару секунд.",
        "too_many": "Слишком много генераций одновременно. Дождись текущих.",
        "blocked": ("Доступ к боту закрыт. Если это ошибка — "
                    f"напиши @{PERSONAL_USERNAME}."),
        "maintenance": "⚙️ Идут техработы. Загляни чуть позже 🙏",
    }
    _status = 403 if err == "blocked" else (503 if err == "maintenance" else 200)
    return web.json_response({"ok": False, "error": err,
                              "msg": _msgs.get(err, "Сейчас не получилось, попробуй ещё раз.")},
                             status=_status)


async def _webgen_guard(uid: int, kind: str, ttl: float = 45.0):
    """Защита платных генераций ИЗ МИНИ-АППА: двойной тап и лимит параллельных.

    В боте у каждой генерации есть замок клика и учёт активных генераций,
    а в мини-аппе их не было вообще: двойной тап по кнопке в вебвью (обычное
    дело на телефоне) списывал кредиты ДВАЖДЫ и запускал две генерации.

    Возвращает (ok, err, click_key). err: 'busy' — дубль клика,
    'too_many' — уже идёт максимум параллельных генераций,
    'blocked' — клиент заблокирован, 'maintenance' — режим техработ.
    """
    _ck = f"webgen:{kind}:{uid}"
    # Сначала право запускать вообще, и только потом замки: иначе отказ
    # заблокированному оставлял бы за ним замок клика на 45 секунд.
    _den, _ = await _web_access_denied(uid)
    if _den:
        return False, _den, _ck
    if not try_acquire_click(_ck, ttl=ttl):
        return False, "busy", _ck
    try:
        if not await mark_generation_active(uid, kind):
            release_click(_ck)
            return False, "too_many", _ck
    except Exception as _e_g:
        logging.warning(f"_webgen_guard mark uid={uid}: {_e_g}")
    return True, "", _ck


async def _webgen_done(uid: int, click_key: str, keep_lock: bool = False):
    """Снимает отметки после генерации из мини-аппа.
    keep_lock=True — для фоновых задач: замок клика оставляем дотикать по TTL,
    чтобы повторный POST в те же секунды не создал вторую задачу."""
    if not keep_lock:
        release_click(click_key)
    try:
        await unmark_generation_active(uid)
    except Exception as _e_d:
        logging.warning(f"_webgen_done unmark uid={uid}: {_e_d}")


async def _check_can_generate(cb_or_msg, uid: int, kind: str = "photo") -> bool:
    """Проверки перед генерацией. kind: 'photo' | 'video' | 'anim'. Возвращает True если можно."""
    # 0) Юзер не заблокирован
    if not await check_not_blocked(cb_or_msg, uid):
        return False

    # A) Проверяем количество активных генераций (макс MAX_CONCURRENT_GENS)
    pool = await get_pool()
    async with pool.acquire() as conn:
        active_count = await conn.fetchval(
            """SELECT COUNT(*) FROM active_generations
               WHERE user_id = $1 AND started_at > NOW() - INTERVAL '30 minutes'""",
            uid
        ) or 0
    if active_count >= MAX_CONCURRENT_GENS:
        msg = f"⏳ У тебя уже {active_count} генераций. Максимум {MAX_CONCURRENT_GENS} одновременно."
        if isinstance(cb_or_msg, CallbackQuery):
            await cb_or_msg.answer(msg, show_alert=True)
        else:
            await cb_or_msg.answer(msg)
        return False

    # B) Почасовой лимит - по категории
    if kind == "video":
        history, limit, label = _video_history, VIDEO_LIMIT_PER_HOUR, "видео"
    elif kind == "anim":
        history, limit, label = _anim_history, ANIM_LIMIT_PER_HOUR, "анимаций"
    elif kind == "motion":
        history, limit, label = _motion_history, MOTION_LIMIT_PER_HOUR, "Motion Control"
    else:
        history, limit, label = _photo_history, PHOTO_LIMIT_PER_HOUR, "фото"

    can, minutes = _check_hourly_limit(uid, history, limit)
    if not can:
        msg = f"⏰ Лимит: {limit} {label} в час.\nПопробуй через {minutes} мин."
        if isinstance(cb_or_msg, CallbackQuery):
            await cb_or_msg.answer(msg, show_alert=True)
        else:
            await cb_or_msg.answer(msg)
        return False

    return True


# ─── Персистентные active_generations (переживают рестарт) ─
# Таблица active_generations надёжнее чем set в памяти - переживает перезапуски бота.
# In-memory set оставлен для обратной совместимости старого кода.

# Пространство ключей для блокировок PostgreSQL «на пользователя». Отдельное
# число, чтобы наши блокировки не пересекались с чужими, если такие появятся.
_GEN_LOCK_NS = 424242

# Метка ЭТОГО запуска процесса. По ней разбор потерянных генераций отличает
# «моя задача, идёт прямо сейчас» от «осталась от прошлого процесса, который
# уже не вернётся». Внешний аудит 29.09.2026, пункт №11.
_WORKER_ID = uuid.uuid4().hex[:12]


async def mark_generation_active(user_id: int, kind: str = "photo") -> bool:
    """Помечает юзера как генерирующего. Допускает до MAX_CONCURRENT_GENS записей.
    Возвращает False если лимит исчерпан.

    Счёт и вставка идут ПОД БЛОКИРОВКОЙ на этого пользователя. Раньше между
    COUNT и INSERT был await, и два одновременных запроса (двойной тап в
    мини-аппе, две вкладки, вебхук и кнопка) успевали оба увидеть «лимит не
    исчерпан» и оба вставить строку. Лимит переставал быть лимитом, а каждая
    лишняя параллельная генерация — это оплаченный запрос к провайдеру.
    Блокировка живёт до конца транзакции и снимается сама, даже если процесс
    упадёт посреди неё. Внешний аудит 29.09.2026, пункт №26.
    """
    pool = await get_pool()
    async with pool.acquire() as conn:
        async with conn.transaction():
            await conn.execute(
                "SELECT pg_advisory_xact_lock($1::int, $2::int)",
                _GEN_LOCK_NS, int(user_id) % 2147483647
            )
            await conn.execute(
                "DELETE FROM active_generations WHERE user_id = $1 AND started_at < NOW() - INTERVAL '30 minutes'",
                user_id
            )
            count = await conn.fetchval(
                "SELECT COUNT(*) FROM active_generations WHERE user_id = $1",
                user_id
            ) or 0
            if count >= MAX_CONCURRENT_GENS:
                return False
            await conn.execute(
                "INSERT INTO active_generations (user_id, kind) VALUES ($1, $2)",
                user_id, kind
            )
    _active_generations.add(user_id)
    return True


async def unmark_generation_active(user_id: int):
    """Убирает одну активную генерацию юзера (самую старую). Вызывать в finally."""
    pool = await get_pool()
    async with pool.acquire() as conn:
        await conn.execute(
            "DELETE FROM active_generations WHERE id = ("
            "  SELECT id FROM active_generations WHERE user_id = $1 "
            "  ORDER BY started_at ASC LIMIT 1"
            ")",
            user_id
        )
        remaining = await conn.fetchval(
            "SELECT COUNT(*) FROM active_generations WHERE user_id = $1", user_id
        ) or 0
    if remaining == 0:
        _active_generations.discard(user_id)


async def fk_check_order_status(order_id: str) -> dict | None:
    """Запрашивает у FreeKassa API статус заказа по нашему MERCHANT_ORDER_ID.

    Возвращает {"status": "paid"|"new"|"failed", "amount": ...} или None при ошибке.

    Пробует несколько endpoint'ов поочерёдно - если один заблокирован, переходит к другому.
    Поле для фильтра - `paymentId` (наш merchant_order_id), а не `orderId`.
    """
    if not FK_API_KEY:
        logging.warning("fk_check_order_status: FK_API_KEY не задан в Railway Variables")
        return None

    # Список endpoint'ов в порядке приоритета - попробуем каждый
    endpoints = [
        "https://api.freekassa.ru/v1/orders",
        "https://api.fk.life/v1/orders",
        "https://api.fk.money/v1/orders",
    ]

    last_error = None
    for endpoint in endpoints:
        try:
            # Nonce в МИЛЛИСЕКУНДАХ - иначе при 2 запросах в одну секунду FK отвергнет
            nonce = str(int(_time_module.time() * 1000))

            params = {
                "shopId": int(FK_SHOP_ID),
                "nonce": nonce,
                "paymentId": str(order_id),
            }

            # HMAC-SHA256 подпись: значения отсортированных по ключам параметров через |
            sorted_vals = [str(v) for k, v in sorted(params.items())]
            sign_str = "|".join(sorted_vals)
            signature = hmac.new(FK_API_KEY.encode(), sign_str.encode(), hashlib.sha256).hexdigest()
            params["signature"] = signature

            headers = {"Content-Type": "application/json", "Accept": "application/json"}

            # Уменьшенный timeout 8 сек - чтобы быстрее переключаться между endpoint'ами
            timeout = aiohttp.ClientTimeout(total=8)

            async with aiohttp.ClientSession(timeout=timeout) as s:
                async with s.post(endpoint, json=params, headers=headers) as r:
                    resp_text = await r.text()

                    if r.status != 200:
                        logging.warning(
                            f"FK API {endpoint} status={r.status} paymentId={order_id} "
                            f"response={resp_text[:200]}"
                        )
                        last_error = f"HTTP {r.status}"
                        continue

                    try:
                        import json as _json
                        data = _json.loads(resp_text) if resp_text else {}
                    except Exception as parse_err:
                        logging.error(f"FK API parse error: {parse_err} response={resp_text[:200]}")
                        last_error = "parse error"
                        continue

                    if data.get("type") == "error":
                        logging.warning(
                            f"FK API {endpoint} type=error paymentId={order_id} "
                            f"response={resp_text[:200]}"
                        )
                        last_error = "api error"
                        continue

                    orders = data.get("orders") or []
                    if not orders:
                        logging.info(
                            f"FK API {endpoint}: пусто для paymentId={order_id} "
                            f"(заказ ещё не создан в FK или не оплачен)"
                        )
                        # Endpoint работает но заказ не найден - возвращаем None но НЕ пробуем другие
                        # endpoint'ы (они дадут тот же результат)
                        return None

                    # По одному нашему счёту у FreeKassa может лежать НЕСКОЛЬКО
                    # попыток оплаты: клиент закрыл форму, вернулся, оплатил со
                    # второго раза. Брать просто первую запись нельзя — если
                    # первой окажется брошенная попытка, оплаченный заказ мы
                    # посчитаем неоплаченным. Берём оплаченную, если она есть.
                    # Внешний аудит 29.09.2026, рядом с пунктом №24.
                    order = next((_o for _o in orders if _o.get("status") == 1), orders[0])
                    if len(orders) > 1:
                        logging.info(
                            f"FK API {endpoint}: paymentId={order_id} — попыток оплаты "
                            f"{len(orders)}, статусы {[_o.get('status') for _o in orders]}")
                    fk_int_status = order.get("status")
                    merchant_id_fk = order.get("merchant_order_id", "")
                    fk_internal_id = order.get("fk_order_id", "")
                    amount = order.get("amount", 0)

                    logging.info(
                        f"FK API {endpoint}: paymentId={order_id} → "
                        f"fk_status={fk_int_status} amount={amount} "
                        f"fk_internal={fk_internal_id}"
                    )

                    if fk_int_status == 1:
                        return {
                            "status": "paid",
                            "amount": amount,
                            "fk_order_id": fk_internal_id,
                            "merchant_order_id": merchant_id_fk,
                        }
                    elif fk_int_status == 8:
                        return {"status": "failed"}
                    elif fk_int_status == 9:
                        return {"status": "cancelled"}
                    else:
                        return {"status": "new"}

        except asyncio.TimeoutError:
            logging.warning(f"FK API {endpoint} TIMEOUT for paymentId={order_id} - пробуем следующий")
            last_error = "timeout"
            continue
        except aiohttp.ClientError as e:
            logging.warning(f"FK API {endpoint} ClientError: {e} - пробуем следующий")
            last_error = f"network: {e}"
            continue
        except Exception as e:
            logging.error(f"FK API {endpoint} exception paymentId={order_id}: {type(e).__name__}: {e}")
            last_error = str(e)
            continue

    # Все endpoint'ы упали
    logging.error(f"❌ FK API: все endpoint'ы недоступны для paymentId={order_id}, last_error={last_error}")
    return None


