@dp.callback_query(F.data == "partner_cab")
async def partner_cabinet(cb: CallbackQuery):
    """Кабинет партнёра: сколько клиентов, сколько заработано, сколько к выплате."""
    uid = cb.from_user.id
    _u = await get_user(uid)
    if not _u or not _u.get("partner"):
        await cb.answer("Раздел доступен только партнёрам", show_alert=True)
        return
    await cb.answer()
    st = await partner_stats(uid)
    _last = await partner_recent_orders(uid, 8)
    try:
        _bot_un = (await bot.get_me()).username
    except Exception:
        _bot_un = ""
    _link = f"https://t.me/{_bot_un}?start=ref_{uid}" if _bot_un else "—"
    lines = [
        "🏢 <b>Кабинет партнёра</b>\n",
        f"👥 Клиентов по твоей ссылке: <b>{st.get('clients') or 0}</b>",
        f"🧾 Оплаченных заказов: <b>{st.get('orders') or 0}</b>",
        f"💰 Заработано всего: <b>{float(st.get('earned') or 0):.0f} ₽</b>",
        f"📅 За текущий месяц: <b>{float(st.get('earned_month') or 0):.0f} ₽</b>",
        f"✅ Выплачено: <b>{float(st.get('paid') or 0):.0f} ₽</b>",
        f"\n💳 <b>К выплате: {float(st.get('balance') or 0):.0f} ₽</b>",
    ]
    if _last:
        lines.append("\n<b>Последние продажи</b>")
        for o in _last:
            _s = SHOP_CATALOG.get(o.get("svc_key") or "", {}) or {}
            _dt = o.get("created_at")
            _ds = _dt.strftime("%d.%m") if _dt else ""
            lines.append(f"• {_ds} {_s.get('name', o.get('svc_key') or '?')} — "
                         f"твоя доля <b>{float(o.get('partner_sum') or 0):.0f} ₽</b>")
    lines.append(f"\n🔗 <b>Твоя ссылка</b>\n<code>{_link}</code>")
    lines.append("\n<i>Клиенты, пришедшие по ней, видят цены с твоей наценкой. "
                 "Доля начисляется после оплаты. По выплатам — пиши Александру.</i>")
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="🔄 Обновить", callback_data="partner_cab")],
        [_eib("Главное меню", "back_main")],
    ])
    try:
        await cb.message.edit_text("\n".join(lines), reply_markup=kb, parse_mode="HTML",
                                   disable_web_page_preview=True)
    except Exception:
        await cb.message.answer("\n".join(lines), reply_markup=kb, parse_mode="HTML",
                                disable_web_page_preview=True)


async def process_partner_earning(client_id: int, order_id: str, amount_rub) -> None:
    """Записывает долю партнёра по оплаченному заказу подписки.

    Доля считается ПРОПОРЦИОНАЛЬНО фактически оплаченной сумме, а не как
    жёсткая разница «цена клиента минус наша доля». Иначе промокод или монетки
    съедали бы нашу маржу целиком, а при большой скидке партнёру причиталось бы
    больше, чем клиент вообще заплатил.

    Пример: розница 1990, уступка 5%, наценка 20% → клиент видит 2388, наша
    доля 1890, партнёру 498 (это 20.9% от цены). Клиент применил промокод и
    заплатил 2149 → партнёру 20.9% от 2149 = 449, нам 1700. Никто не в минусе.

    Начисляем только по заказам КАТАЛОГА (pack вида «shop:<сервис>:<тариф>») —
    кредиты, гифт-карты и генерации в партнёрскую программу не входят.
    """
    try:
        _paid = float(amount_rub or 0)
    except Exception:
        return
    if _paid <= 0:
        return
    _o = await fk_get_order(order_id) or {}
    _pack = str(_o.get("pack") or "")
    if not _pack.startswith("shop:"):
        return
    _parts = _pack.split(":")
    _svc = _parts[1] if len(_parts) > 1 else ""
    try:
        _idx = int(_parts[2]) if len(_parts) > 2 and _parts[2].isdigit() else 0
    except Exception:
        _idx = 0
    # Тариф ищем по ИМЕНИ из заказа, индекс — запасной путь: каталог мог
    # измениться между оплатой и расчётом доли партнёра.
    _s, _p_ord = _plan_by_order(_svc, _idx, _pack_plan_name(_pack))
    _plans = _s.get("plans") or []
    if not _p_ord:
        return
    _base = int(_p_ord.get("price") or 0)
    if _base <= 0:
        return
    ctx = await partner_ctx(int(client_id), _svc)
    if not ctx:
        return
    _full_price, _client_price, _owner_price = partner_prices(
        _base, ctx["discount_pct"], ctx["markup_pct"], ctx.get("promo_pct") or 0)
    if _client_price <= 0 or _client_price <= _owner_price:
        return
    # Наша доля — фиксированная партнёрская цена, партнёру достаётся остаток.
    # Именно так партнёр и предлагал: «тебе фиксированная цена, разница мне».
    # Значит любая скидка (его собственная промо-скидка, промокод, монетки)
    # режет СНАЧАЛА его долю, а наша остаётся целой. Если скидка съела всё —
    # партнёру ноль, но в минус мы не уходим.
    _partner_sum = round(max(0.0, _paid - _owner_price), 2)
    _owner_sum = round(_paid - _partner_sum, 2)
    if _partner_sum <= 0:
        logging.info(f"partner earning: скидка съела долю партнёра order={order_id}")
        return
    _written = await log_partner_earning(
        int(ctx["partner_id"]), int(client_id), order_id, _svc, _idx,
        _base, _client_price, _paid, _partner_sum, _owner_sum)
    if not _written:
        logging.info(f"partner earning дубль order={order_id} — не начисляем")
        return
    logging.info(f"partner earning: order={order_id} партнёр={ctx['partner_id']} "
                 f"оплачено={_paid} доля={_partner_sum}")
    try:
        _st = await partner_stats(int(ctx["partner_id"]))
        await bot.send_message(
            int(ctx["partner_id"]),
            f"💰 <b>Продажа по твоей ссылке</b>\n\n"
            f"📦 {(_s.get('name') or _svc)} · {_p_ord.get('name','')}\n"
            f"💳 Клиент оплатил: <b>{_paid:.0f} ₽</b>\n"
            f"🤝 Твоя доля: <b>{_partner_sum:.0f} ₽</b>\n\n"
            f"Всего к выплате: <b>{float(_st.get('balance') or 0):.0f} ₽</b>",
            parse_mode="HTML")
    except Exception:
        pass
    try:
        await bot.send_message(
            ADMIN_ID,
            f"🏢 <b>Заказ от партнёра</b>\n\n"
            f"👤 клиент {await _who_user(client_id)} · партнёр <code>{ctx['partner_id']}</code>\n"
            f"📦 {(_s.get('name') or _svc)}\n"
            f"💳 оплачено {_paid:.0f} ₽ → тебе {_owner_sum:.0f} ₽, партнёру {_partner_sum:.0f} ₽",
            parse_mode="HTML")
    except Exception:
        pass


async def process_premium_referral(referee_id: int, order_id: str, amount_rub: float):
    """Премиум-рефералка: % монетками с КАЖДОЙ оплаты реферала (только для премиум-партнёров).
    Идемпотентно по order_id, с месячным лимитом из настроек."""
    try:
        if not amount_rub or float(amount_rub) <= 0:
            return
        pool = await get_pool()
        async with pool.acquire() as conn:
            row = await conn.fetchrow(
                "SELECT referred_by FROM users WHERE user_id=$1", referee_id
            )
        if not row or not row["referred_by"]:
            return
        referrer_id = row["referred_by"]
        if referrer_id == referee_id:
            return
        rp = await get_ref_premium(referrer_id)
        if not rp or not rp.get("ref_premium"):
            return
        if await is_blocked(referrer_id):
            return
        # процент: индивидуальный, иначе глобальный из настроек
        pct = rp.get("ref_premium_pct")
        if pct is None:
            try:
                pct = float(await get_setting("ref_premium_pct", "10") or "10")
            except Exception:
                pct = 10.0
        pct = float(pct)
        if pct <= 0:
            return
        reward = round(float(amount_rub) * pct / 100.0, 2)
        if reward <= 0:
            return
        # месячный лимит (0 = без лимита)
        try:
            cap = float(await get_setting("ref_premium_cap", "0") or "0")
        except Exception:
            cap = 0.0
        # Лимит и запись в лог — одной транзакцией (идемпотентность по order_id +
        # блокировка строк месяца). Раньше проверка шла отдельно, и две
        # одновременные оплаты могли пробить месячный cap.
        reward = await log_premium_ref(referrer_id, referee_id, order_id,
                                       float(amount_rub), reward, cap=cap)
        if not reward or reward <= 0:
            logging.info(f"premium ref пропущен (лимит или дубль) order={order_id}")
            return
        # Монетки уже начислены внутри log_premium_ref — одной транзакцией с
        # записью в лог. Отдельного начисления здесь больше нет: именно разрыв
        # между ними терял выплату при рестарте (аудит 29.09.2026, пункт №17).
        try:
            new_coins = await get_coins(referrer_id)
            await bot.send_message(
                referrer_id,
                f"💎 <b>Премиум-реферал</b>\n\n"
                f"Твой реферал оплатил покупку на {int(round(float(amount_rub)))}₽.\n"
                f"🪙 Начислено: <b>+{reward:.0f}₽</b> монетками ({pct:.0f}%).\n"
                f"💰 Баланс монеток: <b>{new_coins:.0f}₽</b>",
                parse_mode="HTML"
            )
        except Exception:
            pass
    except Exception as e:
        logging.error(f"process_premium_referral error: {e}")


async def _send_long_reply(message_or_cb, text: str, reply_markup=None,
                            is_callback: bool = False):
    """Отправляет длинный ответ консультанта, разбивая на части если надо.
    Клавиатура ВСЕГДА прикрепляется к ПОСЛЕДНЕЙ части - так она не 'уезжает' вверх.

    message_or_cb: Message (из chat_message) или CallbackQuery.message (из preset)
    text: ответ консультанта (может быть длинным)
    reply_markup: клавиатура для последнего сообщения
    is_callback: передан ли message_or_cb как CallbackQuery.message
    """
    # Клиент Telegram - это объект Message (даже если пришло из callback)
    send_target = message_or_cb

    parts = _split_long_message(text, max_len=3800)

    for i, part in enumerate(parts):
        is_last = (i == len(parts) - 1)
        kb = reply_markup if is_last else None

        try:
            await send_target.answer(part, reply_markup=kb, parse_mode="HTML")
        except Exception as e:
            # HTML не распарсился - стрипаем форматирование и шлём plain text
            logging.warning(f"HTML send failed (part {i+1}/{len(parts)}): {e}")
            plain = _strip_all_formatting(part)
            try:
                await send_target.answer(plain, reply_markup=kb)
            except Exception as e2:
                logging.error(f"Plain text also failed (part {i+1}): {e2}")


