async def _inject_recs(html: str, exclude_key: str) -> str:
    """Вставляет window.__RECS__ / __CATALOG__ / __BOT__ в <head> мини-аппки."""
    import json as _json
    try:
        _recs = await _build_recs_payload(exclude_key=exclude_key)
        _cat = _build_catalog_payload()
        # Скрытие и порядок сервисов (из админки)
        _hidden = await _shop_hidden_set()
        _order = await _shop_order_list()
        if _hidden:
            for _hk in list(_cat.keys()):
                if _hk in _hidden:
                    _cat.pop(_hk, None)
            _recs = [_r for _r in _recs if _r.get("key") not in _hidden]
        if _order:
            _oidx = {_k: _i for _i, _k in enumerate(_order)}
            _cat = {_k: _cat[_k] for _k in sorted(_cat.keys(), key=lambda k: _oidx.get(k, 10**6))}
        # Вшиваем официальные логотипы (inline SVG) в каталог и в ленту
        _logo_by_key = {}
        for _k in _cat.keys():
            _logo_by_key[_k] = await _logo_html_for(_k, _cat[_k].get("name", ""))
            _cat[_k]["logo"] = _logo_by_key[_k]
        for _it in _recs:
            _it["logo"] = _logo_by_key.get(_it.get("key"), "")
        _uname = await _get_bot_uname()
        try:
            _cats = await _build_shop_categories()
            # оставляем в категориях только видимые сервисы и сортируем по порядку
            _oidx2 = {_k: _i for _i, _k in enumerate(_order)} if _order else {}
            for _c in _cats:
                _c["keys"] = [k for k in _c["keys"] if k in _cat]
                if _order:
                    _c["keys"].sort(key=lambda k: _oidx2.get(k, 10**6))
        except Exception:
            _cats = []
        try:
            _banners = [_b for _b in await _shop_banners() if _b.get("on")]
        except Exception:
            _banners = []
        try:
            from config import IMAGE_MODELS as _IM
            def _img_group(_k, _v):
                _a = (_v.get("api") or "")
                if _k.startswith("img_"): return "Imagen"
                if _k.startswith("nb_"): return "Nano Banana"
                if _k.startswith("gptimg"): return "GPT Image"
                if _k.startswith("flux"): return "Flux"
                if _k.startswith("ideo"): return "Ideogram"
                if "grok" in _k: return "Grok"
                return "Другое"
            _imgmodels = [{"key": _k, "name": _v.get("name", _k), "credits": _v.get("credits", 0),
                           "desc": _v.get("desc", ""), "speed": _v.get("speed", ""),
                           "group": _img_group(_k, _v)}
                          for _k, _v in _IM.items()]
        except Exception:
            _imgmodels = []
        try:
            from config import VIDEO_MODELS as _VM
            def _vid_group(_k):
                if _k.startswith("vid_"): return "Veo"
                if _k.startswith("kling"): return "Kling"
                if _k.startswith("seedance"): return "Seedance"
                if "grok" in _k: return "Grok"
                if _k.startswith("wan"): return "Wan"
                return "Другое"
            _vidmodels = []
            for _k, _v in _VM.items():
                _du = _v.get("durations")
                _durs = ([{"d": _d, "credits": _t[0]} for _d, _t in sorted(_du.items())] if _du
                         else [{"d": 8, "credits": int(_v.get("credits", 0))}])
                _vidmodels.append({"key": _k, "name": _v.get("name", _k),
                                   "credits": _v.get("credits", 0), "desc": _v.get("desc", ""),
                                   "res": _v.get("res", ""), "group": _vid_group(_k),
                                   "durations": _durs})
        except Exception:
            _vidmodels = []
        try:
            from config import EDIT_MODELS as _EM
            _editmodels = [{"key": _k, "name": _v.get("name", _k), "credits": _v.get("credits", 0),
                            "desc": _v.get("desc", "")} for _k, _v in _EM.items()]
        except Exception:
            _editmodels = []
        try:
            from config import ANIM_MODELS as _AM
            _animmodels = [{"key": _k, "name": _v.get("name", _k), "credits": _v.get("credits", 0),
                            "desc": _v.get("desc", ""), "duration": _v.get("duration", 5)}
                           for _k, _v in _AM.items()]
        except Exception:
            _animmodels = []
        try:
            _shophead = {
                "title": (await get_setting("shop_head_title", "") or "Neirosetka — Александр ИИ"),
                "sub": (await get_setting("shop_head_sub", "") or "Подписки на ИИ-сервисы и пополнение App Store"),
                "emoji": (await get_setting("shop_head_emoji", "") or "🛍"),
                "img": (await get_setting("shop_head_img", "") or ""),
                "color": (await get_setting("shop_head_color", "") or ""),
                "pos": (await get_setting("shop_head_pos", "") or "left"),
                "size": int(await get_setting("shop_head_size", "") or "56"),
                "cols": int(await get_setting("shop_cols", "") or "3"),
            }
        except Exception:
            _shophead = {"title": "Neirosetka — Александр ИИ",
                         "sub": "Подписки на ИИ-сервисы и пополнение App Store",
                         "emoji": "🛍", "img": "", "color": "", "pos": "left", "size": 56, "cols": 3}
        _tag = ("<script>window.__RECS__=" + _json.dumps(_recs, ensure_ascii=False)
                + ";window.__CATALOG__=" + _json.dumps(_cat, ensure_ascii=False)
                + ";window.__CATEGORIES__=" + _json.dumps(_cats, ensure_ascii=False)
                + ";window.__BANNERS__=" + _json.dumps(_banners, ensure_ascii=False)
                + ";window.__IMGMODELS__=" + _json.dumps(_imgmodels, ensure_ascii=False)
                + ";window.__VIDMODELS__=" + _json.dumps(_vidmodels, ensure_ascii=False)
                + ";window.__EDITMODELS__=" + _json.dumps(_editmodels, ensure_ascii=False)
                + ";window.__ANIMMODELS__=" + _json.dumps(_animmodels, ensure_ascii=False)
                + ";window.__SHOPHEAD__=" + _json.dumps(_shophead, ensure_ascii=False)
                + ";window.__BOT__=" + _json.dumps(_uname) + ";</script>")
        if "</head>" in html:
            return html.replace("</head>", _tag + "</head>", 1)
        return _tag + html
    except Exception as _e:
        logging.error(f"_inject_recs: {_e}")
        return html


