async def api_admin_packs_save_handler(request: web.Request) -> web.Response:
    """Сохранение пакета кредитов: цена, кредиты, название, показ. Admin-only.

    Удаление намеренно НЕ делаем: пакет, за который кто-то уже платил, лучше
    выключить — тогда он пропадает из бота, но остаётся в истории заказов.
    """
    try:
        try: body = await request.json()
        except Exception: body = {}
        if _admin_uid_from_body(body) != ADMIN_ID:
            return web.json_response({"ok": False}, status=403)
        from config import CREDIT_PACKS
        _act = str(body.get("action") or "save")
        key = str(body.get("key") or "").strip()
        if not key or len(key) > 40 or not re.fullmatch(r"[A-Za-z0-9_\-]+", key):
            return web.json_response({"ok": False, "msg": "Ключ: латиница, цифры, _ и -"})

        if _act == "toggle":
            _on = bool(body.get("enabled"))
            pool = await get_pool()
            async with pool.acquire() as conn:
                _r = await conn.execute(
                    "UPDATE bot_credit_packs SET enabled=$2 WHERE key=$1", key, _on)
            if not (isinstance(_r, str) and _r.strip().endswith(" 1")):
                return web.json_response({"ok": False, "msg": "Пакет не найден"})
            if not _on:
                CREDIT_PACKS.pop(key, None)
            await _reload_prices_safe()
            return web.json_response({"ok": True})

        def _num(field, lo, hi, dflt=None):
            _v = body.get(field)
            if _v is None or _v == "":
                return dflt
            try: _v = int(_v)
            except Exception: return None
            return _v if lo <= _v <= hi else None

        name = str(body.get("name") or "").strip()[:60]
        credits = _num("credits", 1, 1000000)
        price = _num("price", 1, 1000000)
        stars = _num("stars", 0, 1000000, 0)
        if not name or credits is None or price is None or stars is None:
            return web.json_response(
                {"ok": False, "msg": "Название обязательно, кредиты и цена — "
                                     "целые числа больше нуля"})
        desc = str(body.get("desc") or "")[:200]
        badge = str(body.get("badge") or "")[:40]
        sort = _num("sort", 0, 999, 0) or 0
        pool = await get_pool()
        async with pool.acquire() as conn:
            await conn.execute(
                "INSERT INTO bot_credit_packs "
                "(key, name, credits, price, stars, description, badge, enabled, sort_order) "
                "VALUES ($1,$2,$3,$4,$5,$6,$7,TRUE,$8) "
                "ON CONFLICT (key) DO UPDATE SET name=$2, credits=$3, price=$4, "
                "stars=$5, description=$6, badge=$7, sort_order=$8",
                key, name, credits, price, stars, desc, badge, sort)
        await _reload_prices_safe()
        logging.info(f"admin: пакет {key} = {credits} кр. за {price} ₽")
        return web.json_response({"ok": True, "key": key})
    except Exception as _e:
        logging.error(f"api_admin_packs_save: {_e}")
        return web.json_response({"ok": False, "error": "server"}, status=500)


async def _reload_prices_safe():
    """Перечитывает цены из БД в память бота. Сбой не должен ронять сохранение:
    запись уже в базе, а в память она попадёт при следующем старте."""
    try:
        from db import load_prices_from_db
        await load_prices_from_db()
    except Exception as _e:
        logging.warning(f"перечитать цены не вышло (в базе сохранено): {_e}")


async def api_admin_orders_handler(request: web.Request) -> web.Response:
    try:
        try: body = await request.json()
        except Exception: body = {}
        if _admin_uid_from_body(body) != ADMIN_ID:
            return web.json_response({"ok": False}, status=403)
        kinds = body.get("kinds")
        status = str(body.get("status") or "work")
        work_st = ["awaiting_link", "awaiting_payment", "awaiting_creds", "awaiting_setup"]
        pool = await get_pool()
        async with pool.acquire() as conn:
            if status == "done":
                rows = await conn.fetch("SELECT * FROM linkpay_orders WHERE status IN ('done') ORDER BY created_at DESC LIMIT 100")
            else:
                rows = await conn.fetch("SELECT * FROM linkpay_orders WHERE status = ANY($1::text[]) ORDER BY created_at DESC LIMIT 100", work_st)
        if kinds:
            rows = [r for r in rows if r.get("kind") in kinds]
        st = {"awaiting_link": "ждёт ссылку", "awaiting_payment": "ждёт оплаты",
              "awaiting_creds": "ждёт данные", "awaiting_setup": "оформляется",
              "done": "выполнен", "cancelled": "отменён"}
        out = []
        for r in rows:
            out.append({"id": r.get("fk_order_id"), "service": r.get("service_name"),
                        "plan": r.get("plan_name"), "kind": r.get("kind"),
                        "user": ("@" + r["username"]) if r.get("username") else ("id" + str(r.get("user_id"))),
                        "status": st.get(r.get("status"), r.get("status")), "raw": r.get("status") or "",
                        "link": r.get("payment_link")})
        return web.json_response({"ok": True, "orders": out})
    except Exception as _e:
        logging.error(f"api_admin_orders: {_e}")
        return web.json_response({"ok": False}, status=500)


async def api_admin_payments_handler(request: web.Request) -> web.Response:
    """История платежей: деньги, а не выдача. Реальные строки из fk_orders.

    Экран «История платежей» до этого был макетом — пять выдуманных строк и
    четыре константы в пончике, никакого обращения к серверу. Выглядело как
    настоящая статистика, и это худший вид ошибки: по ней можно было принять
    решение. Здесь всё считается по базе.

    Отличие от «Ленты заказов»: та про выдачу (активирован / в работе), эта —
    про оплату: способ, промокод, монетки, отменённые и незавершённые.
    Admin-only.
    """
    import datetime as _dt_pay
    try:
        try: body = await request.json()
        except Exception: body = {}
        if _admin_uid_from_body(body) != ADMIN_ID:
            return web.json_response({"ok": False}, status=403)
        page = max(0, int(body.get("page") or 0))
        q = str(body.get("q") or "").strip()
        flt = str(body.get("filter") or "all")        # all | paid | pending | cancelled
        days = int(body.get("days") or 30)
        days = max(1, min(days, 3650))
        PAGE = 30
        _since = _dt_pay.date.today() - _dt_pay.timedelta(days=days - 1)

        # Отбор по времени: у оплаченных смотрим на paid_at, у неоплаченных его
        # нет вовсе — иначе неоплаченные исчезли бы из выборки целиком.
        # $1 — именно объект date, не строка: с явным ::date asyncpg выводит тип
        # параметра как date и строку не принимает («str has no toordinal»).
        # Живая база это ловит сразу, а в проде это было бы падение экрана.
        #
        # ВАЖНО про два набора условий. Пончик считает ВСЕ статусы за период, а
        # список — только выбранный. Раньше я собирал один список условий и для
        # пончика просто выбрасывал из него строку про статус, оставляя аргументы
        # как есть: получалось «запросу нужен 1 аргумент, передали 2», а при
        # поиске ещё и разъезжалась нумерация $2, $3… Поэтому база (период +
        # поиск) собирается один раз, а условие статуса добавляется ПОСЛЕДНИМ и
        # только в запрос списка — тогда номера у общей части всегда одни и те же.
        base_where = ["COALESCE(f.paid_at, f.created_at) >= $1"]
        base_args = [_since]
        if q:
            _qq = q.lstrip("#@")
            base_args.append(q);          _i1 = len(base_args)
            base_args.append(_qq);        _i2 = len(base_args)
            base_args.append(f"%{q}%");   _i3 = len(base_args)
            base_args.append(f"%{_qq}%"); _i4 = len(base_args)
            base_where.append(
                f"(f.fk_intid = ${_i1} OR CAST(f.num AS TEXT) = ${_i2} "
                f"OR f.order_id ILIKE ${_i3} OR u.username ILIKE ${_i4} "
                f"OR CAST(f.user_id AS TEXT) = ${_i2})")
        where = list(base_where)
        args = list(base_args)
        if flt in ("paid", "pending", "cancelled"):
            args.append(flt); where.append(f"f.status = ${len(args)}")
        where_sql = " AND ".join(where)
        base_sql = " AND ".join(base_where)

        pool = await get_pool()
        async with pool.acquire() as conn:
            # Пончик — по тем же условиям, что и список, но без фильтра статуса:
            # иначе «Оплачены 18» показывалось бы рядом со списком из одних
            # отменённых, и два числа на экране противоречили бы друг другу.
            _stats = await conn.fetch(
                "SELECT f.status, COUNT(*) AS n, COALESCE(SUM(f.amount_rub),0) AS rub "
                "FROM fk_orders f LEFT JOIN users u ON u.user_id=f.user_id "
                f"WHERE {base_sql} GROUP BY f.status", *base_args)
            total = await conn.fetchval(
                "SELECT COUNT(*) FROM fk_orders f LEFT JOIN users u ON u.user_id=f.user_id "
                f"WHERE {where_sql}", *args) or 0
            pages = max(1, (total + PAGE - 1) // PAGE)
            page = min(page, pages - 1)
            rows = await conn.fetch(
                "SELECT f.order_id, f.num, f.user_id, f.amount_rub, f.pack, f.credits, "
                "       f.status, f.payment_method, f.promo_code, f.coins_spent, "
                "       f.paid_at, f.created_at, f.fk_intid, "
                "       COALESCE(u.username,'') AS username, COALESCE(u.full_name,'') AS full_name "
                "FROM fk_orders f LEFT JOIN users u ON u.user_id=f.user_id "
                f"WHERE {where_sql} "
                "ORDER BY COALESCE(f.paid_at, f.created_at) DESC "
                f"LIMIT {PAGE} OFFSET {page * PAGE}", *args)

        def _what(pack, credits):
            """Человеческое название покупки из технического pack."""
            _p = (pack or "")
            if _p.startswith("shop:"):
                _pp = _p.split(":")
                _k = _pp[1] if len(_pp) > 1 else ""
                _i = int(_pp[2]) if len(_pp) > 2 and _pp[2].isdigit() else -1
                _cat = SHOP_CATALOG.get(_k, {}) or {}
                _plans = _cat.get("plans", [])
                _pn = _plans[_i]["name"] if 0 <= _i < len(_plans) else ""
                return (f"{_cat.get('name', _k)} · {_pn}" if _pn else _cat.get("name", _k or "Покупка"))
            if _p.startswith("nsg:"):
                return "App Store"
            return f"Кредиты × {credits}" if credits else "Пополнение"

        _st_ru = {"paid": "оплачен", "pending": "не оплачен", "cancelled": "отменён"}
        _st_tag = {"paid": "g", "pending": "a", "cancelled": "n"}
        _out = []
        for r in rows:
            _when = r["paid_at"] or r["created_at"]
            _out.append({
                "orderId": r["order_id"],
                "num": int(r["num"] or 0),
                "uid": int(r["user_id"] or 0),
                "user": ("@" + r["username"]) if r["username"]
                        else (r["full_name"] or f"id{r['user_id']}"),
                "what": _what(r["pack"], int(r["credits"] or 0)),
                "amount": int(r["amount_rub"] or 0),
                "status": r["status"] or "",
                "statusRu": _st_ru.get(r["status"] or "", r["status"] or "—"),
                "tag": _st_tag.get(r["status"] or "", "b"),
                "method": {"sbp": "СБП", "card": "Карта"}.get(r["payment_method"] or "",
                                                              r["payment_method"] or ""),
                "promo": r["promo_code"] or "",
                "coins": int(r["coins_spent"] or 0),
                "fk": r["fk_intid"] or "",
                "when": _when.isoformat() if _when else "",
            })
        _sd = {x["status"]: {"n": int(x["n"] or 0), "rub": int(x["rub"] or 0)} for x in _stats}
        return web.json_response({
            "ok": True, "rows": _out, "total": total, "page": page, "pages": pages,
            "days": days,
            "stats": [{"key": k, "label": _st_ru.get(k, k), "n": v["n"], "rub": v["rub"]}
                      for k, v in sorted(_sd.items(), key=lambda x: -x[1]["n"])],
            "paidSum": _sd.get("paid", {}).get("rub", 0),
        })
    except Exception as _e:
        logging.error(f"api_admin_payments: {_e}", exc_info=True)
        return web.json_response({"ok": False, "error": "server"}, status=500)


async def api_admin_all_orders_handler(request: web.Request) -> web.Response:
    """Единая ЛЕНТА всех оплаченных заказов (ChatGPT, Claude, App Store, кредиты и
    т.д.) — новейшие сверху, как оплачивают клиенты. Отменённые не показываем
    (у них статус fk_orders='cancelled'). Admin-only."""
    try:
        try: body = await request.json()
        except Exception: body = {}
        if _admin_uid_from_body(body) != ADMIN_ID:
            return web.json_response({"ok": False}, status=403)
        page = int(body.get("page") or 0)
        date_s = str(body.get("date") or "").strip()   # 'YYYY-MM-DD' — конкретный день
        q = str(body.get("q") or "").strip()           # поиск по FreeKassa/№/order_id
        flt = str(body.get("filter") or "all")         # all | done | work | cancelled
        PAGE = 30
        _status = "cancelled" if flt == "cancelled" else "paid"
        # «Активирован» вычисляем в SQL, чтобы работали фильтр + пагинация.
        _act_sql = (
            "((f.pack NOT LIKE 'shop:%' AND f.pack NOT LIKE 'nsg:%') "
            "OR EXISTS(SELECT 1 FROM gpt_codes g WHERE g.order_id=f.order_id AND g.used_at IS NOT NULL) "
            "OR EXISTS(SELECT 1 FROM claude_codes c WHERE c.order_id=f.order_id AND c.used_at IS NOT NULL) "
            "OR EXISTS(SELECT 1 FROM perplexity_codes p WHERE p.order_id=f.order_id AND p.used_at IS NOT NULL) "
            "OR EXISTS(SELECT 1 FROM nsgifts_orders n WHERE n.fk_order_id=f.order_id AND n.status='fulfilled') "
            "OR EXISTS(SELECT 1 FROM linkpay_orders l WHERE l.fk_order_id=f.order_id AND l.status='done') "
            "OR EXISTS(SELECT 1 FROM settings st WHERE st.key=('order_done:'||f.order_id) AND st.value='1'))")
        where = [f"f.status='{_status}'", "f.paid_at IS NOT NULL"]
        if flt == "done":
            where.append(_act_sql)
        elif flt == "work":
            where.append("NOT " + _act_sql)
        args = []
        if date_s:
            args.append(date_s); _di = len(args)
            where.append(f"f.paid_at >= ${_di}::date AND f.paid_at < (${_di}::date + INTERVAL '1 day')")
        if q:
            _qq = q.lstrip("#")
            args.append(q); _i1 = len(args)
            args.append(_qq); _i2 = len(args)
            args.append(f"%{q}%"); _i3 = len(args)
            where.append(f"(f.fk_intid = ${_i1} OR CAST(f.num AS TEXT) = ${_i2} OR f.order_id ILIKE ${_i3})")
        where_sql = " AND ".join(where)
        pool = await get_pool()
        async with pool.acquire() as conn:
            total = await conn.fetchval(f"SELECT COUNT(*) FROM fk_orders f WHERE {where_sql}", *args) or 0
            pages = max(1, (total + PAGE - 1) // PAGE)
            page = max(0, min(page, pages - 1))
            rows = await conn.fetch(
                "SELECT f.order_id, f.user_id, f.amount_rub, f.pack, f.credits, "
                "       f.paid_at, f.num, f.fk_intid, u.username "
                "FROM fk_orders f LEFT JOIN users u ON u.user_id=f.user_id "
                f"WHERE {where_sql} ORDER BY f.paid_at DESC LIMIT {PAGE} OFFSET {page * PAGE}", *args)
            ids = [r["order_id"] for r in rows]
            gpt_used, cl_used, px_used = set(), set(), set()
            lp_map, nsg_map, done_set = {}, {}, set()
            if ids:
                for _tbl, _acc in (("gpt_codes", gpt_used), ("claude_codes", cl_used),
                                   ("perplexity_codes", px_used)):
                    try:
                        _rr = await conn.fetch(
                            f"SELECT DISTINCT order_id FROM {_tbl} "
                            f"WHERE order_id = ANY($1::text[]) AND used_at IS NOT NULL", ids)
                        for x in _rr:
                            _acc.add(x["order_id"])
                    except Exception:
                        pass
                try:
                    for x in await conn.fetch(
                        "SELECT fk_order_id, status FROM linkpay_orders WHERE fk_order_id = ANY($1::text[])", ids):
                        lp_map[x["fk_order_id"]] = x["status"]
                except Exception:
                    pass
                try:
                    for x in await conn.fetch(
                        "SELECT fk_order_id, status FROM nsgifts_orders WHERE fk_order_id = ANY($1::text[])", ids):
                        nsg_map[x["fk_order_id"]] = x["status"]
                except Exception:
                    pass
                try:
                    _dk = [f"order_done:{i}" for i in ids]
                    for x in await conn.fetch(
                        "SELECT key FROM settings WHERE key = ANY($1::text[]) AND value='1'", _dk):
                        done_set.add(x["key"].split(":", 1)[1])
                except Exception:
                    pass
            man_set = set()
            try:
                async with pool.acquire() as conn2:
                    for x in await conn2.fetch("SELECT key FROM settings WHERE key LIKE 'manual:%' AND value='1'"):
                        man_set.add(x["key"])
            except Exception:
                pass
        out = []
        for r in rows:
            oid = r["order_id"]; pack = r["pack"] or ""
            svc_key = ""; svc = ""; plan = ""; idx = 0
            if pack.startswith("shop:"):
                parts = pack.split(":")
                svc_key = parts[1] if len(parts) > 1 else ""
                idx = int(parts[2]) if len(parts) > 2 and parts[2].isdigit() else 0
                scat = SHOP_CATALOG.get(svc_key, {}) or {}
                svc = scat.get("name", svc_key or "Заказ")
                plans = scat.get("plans", [])
                plan = plans[idx]["name"] if 0 <= idx < len(plans) else ""
            elif pack.startswith("nsg:"):
                svc_key, svc, plan = "appstore", "App Store", ""
            else:
                svc_key, svc = "credits", "Кредиты"
                plan = (f"{int(r['credits'])} кр" if r["credits"] else "")
            activated = False; stage = "Оплачено"; stageKey = "paid"
            if svc_key in ("chatgpt", "claude", "perplexity"):
                used = (oid in gpt_used) if svc_key == "chatgpt" else \
                       (oid in cl_used) if svc_key == "claude" else (oid in px_used)
                if used or oid in done_set:
                    activated, stage, stageKey = True, "Активировано", "done"
                elif f"manual:{svc_key}:{idx}" in man_set:
                    stage, stageKey = "В работе", "work"
            elif svc_key == "appstore":
                if nsg_map.get(oid) == "fulfilled":
                    activated, stage, stageKey = True, "Выдано", "done"
                else:
                    stage, stageKey = "В работе", "work"
            elif svc_key == "credits":
                activated, stage, stageKey = True, "Выдано", "done"
            # ручные (linkpay) заказы: статус переопределяет
            _lst = lp_map.get(oid)
            if _lst == "done":
                activated, stage, stageKey = True, "Активировано", "done"
            elif _lst in ("awaiting_link", "awaiting_payment", "awaiting_creds", "awaiting_setup"):
                if stageKey != "done":
                    stage, stageKey = "В работе", "work"
            # «Активировали вручную» (order_done) — для ЛЮБОГО сервиса, если ещё не done
            if (not activated) and (oid in done_set):
                activated, stage, stageKey = True, "Активировано", "done"
            if flt == "cancelled":
                activated, stage, stageKey = False, "Отменён", "cancelled"
            _pa = r["paid_at"]
            out.append({
                "id": oid, "num": r["num"],
                "user": ("@" + r["username"]) if r["username"] else ("id" + str(r["user_id"])),
                "userId": r["user_id"], "username": r["username"] or "",
                "service": svc, "svc": svc_key, "plan": plan, "idx": idx,
                "amount": int(r["amount_rub"] or 0),
                "date": _pa.astimezone(_BOT_TZ).strftime("%d.%m %H:%M") if _pa else "",
                "fk": r["fk_intid"] or "",
                "stage": stage, "stageKey": stageKey, "activated": activated,
                "isAuto": svc_key in ("chatgpt", "claude", "perplexity"),
            })
        return web.json_response({"ok": True, "orders": out,
                                  "page": page, "pages": pages, "total": total})
    except Exception as _e:
        logging.error(f"api_admin_all_orders: {_e}")
        return web.json_response({"ok": False}, status=500)


async def api_admin_feed_order_action_handler(request: web.Request) -> web.Response:
    """Действия по заказу из ленты: cancel | manual | resend. Работает для ЛЮБОГО
    оплаченного заказа (в т.ч. авто-сервисов, которых нет в linkpay). Admin-only."""
    try:
        try: body = await request.json()
        except Exception: body = {}
        if _admin_uid_from_body(body) != ADMIN_ID:
            return web.json_response({"ok": False}, status=403)
        oid = str(body.get("id", "")); action = str(body.get("action", ""))
        pool = await get_pool()
        async with pool.acquire() as conn:
            o = await conn.fetchrow("SELECT user_id, pack, status FROM fk_orders WHERE order_id=$1", oid)
        if not o:
            return web.json_response({"ok": False, "msg": "Заказ не найден"})
        if action == "resolve":
            # «Разобрался»: деньги вернул / выдал вручную — убрать заказ из
            # «Нужно действие». Клиенту ничего не пишем, статус заказа и коды
            # не трогаем: это только отметка для панели. 06.10.2026
            await set_setting(f"order_resolved:{oid}", "1")
            return web.json_response({"ok": True, "msg": "Отмечено: разобрано"})
        if action in ("manual", "resend") and (o["status"] or "") != "paid":
            return web.json_response({"ok": False, "msg": "Заказ не в статусе «оплачен» — это действие для него недоступно"})
        uid = o["user_id"]; pack = o["pack"] or ""
        svc_key = ""; idx = 0
        if pack.startswith("shop:"):
            parts = pack.split(":")
            svc_key = parts[1] if len(parts) > 1 else ""
            idx = int(parts[2]) if len(parts) > 2 and parts[2].isdigit() else 0
        elif pack.startswith("nsg:"):
            svc_key = "appstore"

        if action == "cancel":
            async with pool.acquire() as conn:
                await conn.execute("UPDATE fk_orders SET status='cancelled' WHERE order_id=$1", oid)
            # Отменённый заказ не должен оставлять живой резерв: по нему клиент
            # мог запустить автоматическую активацию уже после отмены.
            if uid:
                try:
                    await delete_pending_activation(int(uid), oid)
                except Exception as _e_dc:
                    logging.warning(f"cancel: резерв {oid}: {_e_dc}")
            # Резерв Claude/Perplexity лежит в своих таблицах: без этого клиент
            # мог активировать подписку по уже отменённому заказу. Резерв НЕ
            # удаляем, а делаем просроченным: клиенту он больше не выдаётся
            # (бот берёт только expires_at > NOW()), а фоновая чистка дальше
            # действует по своему правилу — если активацию даже не начинали,
            # код вернётся в пул; если начинали (bpa_order_id / org_id), код
            # остаётся за заказом и приходит тебе в «Ждущие коды». Удаление
            # резерва отдавало в пул и код с начатой активацией. Ревью 06.10.2026.
            for _ptbl_c in ("claude_pending_activations", "perplexity_pending_activations"):
                try:
                    async with pool.acquire() as _c_cx:
                        await _c_cx.execute(
                            f"UPDATE {_ptbl_c} SET expires_at = NOW() - INTERVAL '1 second' "
                            f"WHERE order_id=$1 AND expires_at > NOW()", oid)
                except Exception as _e_cx:
                    logging.warning(f"cancel: резерв {_ptbl_c} {oid}: {_e_cx}")
            try:
                await set_linkpay_status(oid, "cancelled")  # если есть ручной заказ
            except Exception:
                pass
            if uid:
                try:
                    await bot.send_message(
                        uid, f"❌ <b>Заказ отменён</b>\n\n"
                             f"Если деньги были списаны — напиши по возврату: @{PERSONAL_USERNAME}",
                        parse_mode="HTML")
                except Exception:
                    pass
            return web.json_response({"ok": True})

        if action == "manual":
            _msg_fm = ""
            if svc_key in ("chatgpt", "claude", "perplexity"):
                _ok_fm, _msg_fm, _ = await _admin_manual_close(
                    svc_key, oid, uid, str(body.get("fate") or ""))
                if not _ok_fm:
                    return web.json_response({"ok": False, "msg": _msg_fm})
            else:
                try:
                    await set_linkpay_status(oid, "done")
                except Exception:
                    pass
                await set_setting(f"order_done:{oid}", "1")
            if uid:
                # Было «Готово, пользуйся» без сервиса, срока и номера заказа.
                await client_success_for_order(uid, oid, svc_key)
            return web.json_response({"ok": True, "msg": _msg_fm})

        if action == "resend":
            if svc_key not in ("chatgpt", "claude", "perplexity"):
                return web.json_response({"ok": False, "msg": "Повторная выдача — только для ChatGPT/Claude/Perplexity"})
            scat = SHOP_CATALOG.get(svc_key, {}) or {}
            plans = scat.get("plans", [])
            plan_name = plans[idx]["name"] if 0 <= idx < len(plans) else "Plus"
            # ВАЖНО: ключ тарифа должен совпадать с тем, что используется при ПОКУПКЕ,
            # иначе коды не находятся. Claude/Perplexity имеют свою карту (не plan_name_to_key).
            if svc_key == "claude":
                plan_key = {"Pro": "pro", "Max 5×": "max_5x", "Max 20×": "max_20x"}.get(plan_name, "pro")
            elif svc_key == "perplexity":
                plan_key = "pro"
            else:
                plan_key = plan_name_to_key(plan_name)
            if svc_key == "chatgpt":
                # ВАЖНО: переиспользуем УЖЕ закреплённый за этим заказом код (из pending),
                # чтобы не потратить на один заказ второй код. Новый берём только если
                # прежнего нет (pending истёк и код вернулся в пул).
                _pend = await get_pending_activation(uid)
                # Резерв берём только если он ОТ ЭТОГО ЗАКАЗА. Он хранится по
                # клиенту, и при двух оплаченных заказах подряд код второго
                # мог быть перепривязан к первому. Внешний аудит 29.09.2026.
                if (_pend and _pend.get("code")
                        and str(_pend.get("order_id") or "") == str(oid)):
                    _code = _pend["code"]; _prov = _pend.get("provider") or "987ai"
                else:
                    _code, _prov = await _gpt_pick_code(plan_key)
                    if not _code:
                        return web.json_response({"ok": False, "msg": "Нет свободных кодов ChatGPT"})
                await save_pending_activation(uid, _code, oid, plan_key, plan_name, _prov)
                import urllib.parse as _uq
                from aiogram.types import WebAppInfo as _WAI
                _url = webapp_url("/webapp/chatgpt", plan=plan_name, code=_code)
                try:
                    await bot.send_message(
                        uid,
                        f"🔔 <b>Активация подписки ChatGPT</b>\n\n"
                        f"📦 {scat.get('name','ChatGPT')} {plan_name}\n"
                        f"🎟 Код: <code>{_code}</code>\n\n"
                        f"Нажми кнопку ниже, чтобы активировать 👇",
                        parse_mode="HTML",
                        reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                            [InlineKeyboardButton(text="✨ Активировать подписку", web_app=_WAI(url=_url))],
                            [InlineKeyboardButton(text="❓ Нужна помощь", callback_data="gpt_need_help")],
                        ]))
                except Exception as _se:
                    return web.json_response({"ok": False, "msg": f"Не удалось отправить: {_se}"})
            elif svc_key == "claude":
                # Резерв переиспользуем только ОТ ЭТОГО заказа; неясный исход,
                # уже активированный заказ — отказ с причиной. 08.10.2026
                _ok_cr, _msg_cr = await claude_resend_activation(oid)
                if not _ok_cr:
                    return web.json_response({"ok": False, "msg": re.sub(r"<[^>]+>", "", str(_msg_cr))})
            else:
                # Резерв переиспользуем только ОТ ЭТОГО заказа. 08.10.2026
                _ok_pr, _msg_pr = await perplexity_resend_activation(oid)
                if not _ok_pr:
                    return web.json_response({"ok": False, "msg": re.sub(r"<[^>]+>", "", str(_msg_pr))})
            await set_setting(f"order_done:{oid}", "0")
            return web.json_response({"ok": True})

        return web.json_response({"ok": False, "msg": "Неизвестное действие"})
    except Exception as _e:
        logging.error(f"api_admin_feed_order_action: {_e}")
        return web.json_response({"ok": False}, status=500)


async def api_admin_order_action_handler(request: web.Request) -> web.Response:
    try:
        try: body = await request.json()
        except Exception: body = {}
        if _admin_uid_from_body(body) != ADMIN_ID:
            return web.json_response({"ok": False}, status=403)
        oid = str(body.get("id", "")); action = str(body.get("action", ""))
        order = await get_linkpay_order(oid)
        if not order:
            return web.json_response({"ok": False, "msg": "Заказ не найден"})
        uid = order.get("user_id"); svc = order.get("service_name", "")
        if action == "done":
            await set_linkpay_status(oid, "done")
            try:
                await bot.send_message(uid, f"🎉 <b>Подписка оформлена!</b>\n\n📦 {svc}\n\nСпасибо за покупку! 🙌", parse_mode="HTML")
            except Exception: pass
        elif action == "cancel":
            await set_linkpay_status(oid, "cancelled")
            try:
                await bot.send_message(uid, f"❌ <b>Заказ отменён</b>\n\n📦 {svc}\n\nЕсли это ошибка — напиши @{PERSONAL_USERNAME}.", parse_mode="HTML")
            except Exception: pass
        elif action == "clarify":
            txt = str(body.get("text") or "Уточните, пожалуйста, детали заказа.")
            try:
                from db import add_order_msg
                await add_order_msg(oid, "admin", txt)
            except Exception: pass
            try:
                _rkb = InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="✍️ Ответить", callback_data=f"cl_reply:{oid}")]])
                await bot.send_message(uid, f"✍️ <b>Сообщение от Александра по заказу:</b>\n\n{__import__('html').escape(txt)}\n\nНажми «Ответить», чтобы написать в ответ (например, прислать код).", parse_mode="HTML", reply_markup=_rkb)
            except Exception: pass
        else:
            return web.json_response({"ok": False, "msg": "Неизвестное действие"})
        return web.json_response({"ok": True})
    except Exception as _e:
        logging.error(f"api_admin_order_action: {_e}")
        return web.json_response({"ok": False}, status=500)


async def api_admin_order_thread_handler(request: web.Request) -> web.Response:
    """История заказа (переписка) для Mini App. Admin-only."""
    try:
        try: body = await request.json()
        except Exception: body = {}
        if _admin_uid_from_body(body) != ADMIN_ID:
            return web.json_response({"ok": False}, status=403)
        oid = str(body.get("id", ""))
        order = await get_linkpay_order(oid) or {}
        from db import get_order_thread
        msgs = await get_order_thread(oid)
        out = []
        for m in msgs:
            ts = m.get("created_at")
            out.append({"sender": m["sender"], "text": m.get("text") or "",
                        "date": ts.astimezone(_BOT_TZ).strftime("%d.%m %H:%M") if ts else ""})
        u = await get_user(order.get("user_id")) if order.get("user_id") else None
        tag = ("@" + u["username"]) if (u and u.get("username")) else (("id" + str(order.get("user_id"))) if order.get("user_id") else "—")
        _cr = order.get("created_at")
        _cr_s = _cr.astimezone(_BOT_TZ).strftime("%d.%m.%Y %H:%M") if _cr else ""
        return web.json_response({"ok": True, "order": {
            "id": oid,
            "service": order.get("service_name", ""), "plan": order.get("plan_name") or "",
            "status": order.get("status", ""), "user": tag, "amount": int(order.get("amount_rub") or 0),
            "kind": order.get("kind") or "", "uid": order.get("user_id"), "date": _cr_s,
            "email": order.get("account_email") or "", "passw": order.get("account_pass") or "",
            "link": order.get("payment_link") or ""},
            "messages": out})
    except Exception as _e:
        logging.error(f"api_admin_order_thread: {_e}")
        return web.json_response({"ok": False}, status=500)


