async def api_admin_add_codes_handler(request: web.Request) -> web.Response:
    try:
        try: body = await request.json()
        except Exception: body = {}
        if _admin_uid_from_body(body) != ADMIN_ID:
            return web.json_response({"ok": False}, status=403)
        import re as _re_c
        service = str(body.get("service", ""))
        plan = str(body.get("plan", "") or ("plus" if service == "chatgpt" else "pro"))
        raw = str(body.get("codes", ""))
        # Разбираем ввод максимально терпимо:
        #  • разделители — перенос строки, пробел, запятая, точка с запятой, таб;
        #  • код может быть прислан ССЫЛКОЙ вида https://site/?code=XXXX — достаём code;
        #  • код может начинаться с цифры и содержать _ (старое правило требовало букву
        #    в начале и роняло часть кодов «в никуда»);
        #  • дубликаты внутри одной вставки схлопываем.
        _tokens = [t for t in _re_c.split(r"[\s,;]+", raw.strip()) if t]
        lines = []
        for _t in _tokens:
            _m_url = _re_c.search(r"[?&]code=([A-Za-z0-9\-_]+)", _t)
            lines.append(_m_url.group(1) if _m_url else _t)
        rx = _re_c.compile(r"^[A-Za-z0-9][A-Za-z0-9\-_]{5,}$")
        _seen_batch = set(); _uniq = []
        for _c in lines:
            if _c not in _seen_batch:
                _seen_batch.add(_c); _uniq.append(_c)
        _dupe_in_batch = len(lines) - len(_uniq)
        valid = [c for c in _uniq if rx.match(c)]
        if service not in ("chatgpt", "claude", "perplexity"):
            return web.json_response({"ok": False, "msg": "Неизвестный сервис"})
        if not valid:
            return web.json_response({"ok": False, "msg": "Нет валидных кодов"})
        # Claude и ChatGPT: коды тегируются сайтом-провайдером (у каждого свой пул).
        # Берём provider из запроса, иначе — текущий активный сайт из настроек.
        if service == "claude":
            _reg, _set, _def = CLAUDE_PROVIDERS, "claude", CLAUDE_DEFAULT_PROVIDER
        elif service == "chatgpt":
            _reg, _set, _def = GPT_PROVIDERS, "gpt", GPT_DEFAULT_PROVIDER
        else:
            _reg, _set, _def = None, None, None
        _provider = str(body.get("provider", "") or "").strip()
        if _reg is not None and _provider not in _reg:
            _provider = (await get_setting(f"{_set}_provider", _def) or _def)
            if _provider not in _reg:
                _provider = _def
        # ChatGPT: не даём залить коды в пул отключённого сайта — оттуда их
        # никогда не выдадут (в настройке мог остаться старый 987ai).
        if service == "chatgpt":
            _provider = gpt_enabled_provider(_provider)
        pool = await get_pool()
        added = 0
        dupes = 0            # уже были в базе (ON CONFLICT DO NOTHING) — раньше молча считались добавленными
        _dupe_list = []      # примеры дублей, чтобы админ мог сверить
        _bad_list = [c for c in _uniq if c not in valid][:10]
        async with pool.acquire() as conn:
            for c in valid:
                try:
                    if service == "chatgpt":
                        _res = await conn.execute("INSERT INTO gpt_codes (code, plan, provider) VALUES ($1,$2,$3) ON CONFLICT (code) DO NOTHING", c, plan, _provider)
                    elif service == "claude":
                        _res = await conn.execute("INSERT INTO claude_codes (code, plan, provider) VALUES ($1,$2,$3) ON CONFLICT (code) DO NOTHING", c, plan, _provider)
                    else:
                        _res = await conn.execute("INSERT INTO perplexity_codes (code, plan) VALUES ($1,$2) ON CONFLICT (code) DO NOTHING", c, plan)
                    # asyncpg возвращает 'INSERT 0 1' при вставке и 'INSERT 0 0' при конфликте
                    if isinstance(_res, str) and _res.strip().endswith(" 0"):
                        dupes += 1
                        if len(_dupe_list) < 10:
                            _dupe_list.append(c)
                    else:
                        added += 1
                except Exception as _e_ins:
                    dupes += 1
                    if len(_dupe_list) < 10:
                        _dupe_list.append(c)
                    logging.warning(f"add-codes insert {c}: {_e_ins}")
        _msg = {"ok": True, "added": added, "dupes": dupes,
                "skipped": len(_uniq) - len(valid), "dupInBatch": _dupe_in_batch,
                "dupeList": _dupe_list, "badList": _bad_list, "total": len(lines)}

        # Сразу спрашиваем сайт, целы ли залитые коды. Код, пришедший в пул уже
        # потраченным, иначе всплывёт только у клиента в момент активации — и
        # будет выглядеть как поломка бота, хотя вопрос к поставщику.
        # Проверяем ВСЕ присланные (valid), а не только новые: если код уже был
        # в базе, знать его состояние тем более нужно.
        # Проверяем не больше 300 за раз: страница сайта столько и принимает,
        # а на большой партии несколько запросов подряд подвесили бы ответ
        # панели. Остальное досмотрит /gpt_check_pool.
        _chk_list = valid[:300]
        _chk_rest = len(valid) - len(_chk_list)
        if _chk_list and (service != "chatgpt" or _provider == "bpa"):
            try:
                from chatgpt_activation import bpa_query_codes, BPA_FREE_STATUSES
                _q = await bpa_query_codes(_chk_list)
                _tbl_chk = {"chatgpt": "gpt_codes", "claude": "claude_codes",
                            "perplexity": "perplexity_codes"}[service]
                _spent_new, _okn = [], 0
                for _c in _chk_list:
                    _i = _q.get(_c.strip().upper()) or {}
                    _v = _i.get("status", "")
                    if not _v:
                        continue                 # сайт промолчал — не трогаем
                    if _v in BPA_FREE_STATUSES:
                        _okn += 1
                        continue
                    _spent_new.append({"code": _c, "status": _v,
                                       "email": _i.get("email", ""),
                                       "when": _i.get("when", "")})
                if _spent_new:
                    async with pool.acquire() as _cn3:
                        for _r3 in _spent_new:
                            try:
                                await _cn3.execute(
                                    f"UPDATE {_tbl_chk} SET check_status='error', "
                                    f"last_checked_at=NOW(), flagged_reason=$2 "
                                    f"WHERE code=$1",
                                    _r3["code"],
                                    f"при загрузке: {_r3['status']} — пришёл уже потраченным")
                            except Exception as _e_f3:
                                logging.warning(f"add-codes флаг {_r3['code']}: {_e_f3}")
                    logging.warning(
                        f"add-codes: {len(_spent_new)} из {len(_chk_list)} пришли "
                        f"уже потраченными ({service})")
                _msg["checked"] = len(_q)
                _msg["checkedOk"] = _okn
                _msg["spent"] = _spent_new
                _msg["checkRest"] = _chk_rest
            except Exception as _e_q:
                logging.warning(f"add-codes проверка на сайте: {_e_q}")
        if service in ("claude", "chatgpt"):
            _msg["provider"] = _provider
        if service == "chatgpt":
            # Остатки по маршрутам после заливки — чтобы сразу видеть, чего мало.
            # Маршрут проставляет триггер в БД по префиксу кода, руками его не
            # задают: иначе появился бы способ ошибиться и сломать защиту.
            try:
                async with pool.acquire() as _c_rt:
                    _rt_rows = await _c_rt.fetch(
                        "SELECT COALESCE(route,'') AS route, plan, COUNT(*) AS n "
                        "FROM gpt_codes WHERE is_used=FALSE AND provider=$1 "
                        "AND COALESCE(check_status,'unchecked') NOT IN ('used','invalid') "
                        "GROUP BY COALESCE(route,''), plan ORDER BY route, plan",
                        _provider)
                _msg["routes"] = [
                    {"route": r["route"],
                     "label": GPT_ROUTE_LABELS.get(r["route"], "без маршрута"),
                     "plan": r["plan"], "free": int(r["n"])} for r in _rt_rows]
            except Exception as _e_rt:
                logging.warning(f"add-codes routes: {_e_rt}")
            _msg["noRoute"] = [c for c in valid if not gpt_route_for_code(c)][:10]
        return web.json_response(_msg)
    except Exception as _e:
        logging.error(f"api_admin_add_codes: {_e}")
        return web.json_response({"ok": False}, status=500)


async def api_admin_release_codes_handler(request: web.Request) -> web.Response:
    """Возврат кодов в пул: снимает пометку «использован» у перечисленных кодов.
    Нужно, если код ошибочно сожжён (напр. ложное «уже использован»). Admin-only.
    Разбор ввода такой же терпимый, как в add-codes (ссылки/пробелы/цифры)."""
    try:
        try: body = await request.json()
        except Exception: body = {}
        if _admin_uid_from_body(body) != ADMIN_ID:
            return web.json_response({"ok": False}, status=403)
        import re as _re_r
        service = str(body.get("service", ""))
        _tbl = {"chatgpt": "gpt_codes", "claude": "claude_codes",
                "perplexity": "perplexity_codes"}.get(service)
        if not _tbl:
            return web.json_response({"ok": False, "msg": "Неизвестный сервис"})
        raw = str(body.get("codes", ""))
        _tokens = [t for t in _re_r.split(r"[\s,;]+", raw.strip()) if t]
        codes = []
        for _t in _tokens:
            _m = _re_r.search(r"[?&]code=([A-Za-z0-9\-_]+)", _t)
            codes.append(_m.group(1) if _m else _t)
        codes = list(dict.fromkeys([c for c in codes if c]))   # уникальные, порядок сохранён
        if not codes:
            return web.json_response({"ok": False, "msg": "Нет кодов"})
        pool = await get_pool()
        async with pool.acquire() as conn:
            if _tbl == "gpt_codes":
                _res = await conn.execute(
                    "UPDATE gpt_codes SET is_used=FALSE, used_by=NULL, used_at=NULL, order_id=NULL "
                    "WHERE code = ANY($1::text[])", codes)
            elif _tbl == "claude_codes":
                _res = await conn.execute(
                    "UPDATE claude_codes SET is_used=FALSE, used_by=NULL, used_at=NULL, order_id=NULL, org_id=NULL "
                    "WHERE code = ANY($1::text[])", codes)
            else:
                _res = await conn.execute(
                    "UPDATE perplexity_codes SET is_used=FALSE, used_by=NULL, used_at=NULL "
                    "WHERE code = ANY($1::text[])", codes)
        _released = int(_res.split()[-1]) if isinstance(_res, str) and _res.split()[-1].isdigit() else 0
        return web.json_response({"ok": True, "released": _released, "total": len(codes)})
    except Exception as _e:
        logging.error(f"api_admin_release_codes: {_e}")
        return web.json_response({"ok": False}, status=500)


# ── Одна рассылка за раз ────────────────────────────────────────────────
# Две рассылки, идущие одновременно, — это сообщение ДВАЖДЫ каждому клиенту.
# Защита от дублей внутри одной рассылки (таблица broadcast_sent) тут не
# спасает: у второго запуска свой номер, и он честно обходит весь список
# заново. 20.09.2026 клиенты получили рассылку дважды с разницей в минуту
# именно так — из мини-аппа запрос ушёл два раза.
_BC_LOCK = {"busy": False, "started": 0.0, "fp": "", "fp_at": 0.0}


def broadcast_claim(fingerprint: str = "") -> str:
    """Занимает право на рассылку. Пустая строка — можно, иначе причина отказа.

    Два рубежа:
      • busy  — прямо сейчас рассылка уже идёт;
      • fp    — такую же рассылку запускали меньше 15 минут назад. Это про
                повторный запрос с тем же содержимым: второй тап по кнопке,
                ретрай мини-аппа на плохой связи, дубль апдейта от Telegram.
    Функция синхронная и без await намеренно: внутри одного цикла событий её
    нельзя «переложить» между двумя параллельными запросами, а значит гонки
    двух нажатий здесь не существует.
    """
    import time as _t_bl
    _now = _t_bl.time()
    # Зависший захват (процесс упал, finally не отработал) отпускаем сами.
    if _BC_LOCK["busy"] and _now - _BC_LOCK["started"] > 7200:
        logging.warning("broadcast: снимаю зависший замок (больше 2 часов)")
        _BC_LOCK["busy"] = False
    if _BC_LOCK["busy"]:
        return "рассылка уже идёт"
    if fingerprint and fingerprint == _BC_LOCK["fp"] and _now - _BC_LOCK["fp_at"] < 900:
        return "точно такая же рассылка запускалась меньше 15 минут назад"
    _BC_LOCK.update({"busy": True, "started": _now})
    if fingerprint:
        _BC_LOCK.update({"fp": fingerprint, "fp_at": _now})
    return ""


def broadcast_release() -> None:
    """Отпускает замок. Отпечаток НЕ сбрасываем — он и должен пережить
    окончание рассылки, иначе повтор сразу после неё снова пройдёт."""
    _BC_LOCK["busy"] = False


async def api_admin_broadcast_handler(request: web.Request) -> web.Response:
    try:
        try: body = await request.json()
        except Exception: body = {}
        if _admin_uid_from_body(body) != ADMIN_ID:
            return web.json_response({"ok": False}, status=403)
        text = str(body.get("text", "")).strip()
        if not text:
            return web.json_response({"ok": False, "msg": "Пустой текст"})
        pool = await get_pool()

        # Здесь была ВТОРАЯ, независимая рассылка: без номера, без отметок о
        # доставке, без защиты от повторного запуска и на send_message вместо
        # copy_message — то есть фото и видео из мини-аппа не уходили вовсе.
        # Любой повтор запроса (второй тап, ретрай на плохой связи) запускал
        # полный проход по всем ещё раз: 20.09.2026 клиенты получили рассылку
        # дважды с разницей в минуту.
        #
        # Теперь мини-апп пользуется тем же движком, что и админка в боте:
        # текст сначала уходит Александру (он видит ровно то, что получат
        # клиенты), а дальше копируется всем — с отметкой по каждому,
        # переживанием флуд-лимита и возможностью дослать после обрыва.
        # Аудитория из мини-аппа. Проверяем по справочнику движка, а не
        # доверяем строке из браузера: неизвестное значение молча превратилось
        # бы в «всем», и рассылка для клиентов одного партнёра ушла бы всей базе.
        from handlers_admin import BC_AUDIENCES, bc_audience_name
        _aud = str(body.get("audience") or "all")
        if _aud not in BC_AUDIENCES:
            return web.json_response({"ok": False, "msg": "Неизвестная аудитория"})
        try:
            _pid = int(body.get("partnerId") or 0)
        except Exception:
            _pid = 0
        if BC_AUDIENCES[_aud][2] and not _pid:
            return web.json_response({"ok": False, "msg": "Не указан партнёр"})
        _ptag = ""
        if _pid:
            _pu = await get_user(_pid)
            import html as _h_pt
            _ptag = ("@" + (_pu or {}).get("username", "")) if (_pu or {}).get("username") \
                else _h_pt.escape(strip_surrogates((_pu or {}).get("full_name") or "")) \
                or f"id{_pid}"

        _, _w_bc, _needs_bc = BC_AUDIENCES[_aud]
        _sql_bc = "SELECT COUNT(*) FROM users WHERE is_blocked=0 " + _w_bc
        async with pool.acquire() as conn:
            _cnt = (await conn.fetchval(_sql_bc, _pid) if _needs_bc
                    else await conn.fetchval(_sql_bc)) or 0
        if not _cnt:
            return web.json_response({"ok": False, "msg": "В этой аудитории никого нет"})

        import hashlib as _hl_bc
        _fp = ("webapp:" + _aud + ":" + str(_pid) + ":"
               + _hl_bc.sha256(text.encode("utf-8")).hexdigest()[:16])
        _why = broadcast_claim(_fp)
        if _why:
            logging.warning(f"broadcast(webapp): запуск отклонён — {_why}")
            return web.json_response({"ok": False, "msg": "Не запускаю: " + _why})
        try:
            _src = await bot.send_message(ADMIN_ID, text, parse_mode="HTML")
        except Exception as _e_src:
            broadcast_release()
            logging.error(f"broadcast(webapp): образец не отправился: {_e_src}")
            return web.json_response({"ok": False, "msg": "Не смог отправить образец себе"})
        from handlers_admin import _do_broadcast
        asyncio.create_task(_do_broadcast(ADMIN_ID, _src.message_id, None, _src,
                                          claimed=True, audience=_aud,
                                          partner_id=_pid, partner_tag=_ptag))
        return web.json_response({"ok": True, "count": int(_cnt),
                                  "audience": bc_audience_name(_aud, _pid, _ptag)})
    except Exception as _e:
        logging.error(f"api_admin_broadcast: {_e}")
        return web.json_response({"ok": False}, status=500)

def _pack_shop(key, idx, plan_name: str = "") -> str:
    """Строка заказа для колонки pack: shop:КЛЮЧ:ИНДЕКС:ИМЯ_ТАРИФА.

    Четвёртый сегмент — СНИМОК имени тарифа на момент покупки. Раньше в
    заказе жил только позиционный индекс в каталоге, и стоило удалить более
    ранний тариф, как индексы съезжали: оплаченный заказ выдавал уже другой
    товар по старой цене. Внешний аудит 29.09.2026.

    Старые парсеры читают [1] и [2] и продолжают работать. Двоеточие из
    имени убираем, чтобы не разъехалась разбивка.
    """
    _nm = str(plan_name or "").replace(":", " ").strip()
    return f"shop:{key}:{idx}" + (f":{_nm}" if _nm else "")


def _plan_by_order(shop_key: str, plan_idx: int, plan_name: str = ""):
    """Возвращает (сервис, тариф) для заказа: сперва по ИМЕНИ, потом по индексу.

    Имя — то, что клиент реально купил. Индекс остаётся запасным путём для
    заказов, созданных до появления четвёртого сегмента.
    """
    _s = SHOP_CATALOG.get(shop_key, {}) or {}
    _plans = _s.get("plans", []) or []
    _nm = str(plan_name or "").strip()
    if _nm:
        for _p in _plans:
            if str(_p.get("name", "")).strip() == _nm:
                return _s, _p
        # Имя в заказе есть, а такого тарифа в каталоге больше нет — значит
        # его удалили после оформления счёта. Брать «того, кто теперь стоит
        # под этим номером» НЕЛЬЗЯ: клиент оплатил одно, а получил бы другое.
        # Возвращаем пусто — вызывающий отправит заказ на ручную выдачу.
        # Повторный внешний аудит 29.09.2026, пункт №9.
        logging.warning(f"заказ: тариф {_nm!r} у {shop_key!r} исчез из каталога — "
                        f"подбирать замену по индексу {plan_idx} не буду")
        return _s, {}
    # Имени нет — это заказ, созданный до появления имени в pack. Для него
    # индекс остаётся единственным, что есть.
    return _s, (_plans[plan_idx] if 0 <= plan_idx < len(_plans) else {})


def _pack_plan_name(pack: str) -> str:
    """Имя тарифа из pack (4-й сегмент). Пусто — старый заказ."""
    _pp = str(pack or "").split(":")
    return _pp[3].strip() if len(_pp) > 3 else ""


async def _admin_fail_shot(text, screenshot=None, order_id=None):
    """Шлёт админу текст о сбое и, если есть, скриншот сайта отдельным фото.

    Возвращает message_id отправленного текста (или None) — чтобы сообщение
    можно было потом отредактировать, когда ситуация разрешится.
    """
    _mid = None
    try:
        _m = await bot.send_message(ADMIN_ID, text, parse_mode="HTML")
        _mid = getattr(_m, "message_id", None)
    except Exception:
        try:
            _m = await bot.send_message(ADMIN_ID, text)
            _mid = getattr(_m, "message_id", None)
        except Exception:
            pass
    # Запоминаем сообщение о сбое по заказу: если активация всё-таки
    # состоится — сама или сверкой — оно перепишется в «прошла», а не
    # останется висеть неправдой. Александр попросил 23.09.2026, увидев
    # «не помог и iOS-маршрут» по коду, который сайт как раз дозавершал.
    if _mid and order_id:
        try:
            await set_setting(f"gpt_confirm_msg:{order_id}", str(_mid))
        except Exception as _e_fs:
            logging.warning(f"gpt confirm msg id: {_e_fs}")
    if screenshot:
        try:
            from aiogram.types import BufferedInputFile
            await bot.send_photo(
                ADMIN_ID,
                BufferedInputFile(screenshot, filename="activation.png"),
                caption="📸 Экран сайта активации")
        except Exception as _se:
            logging.warning(f"send fail screenshot: {_se}")
    return _mid


_SAFE_REL_ALERT_AT = 0.0      # когда последний раз сообщали про невозврат


async def gpt_activation_already_done(code: str, user_id: int,
                                      order_id: str = "") -> bool:
    """Записана ли уже эта активация — кем-то другим, пока мы работали.

    Активация клиента и сверка идут параллельно и могут прийти к финишу в
    разном порядке. Сверка узнаёт об успехе от сайта и закрывает заказ; задача
    активации в это время ещё висит и, добравшись до конца, объявляет неудачу
    по уже закрытому заказу — с криком в чат и «не удалось» клиенту, у которого
    подписка работает.

    Признак «уже записано» один и надёжный: код закреплён ЗА ЭТИМ клиентом и
    привязан к заказу. Это делает только запись активации — ни перебор, ни
    отказ такого не оставляют.
    """
    _c = (code or "").strip().upper()
    if not _c or not user_id:
        return False
    pool = await get_pool()
    async with pool.acquire() as conn:
        _r = await conn.fetchrow(
            "SELECT used_by, order_id FROM gpt_codes WHERE UPPER(code)=$1", _c)
        if _r and _r["used_by"] and int(_r["used_by"]) == int(user_id) \
                and (_r["order_id"] or ""):
            return True
        if order_id:
            # Тот же заказ мог закрыться ДРУГИМ кодом (перебор, ручная выдача).
            # Клиенту подписка уже записана — второй раз объявлять неудачу не о чем.
            _n = await conn.fetchval(
                "SELECT COUNT(*) FROM gpt_codes WHERE order_id=$1 AND used_by=$2",
                order_id, int(user_id)) or 0
            if _n:
                return True
    return False


def _gpt_fail_why(result: dict, code: str = "") -> str:
    """Техническая причина отказа — строкой для сообщения админу.

    Раньше в чат уходил только человеческий текст сайта («Покупку завершить
    не удалось»), по которому нельзя понять ни что сломалось, ни что делать.
    Технические поля при этом БЫЛИ: HTTP-код и error_code при отказе на
    /api/gpt/activate, provider_status у GET /api/gpt/orders/{id}, статус
    самого кода на /query. Бот их читал и выбрасывал.

    Собираем всё, что есть, в одну строку. Пусто — значит сайт не дал ничего,
    кроме текста; тогда строки в сообщении просто не будет.
    """
    if not isinstance(result, dict):
        return ""
    _p = []
    _http, _ec = result.get("http"), str(result.get("error_code") or "").strip()
    if _http:
        _p.append(f"HTTP {_http}" + (f" · <code>{_ec}</code>" if _ec else ""))
    elif _ec:
        _p.append(f"<code>{_ec}</code>")
    for _k, _label in (("order_status", "заказ"), ("provider_status", "провайдер"),
                       ("site_status", "код на сайте")):
        _v = str(result.get(_k) or "").strip()
        if _v:
            _p.append(f"{_label}: <code>{_v}</code>")
    if code:
        _rt = gpt_route_for_code(code)
        if _rt:
            _p.append("маршрут: " + GPT_ROUTE_LABELS.get(_rt, _rt))
    # Флаги решают, что бот сделает дальше, — их стоит видеть рядом с причиной.
    _flags = [_f for _f in ("code_already_used", "wrong_account", "token_invalid",
                            "has_plan", "out_of_stock", "site_paused",
                            "site_claimed", "openai_blocked", "needs_check",
                            "site_payment_failed")
              if result.get(_f)]
    if _flags:
        _p.append("признаки: " + ", ".join(_flags))
    _oid = str(result.get("order_id") or "").strip()
    if _oid:
        _p.append(f"заказ сайта: <code>{_oid}</code>")
    return ("\U0001f50e <b>Причина:</b> " + " \u00b7 ".join(_p) + "\n") if _p else ""


async def _who_user(uid) -> str:
    """«@ник (id)» для сообщений админу.

    Ник у бота есть всегда — он лежит в users с первого /start. Но в
    сообщениях его подставляли руками и не везде: в одних был «@ник», в
    других голый номер, и по такому сообщению нельзя ни написать клиенту,
    ни узнать его в переписке, не идя в базу. Один помощник на все случаи.
    """
    try:
        _u = await get_user(int(uid))
    except Exception:
        _u = None
    _n = ((_u or {}).get("username") or "").strip()
    if _n:
        # Юзернейм Telegram — только буквы, цифры и подчёркивание, экранировать
        # нечего. А вот ИМЯ пользователь пишет какое угодно.
        return f"@{_n} (<code>{uid}</code>)"
    _f = ((_u or {}).get("full_name") or "").strip()
    if _f:
        # ОБЯЗАТЕЛЬНО экранируем. В имени Telegram допускает < > &, а все
        # сообщения админу уходят с parse_mode=HTML: одна угловая скобка в
        # имени клиента — и Telegram отклоняет ВСЁ сообщение целиком
        # («can't parse entities»). Отправка обёрнута в try/except, поэтому
        # уведомление просто не пришло бы, молча. strip_surrogates от этого
        # не спасает: он чистит суррогаты, а не разметку.
        import html as _h_wu
        return f"{_h_wu.escape(strip_surrogates(_f))} (<code>{uid}</code>)"
    return f"<code>{uid}</code>"


async def _run_activation_job(
    job_id: str, code: str, access_token: str,
    user_id: int, order_id: str, plan_name: str,
    provider: str = "987ai", session_raw: str = "", force: bool = False
):
    """Фоновая задача: Playwright-активация. Не держит HTTP-соединение.
    provider: '987ai' (текущий, по access_token) | 'aipro' (6661231.xyz, по Session JSON).
    force=True — клиент подтвердил принудительную активацию поверх уже активной подписки."""
    async def _do_activate(_code):
        # Каждая попытка активации проходит ровно здесь. Пишем по строке в
        # журнал заказа: код, сайт, чем кончилось. Потом карточки показывают
        # «с какой попытки прошло и что мешало». Александр 04.10.2026.
        _res_at = await _do_activate_raw(_code)
        try:
            await _gpt_log_attempt(order_id, _code, provider, _res_at)
        except Exception as _e_at:
            logging.warning(f"журнал попыток {order_id}: {_e_at}")
        return _res_at

    async def _do_activate_raw(_code):
        if provider == "bpa":
            from chatgpt_activation import activate_chatgpt_bpa
            return await activate_chatgpt_bpa(_code, session_raw or access_token, force=force)
        if provider == "aipro":
            from chatgpt_activation import activate_chatgpt_aipro
            return await activate_chatgpt_aipro(_code, session_raw or access_token, force=force)
        if provider == "kkqq":
            from chatgpt_activation import activate_chatgpt_kkqq
            return await activate_chatgpt_kkqq(_code, session_raw or access_token, force=force)
        if provider == "redeem":
            from chatgpt_activation import activate_chatgpt_redeemgpt
            return await activate_chatgpt_redeemgpt(_code, session_raw or access_token, force=force)
        return await activate_chatgpt(_code, access_token)
    try:
        # ── Тестовый режим: код начинается с TEST → пропускаем Playwright ────
        if code.startswith("TEST-"):
            await asyncio.sleep(3)  # имитируем задержку активации
            await delete_pending_activation(user_id, order_id)
            _activation_jobs[job_id] = {"status": "done", "success": True}
            try:
                await bot.send_message(
                    ADMIN_ID,
                    f"🧪 <b>Тест активации завершён</b>\n"
                    f"👤 {await _who_user(user_id)} — тестовый код, нигде не записан.",
                    parse_mode="HTML"
                )
            except Exception:
                pass
            return
        # ─────────────────────────────────────────────────────────────────────
        result = await _do_activate(code)

        # ── Сайт на паузе: ждём и пробуем сами, тем же кодом ────────────────
        # 18.09.2026: сайт ответил «Service temporarily paused for maintenance.
        # Codes stay valid; retry later» — то есть сам попросил повторить. Бот
        # вместо этого объявил провал и увёл заказ в ручной режим, а клиента
        # ещё и заблокировал на несколько минут защитой от двойного запуска.
        # Клиент видел «не получилось» и не мог даже нажать заново.
        #
        # Повторяем ЗДЕСЬ, внутри той же задачи: замок на клиенте наш, значит
        # сам себе он не мешает, и лишних кодов из пула никто не возьмёт — код
        # тот же. Три попытки с паузой в минуту: если сайт чинят дольше, дальше
        # ждать бессмысленно, и тогда разбираемся как раньше.
        _paused_tries = 0
        while result.get("site_paused") and _paused_tries < 3:
            _paused_tries += 1
            logging.warning(
                f"GPT: сайт на паузе, попытка {_paused_tries}/3 через 60 с "
                f"(код {code}, клиент {user_id})")
            _activation_jobs[job_id] = {"status": "pending", "retrying": True}
            if _paused_tries == 1:
                try:
                    await bot.send_message(
                        user_id,
                        "⏳ <b>Активация на паузе — сайт активации на техобслуживании.</b>\n\n"
                        f"{_GPT_PAID_LINE}\n"
                        "👉 Ничего делать не нужно: это ненадолго, пробую сам каждую "
                        "минуту и напишу, как получится 🙌",
                        parse_mode="HTML")
                except Exception:
                    pass
            await asyncio.sleep(60)
            # Освежаем метку «активация идёт». Она считается протухшей через
            # 10 минут, а с тремя паузами по минуте и опросом сайта задача
            # легко живёт дольше. Протухни метка — клиент смог бы запустить
            # ВТОРУЮ активацию поверх работающей и забрать второй код: ровно
            # та беда, от которой этот замок и ставили.
            try:
                await claim_gpt_activation(user_id, stale_minutes=0)
            except Exception as _e_cl:
                logging.warning(f"GPT: не освежил метку активации {user_id}: {_e_cl}")
            result = await _do_activate(code)
        if _paused_tries and not result.get("site_paused"):
            logging.warning(
                f"GPT: сайт ожил после {_paused_tries} попыток (код {code})")

        _plan_key = plan_name_to_key(plan_name)
        # Ник клиента — один раз на всю задачу, дальше только подстановка.
        _who_u = await _who_user(user_id)
        # Контекст заказа для КАЖДОГО сообщения Александру по этой активации:
        # заказ и FreeKassa, оплата, сайт и маршрут кода, аккаунт клиента.
        # Александр 07.10.2026.
        async def _actx(_cd=None, show_site=True, show_route=True):
            return await _adm_gpt_ctx(order_id, _cd or code, provider,
                                      session_raw or access_token, show_site=show_site,
                                      show_route=show_route, uid=user_id)
        _gpt_used_codes = []        # все сожжённые использованные коды (для отчёта)
        _tried_sites = [provider]   # сайты, где уже пробовали
        # Почему перебор кодов прекратили ДОБРОВОЛЬНО. Пустая строка — не
        # прекращали. 19.09.2026: защита «сначала спроси сайт, потом жги»
        # остановила перебор на первом же коде, но флаг code_already_used в
        # result остался — и терминальная ветка объявила «коды закончились на
        # ВСЕХ сайтах» при полном пуле и НУЛЕ сожжённых кодов. Это два разных
        # события, и путать их нельзя: на одно надо докупать коды, на другое —
        # разбираться с сайтом.
        _burn_stop = {"why": ""}
        _switch_msg_id = None
        _switch_text = ""

        # Исход последнего возврата — чтобы сообщения не гадали, а писали
        # по факту: вернули / сайт ещё держит / застрял.
        _rel_last = {"state": "", "site": ""}

        def _rel_phrase(_ok: bool) -> str:
            """Фраза о судьбе кода — по факту возврата, а не по догадке.

            Раньше вариант был один на всё («НЕ вернулся — сайт не
            подтвердил»), и им подписывался в том числе случай, когда сайт
            как раз ответил вполне определённо: подписку по коду он выдал.
            """
            if _ok:
                return "код возвращён в пул"
            _s = _rel_last.get("site") or ""
            if _rel_last.get("state") == "awaiting":
                return (f"сайт ещё держит его ({_s}) — верну в пул сам, "
                        f"как освободится")
            if _s in ("fulfilled", "zoom_token_ready"):
                return f"код потрачен: сайт выдал по нему подписку ({_s})"
            return ("код в пул НЕ вернулся — сайт не подтвердил, что он цел; "
                    "проверь <code>/gpt_codes_recover</code>")

        async def _safe_release(_c, dead_reason: str = ""):
            """Возврат кода в пул ТОЛЬКО с подтверждением сайта.

            Активация могла провалиться на нашей стороне, пока у сайта заказ по
            этому коду ещё жив: он спокойно доводит его до конца через часы.
            Прежний безусловный возврат отдавал такой код следующему клиенту —
            тот получал «код уже использован», код сжигался, и цикл шёл дальше.
            Так 10.09.2026 за минуту ушло пять кодов, и каждый из них сайт
            активировал позже, на СВОЙ аккаунт.

            Спрашиваем ровно про один код — это дёшево. Сказал unused — вернём.
            Сказал что-то другое или промолчал — оставляем за клиентом и метим:
            решение о судьбе кода принимает Александр, а не догадка.
            """
            # Если активация уже записана (сверка нас обогнала) — код и должен
            # остаться за клиентом, и тревожить незачем: «не вернул в пул»
            # звучит как проблема, а это ровно правильный исход.
            _rel_last["state"], _rel_last["site"] = "", ""
            try:
                if await gpt_activation_already_done(_c, user_id, order_id):
                    logging.info(f"_safe_release: {_c} — активация уже записана, молчу")
                    return False
            except Exception:
                pass
            _free_st = ("unused",)      # запас на случай, если импорт упадёт:
            _v = ""                     # иначе ниже был бы NameError и код
            try:                        # молча не вернулся бы вообще
                from chatgpt_activation import bpa_query_codes, BPA_FREE_STATUSES
                _free_st = BPA_FREE_STATUSES
                _q = await bpa_query_codes([_c])
                _v = (_q.get((_c or "").strip().upper()) or {}).get("status", "")
            except Exception as _e_sr:
                logging.warning(f"_safe_release {_c}: {_e_sr}")
                _v = ""
            _rel_last["site"] = _v
            if _v in _free_st:
                await release_gpt_code(_c)
                _rel_last["state"] = "released"
                return True
            # Исключение ровно на один случай: САЙТ САМ объявил заказ мёртвым и
            # написал, что списания, hold и подписки нет (failed_precharge).
            # Тогда молчание /query — это не «заказ ещё жив», а «кода в таблице
            # нет, потому что он и не тратился»: филиппинские коды там не
            # показываются вовсе. Держать такой код за клиентом значит терять
            # его на ровном месте — ровно об этом Александр написал 23.09.2026.
            # Ограничение жёсткое: любой «использованный» статус сайта (claimed
            # / fulfilled / zoom_token_ready) отменяет исключение — там заказ
            # действительно может дозреть позже.
            try:
                from chatgpt_activation import BPA_USED_STATUSES as _USED_SR
            except Exception:
                _USED_SR = ("claimed", "fulfilled", "zoom_token_ready")
            if dead_reason and _v not in _USED_SR:
                await release_gpt_code(_c)
                _rel_last["state"] = "released"
                logging.warning(
                    f"_safe_release: {_c} возвращён в пул — {dead_reason}; "
                    f"/query ответил: {_v or 'молчит'}")
                return True
            # Сайт признал заказ мёртвым, но код ещё держит в «claimed». Это
            # не «код потрачен»: claimed — промежуточное состояние, и после
            # провалившегося заказа сайт через несколько минут сам вернёт код
            # в «unused». Отдавать его следующему клиенту ПРЯМО СЕЙЧАС нельзя
            # (claimed может дозреть до fulfilled — так 10.09.2026 ушло пять
            # кодов), но и бросать нельзя: ни одна фоновая задача помеченные
            # коды не подбирает. Помечаем особой меткой — её ждёт
            # gpt_dead_order_release_loop: он переспрашивает сайт каждые 10
            # минут и возвращает код в пул сам, как только тот освободится.
            # Ждать освобождения имеет смысл ТОЛЬКО для «claimed» — это и есть
            # промежуточное состояние. «fulfilled» / «zoom_token_ready» значат,
            # что сайт подписку ВЫДАЛ: код потрачен, ждать нечего, а само
            # сочетание «заказ failed, а код fulfilled» — противоречие сайта,
            # и звать Александра надо сразу, а не через десять минут.
            _await_free = bool(dead_reason and _v == "claimed")
            _site_spent = bool(dead_reason and _v in _USED_SR and not _await_free)
            _rel_last["state"] = "awaiting" if _await_free else "stuck"
            _pool_sr = await get_pool()
            async with _pool_sr.acquire() as _cn_sr:
                await _cn_sr.execute(
                    "UPDATE gpt_codes SET check_status='error', last_checked_at=NOW(), "
                    "flagged_reason=$2 WHERE code=$1",
                    _c,
                    (f"ждём освобождения: сайт держит {_v} после отказа ({dead_reason})"
                     if _await_free else
                     f"сайт выдал подписку ({_v}), хотя заказ провалился"
                     if _site_spent else
                     f"не возвращён в пул: сайт ответил {_v or '(молчит)'}"))
            if _await_free:
                logging.warning(
                    f"_safe_release: {_c} — сайт держит {_v} после отказа "
                    f"({dead_reason}); поставлен в очередь на авто-возврат.")
            logging.warning(
                f"_safe_release: {_c} НЕ возвращён в пул — сайт: {_v or 'молчит'}")
            # Если сайт лежит, таких кодов будет много подряд — не заваливаем
            # админа одинаковыми сообщениями, одного в 15 минут достаточно.
            # Код в «claimed» с ЖИВЫМ резервом: сверка возьмёт его на слежение,
            # а следом уйдёт карточка «авто-активация НЕУДАЧА» с тем же кодом,
            # тем же клиентом и кнопкой «Проверить сейчас». Отдельное сообщение
            # здесь — третий рассказ об одном событии, да ещё и с советом
            # /gpt_codes_recover, который делать не надо. Пометку на коде
            # оставляем: именно она защищает пул. Александр 02.10.2026.
            if _v == "claimed":
                _has_pend_sr = False
                try:
                    async with _pool_sr.acquire() as _c_pc:
                        _has_pend_sr = bool(await _c_pc.fetchval(
                            "SELECT 1 FROM gpt_pending_activations "
                            "WHERE UPPER(code)=$1", str(_c).strip().upper()))
                except Exception as _e_pc:
                    logging.warning(f"_safe_release: резерв по {_c}: {_e_pc}")
                if _has_pend_sr:
                    # НЕ просто молчим. Между этим местом и отправкой карточки
                    # «НЕУДАЧА» — одиннадцать точек выхода из задачи, то есть
                    # карточка приходит НЕ всегда, и молчание оставило бы
                    # Александра вообще без сообщения. Поэтому ставим код на
                    # слежение: оно гарантированно скажет «активация идёт» в
                    # течение минуты, и текст там полезнее, чем «код не вернул
                    # в пул» с советом /gpt_codes_recover, который тут вреден.
                    # Нашёл при самопроверке 02.10.2026.
                    try:
                        _k_sr = f"gptclaim:{str(_c).strip().upper()}"
                        if not (await get_setting(_k_sr, "") or "").strip():
                            import time as _t_sr2
                            await set_setting(
                                _k_sr,
                                f"{user_id}|{order_id or ''}|{int(_t_sr2.time())}|")
                    except Exception as _e_sr2:
                        logging.warning(f"_safe_release: слежение за {_c}: {_e_sr2}")
                    logging.info(f"_safe_release: {_c} в claimed — поставил на "
                                 f"слежение, отдельное сообщение не шлю.")
                    return False
            global _SAFE_REL_ALERT_AT
            import time as _t_sr
            if _t_sr.time() - _SAFE_REL_ALERT_AT < 900:
                return False
            _SAFE_REL_ALERT_AT = _t_sr.time()
            try:
                await bot.send_message(
                    ADMIN_ID,
                    (f"⏳ <b>Код вернётся в пул сам</b>\n"
                     f"🔑 <code>{_c}</code> · сайт держит: <b>{_v}</b>\n"
                     f"👤 {_who_u} · {plan_name}\n{await _actx(_c)}\n"
                     f"Заказ сайт признал мёртвым, но код ещё в «{_v}». Это "
                     f"промежуточное состояние: после провалившегося заказа "
                     f"сайт сам вернёт код в «unused». Буду переспрашивать "
                     f"каждые 10 минут и верну в пул, как освободится. "
                     f"Делать ничего не нужно."
                     if _await_free else
                     f"⚠️ <b>Сайт противоречит сам себе</b>\n"
                     f"🔑 <code>{_c}</code> · заказ провалился, а код <b>{_v}</b>\n"
                     f"👤 {_who_u} · {plan_name}\n{await _actx(_c)}\n"
                     f"«{_v}» значит, что подписку по этому коду сайт ВЫДАЛ. "
                     f"Возможно, она уже у клиента — проверь заказ, могли уйти "
                     f"две. Код потрачен, в пул не вернул."
                     if _site_spent else
                     f"🔒 <b>Код не вернул в пул</b>\n"
                     f"🔑 <code>{_c}</code> · сайт: <b>{_v or 'не ответил'}</b>\n"
                     f"👤 {_who_u} · {plan_name}\n{await _actx(_c)}\n"
                     f"Активация у нас не удалась, но у сайта заказ по этому коду "
                     f"может быть ещё жив — вернуть его в пул значит отдать "
                     f"следующему клиенту уже потраченный. Проверь: "
                     f"<code>/gpt_codes_recover</code>"),
                    parse_mode="HTML")
            except Exception:
                pass
            return False

        def _dead_order_reason(_res) -> str:
            """Сайт сам объявил заказ мёртвым и написал, что денег не брал.

            Единственный случай, когда код можно вернуть в пул без «unused» от
            /query: филиппинских кодов /query не показывает вовсе, и молчание
            там ничего не доказывает — а вот failed_precharge со сверкой сайта
            доказывает, что код не тратился.
            """
            return ("сайт подтвердил: платёж не прошёл, списания и подписки нет"
                    if (_res or {}).get("site_payment_failed") else "")

        async def _settle_before_verdict(_c, _res) -> bool:
            """Пауза и перепроверка, прежде чем называть активацию неудачей.

            Сайт регулярно дозавершает покупку уже ПОСЛЕ того, как отдал нам
            отказ, и код в этот момент стоит у него в «claimed» — то есть
            заказ в работе, а не провален. Ровно этот разрыв Александр
            закрывал руками кнопкой «Проверить сейчас».

            В основном пути такая пауза есть с этапа 7. А повторная попытка по
            iOS внутри _ios_rescue судила результат сразу — и 23.09.2026
            прислала «не помог и iOS-маршрут» по коду GPTI-CNTC-VYQK-QEYT,
            который сайт в ту же минуту держал в «claimed».

            Порядок: 8 секунд → активация уже записана? → сверка → если код
            всё ещё «claimed», ждём, пока дозреет до «fulfilled» (org ID и
            почту сайт публикует только вместе с ним, иначе сверке нечего
            подтверждать), и спрашиваем сверку ещё раз.

            True — активация подтвердилась, неудачу объявлять нельзя.
            """
            if (_res.get("token_invalid") or _res.get("needs_force_confirm")
                    or _res.get("out_of_stock") or _res.get("site_paused")):
                return False      # ответ окончательный, ждать нечего
            import asyncio as _aio_sv
            await _aio_sv.sleep(8)
            for _stage in range(2):
                try:
                    if await gpt_activation_already_done(_c, user_id, order_id):
                        logging.warning(f"GPT: {_c} подтвердился за паузу — "
                                        f"неудачу НЕ объявляю")
                        return True
                except Exception as _e_sv1:
                    logging.warning(f"GPT: проверка в паузе {_c}: {_e_sv1}")
                try:
                    if (await gpt_reconcile_orphans(only_code=_c)).get("fixed"):
                        logging.warning(f"GPT: {_c} закрыт сверкой за паузу")
                        return True
                except Exception as _e_sv2:
                    logging.warning(f"GPT: сверка в паузе {_c}: {_e_sv2}")
                if _stage:
                    break
                try:
                    from chatgpt_activation import bpa_wait_fulfilled
                    _st_sv, _ = await bpa_wait_fulfilled(_c, tries=4, pause=15.0)
                    if _st_sv != "fulfilled":
                        break      # не «claimed» — ждать больше нечего
                    logging.warning(f"GPT: {_c} дозрел до fulfilled за паузу — "
                                    f"спрашиваю сверку ещё раз")
                except Exception as _e_sv3:
                    logging.warning(f"GPT: ожидание fulfilled {_c}: {_e_sv3}")
                    break
            return False

        async def _burn_code(_c):
            """Помечаем использованный код навсегда — в пул не возвращаем."""
            try:
                _p = await get_pool()
                async with _p.acquire() as _cn:
                    await _cn.execute(
                        "UPDATE gpt_codes SET is_used=TRUE, used_by=$1, used_at=NOW() WHERE code=$2",
                        user_id, _c)
            except Exception as _e:
                logging.error(f"Не удалось пометить плохой код {_c}: {_e}")

        # ── СПАСЕНИЕ ЧЕРЕЗ bypriceactivate.pro ──────────────────────────────
        # Коды у сайтов общие: на 999uu штатно гасятся коды BYPRICE-..., а API
        # bypriceactivate сам выбирает маршрут по коду и умеет пополнять поверх
        # активной подписки. Поэтому «на 999uu нет стока» — не повод брать НОВЫЙ
        # код на другом сайте (так на один заказ уходило два кода): несём ТОТ ЖЕ.
        # Возвращает: "ok" — bpa активировал; "stop" — не вышло, дальше не жжём;
        # None — случай не наш (сток есть / сайт не 999uu / уже пробовали).
        _bpa_rescue_done = False

        async def _bpa_rescue():
            nonlocal result, _bpa_rescue_done
            if _bpa_rescue_done or provider != "987ai":
                return None
            # Несём код на bpa при ЛЮБОМ сбое 999uu, при котором код остался цел:
            # нет стока, таймаут, «принудительное не помогло», сбой сайта.
            # Не несём: код израсходован и ошибки клиента (протух токен, нужна
            # проверка, нужно подтверждение) — там смена сайта не помогает.
            if (result.get("success") or result.get("code_already_used")
                    or result.get("token_invalid") or result.get("needs_check")
                    or result.get("needs_force_confirm")):
                return None
            _was_oos = bool(result.get("out_of_stock"))
            _bpa_rescue_done = True
            _why = "нет стока" if _was_oos else "сбой/таймаут"
            logging.warning(f"GPT: 999uu не смог ({_why}) — несу ТОТ ЖЕ код {code} на bypriceactivate")
            _sess_for_bpa = session_raw or access_token
            _ok = False
            _err = ""
            if not _sess_for_bpa:
                _err = "нет session JSON (клиент на старой версии мини-аппа)"
            else:
                try:
                    from chatgpt_activation import activate_chatgpt_bpa as _bpa_act
                    _r = await _bpa_act(code, _sess_for_bpa)
                    _ok = bool(_r.get("success"))
                    _err = (_r.get("error") or "неизвестная ошибка")[:200]
                    if _r.get("code_already_used"):
                        await _burn_code(code)   # код реально израсходован
                    result = _r
                except Exception as _e_b:
                    _err = f"{type(_e_b).__name__}: {_e_b}"[:200]
                    logging.error(f"GPT bpa rescue: {_e_b}", exc_info=True)
            _err_safe = _err.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
            try:
                await bot.send_message(
                    ADMIN_ID,
                    ("✅ <b>ChatGPT — выручил bypriceactivate</b>\n\n"
                     if _ok else
                     "🚨 <b>ChatGPT — не вышло ни на 999uu, ни на bypriceactivate</b>\n\n")
                    + f"👤 {_who_u} · {plan_name}\n{await _actx(show_site=False)}"
                      f"🔑 <code>{code}</code>\n\n"
                    + (f"На 999uu — {_why}. Тот же код прошёл на bypriceactivate."
                       if _ok else
                       f"На 999uu — {_why}. bypriceactivate: {_err_safe}\n"
                       + ("Новые коды НЕ трогал — активируй вручную этим же кодом."
                          if _was_oos else "Пробую остальные сайты их кодами.")),
                    parse_mode="HTML")
            except Exception:
                pass
            if _ok:
                return "ok"
            # bpa уже пробован — чтобы цепочка не взяла оттуда ЕЩЁ один код
            if "bpa" not in _tried_sites:
                _tried_sites.append("bpa")
            if not _was_oos:
                # Обычный сбой: пусть цепочка добьёт остальные сайты своими кодами.
                # Полный стоп делаем только когда стока нет — там перебор бессмыслен.
                return "next"
            _activation_jobs[job_id] = {
                "status": "done", "success": False, "manual": True,
                "error": _gpt_wait_web("на сайте активации временно нет свободных мест")}
            try:
                await bot.send_message(
                    user_id,
                    _gpt_wait_text("на сайте активации временно нет свободных мест"),
                    parse_mode="HTML", reply_markup=_gpt_support_kb())
            except Exception:
                pass
            return "stop"

        _GPT_MAX_BURN = 5      # максимум кодов на ОДИН заказ, см. ниже

        # Сколько iOS-кодов уже ушло на сайт по этому заказу. Считаем отдельно
        # от филиппинских, потому что риск у них разный:
        #   iOS   — реально применяет подписку на ЛЮБОЙ аккаунт, и она
        #           складывается (пять подряд лягут пять раз). Второй iOS-код
        #           на тот же аккаунт — это прямая потеря денег.
        #   Филиппины — на аккаунте с активным тарифом сайт код отклоняет,
        #           код цел и возвращается в пул.
        # Поэтому перебор iOS-кодов разрешаем только когда сайт ПРЯМО сказал,
        # что предыдущий ушёл на ЧУЖОЙ аккаунт (wrong_account) — тогда клиенту
        # он подписку не дал и брать следующий безопасно.
        _ios_sent = 1 if gpt_route_for_code(code) == "ios" else 0

        async def _site_says_used(_c):
            """Спрашиваем САЙТ, потрачен ли код.

            Возвращает ПАРУ (вердикт, что_ответил_сайт): True / False / None и
            сырой статус строкой. Раньше отдавался только вердикт, и None
            означал сразу две несовместимые вещи — «сайт промолчал» и «сайт
            ответил failed / not_in_db / незнакомым статусом». В сообщении
            админу обе превращались в «статус узнать не удалось», и понять по
            нему, что на самом деле случилось с кодом, было нельзя.

            Зачем: раньше «код уже использован» решалось ТОЛЬКО по тексту ответа
            сайта, а сам статус кода никто не спрашивал. 15.09.2026 это сожгло
            пять целых Plus-кодов подряд по заказу 248333474 — на странице
            bypriceactivate.pro/query все пять значились unused, без почты и без
            Organization ID, то есть их никто не активировал.

            Страница /query — это то же самое, что Александр открывает руками,
            и она отвечает по каждому коду: unused / claimed / fulfilled.
            Спросить её дешевле, чем потерять код.
            """
            if provider != "bpa":
                return None, ""      # у остальных сайтов такой страницы нет
            # Спрашиваем ДО ТРЁХ РАЗ. Пустой ответ /query — это почти всегда
            # разовая осечка: сеть моргнула, сайт притормозил, упёрлись в лимит
            # частоты. Приговором коду это не является, а одной попытки хватало,
            # чтобы остановить весь заказ: защита ниже не жжёт код и прекращает
            # перебор, клиент уходит в ручной режим при ПОЛНОМ пуле.
            # 19.09.2026, заказ #5395, код GPTP-JTRU-WZ3P-3SSC: ровно так.
            # Повторяем только при невнятном ответе. Любой понятный статус —
            # unused, claimed, fulfilled, failed — возвращается сразу.
            import asyncio as _aio_sq
            _last_err = ""
            for _att in range(3):
                try:
                    from chatgpt_activation import (bpa_query_codes, BPA_USED_STATUSES,
                                                    BPA_FREE_STATUSES)
                    _q = await bpa_query_codes([_c])
                except Exception as _e:
                    logging.warning(f"GPT: не смог спросить сайт про код {_c} "
                                    f"(попытка {_att + 1}/3): {_e}")
                    _last_err = "сбой запроса: " + str(_e)[:80]
                    if _att < 2:
                        await _aio_sq.sleep(3)
                    continue
                _row = (_q or {}).get(_c) or (_q or {}).get(str(_c).upper()) or {}
                _st = str(_row.get("status") or "").strip().lower()
                if _st:
                    if _att:
                        logging.warning(f"GPT: статус кода {_c} получен только "
                                        f"с {_att + 1}-й попытки: {_st}")
                    if _st in BPA_FREE_STATUSES:
                        return False, _st
                    if _st in BPA_USED_STATUSES:
                        return True, _st
                    return None, _st     # failed / not_in_db / незнакомый — не решаем
                _last_err = ""           # сайт ответил, но кода в таблице нет
                if _att < 2:
                    await _aio_sq.sleep(3)
            logging.error(f"GPT: сайт три раза подряд не сказал ничего внятного "
                          f"про код {_c}" + (f" ({_last_err})" if _last_err else ""))
            return None, _last_err

        async def _cycle_used_current_site() -> bool:
            """Перебирает коды ТЕКУЩЕГО сайта, пока приходит code_already_used.
            Обновляет code/result. Возвращает True, если сайт исчерпан
            использованными кодами (пора уходить на другой сайт)."""
            nonlocal code, result, _ios_sent
            # Потолок 5, а не 30. Пять кодов подряд «уже использованы» — это уже
            # не «в пуле попался потраченный», а системный сбой: так 12.09.2026
            # за две минуты ушло 8 кодов. Дешевле остановиться и активировать
            # вручную, чем выесть пул на одном заказе.
            while (not result.get("success") and result.get("code_already_used")
                   and len(_gpt_used_codes) < _GPT_MAX_BURN):
                # СНАЧАЛА СПРАШИВАЕМ САЙТ, а уже потом жжём. Слово «already» в
                # тексте ошибки — это НЕ доказательство того, что код потрачен:
                # тем же ответом сайт отвечает и на «аккаунту нельзя», и на свои
                # внутренние сбои. Жечь по тексту — то, что 15.09.2026 съело
                # пять целых кодов подряд.
                _used_on_site, _raw_st = await _site_says_used(code)
                if _used_on_site is not True:
                    if _used_on_site is False:
                        _why = "сайт говорит, что код ЦЕЛ (unused)"
                    elif _raw_st:
                        # Сайт ОТВЕТИЛ — просто ответом, по которому нельзя
                        # решить судьбу кода. Это совсем не то же самое, что
                        # молчание, и путать их в отчёте нельзя.
                        _why = f"сайт ответил «{_raw_st}» — по такому статусу решать нельзя"
                    else:
                        _why = "сайт не ответил про этот код (пустой ответ /query)"
                    if _used_on_site is False:
                        # Код цел — возвращаем в пул, он ничей.
                        try:
                            await release_gpt_code(code)
                        except Exception as _e_rel:
                            logging.error(f"не смог вернуть код {code} в пул: {_e_rel}")
                    _burn_stop["why"] = f"не стал жечь код {code} — {_why}"
                    logging.error(
                        f"GPT: НЕ жгу код {code} — {_why}. uid={user_id} "
                        f"order={order_id} ответ сайта={str(result.get('error'))[:200]!r}")
                    try:
                        await bot.send_message(
                            ADMIN_ID,
                            f"🛑 <b>Не стал сжигать код</b>\n"
                            f"🔑 <code>{code}</code>\n"
                            f"👤 {_who_u} · {plan_name}\n"
                            f"🆔 <code>{order_id}</code>\n"
                            f"{await _actx()}\n"
                            f"Сайт ответил «уже использован», но {_why}.\n"
                            + ("Код возвращён в пул.\n" if _used_on_site is False
                               else "Код оставлен закреплённым за клиентом.\n")
                            + _gpt_fail_why(result, code)
                            + f"\n<i>Ответ сайта:</i> <code>"
                            + str(result.get("error") or "—")[:300]
                            + "</code>\n\nАктивируй вручную.",
                            parse_mode="HTML")
                    except Exception:
                        pass
                    return False
                _gpt_used_codes.append(code)
                # Код был активирован НЕ нашим клиентом: сайт вернул чужой,
                # уже завершённый заказ. Значит в пуле лежал потраченный код —
                # админу надо об этом знать, это не рядовая «занятость».
                if result.get("wrong_account"):
                    try:
                        await bot.send_message(
                            ADMIN_ID,
                            f"⚠️ <b>В пуле оказался УЖЕ ПОТРАЧЕННЫЙ код</b>\n"
                            f"🔑 <code>{code}</code> — сжёг, беру следующий\n"
                            f"👤 Клиент: {_who_u} · {plan_name}\n"
                            f"🆔 <code>{order_id}</code>\n"
                            f"{await _actx()}"
                            + (f"📧 Ушёл на: <code>{result.get('other_email')}</code>\n"
                               if result.get("other_email") else "")
                            + "\nРаньше бот в такой ситуации рапортовал успех "
                              "с чужой почтой. Проверь пул: /gpt_codes_status",
                            parse_mode="HTML")
                    except Exception:
                        pass
                await _burn_code(code)
                logging.warning(f"Код {code} уже использован (site={provider}), беру следующий")
                # Маршрут держим тот же: филиппинский код нельзя подсунуть
                # аккаунту с подпиской, а iOS — наоборот, годится везде.
                _rt_cur = gpt_route_for_code(code) if provider == "bpa" else None
                # ЗАЩИТА ОТ ДВОЙНОЙ ПОДПИСКИ НА ОДИН АККАУНТ.
                # Следующий код того же маршрута iOS отправим только если сайт
                # подтвердил, что предыдущий лёг на ЧУЖОЙ аккаунт. Иначе он мог
                # лечь на аккаунт этого клиента — и второй код добавит ему
                # вторую подписку поверх первой, за наши деньги.
                if _rt_cur == "ios" and _ios_sent >= 1 and not result.get("wrong_account"):
                    _burn_stop["why"] = ("второй iOS-код на тот же аккаунт не выдаю — сайт не подтвердил, что первый ушёл на чужой")
                    logging.warning(
                        f"GPT: второй iOS-код на аккаунт uid={user_id} НЕ выдаю "
                        f"(сайт не подтвердил чужой аккаунт) — ручной режим")
                    try:
                        await bot.send_message(
                            ADMIN_ID,
                            f"🛑 <b>Не стал выдавать второй iOS-код</b>\n"
                            f"👤 {_who_u} · {plan_name}\n{await _actx()}"
                            f"🔑 <code>{code}</code>\n"
                            f"🆔 <code>{order_id}</code>\n\n"
                            + _gpt_fail_why(result, code) +
                            f"\nПервый iOS-код мог уже лечь на аккаунт клиента — "
                            f"второй добавил бы подписку поверх, за наши деньги. "
                            f"Проверь код на сайте и активируй вручную.",
                            parse_mode="HTML")
                    except Exception:
                        pass
                    return False
                _nc = await get_next_gpt_code(_plan_key, provider, _rt_cur)
                if not _nc:
                    return True   # на этом сайте кодов больше нет
                if gpt_route_for_code(_nc) == "ios":
                    _ios_sent += 1
                await save_pending_activation(user_id, _nc, order_id, _plan_key, plan_name, provider)
                code = _nc
                if len(_gpt_used_codes) == 1:
                    try:
                        await bot.send_message(
                            user_id,
                            "⏳ Активация идёт — нужно ещё немного времени. "
                            "Не закрывай мини-приложение, ничего повторять не нужно.",
                            parse_mode="HTML")
                    except Exception:
                        pass
                result = await _do_activate(code)
            if (len(_gpt_used_codes) >= _GPT_MAX_BURN
                    and result.get("code_already_used")):
                # Дальше не жжём. Код оставляем закреплённым за клиентом.
                try:
                    await bot.send_message(
                        ADMIN_ID,
                        f"🛑 <b>Стоп: подряд {_GPT_MAX_BURN} кодов «уже использованы»</b>\n"
                        f"👤 {_who_u} · {plan_name}\n{await _actx()}"
                        f"🆔 <code>{order_id}</code>\n"
                        f"♻️ Потрачены: {', '.join(_gpt_used_codes)}\n\n"
                        f"Это не похоже на случайность — перебор остановлен, "
                        f"чтобы не выесть пул. Активируй вручную и проверь коды: "
                        f"<code>/gpt_codes_recover</code>",
                        parse_mode="HTML")
                except Exception:
                    pass
                _burn_stop["why"] = (f"потолок перебора: подряд {_GPT_MAX_BURN} кодов «уже использованы»")
                logging.error(f"GPT: потолок перебора ({_GPT_MAX_BURN}) uid={user_id} "
                              f"order={order_id} коды={_gpt_used_codes}")
            return False

        # Ошибки КЛИЕНТА — сменой сайта не лечатся (протухшая сессия, «нужна проверка»,
        # подтверждение принудительной активации). Их НЕ фолбэсим по сайтам.
        def _client_stop(_res):
            # site_paused здесь же, хотя к клиенту отношения не имеет: смысл
            # списка — «дальше перебирать сайты бессмысленно». Сайт на
            # техобслуживании мы уже трижды переспросили, а уход на другой сайт
            # означал бы вернуть его код в пул — через _safe_release, который
            # до лежащего сайта не достучится, пометит код и пришлёт «код не
            # вернул в пул». Ровно этот шум Александр и видел 18.09.2026.
            # Код цел, сайт сам написал «codes stay valid» — оставляем за
            # клиентом и идём в свою ветку.
            return bool(_res.get("token_invalid") or _res.get("needs_check")
                        or _res.get("needs_force_confirm")
                        or _res.get("site_paused"))

        # ── ПЕРЕВОД НА iOS, КОГДА НЕ ПРОХОДИТ САМА ПОКУПКА ────────────────
        # Филиппинский маршрут — это покупка на стороне сайта, и она падает по
        # трём причинам: её рубит антифрод OpenAI («деньги не списаны»), на
        # аккаунте уже есть платный план, или у самого сайта не проходит его
        # карта (failed_precharge). Смена САЙТА ни в одном случае не помогает —
        # помогает смена МАРШРУТА: через iOS (чек Apple) покупка проходит.
        # Филиппинский код при этом цел, возвращаем его в пул.
        _ios_rescue_done = False

        async def _ios_rescue():
            nonlocal result, code, _ios_rescue_done, _ios_sent
            if _ios_rescue_done or provider != "bpa":
                return None
            if result.get("success") or _client_stop(result):
                return None
            # has_plan — тот же случай, просто сайт назвал его иначе:
            # «у аккаунта уже есть платный план». Филиппинский код на таком
            # аккаунте не сработает никогда, а iOS сработает. Раньше ветка
            # ждала только openai_blocked, и 409 GPT_PLAN_ALREADY_ACTIVE
            # проходил мимо неё (20.09.2026, заказ #5456).
            # site_payment_failed — у САЙТА не прошёл платёж по его карте
            # (provider_status=failed_precharge). Филиппинский маршрут в эту
            # карту и упирается, а iOS выдаёт чеки из запаса, без списания —
            # значит переход решает заказ. Код при этом цел: сайт сам
            # подтвердил, что списания и подписки не было.
            if not (result.get("openai_blocked") or result.get("has_plan")
                    or result.get("site_payment_failed")):
                return None
            if gpt_route_for_code(code) != "ph":
                return None      # уже iOS — переводить некуда
            # Второй iOS-код на один заказ не выдаём никогда. iOS ложится на
            # ЛЮБОЙ аккаунт и стакается до пяти раз: лишний код — это прямые
            # деньги, а клиенту вторая подписка поверх первой не нужна.
            # Сейчас сюда и так не попасть с iOS-кодом (проверка маршрута
            # выше), но инвариант должен держаться на месте, а не на порядке
            # вызовов: однажды эту ветку позовут откуда-то ещё.
            if _ios_sent >= 1:
                logging.warning(f"GPT ios rescue: uid={user_id} iOS-код уже "
                                f"отправляли — второй не беру")
                return None
            # Причина у трёх веток разная, и в сообщениях она должна быть
            # разной. Раньше все три подписывались «OpenAI отклонил покупку» —
            # и Александр читал это там, где на самом деле у САЙТА не прошла
            # его карта. Считаем ДО повторной активации: ниже result
            # перезаписывается результатом iOS-попытки.
            if result.get("site_payment_failed"):
                _why_short = "у сайта не прошёл платёж по его карте"
                _why_long = ("сайт не смог оплатить заказ своей картой "
                             "(provider_status=failed_precharge); по его сверке "
                             "списания, hold и подписки по заказу нет")
            elif result.get("has_plan"):
                _why_short = "на аккаунте уже есть платный план"
                _why_long = ("OpenAI ответил, что на аккаунте уже активен платный "
                             "план — филиппинский код на таком аккаунте не сработает")
            else:
                _why_short = "OpenAI отклонил покупку"
                _why_long = ("покупку заблокировала защита OpenAI, деньги "
                             "не списаны")
            _dead_reason = _dead_order_reason(result)
            _ios_rescue_done = True
            _new = await get_next_gpt_code(_plan_key, "bpa", "ios")
            if not _new:
                # iOS-кодов нет: филиппинский вернём в пул и уйдём в ручной
                # режим. Пробовать тем же маршрутом ещё раз бессмысленно —
                # его только что отбил антифрод.
                try:
                    # Код сайту уже отправляли — возвращаем только с его
                    # подтверждением, иначе отдадим следующему клиенту заказ,
                    # который сайт ещё может дозавершить. Исключение —
                    # _dead_reason: сайт сам написал, что заказ мёртв и денег
                    # не брал.
                    _rel_ok = bool(await _safe_release(code, _dead_reason))
                except Exception as _e_rl:
                    _rel_ok = False
                    logging.warning(f"_safe_release {code}: {_e_rl}")
                await delete_pending_activation(user_id, order_id)
                logging.warning(f"GPT ios rescue: uid={user_id} нет iOS-кодов, ручной режим")
                # Писать «возвращён в пул» независимо от исхода нельзя: если
                # сайт не подтвердил, что код цел, он остался за клиентом — и
                # Александр должен видеть это, а не верить сообщению.
                _rel_txt = _rel_phrase(_rel_ok)
                await _admin_fail_shot(
                    f"🚨 <b>ChatGPT — {_why_short}, а iOS-кодов нет</b>\n"
                    f"👤 {_who_u} · {plan_name}\n"
                    f"🔑 <code>{code}</code> — {_rel_txt}\n"
                    f"🔎 Причина: {_why_long}\n"
                    f"🆔 <code>{order_id}</code>\n"
                    f"{await _actx()}\n"
                    f"Перевести заказ на iOS нечем. "
                    f"Пополни iOS-коды или активируй вручную.", order_id=order_id)
                _why_cl = ("для твоего аккаунта нужен другой тип кода"
                           if result.get("has_plan") or result.get("openai_blocked")
                           else "у сайта активации не прошёл платёж с его стороны")
                _activation_jobs[job_id] = {
                    "status": "done", "success": False, "manual": True,
                    "error": _gpt_wait_web(_why_cl, "Александр активирует вручную в течение часа",
                                           keep_code=False)}
                try:
                    await bot.send_message(
                        user_id,
                        _gpt_wait_text(_why_cl, "Александр активирует вручную в течение часа",
                                       keep_code=False),
                        parse_mode="HTML", reply_markup=_gpt_support_kb())
                except Exception:
                    pass
                return "stop"

            _old_code = code
            try:
                # То же самое: заказ на сайте мог остаться живым — возвращаем
                # с подтверждением сайта (или по его же признанию, что заказ
                # мёртв, — _dead_reason).
                _rel_ok2 = bool(await _safe_release(_old_code, _dead_reason))
            except Exception as _e_rl2:
                _rel_ok2 = False
                logging.warning(f"_safe_release {_old_code}: {_e_rl2}")
            # Сайт ответил, что код fulfilled: подписку по нему он ВЫДАЛ.
            # Прежде чем тратить iOS-код (а это прямые деньги: iOS ложится на
            # любой аккаунт и стоит дороже), спросим сверку — кому именно она
            # ушла. Подтвердится наш клиент — заказ закрыт, а iOS-код
            # возвращаем нетронутым: сайту мы его даже не отправляли.
            if _rel_last.get("site") in ("fulfilled", "zoom_token_ready"):
                try:
                    _rr_ios = await gpt_reconcile_orphans(only_code=_old_code)
                except Exception as _e_rc2:
                    _rr_ios = {}
                    logging.warning(f"ios rescue: сверка {_old_code}: {_e_rc2}")
                if _rr_ios.get("fixed"):
                    try:
                        await release_gpt_code(_new)   # даже не отправляли
                    except Exception:
                        pass
                    await delete_pending_activation(user_id, order_id)
                    _activation_jobs[job_id] = {"status": "done", "success": True}
                    logging.warning(f"ios rescue: {_old_code} закрыт сверкой — "
                                    f"iOS-код {_new} не потрачен.")
                    try:
                        await bot.send_message(
                            ADMIN_ID,
                            f"✅ <b>ChatGPT — закрыто сверкой, iOS-код сэкономлен</b>\n\n"
                            f"👤 {_who_u} · {plan_name}\n{await _actx(_old_code)}"
                            f"🇵🇭 <code>{_old_code}</code> — сайт всё-таки выдал по нему "
                            f"подписку, сверка подтвердила клиента\n"
                            f"📱 <code>{_new}</code> — возвращён в пул, сайту не "
                            f"отправляли\n"
                            f"🆔 <code>{order_id}</code>",
                            parse_mode="HTML")
                    except Exception:
                        pass
                    return "stop"
                logging.warning(f"ios rescue: сверка по {_old_code} клиента не "
                                f"подтвердила — продолжаю по iOS {_new}.")
            code = _new
            _ios_sent += 1          # перевели на iOS — это и есть первый iOS-код
            await save_pending_activation(user_id, code, order_id, _plan_key, plan_name, "bpa")
            logging.warning(
                f"GPT ios rescue: uid={user_id} {_why_short} по {_old_code} "
                f"(ph) → повторяю через iOS {code}")
            result = await _do_activate(code)
            _ok_ios = bool(result.get("success"))
            # Та же болезнь, что и в основном пути: сайт дозавершает покупку
            # через несколько секунд после отказа. Ждём и перепроверяем,
            # прежде чем писать «не помог».
            _late_ok = False if _ok_ios else await _settle_before_verdict(code, result)
            _rel_line2 = _rel_phrase(_rel_ok2)
            _mid_ios = None
            try:
                _m_ios = await bot.send_message(
                    ADMIN_ID,
                    ("✅ <b>ChatGPT — выручил iOS-маршрут</b>\n\n" if _ok_ios else
                     "✅ <b>ChatGPT — iOS-маршрут выручил, подтвердилось "
                     "с задержкой</b>\n\n" if _late_ok else
                     "🚨 <b>ChatGPT — не помог и iOS-маршрут</b>\n\n")
                    + f"👤 {_who_u} · {plan_name}\n"
                      f"🇵🇭 Филиппинский <code>{_old_code}</code> — {_why_short}; "
                      f"{_rel_line2}\n"
                      f"🔎 Причина: {_why_long}\n"
                      f"📱 iOS <code>{code}</code> — "
                    + ("активация прошла" if _ok_ios else
                       "активация прошла (подтвердилась после паузы)" if _late_ok
                       else "тоже не вышло")
                    + f"\n🆔 <code>{order_id}</code>\n"
                    + ("" if (_ok_ios or _late_ok) else _gpt_fail_why(result, code))
                    + await _actx(),
                    parse_mode="HTML")
                _mid_ios = getattr(_m_ios, "message_id", None)
            except Exception:
                pass
            # Сообщение о неудаче запоминаем: сверка может закрыть заказ
            # позже, и тогда оно перепишется в «активация прошла».
            if (not _ok_ios) and (not _late_ok) and _mid_ios and order_id:
                try:
                    await set_setting(f"gpt_confirm_msg:{order_id}", str(_mid_ios))
                except Exception as _e_mi:
                    logging.warning(f"gpt confirm msg id (ios): {_e_mi}")
            if _late_ok:
                # Активацию уже записали сверка или прошлый заход — второй раз
                # проводить её по общему пути нельзя.
                _activation_jobs[job_id] = {"status": "done", "success": True}
                return "stop"
            return "ok" if _ok_ios else None

        # 0) 999uu без стока → тот же код на bypriceactivate (до всякого перебора)
        if await _bpa_rescue() == "stop":
            return

        # 0б) покупка на филиппинском коде не прошла (антифрод OpenAI, уже
        #     есть план или не прошла карта САЙТА) → пробуем iOS-маршрут
        if await _ios_rescue() == "stop":
            return

        # 1) текущий сайт: сперва перебор использованных кодов
        await _cycle_used_current_site()

        # 2) единый авто-фолбэк по сайтам: пока нет успеха и это не ошибка клиента —
        #    уходим на следующий сайт, где ЕСТЬ коды, и там снова перебираем
        #    использованные. Причина ухода: сбой сайта (таймаут/522/нет стока) ИЛИ
        #    на этом сайте кончились коды (все использованы).
        while (not result.get("success")) and (not _client_stop(result)):
            _next = None
            for _np in await _gpt_provider_order():
                if _np in _tried_sites:
                    continue
                _nc = await get_next_gpt_code(_plan_key, _np)
                if _nc:
                    # Та же защита, что и в переборе кодов: второй iOS-код на
                    # тот же аккаунт выдаём только при подтверждённом чужом
                    # аккаунте — иначе клиент получит вторую подписку поверх.
                    if (gpt_route_for_code(_nc) == "ios" and _ios_sent >= 1
                            and not result.get("wrong_account")):
                        try:
                            await release_gpt_code(_nc)   # даже не отправляли
                        except Exception:
                            pass
                        _burn_stop["why"] = ("на другом сайте лежит только iOS-код, а второй iOS на тот же аккаунт выдавать нельзя")
                        logging.warning(
                            f"GPT: второй iOS-код при смене сайта НЕ выдаю "
                            f"uid={user_id}")
                        continue
                    _next = (_np, _nc)
                    break
            if not _next:
                # Сайтов с кодами больше нет. Если текущий код НЕ израсходован
                # (сбой сайта / на аккаунте уже есть подписка) и это не кейс,
                # где код нужен для повторной попытки (force/токен) — вернём его
                # в пул, чтобы он НЕ сгорел.
                # НЕ возвращаем код в пул: резерв клиента остаётся на этом
                # коде (повтор клиента или твоя ручная активация «ИМ ЖЕ»).
                # Раньше при ответе сайта «unused» код уходил в пул, а резерв
                # продолжал на него указывать — пул мог отдать тот же код
                # другому покупателю, пока первый жмёт «Повторить». Если
                # активацию так и не доведут, код вернёт фоновая чистка после
                # окна (когда резерва уже нет). Перепроверка 07.10.2026.
                break  # сайтов с кодами больше нет
            _was_used = bool(result.get("code_already_used"))
            _fail_reason = (result.get("error")
                            or ("код уже использован" if _was_used else "сбой сайта"))[:140]
            # Прежний код валиден (сбой сайта, не «использован») → вернём в пул,
            # но только если сайт подтвердит, что он цел: заказ по нему мог
            # остаться живым и завершиться позже.
            if not _was_used:
                try:
                    await _safe_release(code, _dead_order_reason(result))
                except Exception:
                    pass
            provider, code = _next
            if gpt_route_for_code(code) == "ios":
                _ios_sent += 1
            _tried_sites.append(provider)
            await save_pending_activation(user_id, code, order_id, _plan_key, plan_name, provider)
            _activation_jobs[job_id] = {"status": "pending", "retrying": True}
            _switch_text = (
                f"🔀 <b>ChatGPT — авто-переключение сайта</b> ({plan_name})\n"
                f"Прежний сайт не сработал: {_fail_reason}\n"
                f"Ушли на <b>{gpt_provider_name(provider)}</b>.")
            try:
                _sw_msg = await bot.send_message(ADMIN_ID, _switch_text, parse_mode="HTML")
                _switch_msg_id = _sw_msg.message_id
            except Exception:
                _switch_msg_id = None
            result = await _do_activate(code)
            # Ушли на 999uu и там нет стока → тот же код на bypriceactivate.
            # Это ОСНОВНОЙ сценарий: Plus-клиент стартует на приоритетном сайте,
            # получает «на аккаунте уже есть подписка» и попадает сюда.
            _rescue = await _bpa_rescue()
            if _rescue == "stop":
                return
            if _rescue == "ok":
                break
            await _cycle_used_current_site()  # на новом сайте тоже перебираем использованные

        # 3) КОДЫ КОНЧИЛИСЬ ВЕЗДЕ: результат — «код использован», а свободных кодов больше
        #    нет ни на одном сайте. Это терминальный случай → ручная активация.
        if (not result.get("success")) and result.get("code_already_used"):
            _skipped = (f"♻️ Пропущены использованные ({len(_gpt_used_codes)}): "
                        f"{', '.join(_gpt_used_codes)}\n" if _gpt_used_codes else "")
            # Сколько кодов РЕАЛЬНО осталось. Без этой строки сообщение «коды
            # закончились» невозможно проверить, не открывая панель, — а
            # 19.09.2026 оно как раз и оказалось неправдой.
            _left_line = ""
            try:
                _pl = await get_pool()
                async with _pl.acquire() as _c_left:
                    _lrows = await _c_left.fetch(
                        "SELECT COALESCE(route,'—') AS route, COUNT(*) AS n "
                        "FROM gpt_codes WHERE plan=$1 AND provider=$2 AND is_used=FALSE "
                        "  AND COALESCE(check_status,'unchecked') NOT IN ('used','invalid') "
                        "GROUP BY 1 ORDER BY 1", _plan_key, provider)
                _left_total = sum(int(_r["n"]) for _r in _lrows)
                if _lrows:
                    _left_line = ("🔑 Свободно на " + gpt_provider_name(provider) + ": "
                                  + ", ".join(f"{_r['route']} — {_r['n']}" for _r in _lrows)
                                  + f" (всего {_left_total})\n")
                else:
                    _left_line = f"🔑 Свободных кодов {_plan_key} на {gpt_provider_name(provider)}: 0\n"
            except Exception as _e_left:
                logging.warning(f"GPT: не посчитал остаток пула: {_e_left}")

            if _burn_stop["why"]:
                # Коды ЕСТЬ — перебор прекращён сознательно, защитой. Это не
                # «закончились»: докупать нечего, надо разбираться с кодом или
                # с сайтом. Раньше оба случая слались одним текстом про
                # «закончились на ВСЕХ сайтах», причём с нулём сожжённых кодов.
                await _admin_fail_shot(
                    f"🛑 <b>ChatGPT — перебор кодов остановлен защитой</b> ({plan_name})\n"
                    f"👤 {_who_u} ждёт активации.\n"
                    f"🆔 <code>{order_id}</code>\n"
                    f"{await _actx()}\n"
                    f"⛔️ Причина: {_burn_stop['why']}\n"
                    + _gpt_fail_why(result, code)
                    + f"{_left_line}"
                    f"{_skipped}"
                    f"\n<i>Ответ сайта:</i> <code>"
                    + str(result.get("error") or "—")[:300] + "</code>\n\n"
                    f"Коды в пуле есть — добавлять не нужно. Активируй вручную, "
                    f"а код проверь: <code>/gpt_check</code>",
                    result.get("screenshot"), order_id=order_id)
                logging.error(
                    f"GPT: перебор остановлен защитой uid={user_id} order={order_id} "
                    f"причина={_burn_stop['why']!r} сожжено={len(_gpt_used_codes)}")
            else:
                await _admin_fail_shot(
                    f"🚨 <b>ChatGPT — коды {_plan_key} закончились на ВСЕХ сайтах</b> ({plan_name})\n"
                    f"👤 {_who_u} ждёт активации.\n{await _actx(show_site=False)}"
                    f"🧭 Пробовали: {', '.join(gpt_provider_name(_p) for _p in _tried_sites)}\n"
                    f"{_left_line}"
                    f"{_skipped}"
                    f"Добавь коды: /add_gpt_codes",
                    result.get("screenshot"), order_id=order_id)
            # Клиенту тоже не врём. «Коды закончились» — правда только когда
            # пул действительно пуст; при остановке защитой коды есть, просто
            # выдать их автоматически нельзя.
            _why_co = ("автоматическая активация остановлена для проверки"
                       if _burn_stop["why"] else "коды временно закончились")
            _activation_jobs[job_id] = {
                "status": "done", "success": False, "manual": True,
                "error": _gpt_wait_web(_why_co, "Александр активирует вручную в течение часа",
                                       keep_code=False)}
            # Раньше клиент узнавал об этом только в мини-приложении — если
            # он его закрыл, в чате было пусто.
            try:
                await bot.send_message(
                    user_id,
                    _gpt_wait_text(_why_co, "Александр активирует вручную в течение часа",
                                   keep_code=False),
                    parse_mode="HTML", reply_markup=_gpt_support_kb())
            except Exception:
                pass
            return

        # 4) СБОЙ САЙТА и других сайтов с кодами нет → сообщаем и уходим в общую
        #    обработку ошибок (ретраи/токен) ниже.
        # Отдельного алерта «не удалось ни на одном сайте» больше НЕТ: ниже по
        # тексту уже уходит подробный «авто-активация НЕУДАЧА» с тем же кодом и
        # ошибкой. Два сообщения об одной неудаче только зашумляли чат — список
        # пройденных сайтов перенесён в то, второе сообщение.

        if result.get("success"):
            _email = result.get("email") or _extract_email_from_token(access_token)
            await mark_gpt_code_used(code, user_id, order_id, _email)
            await delete_pending_activation(user_id, order_id)
            # Номер заказа + FreeKassa для сообщений клиенту
            _ord_ok = await fk_get_order(order_id)
            _fkno_ok = (_ord_ok or {}).get("fk_intid") or ""
            _num_ok = (_ord_ok or {}).get("num")
            _onum_ok = f"#{_num_ok}" if _num_ok else order_id
            _ordline_ok = f"🧾 Заказ {_onum_ok}" + (f" · FreeKassa {_fkno_ok}" if _fkno_ok else "")
            # Заменяем сообщение клиента на поздравление и убираем кнопку «Нужна помощь».
            # Единый вид успеха (client_success_text). Если сообщения активации
            # нет (force-повтор через новый веб-апп) или правка не удалась —
            # уходит НОВОЕ сообщение: раньше при неудачной правке клиент не
            # получал подтверждения вовсе. 06.10.2026
            _mid = _gpt_act_msg.pop(user_id, None)
            await client_success_deliver(
                user_id,
                client_success_text("chatgpt", plan_name, account=_email or "",
                                    end=client_end_date(plan_name), order_line=_ordline_ok),
                client_success_kb("chatgpt"), edit_mid=_mid)
            # Счётчик попыток — с нуля: иначе следующий заказ того же клиента
            # начинался с «Попытка 2 из 3».
            _gpt_retry_counts.pop(user_id, None)
            try:
                import datetime as _dt
                _used_at = _dt.datetime.now(_BOT_TZ).strftime("%d.%m.%Y %H:%M")
                # Получаем username и full_name клиента из БД
                try:
                    _pool = await get_pool()
                    async with _pool.acquire() as _conn:
                        _urow = await _conn.fetchrow(
                            "SELECT username, full_name FROM users WHERE user_id=$1", user_id
                        )
                    _username  = _urow["username"]  if _urow and _urow["username"]  else ""
                    _full_name = _urow["full_name"] if _urow and _urow["full_name"] else ""
                except Exception:
                    _username = _full_name = ""
                import html as _h_tgn
                _tg_name = (f"@{_username}" if _username
                            else _h_tgn.escape(strip_surrogates(_full_name or ""))) \
                    or f"id{user_id}"
                # Оплата, промокод и журнал попыток: без них по сообщению не
                # понять ни выручку, ни то, с какой попытки прошло.
                # Александр 04.10.2026.
                _pay_ok = _promo_ok = ""
                try:
                    _o_ok = await fk_get_order(order_id) or {}
                    _b_ok = []
                    if _o_ok.get("amount_rub"):
                        _b_ok.append(f"<b>{int(_o_ok['amount_rub'])} \u20bd</b>")
                    _pm_ok = {"sbp": "СБП", "card": "карта"}.get(
                        (_o_ok.get("payment_method") or "").strip().lower(), "")
                    if _pm_ok:
                        _b_ok.append(_pm_ok)
                    if _o_ok.get("paid_at"):
                        try:
                            _b_ok.append(_o_ok["paid_at"].astimezone(_BOT_TZ).strftime("%d.%m %H:%M"))
                        except Exception:
                            pass
                    _pay_ok = " \u00b7 ".join(_b_ok)
                    _promo_ok = (_o_ok.get("promo_code") or "").strip()
                except Exception as _e_ok:
                    logging.warning(f"авто-активация OK: заказ {order_id}: {_e_ok}")
                _att_ok = await gpt_attempts_block(order_id)
                _caption = (
                    f"✅ <b>ChatGPT авто-активация OK</b>\n\n"
                    f"👤 Клиент: <b>{_tg_name}</b>  (<code>{user_id}</code>)\n"
                    f"📦 Тариф: <b>{plan_name}</b>\n"
                    + (f"💳 Оплата: {_pay_ok}\n" if _pay_ok else "")
                    + (f"🎟 Промокод: <b>{_h_tgn.escape(_promo_ok)}</b>\n" if _promo_ok else "")
                    + f"🔑 Итоговый код: <code>{code}</code>\n"
                    + f"📧 Email: <b>{_email or '—'}</b>\n"
                    + f"⏱ Время: <b>{_used_at}</b>\n"
                    + f"🆔 Order: <code>{order_id}</code>\n"
                    + await _fk_num_line(order_id)
                    + (f"\n{_att_ok}\n" if _att_ok else "")
                )
                # принудительное продление поверх уже активной подписки
                if result.get("forced"):
                    _pu = result.get("prev_until") or "—"
                    _caption += (
                        f"\n\n♻️ <b>Принудительное продление</b> (клиент подтвердил поверх активной подписки)\n"
                        f"📅 Прошлая подписка действовала до: <b>{_pu}</b>\n"
                        f"⏱ Последняя активация: <b>{_used_at}</b>"
                    )
                # Если было авто-переключение сайта — дописываем ИТОГ в то самое сообщение,
                # чтобы в одном месте было видно: куда ушли и чем закончилось.
                # Висящее по этому заказу сообщение о сбое закрываем — любое,
                # не только «у аккаунта уже есть Plus»: с 23.09.2026 свой
                # message_id кладут сюда все сообщения о неудаче этой
                # активации, чтобы ни одно не осталось висеть неправдой.
                try:
                    _gf_key = f"gpt_confirm_msg:{order_id}"
                    _gf_mid2 = (await get_setting(_gf_key, "") or "").strip()
                    if _gf_mid2.isdigit():
                        _gf_txt = (
                            f"✅ <b>ChatGPT — активация прошла</b>\n\n"
                            f"👤 Клиент: <b>{_tg_name}</b> (<code>{user_id}</code>)\n"
                            f"📧 Email: <b>{_email or '—'}</b>\n"
                            f"🔑 Итоговый код: <code>{code}</code>\n"
                            f"📦 Тариф: <b>{plan_name}</b>\n"
                            f"🆔 <code>{order_id}</code>\n"
                            + await _fk_num_line(order_id)
                            + f"⏱ {_used_at}")
                        try:
                            await bot.edit_message_text(
                                _gf_txt, chat_id=ADMIN_ID,
                                message_id=int(_gf_mid2), parse_mode="HTML")
                        except Exception as _e_ge:
                            logging.info(f"gpt confirm msg edit: {_e_ge}")
                        await set_setting(_gf_key, "")
                except Exception as _e_gf2:
                    logging.warning(f"gpt confirm msg close: {_e_gf2}")
                try:
                    if locals().get("_switch_msg_id"):
                        await bot.edit_message_text(
                            _switch_text
                            + "\n\n✅ <b>Активация успешна</b>\n"
                              f"👤 Клиент: <b>{_tg_name}</b> (<code>{user_id}</code>)\n"
                              f"📧 Почта: <b>{_email or '—'}</b>\n"
                              f"🔑 Ключ: <code>{code}</code>\n"
                              f"🌐 Сайт активации: <b>{gpt_provider_name(provider)}</b>\n"
                              f"⏱ {_used_at}",
                            chat_id=ADMIN_ID, message_id=_switch_msg_id, parse_mode="HTML")
                except Exception as _e_sw:
                    logging.warning(f"edit switch msg: {_e_sw}")
                _gu = _gpt_used_codes if "_gpt_used_codes" in dir() else []
                if _gu:
                    _uc = "\n".join(f"   • <code>{c}</code>" for c in _gu)
                    _caption += f"\n\n♻️ <b>Пропущены уже использованные коды</b> ({len(_gu)}):\n{_uc}"
                # Карточку заказа правим ВСЕГДА — и когда пропускались уже
                # использованные коды тоже. Раньше в этом случае успех уходил
                # НОВЫМ сообщением, а карточка так и висела «оплачен»: в чате
                # одновременно были «заказ оплачен» и «активировано», и понять,
                # что с заказом, можно было только вчитываясь.
                _edited = False
                try:
                    _ord_ok = await fk_get_order(order_id)
                    _amid_ok = (_ord_ok or {}).get("admin_msg_id")
                except Exception:
                    _amid_ok = None
                if _amid_ok:
                    try:
                        await bot.edit_message_text(_caption, chat_id=ADMIN_ID,
                                                    message_id=_amid_ok, parse_mode="HTML")
                        _edited = True
                    except Exception as _e_ed:
                        if "not modified" in str(_e_ed).lower():
                            _edited = True
                if not _edited:
                    await bot.send_message(ADMIN_ID, _caption, parse_mode="HTML")
            except Exception:
                pass
            _fail_clear("gpt", user_id)
            _activation_jobs[job_id] = {"status": "done", "success": True}
        else:
            # `or`, а не значение по умолчанию: сайт иногда отдаёт ПУСТУЮ
            # строку, и в чат уходило голое «❗» без единого слова причины.
            error_text = result.get("error") or "Сайт не объяснил причину"
            # ── Пауза перед приговором ──────────────────────────────────────
            # Сайт регулярно дозавершает активацию через несколько секунд
            # после того, как отдал нам отказ. Из-за этого клиент получал
            # «не удалось», Александр жал «Проверить сейчас» — и подписка
            # оказывалась на месте. Так повторялось изо дня в день.
            # Теперь бот выжидает и перепроверяет САМ, прежде чем кого-то
            # пугать. Восемь секунд: столько занимает дозапись у сайта в
            # большинстве случаев, а клиент такой задержки не замечает.
            #
            # НЕ ждём там, где ответ окончательный и мгновенный: битая
            # сессия, нужен форс, нет стока, сайт на техобслуживании —
            # там пауза только тормозила бы ответ клиенту.
            if not (result.get("token_invalid") or result.get("needs_force_confirm")
                    or result.get("out_of_stock") or result.get("site_paused")):
                await asyncio.sleep(8)
                try:
                    if await gpt_activation_already_done(code, user_id, order_id):
                        logging.warning(
                            f"GPT: {code} подтвердился за паузу — неудачу НЕ объявляю")
                        _activation_jobs[job_id] = {"status": "done", "success": True}
                        return
                except Exception as _e_pw:
                    logging.warning(f"GPT: проверка в паузе {code}: {_e_pw}")
                try:
                    _rr0 = await gpt_reconcile_orphans(only_code=code)
                    if _rr0.get("fixed"):
                        logging.warning(
                            f"GPT: {code} закрыт сверкой за паузу перед приговором")
                        _activation_jobs[job_id] = {"status": "done", "success": True}
                        return
                except Exception as _e_pr:
                    logging.warning(f"GPT: сверка в паузе {code}: {_e_pr}")

            # ── Гонка со сверкой ────────────────────────────────────────────
            # 18.09.2026, код GPTI-0AGH-UM2C-NJ1N: в 14:55 сверка увидела на
            # сайте успех и закрыла заказ («дописано сверкой»), а в 14:58 эта
            # задача — всё ещё висевшая в воздухе — доехала до конца и объявила
            # НЕУДАЧУ по уже закрытому заказу. В чат ушли «код не вернул в пул»
            # и «авто-активация НЕУДАЧА» для подписки, которая работает.
            # Клиенту при этом грозило «не удалось» после «подписка активна».
            #
            # Спрашиваем базу: не записана ли эта активация, пока мы шли сюда.
            # Записана — молчим. Проигравший в гонке не должен кричать.
            try:
                if await gpt_activation_already_done(code, user_id, order_id):
                    logging.warning(
                        f"GPT: неудача по {code} uid={user_id} НЕ объявляется — "
                        f"активация уже записана (сверка обогнала задачу).")
                    _activation_jobs[job_id] = {"status": "done", "success": True}
                    try:
                        await bot.send_message(
                            ADMIN_ID,
                            f"ℹ️ <b>Активация закрыта раньше</b>\n"
                            f"🔑 <code>{code}</code> · {_who_u}\n\n"
                            f"Задача активации дошла до конца и собиралась "
                            f"сообщить о неудаче, но заказ к этому моменту уже "
                            f"закрыт сверкой. Ничего делать не нужно.",
                            parse_mode="HTML")
                    except Exception:
                        pass
                    return
            except Exception as _e_rc:
                logging.warning(f"GPT: проверка «уже записано» {code}: {_e_rc}")

            # ── Сайт не уложился в срок, но код у него уже использован ──────
            # Ровно то, что 18.09.2026 Александр делал руками кнопкой
            # «Проверить сейчас»: прогнать сверку по этому коду немедленно.
            # Она подтвердит личность по Organization ID или почте и, если
            # сойдётся, сама запишет подписку, поправит карточку и напишет
            # клиенту. Не сойдётся — пойдём дальше объявлять неудачу, как и
            # раньше. Нажимать кнопку самому больше не нужно.
            if result.get("site_claimed"):
                # Сверка запускается НЕ один раз. Она подтверждает личность по
                # Organization ID или почте, а сайт публикует их только вместе
                # с «fulfilled». Единственная попытка почти всегда приходилась
                # на «claimed», когда подтверждать ещё нечем, — и заказ уходил
                # в неудачу, хотя через пару минут та же сверка его закрывала
                # (кнопкой «Проверить сейчас» или фоном). Три захода с паузой
                # в минуту перекрывают этот разрыв; фоновая сверка раз в пять
                # минут остаётся последним рубежом.
                import asyncio as _aio_sc
                for _try_sc in range(3):
                    try:
                        _rr = await gpt_reconcile_orphans(only_code=code)
                        if _rr.get("fixed"):
                            logging.warning(
                                f"GPT: {code} закрыт сверкой после таймаута "
                                f"(попытка {_try_sc + 1}, сайт: "
                                f"{result.get('site_status') or '?'}).")
                            _activation_jobs[job_id] = {"status": "done", "success": True}
                            return
                    except Exception as _e_sc:
                        logging.warning(f"GPT: срочная сверка {code} "
                                        f"(попытка {_try_sc + 1}): {_e_sc}")
                    if _try_sc < 2:
                        await _aio_sc.sleep(60)
                logging.warning(
                    f"GPT: {code} — сайт считает код использованным, но за три "
                    f"захода сверка личность не подтвердила; объявляю неудачу.")

            _plan_key = plan_name_to_key(plan_name)
            import urllib.parse as _uparse2
            from aiogram.types import WebAppInfo as _WebAppInfo

            # ── needs_force_confirm: у аккаунта уже есть активная подписка. Спрашиваем
            #    клиента и, если подтвердит, активируем принудительно (force=1). Код НЕ трогаем.
            if result.get("needs_force_confirm"):
                import urllib.parse as _uparse_f
                from aiogram.types import WebAppInfo as _WebAppInfoF
                _acc = result.get("already_account") or ""
                _until = result.get("already_until") or ""
                _force_url = (
                    webapp_url("/webapp/chatgpt", plan=plan_name, code=code, force="1")
                )
                try:
                    # Было «уже есть подписка ChatGPT Plus» — в том числе клиенту,
                    # купившему Go, и без второго выхода «другой аккаунт». 07.10.2026
                    import html as _h_fc
                    await bot.send_message(
                        user_id,
                        "⚠️ <b>Активация на паузе — на аккаунте уже есть действующая подписка ChatGPT.</b>"
                        + (f"\n📧 Аккаунт: <code>{_h_fc.escape(str(_acc))}</code>" if _acc else "")
                        + (f"\n📅 Действует до: <b>{_h_fc.escape(str(_until))}</b>" if _until else "")
                        + f"\n\n{_GPT_PAID_LINE}\n"
                          "👉 Выбери одно:\n"
                          "• <b>«Активировать поверх»</b> — новая подписка начнётся сейчас, "
                          "остаток текущей может сгореть (не суммируется).\n"
                          "• <b>«Другой аккаунт»</b> — войди в ChatGPT в аккаунт без подписки "
                          "и вставь текст со страницы <b>chatgpt.com/api/auth/session</b> заново.",
                        parse_mode="HTML",
                        reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                            [InlineKeyboardButton(text="⚡ Активировать поверх",
                                                  web_app=_WebAppInfoF(url=_force_url))],
                            [InlineKeyboardButton(text="🔄 Другой аккаунт",
                                                  web_app=_WebAppInfoF(url=webapp_url(
                                                      "/webapp/chatgpt", plan=plan_name, code=code))),
                             InlineKeyboardButton(text="💬 Поддержка",
                                                  url=f"https://t.me/{PERSONAL_USERNAME}")],
                        ])
                    )
                except Exception as _fe:
                    logging.error(f"needs_force_confirm msg: {_fe}")
                _gf_mid = await _admin_fail_shot(
                    "⚠️ <b>ChatGPT — у аккаунта уже есть Plus</b> (клиенту предложено активировать принудительно)\n\n"
                    f"👤 {_who_u} · {plan_name}\n"
                    f"🔑 <code>{code}</code>\n"
                    f"📧 {_acc or '—'}" + (f" · до {_until}" if _until else "")
                    + f"\n🆔 <code>{order_id}</code>\n"
                    + await _actx(),
                    result.get("screenshot"))
                # Клиент подтвердит отдельным запуском, возможно после редеплоя —
                # id сообщения кладём в настройку, чтобы потом переписать его
                # в «успешно» и не оставлять висящих предупреждений.
                if _gf_mid:
                    try:
                        await set_setting(f"gpt_confirm_msg:{order_id}", str(_gf_mid))
                    except Exception as _e_gf:
                        logging.warning(f"gpt confirm msg id: {_e_gf}")
                _activation_jobs[job_id] = {"status": "done", "success": False, "need_force": True,
                                            "account": _acc, "until": _until,
                                            "error": "На аккаунте уже есть действующая подписка ChatGPT."}
                return

            # ── Тип ошибки определяет что делать дальше ──────────────────────
            # needs_check: активация МОГЛА пройти (сайт был в процессе). НЕ блэймим токен,
            # НЕ даём авто-повтор (риск двойной активации), код не трогаем; клиенту —
            # нейтральный экран, админу — скриншот на ручную проверку.
            if result.get("needs_check"):
                try:
                    await bot.send_message(
                        user_id, _GPT_PROCESSING_TEXT,
                        parse_mode="HTML", reply_markup=_gpt_support_kb())
                except Exception:
                    pass
                await _admin_fail_shot(
                    "⚠️ <b>ChatGPT — нужна ручная проверка</b>\n\n"
                    f"👤 {_who_u} · {plan_name}\n{await _actx()}"
                    f"🔑 <code>{code}</code>\n"
                    f"{error_text}\n\n"
                    f"Проверь на {gpt_provider_name(provider)} по email клиента ПЕРЕД повторной активацией (риск двойной).",
                    result.get("screenshot"), order_id=order_id)
                _activation_jobs[job_id] = {"status": "done", "success": False, "pending": True,
                                            "error": _GPT_PROCESSING_WEB}
                return

            _token_invalid = result.get("token_invalid", False)
            _fail_kind = _gpt_fail_kind(result)
            # Сайт держит код в «claimed» (или не уложился в срок): активация,
            # скорее всего, идёт и дозреет сама. Это не «попытка не удалась»:
            # «Повторить» здесь только навредит. Клиенту — «обрабатывается,
            # 10–15 минут», карточка Александру уходит как обычно. 07.10.2026
            # Пустая ошибка — исход неизвестен, ниже включается слежение: это
            # тоже «обрабатывается», а не «попытка не удалась» с «Повторить».
            _client_processing = bool(result.get("site_claimed")
                                      or "долго обрабатывал" in (error_text or "")
                                      or not (result.get("error") or "").strip())

            if _token_invalid:
                # Токен от клиента невалидный/истёк — код не трогаем, просим переcкопировать
                # Pending остаётся с тем же кодом, сессия жива
                _same_url = (
                    webapp_url("/webapp/chatgpt", plan=plan_name, code=code)
                )
                try:
                    # Текст Александра 06.10.2026: что случилось, что с деньгами,
                    # одно действие. Кнопка «Поддержка» — ссылка на Александра.
                    await bot.send_message(
                        user_id,
                        _GPT_TOKEN_FAIL_TEXT,
                        parse_mode="HTML",
                        reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
                            InlineKeyboardButton(text="🔄 Повторить",
                                                 web_app=_WebAppInfo(url=_same_url)),
                            InlineKeyboardButton(text="💬 Поддержка",
                                                 url=f"https://t.me/{PERSONAL_USERNAME}"),
                        ]])
                    )
                except Exception as _te:
                    logging.error(f"Token invalid message failed: {_te}")

            elif result.get("site_paused"):
                # Три попытки за три минуты — сайт всё ещё чинят. Код цел и
                # закреплён за клиентом: сайт прямо пишет «codes stay valid».
                # Возвращать его в пул и тревожить «не вернул в пул» не о чем.
                _gpt_retry_counts.pop(user_id, None)
                try:
                    await bot.send_message(
                        user_id,
                        _gpt_wait_text("сайт активации всё ещё на техобслуживании",
                                       "Александр активирует вручную, как только сайт оживёт"),
                        parse_mode="HTML", reply_markup=_gpt_support_kb())
                except Exception:
                    pass
                if _fail_should_alert("gpt", user_id):
                    try:
                        await bot.send_message(
                            ADMIN_ID,
                            f"⏸ <b>ChatGPT — сайт на техобслуживании</b>\n"
                            f"👤 {_who_u} · {plan_name}\n"
                            f"🔑 <code>{code}</code>\n"
                            f"🆔 <code>{order_id}</code>\n"
                            + await _actx()
                            + f"❗ {error_text}\n\n"
                            f"Пробовал сам 3 раза с паузой в минуту — сайт всё "
                            f"ещё закрыт. Код ЦЕЛ и закреплён за клиентом, "
                            f"в пул не возвращён. Как оживёт — активируй его "
                            f"или дай клиенту нажать «Активировать» заново.",
                            parse_mode="HTML")
                    except Exception:
                        pass
                _activation_jobs[job_id] = {
                    "status": "done", "success": False, "manual": True,
                    "error": _gpt_wait_web("сайт активации на техобслуживании",
                                           "Александр активирует вручную, как только сайт оживёт")}
                return

            elif result.get("out_of_stock"):
                # Нет свободных мест на сайте — токен клиента тут ни при чём.
                # Раньше этот случай попадал в общую ветку и бот советовал
                # «обнови токен», хотя обновляй не обновляй — мест нет.
                _gpt_retry_counts.pop(user_id, None)
                try:
                    await bot.send_message(
                        user_id,
                        _gpt_wait_text("на сайте активации сейчас нет свободных мест"),
                        parse_mode="HTML", reply_markup=_gpt_support_kb())
                except Exception:
                    pass
                if _fail_should_alert("gpt", user_id):
                    try:
                        await bot.send_message(
                            ADMIN_ID,
                            f"🚨 <b>ChatGPT — на сайте нет мест</b>\n"
                            f"👤 {_who_u} · {plan_name}\n"
                            f"🔑 <code>{code}</code>\n"
                            f"🆔 <code>{order_id}</code>\n"
                            + await _actx()
                            + f"❗ {error_text}\n\n"
                            f"Код за клиентом, не сожжён. Активируй вручную.",
                            parse_mode="HTML")
                    except Exception:
                        pass
                _activation_jobs[job_id] = {
                    "status": "done", "success": False, "manual": True,
                    "error": _gpt_wait_web("на сайте активации сейчас нет свободных мест")}
                return
            elif _client_processing:
                # Сайт держит код — активация, скорее всего, дозреет. Клиенту —
                # «обрабатывается», без «Повторить»; слежение за кодом включаем,
                # чтобы бот сам написал клиенту, когда сайт закончит.
                try:
                    _k_cp = f"gptclaim:{str(code).strip().upper()}"
                    if not (await get_setting(_k_cp, "") or "").strip():
                        import time as _t_cp
                        await set_setting(
                            _k_cp, f"{user_id}|{order_id or ''}|{int(_t_cp.time())}|")
                except Exception as _e_cp:
                    logging.warning(f"GPT: слежение за {code}: {_e_cp}")
                try:
                    await bot.send_message(user_id, _GPT_PROCESSING_TEXT, parse_mode="HTML",
                                           reply_markup=_gpt_support_kb())
                except Exception:
                    pass
            else:
                # Другая ошибка (таймаут, сеть, неизвестное) — код остаётся тем же
                # Считаем попытки только для не-токенных ошибок
                _gpt_retry_counts.setdefault(user_id, 0)
                _gpt_retry_counts[user_id] += 1
                attempt = _gpt_retry_counts[user_id]
                MAX_RETRIES = 3

                if attempt < MAX_RETRIES:
                    # Pending остаётся, код тот же — клиент просто повторяет
                    _same_url = (
                        webapp_url("/webapp/chatgpt", plan=plan_name, code=code)
                    )
                    try:
                        # Сырой ответ сайта клиенту больше не показываем: бывал
                        # английским, с кодами HTTP, а символ «<» в нём срывал
                        # отправку всего сообщения (HTML). Он уходит Александру.
                        # «Бесплатный план» тоже убран: Go и iOS-коды ложатся на
                        # любой аккаунт, совет отпугивал. 06.10.2026
                        # Подсказка — по виду ошибки: что случилось и что
                        # изменить. «Повторить» — только там, где повтор может
                        # помочь (при проблеме с кодом на нашей стороне — нет).
                        # Александр 07.10.2026.
                        await bot.send_message(
                            user_id,
                            _gpt_fail_text(_fail_kind, attempt, MAX_RETRIES),
                            parse_mode="HTML",
                            reply_markup=_gpt_support_kb(
                                _same_url if _GPT_FAIL_HINTS.get(
                                    _fail_kind, _GPT_FAIL_HINTS["unknown"])[2] else ""))
                    except Exception as _re:
                        logging.error(f"Retry message failed: {_re}")
                else:
                    # Исчерпаны авто-попытки. ВАЖНО: код и pending НЕ трогаем —
                    # чтобы клиент не упирался в «Время сессии истекло», а Александр
                    # мог активировать вручную тем же кодом. Код освободится сам через
                    # ~2 часа (gpt_codes_cleanup_loop), если активация так и не случится.
                    _gpt_retry_counts.pop(user_id, None)
                    try:
                        await bot.send_message(
                            user_id,
                            f"😔 <b>Активация не прошла автоматически</b> "
                            f"(все {MAX_RETRIES} попытки).\n\n"
                            f"💳 Оплата сохранена, код за тобой.\n"
                            f"👉 Ничего больше делать не нужно — Александр уже получил "
                            f"уведомление и активирует подписку вручную этим же кодом. "
                            f"Хочешь быстрее — нажми «Поддержка».",
                            parse_mode="HTML",
                            reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
                                InlineKeyboardButton(text="💬 Поддержка",
                                                     url=f"https://t.me/{PERSONAL_USERNAME}"),
                            ]])
                        )
                    except Exception:
                        pass
                    # Уведомляем Александра С КОДОМ — чтобы активировал вручную (не чаще 1/15 мин на клиента)
                    if _fail_should_alert("gpt", user_id):
                        await _admin_fail_shot(
                            "🚨 <b>Авто-активация ChatGPT не удалась</b>\n\n"
                            f"👤 {_who_u}\n"
                            f"🔑 Код: <code>{code}</code>\n"
                            f"📦 Тариф: <b>{plan_name}</b>\n"
                            f"🆔 Заказ: <code>{order_id}</code>\n"
                            + await _actx()
                            + f"⚠️ Ошибка: {error_text}\n\n"
                            "Код зарезервирован за клиентом — активируй вручную ИМ ЖЕ.",
                            result.get("screenshot"), order_id=order_id
                        )
                    _activation_jobs[job_id] = {
                        "status": "done", "success": False,
                        "manual": True,   # без «Попробовать снова» — текст говорит «не повторяй»
                        "error": ("Активация не прошла автоматически. Оплата сохранена, код за тобой — "
                                  "Александр уже знает и активирует вручную, повторять не нужно.")
                    }
                    return  # выходим, не перезаписываем job ниже

            # ── Сайт не назвал причину — значит исход НЕИЗВЕСТЕН ──────────
            # Это не «не получилось», это «мы не знаем». В такие моменты
            # активация у сайта часто ещё ИДЁТ и дозревает через минуту-другую,
            # а клиент уже видел красное «Не получилось» и считал, что
            # подписки нет. Теперь задача остаётся В РАБОТЕ: мини-апп
            # продолжает крутить, а бот следит за кодом до конечного
            # состояния — fulfilled или unused. Александр 02.10.2026.
            if not (result.get("error") or "").strip():
                import time as _t_job
                _activation_jobs[job_id] = {
                    "status": "pending", "watching": True,
                    "code": str(code), "user_id": int(user_id),
                    "order_id": str(order_id or ""),
                    "since": int(_t_job.time()),
                    "note": "Сайт обрабатывает запрос — слежу за активацией."}
                try:
                    _k_nw = f"gptclaim:{str(code).strip().upper()}"
                    if not (await get_setting(_k_nw, "") or "").strip():
                        import time as _t_nw
                        await set_setting(
                            _k_nw,
                            f"{user_id}|{order_id or ''}|{int(_t_nw.time())}|")
                except Exception as _e_nw:
                    logging.warning(f"GPT: слежение за {code}: {_e_nw}")
                logging.warning(f"GPT: {code} — сайт не объяснил причину, "
                                f"клиенту ошибку НЕ показываю, слежу за кодом.")
            else:
                # Клиенту в мини-приложении — человеческий текст, а не сырой
                # ответ сайта (бывал английским, с кодами HTTP). Сам текст
                # ошибки уходит Александру ниже. 06.10.2026
                if _client_processing:
                    _activation_jobs[job_id] = {"status": "done", "success": False,
                                                "pending": True, "error": _GPT_PROCESSING_WEB}
                else:
                    _activation_jobs[job_id] = {
                        "status": "done", "success": False,
                        # без «Попробовать снова», если повтор не поможет
                        "manual": not _GPT_FAIL_HINTS.get(
                            _fail_kind, _GPT_FAIL_HINTS["unknown"])[2],
                        "error": (_GPT_TOKEN_FAIL_WEB if _token_invalid
                                  else _gpt_fail_web(_fail_kind))}
            if _fail_should_alert("gpt", user_id):
              try:
                import datetime as _dt
                _fail_at = _dt.datetime.now(_BOT_TZ).strftime("%d.%m.%Y %H:%M")
                try:
                    _pool2 = await get_pool()
                    async with _pool2.acquire() as _conn2:
                        _urow2 = await _conn2.fetchrow(
                            "SELECT username, full_name FROM users WHERE user_id=$1", user_id
                        )
                    _un2 = _urow2["username"]  if _urow2 and _urow2["username"]  else ""
                    _fn2 = _urow2["full_name"] if _urow2 and _urow2["full_name"] else ""
                except Exception:
                    _un2 = _fn2 = ""
                import html as _h_tg2
                _tg2 = (f"@{_un2}" if _un2 else _h_tg2.escape(strip_surrogates(_fn2 or ""))) or f"id{user_id}"
                screenshot = result.get("screenshot")
                txt = (
                    f"❌ <b>ChatGPT авто-активация НЕУДАЧА</b>\n\n"
                    f"👤 Клиент: <b>{_tg2}</b>  (<code>{user_id}</code>)\n"
                    f"🔑 Код: <code>{code}</code>\n"
                    f"📦 Тариф: <b>{plan_name}</b>\n"
                    f"⏱ Время: <b>{_fail_at}</b>\n"
                    f"🧭 Пробовали: {', '.join(gpt_provider_name(_p) for _p in _tried_sites)}\n"
                    + await _actx(show_site=False, show_route=False)   # маршрут — в «Причине»
                    + f"❗ {error_text}\n"
                    + _gpt_fail_why(result, code)
                )
                # Сайт не успел за отведённые 5 минут — это НЕ отказ. Он почти
                # всегда дозавершает заказ через минуту-другую. Называть это
                # «неудачей» без оговорки значит каждый раз пугать зря.
                _slow = "долго обрабатывал" in (error_text or "")
                if _slow:
                    txt += ("\n⏳ Сайт не уложился в отведённые 5 минут. Чаще "
                            "всего он дозавершает заказ через минуту-другую — "
                            "тогда сверка закроет его сама.\n"
                            "Не хочешь ждать — нажми кнопку ниже.")
                else:
                    txt += "🔒 Код закреплён за клиентом — активируй вручную ИМ ЖЕ."
                # Кнопка проверки: сверка сама зайдёт сюда в течение 5 минут, но
                # ждать не обязательно — по нажатию проверяем этот код сразу.
                _kb_rc = InlineKeyboardMarkup(inline_keyboard=[[
                    InlineKeyboardButton(text="🔄 Проверить сейчас",
                                         callback_data=f"gptrc:{code}")]])
                if screenshot and len(txt) > 1000:
                    # Подпись к фото — максимум 1024 символа, а с контекстом
                    # заказа карточка бывает длиннее: шлём текстом, фото — следом.
                    _m_fin = await bot.send_message(ADMIN_ID, txt, parse_mode="HTML",
                                                    reply_markup=_kb_rc)
                    try:
                        await bot.send_photo(ADMIN_ID, BufferedInputFile(screenshot, "err.png"))
                    except Exception as _e_ph:
                        logging.warning(f"gpt fail photo: {_e_ph}")
                    screenshot = None   # ниже: id текста можно запомнить для правки
                elif screenshot:
                    _m_fin = await bot.send_photo(
                        ADMIN_ID, BufferedInputFile(screenshot, "err.png"),
                        caption=txt, parse_mode="HTML", reply_markup=_kb_rc)
                else:
                    _m_fin = await bot.send_message(ADMIN_ID, txt, parse_mode="HTML",
                                                    reply_markup=_kb_rc)
                # Это сообщение Александр видит чаще всех. Если сверка потом
                # закроет заказ, оно перепишется в «активация прошла».
                # Фото не переписывается текстом — только обычное сообщение.
                if (not screenshot) and order_id and getattr(_m_fin, "message_id", None):
                    try:
                        await set_setting(f"gpt_confirm_msg:{order_id}",
                                          str(_m_fin.message_id))
                    except Exception as _e_fin:
                        logging.warning(f"gpt confirm msg id (final): {_e_fin}")
                # Карточка — это и есть объявление «активация не удалась, код
                # в claimed, разбираюсь». Значит петле слежения повторять
                # «активация идёт» уже не нужно: ставим ей флаг «объявлено».
                try:
                    _k_card = f"gptclaim:{str(code).strip().upper()}"
                    _v_card = (await get_setting(_k_card, "") or "").strip()
                    if _v_card:
                        _pc = _v_card.split("|")
                        while len(_pc) < 4:
                            _pc.append("")
                        if "a" not in _pc[3]:
                            _pc[3] += "a"
                            await set_setting(_k_card, "|".join(_pc[:4]))
                except Exception as _e_card:
                    logging.warning(f"gpt: флаг объявления по {code}: {_e_card}")
              except Exception:
                pass
    except Exception as e:
        import html as _h_ie
        logging.error(f"_run_activation_job {job_id}: {e}", exc_info=True)
        _activation_jobs[job_id] = {
            "status": "done", "success": False, "manual": True,
            "error": ("Внутренняя ошибка бота. Оплата сохранена, код за тобой — "
                      "нажми «Написать Александру», активируем вручную.")
        }
        # Раньше об этом знал только лог — клиент ждал, а ты не знал, что ждать.
        try:
            await bot.send_message(
                ADMIN_ID,
                f"🧨 <b>ChatGPT — внутренняя ошибка активации</b>\n"
                f"👤 {await _who_user(user_id)} · {plan_name}\n"
                f"🔑 <code>{code}</code>\n"
                + await _adm_gpt_ctx(order_id, code, provider, session_raw or access_token, uid=user_id)
                + f"❗ <code>{_h_ie.escape((type(e).__name__ + ': ' + str(e))[:300])}</code>\n\n"
                  f"Код за клиентом. Клиенту показано: «внутренняя ошибка, напиши Александру».",
                parse_mode="HTML")
        except Exception as _e_ie:
            logging.warning(f"внутренняя ошибка: не сообщил админу: {_e_ie}")
    finally:
        # снимаем метку активной активации клиента (защита от двойного запуска)
        try:
            if _gpt_job_active.get(user_id) == job_id:
                _gpt_job_active.pop(user_id, None)
        except Exception:
            pass
        try:
            await release_gpt_activation(user_id)
        except Exception as _e_rel:
            logging.warning(f"release_gpt_activation uid={user_id}: {_e_rel}")


# Клиенты, уже предупреждённые о повторной активации.
# Повторное нажатие «Попробовать снова» = принудительная активация (на другой аккаунт).
#
# Раньше это жило ТОЛЬКО в памяти процесса: любой деплой или рестарт стирал
# отметку, и клиент, уже нажавший «Попробовать снова», получал предупреждение
# заново — и не мог активировать, пока не нажмёт ещё раз. Теперь отметка
# дублируется в settings и живёт час; память остаётся быстрым кэшем.
# _gpt_double_warned убран вместе с предупреждением о повторной активации
# ChatGPT (18.09.2026): ссылаться на него стало нечему. У Perplexity свой
# набор, у Claude — свой, они не тронуты.
_claude_double_warned: set = set()
_DBL_WARN_TTL = 3600  # секунд: через час предупредим снова (это защита, а не помеха)


async def _dbl_warned_is(kind: str, uid: int, mem: set) -> bool:
    if uid in mem:
        return True
    try:
        import time as _t_dw
        _ts = await get_setting(f"dblwarn:{kind}:{uid}", "") or ""
        if _ts and (_t_dw.time() - float(_ts)) < _DBL_WARN_TTL:
            mem.add(uid)
            return True
    except Exception:
        pass
    return False


async def _dbl_warned_set(kind: str, uid: int, mem: set):
    mem.add(uid)
    try:
        import time as _t_dw
        await set_setting(f"dblwarn:{kind}:{uid}", str(_t_dw.time()))
    except Exception as _e_dw:
        logging.warning(f"dblwarn set {kind}:{uid}: {_e_dw}")


async def _dbl_warned_clear(kind: str, uid: int, mem: set):
    mem.discard(uid)
    try:
        await set_setting(f"dblwarn:{kind}:{uid}", "")
    except Exception as _e_dw:
        logging.warning(f"dblwarn clear {kind}:{uid}: {_e_dw}")

# Антиспам алертов о НЕУДАЧНОЙ активации: не чаще 1 раза в 15 мин на (сервис, клиент).
# Успех сбрасывает троттл (следующий сбой снова уведомит сразу).
_fail_alert_at: dict = {}
def _fail_should_alert(service: str, user_id: int, window: int = 900) -> bool:
    import time as _t
    _k = (service, user_id)
    _now = _t.time()
    if _now - _fail_alert_at.get(_k, 0.0) >= window:
        _fail_alert_at[_k] = _now
        return True
    return False
def _fail_clear(service: str, user_id: int):
    _fail_alert_at.pop((service, user_id), None)

