async def _playwright_launch_ok() -> bool:
    """Единственная НАДЁЖНАЯ проверка — реально запустить браузер. glob по папкам
    не ловит рассинхрон версий playwright ↔ скачанной сборки браузера (после апгрейда
    playwright папка chromium-* остаётся старой и launch падает 'Failed to launch')."""
    try:
        from playwright.async_api import async_playwright
        async with async_playwright() as p:
            b = await p.chromium.launch(
                headless=True,
                args=["--no-sandbox", "--disable-dev-shm-usage", "--disable-gpu",
                      "--disable-setuid-sandbox", "--single-process"])
            await b.close()
        return True
    except Exception as e:
        logging.warning(f"playwright launch-test failed: {str(e)[:220]}")
        return False


async def _pw_install(browsers_path: str, with_deps: bool) -> int:
    os.environ["PLAYWRIGHT_BROWSERS_PATH"] = browsers_path
    env = {**os.environ, "PLAYWRIGHT_BROWSERS_PATH": browsers_path}
    args = ["python", "-m", "playwright", "install"] + (["--with-deps"] if with_deps else []) + ["chromium"]
    logging.warning(f"⚠️ Ставим Playwright chromium в {browsers_path} (with_deps={with_deps}, ~2-3 мин)...")
    try:
        proc = await asyncio.create_subprocess_exec(
            *args, env=env,
            stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE)
        _, stderr = await proc.communicate()
        if proc.returncode != 0:
            logging.error(f"playwright install rc={proc.returncode}: {stderr.decode()[:300]}")
        return proc.returncode
    except Exception as e:
        logging.error(f"playwright install error: {e}")
        return 1


async def _ensure_playwright_browser():
    """
    Гарантирует РАБОТОСПОСОБНЫЙ Playwright Chromium (а не просто наличие папки).

    В идеале браузер скачан при сборке (Nixpacks) в /app/pw-browsers/. Но если
    playwright обновился, а браузер остался старой сборки — launch падает. Поэтому
    проверяем именно запуском и при неудаче переустанавливаем под текущую версию.
    """
    import glob

    # 1) Пробуем уже имеющийся браузер в известных путях — проверяя ЗАПУСКОМ.
    for browsers_path in ["/app/pw-browsers", "/tmp/pw-browsers"]:
        if glob.glob(f"{browsers_path}/chromium*"):
            os.environ["PLAYWRIGHT_BROWSERS_PATH"] = browsers_path
            if await _playwright_launch_ok():
                logging.info(f"✅ Playwright OK: {browsers_path}")
                return

    # 2) Не запускается — (пере)устанавливаем браузер под ТЕКУЩУЮ версию playwright.
    #    Сначала в персистентный /app с системными зависимостями, затем /tmp как запас.
    for browsers_path, with_deps in [("/app/pw-browsers", True), ("/tmp/pw-browsers", False)]:
        await _pw_install(browsers_path, with_deps)
        os.environ["PLAYWRIGHT_BROWSERS_PATH"] = browsers_path
        if await _playwright_launch_ok():
            logging.info(f"✅ Playwright установлен и запускается: {browsers_path}")
            return

    logging.error("❌ Playwright браузер не удалось подготовить — браузерные активации будут падать. "
                  "Проверь системные библиотеки/деплой.")


async def _check_one_gpt_code(code_row: dict) -> str:
    """Проверяет один код. Возвращает новый check_status."""
    from chatgpt_activation import check_gpt_code
    try:
        result = await check_gpt_code(code_row["code"])
        return result.get("status", "error"), result.get("email", "")
    except Exception as e:
        logging.error(f"_check_one_gpt_code {code_row['code']}: {e}")
        return "error", ""


# ─── Мультипровайдер Claude: выбор активного сайта + авто-фолбэк ──────────────
async def _claude_active_provider() -> str:
    p = await get_setting("claude_provider", CLAUDE_DEFAULT_PROVIDER) or CLAUDE_DEFAULT_PROVIDER
    return p if p in CLAUDE_PROVIDERS else CLAUDE_DEFAULT_PROVIDER


async def _claude_failover_on() -> bool:
    return (await get_setting("claude_failover", "1") or "1") == "1"


async def _claude_provider_order() -> list:
    """Активный провайдер первым; при включённом фолбэке — остальные следом."""
    active = await _claude_active_provider()
    order = [active]
    if await _claude_failover_on():
        for p in CLAUDE_PROVIDER_ORDER:
            if p in CLAUDE_PROVIDERS and p not in order:
                order.append(p)
    return order


async def _claude_pick_code(plan: str):
    """Берёт код из пула активного провайдера. Если пусто и включён фолбэк —
    пробует остальные сайты. Возвращает (code, provider) либо (None, None).
    При уходе на запасной сайт уведомляет админа."""
    order = await _claude_provider_order()
    active = order[0]
    for prov in order:
        code = await get_next_claude_code(plan, prov)
        if code:
            if prov != active:
                try:
                    await bot.send_message(
                        ADMIN_ID,
                        f"🔀 <b>Claude — авто-переключение сайта</b>\n"
                        f"У <b>{claude_provider_name(active)}</b> закончились коды ({plan}).\n"
                        f"Активация ушла на <b>{claude_provider_name(prov)}</b>.\n"
                        f"Пополни коды на {claude_provider_name(active)}.",
                        parse_mode="HTML")
                except Exception:
                    pass
            return code, prov
    return None, None


# ─── Активация Claude через разные API сайтов (bpa | partner) ─────────────────
async def _claude_bpa_redeem(base: str, code: str, org_id: str) -> dict:
    """Первый сайт (bypriceactivate.pro): POST /api/activate {code, org_id}.
    Возвращает нормализованный dict: {ok, ref, err_kind, err_msg}."""
    try:
        async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=30)) as _s:
            async with _s.post(f"{base}/api/activate",
                               json={"code": code, "org_id": org_id},
                               headers={"Content-Type": "application/json"}) as _r:
                try: _d = await _r.json()
                except Exception: _d = {}
                if _r.status == 201:
                    _oid = _d.get("order_id")
                    if not _oid:
                        return {"ok": False, "err_kind": "other", "err_msg": "Сервис не вернул order_id."}
                    return {"ok": True, "ref": str(_oid)}
                if _r.status == 409:
                    _det = _d.get("detail", "")
                    _detl = (_det or "").lower()
                    # ЭТОТ код уже израсходован → берём СЛЕДУЮЩИЙ код того же сайта
                    # (сайт отдаёт разные формулировки: already claimed / already fulfilled / used)
                    if ("already claimed" in _detl or "already fulfilled" in _detl
                            or "fulfilled" in _detl or "already used" in _detl
                            or "already redeemed" in _detl or "code used" in _detl):
                        return {"ok": False, "err_kind": "already_claimed", "err_msg": _det}
                    if ("out of stock" in _detl or "no stock" in _detl
                            or "no available" in _detl or "insufficient" in _detl):
                        return {"ok": False, "err_kind": "out_of_stock", "err_msg": _det}
                    if _blob_has_plan(_det):
                        return {"ok": False, "err_kind": "has_plan", "err_msg": _det}
                    return {"ok": False, "err_kind": "other", "err_msg": _det or "Ошибка кода."}
                if _r.status == 404:
                    return {"ok": False, "err_kind": "not_found", "err_msg": "Код не найден."}
                if _r.status == 400:
                    # по докам: «org_id must be a valid UUID» / «code is required» / «JSON body required»
                    _det4 = (_d.get("detail", "") or "").lower()
                    if "org_id" in _det4 or "uuid" in _det4:
                        return {"ok": False, "err_kind": "bad_org", "err_msg": _d.get("detail", "")}
                    return {"ok": False, "err_kind": "other", "err_msg": _d.get("detail", "") or "HTTP 400"}
                return {"ok": False, "err_kind": "other", "err_msg": f"HTTP {_r.status}"}
    except aiohttp.ClientError as _e:
        return {"ok": False, "err_kind": "network", "err_msg": str(_e)}


# bypriceactivate.pro: регион зашит в ПРЕФИКС кода (AU-… = Австралия, TR-… = Турция).
# Продукт на сайте называется «{база}_{регион}», напр. claude_pro_australia / claude_pro_turkey.
_BPA_REGIONS = {"AU": "australia", "TR": "turkey", "EG": "egypt", "US": "usa",
                "IN": "india", "NG": "nigeria", "BR": "brazil", "ID": "indonesia"}


def _bpa_product_for_code(plan_key: str, code: str) -> str:
    """Определяет продукт bpa по тарифу и префиксу кода. '' — если не удалось."""
    _base = {"pro": "claude_pro", "max_5x": "claude_max_5x",
             "max_20x": "claude_max_20x"}.get((plan_key or "").lower())
    if not _base:
        return ""
    _pref = (code or "").split("-")[0].upper() if "-" in (code or "") else ""
    _reg = _BPA_REGIONS.get(_pref)
    return f"{_base}_{_reg}" if _reg else _base


async def _claude_bpa_stock_product(base: str, product: str) -> int:
    """Сток bypriceactivate.pro по КОНКРЕТНОМУ продукту (GET /api/stock/{product}).
    Возвращает available или -1, если неизвестно (тогда просто пробуем код)."""
    if not product:
        return -1
    try:
        async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=15)) as _s:
            async with _s.get(f"{base}/api/stock/{product}") as _r:
                if _r.status != 200:
                    return -1
                _d = await _r.json()
        return int(_d.get("available", -1))
    except Exception:
        return -1


def _blob_has_plan(s: str) -> bool:
    """Признаки того, что у аккаунта клиента УЖЕ есть активная подписка Claude
    (клиент может исправить сам — отменить текущую подписку)."""
    s = (s or "").lower()
    return any(k in s for k in [
        "already subscribed", "active subscription", "existing subscription",
        "already has a subscription", "already a member", "already have",
        "已订阅", "订阅中", "已是会员", "已有订阅", "当前已订阅",
    ])


async def _claude_partner_redeem(cfg: dict, code: str, org_id: str, order_id: str,
                                 run: str = "") -> dict:
    """Второй сайт (rootchatgptplus.com): partner-API.
    POST /api/partner/v1/redemptions  (Bearer + Idempotency-Key)
    body {card_code, organization_id, confirm_overwrite:true}."""
    import json as _json
    import hashlib as _hl_pr
    base = cfg.get("base", ""); key = cfg.get("key", ""); _pn = cfg.get("name", base)
    if not key:
        return {"ok": False, "err_kind": "other",
                "err_msg": f"Ключ сайта {_pn} не задан (переменная окружения с API-ключом)."}
    # Ключ идемпотентности — на ОДИН запрос (заказ + код + прогон цепочки).
    # Был один на весь заказ («GPT11-{order}»): второй код того же заказа
    # уходил с тем же ключом, и сайт по правилам идемпотентности вправе вернуть
    # ответ на ПЕРВЫЙ запрос — «card_used» / «no_stock» чужого кода. Повтор
    # того же запроса после обрыва связи идёт с тем же ключом — так сайт не
    # проведёт активацию дважды. 08.10.2026
    headers = {
        "Authorization": f"Bearer {key}",
        "Content-Type": "application/json",
        "Idempotency-Key": "GPT11-" + _hl_pr.md5(
            f"{order_id}|{str(code).strip().upper()}|{run}".encode("utf-8")).hexdigest()[:24],
    }
    _http, _txt, _d = 0, "", {}
    _was_unclear = False   # первая попытка оборвалась ПОСЛЕ отправки
    for _try in range(2):
        try:
            async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=30)) as _s:
                async with _s.post(f"{base}/api/partner/v1/redemptions",
                                   json={"card_code": code, "organization_id": org_id,
                                         "confirm_overwrite": True},
                                   headers=headers) as _r:
                    _http = _r.status
                    _txt = await _r.text()
                    try: _d = _json.loads(_txt)
                    except Exception: _d = {}
            if _http in (500, 502, 504):
                # 500/502/504: запрос мог дойти и выполниться (503 «недоступен»
                # — отказ ДО обработки, его разбираем ниже как обычный сбой).
                # Повтор с тем же ключом безопасен; не помогло — исход неясен.
                if _try == 0:
                    logging.warning(f"partner redeem {_pn}: HTTP {_http} — повтор тем же ключом")
                    _was_unclear = True
                    await asyncio.sleep(3)
                    continue
                logging.error(f"partner redeem {_pn} HTTP {_http}: {_txt[:300]}")
                return {"ok": False, "err_kind": "unclear",
                        "err_msg": f"сайт ответил HTTP {_http} дважды"}
            break
        except aiohttp.ClientConnectorError as _e_cc:
            # Соединиться не удалось — ЭТОТ запрос до сайта не дошёл. Но если
            # первая попытка оборвалась после отправки, исход всё равно неясен.
            if _was_unclear:
                return {"ok": False, "err_kind": "unclear",
                        "err_msg": f"обрыв после отправки, повтор не соединился: {_e_cc}"}
            return {"ok": False, "err_kind": "network", "err_msg": str(_e_cc)}
        except (aiohttp.ClientError, asyncio.TimeoutError) as _e_pr:
            # Обрыв ПОСЛЕ отправки: сайт мог принять код. Повторяем тем же
            # ключом — сайт вернёт ответ на исходный запрос. Не вышло — исход
            # неясен, решает Александр.
            if _try == 0:
                logging.warning(f"partner redeem {_pn}: обрыв ({type(_e_pr).__name__}) — повтор тем же ключом")
                _was_unclear = True
                await asyncio.sleep(3)
                continue
            return {"ok": False, "err_kind": "unclear",
                    "err_msg": f"{type(_e_pr).__name__}: {_e_pr}"}
    # После обрыва первой попытки любой ответ, кроме успеха, неоднозначен:
    # «card_used» может значить, что код списал НАШ же первый запрос.
    if _was_unclear and not (isinstance(_d, dict) and _d.get("code") == 0):
        logging.error(f"partner redeem {_pn}: после обрыва ответ HTTP {_http}: {_txt[:300]}")
        return {"ok": False, "err_kind": "unclear",
                "err_msg": f"после обрыва связи сайт ответил: {(_txt or '')[:150]}"}
    try:
        if _d.get("code") == 0:
            _data = _d.get("data") or {}
            _ref = str(_data.get("order_no") or "")
            if not _ref:
                return {"ok": False, "err_kind": "other", "err_msg": "Сайт не вернул order_no."}
            return {"ok": True, "ref": _ref}
        # логируем сырой ответ сайта для диагностики
        logging.error(f"partner redeem {_pn} HTTP {_http}: {_txt[:600]}")
        # ошибка: маппим по ключевым словам в ответе
        _blob = _json.dumps(_d, ensure_ascii=False).lower() if _d else (_txt or "").lower()
        if "card_used" in _blob or "已使用" in _blob:
            return {"ok": False, "err_kind": "already_claimed", "err_msg": "card_used"}
        if "no_stock" in _blob or "库存" in _blob:
            return {"ok": False, "err_kind": "out_of_stock", "err_msg": "no_stock"}
        if "invalid_card" in _blob:
            return {"ok": False, "err_kind": "not_found", "err_msg": "invalid_card"}
        if "invalid_organization_id" in _blob:
            return {"ok": False, "err_kind": "bad_org", "err_msg": "invalid_organization_id"}
        if _blob_has_plan(_blob):
            return {"ok": False, "err_kind": "has_plan", "err_msg": "already_subscribed"}
        if "ip_not_allowed" in _blob:
            return {"ok": False, "err_kind": "other",
                    "err_msg": f"IP сервера (152.55.176.64) не в белом списке {_pn}."}
        if "invalid_api_key" in _blob:
            return {"ok": False, "err_kind": "other", "err_msg": f"Неверный API-ключ сайта {_pn}."}
        if "not found" in _blob or _http == 404:
            return {"ok": False, "err_kind": "other",
                    "err_msg": f"У {_pn} нет partner-API по этому адресу (HTTP {_http}). Нужен свой API/ключ."}
        _msg = str(_d.get("message") or _d.get("error") or f"Ошибка сайта {_pn} (HTTP {_http}).")
        return {"ok": False, "err_kind": "other", "err_msg": _msg}
    except Exception as _e:
        return {"ok": False, "err_kind": "other", "err_msg": f"разбор ответа: {_e}"}


def _ipiap_order_no(order_id: str) -> str:
    """orderNo для ipiap обязан быть ровно 32 символа — берём md5 от нашего order_id
    (детерминированно ⇒ идемпотентно при ретраях)."""
    import hashlib as _hl
    return _hl.md5(f"GPT11-{order_id}".encode("utf-8")).hexdigest()


def _ipiap_sign(body_str: str, secret: str) -> str:
    import hashlib as _hl
    return _hl.md5((body_str + secret).encode("utf-8")).hexdigest()


async def _http_ip_retry(method, url, *, headers=None, data=None, total=30, retries=5):
    """HTTP-запрос с повтором при IP-отказе (403) и сетевой ошибке.
    Railway HA даёт 3 общих egress-IP; часть запросов уходит с не-белого IP и упирается
    в whitelist поставщика (403). Новое соединение может уйти с белого IP — повторяем.
    Безопасно для идемпотентных вызовов: ipiap orderNo и vip666 idempotency_key
    детерминированы, поэтому сервер дедуплицирует повтор, а 403 приходит ДО обработки.
    Возвращает (status, text); status=0 при полном провале сети."""
    _st, _tx = 0, ""
    for _i in range(retries):
        try:
            async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=total)) as _s:
                async with _s.request(method, url, headers=headers, data=data) as _r:
                    _st = _r.status
                    _tx = await _r.text()
                    if _r.status != 403:
                        return _st, _tx
                    logging.warning(f"_http_ip_retry 403 (попытка {_i+1}) {url}")
        except aiohttp.ClientError as _e:
            _st, _tx = 0, str(_e)
        await asyncio.sleep(0.6)
    return _st, _tx


async def _claude_order_redeem(cfg: dict, code: str, org_id: str, order_id: str) -> dict:
    """Сайт ipiap.com: order-API с подписью MD5.
    POST /api/order/create  header sign=MD5(body+apiSecret),
    body {apiId, orderNo(32), serialNumber, organizationId}."""
    import json as _json
    base = cfg.get("base", ""); api_id = cfg.get("api_id", ""); secret = cfg.get("api_secret", "")
    _pn = cfg.get("name", base)
    if not api_id or not secret:
        return {"ok": False, "err_kind": "other",
                "err_msg": f"Не заданы apiId/apiSecret сайта {_pn} "
                           f"(переменные IPIAP_CLAUDE_API_ID / IPIAP_CLAUDE_API_SECRET)."}
    order_no = _ipiap_order_no(order_id)
    body = {"apiId": api_id, "orderNo": order_no, "serialNumber": code}
    if org_id:
        body["organizationId"] = org_id
    body_str = _json.dumps(body, ensure_ascii=False, separators=(",", ":"))
    headers = {"sign": _ipiap_sign(body_str, secret), "Content-Type": "application/json"}
    try:
        _http, _txt = await _http_ip_retry("POST", f"{base}/api/order/create",
                                           headers=headers, data=body_str.encode("utf-8"))
        if _http == 0:
            return {"ok": False, "err_kind": "network", "err_msg": _txt}
        try: _d = _json.loads(_txt)
        except Exception: _d = {}
        if _d.get("code") == 0:
            _ref = str((_d.get("data") or {}).get("orderNo") or order_no)
            return {"ok": True, "ref": _ref}
        logging.error(f"order redeem {_pn} HTTP {_http}: {_txt[:600]}")
        _blob = (_txt or "").lower()
        _msg = str(_d.get("msg") or _d.get("message") or f"Ошибка сайта {_pn} (HTTP {_http}).")
        # код не принадлежит этому продавцу (коды из другого источника) — НЕ про подпись/IP
        if ("不是本商户" in _blob or "本商户" in _blob or "not the merchant" in _blob
                or "not your" in _blob or "wrong merchant" in _blob):
            return {"ok": False, "err_kind": "other",
                    "err_msg": f"{_pn}: код не принадлежит этому продавцу (коды из другого источника). {_msg}"}
        if _d.get("code") == 500 or "sign" in _blob:
            return {"ok": False, "err_kind": "other",
                    "err_msg": f"Ошибка подписи/секрета {_pn} (проверь apiSecret/whitelist IP). {_msg}"}
        if _blob_has_plan(_blob):
            return {"ok": False, "err_kind": "has_plan", "err_msg": _msg}
        if "已使用" in _blob or "already" in _blob or "used" in _blob:
            return {"ok": False, "err_kind": "already_claimed", "err_msg": _msg}
        if "库存" in _blob or "stock" in _blob:
            return {"ok": False, "err_kind": "out_of_stock", "err_msg": _msg}
        if "不存在" in _blob or "not found" in _blob or "invalid" in _blob:
            return {"ok": False, "err_kind": "not_found", "err_msg": _msg}
        return {"ok": False, "err_kind": "other", "err_msg": _msg}
    except aiohttp.ClientError as _e:
        return {"ok": False, "err_kind": "network", "err_msg": str(_e)}


async def _claude_order_query(cfg: dict, order_no: str) -> dict:
    """Опрос статуса заказа ipiap: POST /api/order/query.
    Возвращает {status: 'success'|'failed'|'pending', reason}."""
    import json as _json
    base = cfg.get("base", ""); api_id = cfg.get("api_id", ""); secret = cfg.get("api_secret", "")
    body = {"apiId": api_id, "orderNo": order_no}
    body_str = _json.dumps(body, ensure_ascii=False, separators=(",", ":"))
    headers = {"sign": _ipiap_sign(body_str, secret), "Content-Type": "application/json"}
    try:
        _hs, _txt = await _http_ip_retry("POST", f"{base}/api/order/query",
                                         headers=headers, data=body_str.encode("utf-8"), total=20)
        try: _d = _json.loads(_txt)
        except Exception: _d = {}
        _data = _d.get("data") or {}
        _st = _data.get("orderStatus")
        if _st == 2:
            return {"status": "success", "reason": ""}
        if _st == 3:
            return {"status": "failed", "reason": str(_data.get("reason") or "")}
        return {"status": "pending", "reason": ""}
    except Exception as _e:
        return {"status": "pending", "reason": str(_e)}


def _agent_idem(order_id, code) -> str:
    """Идемпотентный ключ для agent-API (vip666): один и тот же для повторов
    одной и той же попытки (order+code). Формат подходит под ^[A-Za-z0-9][...]{7,127}$."""
    import hashlib as _h
    _raw = f"{order_id}:{code}".encode("utf-8")
    return "redeem-" + _h.md5(_raw).hexdigest()   # 7 + 32 = 39 симв.


def _agent_base(cfg: dict) -> str:
    """Нормализует base agent-API: убирает хвостовой /api/agent/v1, если он уже
    включён в VIP666_AGENT_BASE (чтобы не задвоить префикс при сборке URL)."""
    b = (cfg.get("base", "") or "").rstrip("/")
    if b.endswith("/api/agent/v1"):
        b = b[:-len("/api/agent/v1")]
    return b


async def _claude_agent_redeem(cfg: dict, code: str, org_id: str, order_id: str) -> dict:
    """Сайт vip666ai.com: «代理 API v1» (Agent API).
    POST /api/agent/v1/cards/redeem, заголовок X-Agent-API-Key,
    body {card_code, redeem_type:'claude_org_id', target_value/target_confirm=orgId,
    idempotency_key}. Возвращает {ok, ref=idempotency_key} либо err_kind."""
    import json as _json
    base = _agent_base(cfg); key = cfg.get("key", "")
    _pn = cfg.get("name", base)
    if not key:
        return {"ok": False, "err_kind": "other",
                "err_msg": f"Не задан API-ключ сайта {_pn} (переменная VIP666_AGENT_KEY)."}
    if not org_id:
        return {"ok": False, "err_kind": "bad_org",
                "err_msg": f"{_pn}: не передан Organization ID."}
    _idem = _agent_idem(order_id, code)
    body = {"card_code": code, "redeem_type": "claude_org_id",
            "target_value": org_id, "target_confirm": org_id, "idempotency_key": _idem}
    body_str = _json.dumps(body, ensure_ascii=False, separators=(",", ":"))
    headers = {"X-Agent-API-Key": key, "Content-Type": "application/json"}
    try:
        _http, _txt = await _http_ip_retry("POST", f"{base}/api/agent/v1/cards/redeem",
                                           headers=headers, data=body_str.encode("utf-8"))
        if _http == 0:
            return {"ok": False, "err_kind": "network", "err_msg": _txt}
        try: _d = _json.loads(_txt)
        except Exception: _d = {}
        _code = _d.get("code")
        if _code == 0:
            # ref = idempotency_key: по нему опрашиваем статус (GET /redeem/{idem})
            return {"ok": True, "ref": _idem}
        logging.error(f"agent redeem {_pn} HTTP {_http} code={_code}: {_txt[:600]}")
        _msg = str(_d.get("message") or f"Ошибка сайта {_pn} (HTTP {_http}).")
        # Бизнес-коды (HTTP 200): карта/остаток/подтверждение
        if _code == 100102:                     # уже использована → следующий код
            return {"ok": False, "err_kind": "already_claimed", "err_msg": _msg}
        if _code in (100101, 100103):           # невалидна / просрочена → следующий код
            return {"ok": False, "err_kind": "not_found", "err_msg": _msg}
        if _code == 100501 or _http in (500, 503):  # нет остатка / сервис недоступен → следующий сайт
            return {"ok": False, "err_kind": "out_of_stock", "err_msg": _msg}
        if _code == 100401:                     # нужно подтверждение перезаписи = уже есть подписка
            return {"ok": False, "err_kind": "has_plan", "err_msg": _msg}
        if _blob_has_plan((_txt or "").lower()):
            return {"ok": False, "err_kind": "has_plan", "err_msg": _msg}
        if _code == 40300 or _http == 403:      # ключ/scope/источник → это про КОНФИГ, не про код
            _b403 = (_txt or "").lower()
            if "来源" in _b403 or "域名" in _b403 or "origin" in _b403 or "source" in _b403:
                # ключ ограничен по домену-источнику (允许来源). Сервер-к-серверу мы без Origin —
                # админ сайта должен снять ограничение (允许来源 = 未限制) для этого ключа.
                return {"ok": False, "err_kind": "other",
                        "err_msg": f"{_pn}: ключ ограничен по домену-источнику (允许来源). "
                                   f"Попроси админа снять ограничение источника для ключа (未限制). {_msg}"}
            return {"ok": False, "err_kind": "other",
                    "err_msg": f"{_pn}: доступ запрещён (проверь VIP666_AGENT_KEY/scope). {_msg}"}
        if _code == 40900 or _http == 409:      # ещё обрабатывается — уходим в опрос статуса
            return {"ok": True, "ref": _idem}
        # 100301 充值失败 / 40000 / прочее → считаем сбоем сайта, пробуем следующий
        return {"ok": False, "err_kind": "other", "err_msg": _msg}
    except aiohttp.ClientError as _e:
        return {"ok": False, "err_kind": "network", "err_msg": str(_e)}


async def _claude_agent_query(cfg: dict, idem: str) -> dict:
    """Опрос статуса agent-API vip666: GET /api/agent/v1/redeem/{idempotency_key}.
    status: pending|processing|success|failed|review|unknown."""
    import json as _json
    base = _agent_base(cfg); key = cfg.get("key", "")
    headers = {"X-Agent-API-Key": key}
    try:
        _hs, _txt = await _http_ip_retry("GET", f"{base}/api/agent/v1/redeem/{idem}",
                                         headers=headers, total=20)
        try: _d = _json.loads(_txt)
        except Exception: _d = {}
        _st = str(((_d.get("data") or {}).get("status")) or "").lower()
        if _st == "success":
            return {"status": "success", "reason": ""}
        if _st in ("failed", "review"):
            return {"status": "failed", "reason": str((_d.get("data") or {}).get("message") or "")}
        return {"status": "pending", "reason": ""}
    except Exception as _e:
        return {"status": "pending", "reason": str(_e)}


async def _claude_redeem_via(provider: str, code: str, org_id: str, order_id: str,
                             run: str = "") -> dict:
    """Единый вызов активации Claude под любой сайт (по типу api).
    run — номер прогона цепочки (для ключа идемпотентности partner-API)."""
    cfg = CLAUDE_PROVIDERS.get(provider, {})
    if cfg.get("api") == "partner":
        return await _claude_partner_redeem(cfg, code, org_id, order_id, run=run)
    if cfg.get("api") == "agent":
        return await _claude_agent_redeem(cfg, code, org_id, order_id)
    if cfg.get("api") == "order":
        return await _claude_order_redeem(cfg, code, org_id, order_id)
    if cfg.get("api") == "browser":
        # Браузерные сайты (6661231.xyz) активируются отдельной фоновой задачей,
        # синхронный redeem для них не поддерживается (защита от блокировки HTTP).
        return {"ok": False, "err_kind": "other",
                "err_msg": f"{cfg.get('name', provider)} — браузерная активация, не через redeem."}
    return await _claude_bpa_redeem(cfg.get("base", ""), code, org_id)


# ─── Мультипровайдер ChatGPT: выбор активного сайта + авто-фолбэк ─────────────
def _gpt_off_providers() -> set:
    """Сайты, выключенные в коде (не в настройках) — GPT_ENABLED_PROVIDERS.

    Отдельно от паузы в админке: пауза временная и снимается кнопкой, а это
    осознанное отключение старых сайтов. Возврат — правкой списка в config.
    """
    return {p for p in GPT_PROVIDERS if p not in GPT_ENABLED_PROVIDERS}


async def _gpt_active_provider() -> str:
    """Активный сайт. Если в настройке остался выключенный сайт (например
    987ai после переезда на bypriceactivate) — молча берём первый включённый,
    иначе активация ушла бы на отключённый сайт мимо настроек кода."""
    p = await get_setting("gpt_provider", GPT_DEFAULT_PROVIDER) or GPT_DEFAULT_PROVIDER
    _off = _gpt_off_providers()
    if p not in GPT_PROVIDERS or p in _off:
        for _c in list(GPT_ENABLED_PROVIDERS) + [GPT_DEFAULT_PROVIDER]:
            if _c in GPT_PROVIDERS and _c not in _off:
                if p != _c:
                    logging.info(f"GPT: активный сайт {p!r} отключён в коде → {_c!r}")
                return _c
    return p


async def _gpt_failover_on() -> bool:
    return (await get_setting("gpt_failover", "1") or "1") == "1"


async def _gpt_provider_order() -> list:
    # сайты, поставленные админом на паузу (gpt_disabled) — исключаем из цепочки,
    # чтобы ни активация, ни фолбэк не уходили на приостановленный сайт.
    try:
        _dis_raw = await get_setting("gpt_disabled", "") or ""
        _disabled = {p for p in _dis_raw.split(",") if p}
    except Exception:
        _disabled = set()
    _disabled |= _gpt_off_providers()
    active = await _gpt_active_provider()
    order = []
    if active in GPT_PROVIDERS and active not in _disabled:
        order.append(active)
    if await _gpt_failover_on():
        for p in GPT_PROVIDER_ORDER:
            if p in GPT_PROVIDERS and p not in order and p not in _disabled:
                order.append(p)
    return order


async def gpt_resend_activation(order_id: str) -> tuple:
    """Повторно шлёт клиенту кнопку активации ChatGPT по заказу.

    Та же логика, что у кнопки «Отправить кнопку активации ещё раз» в
    админ-панели, вынесенная отдельно: её дёргает и панель, и кнопка под
    уведомлением «Истекло окно активации» — чтобы не искать заказ руками.

    Возвращает (успех, текст для админа).
    """
    _oid = str(order_id or "").strip()
    if not _oid:
        return False, "Пустой номер заказа"
    pool = await get_pool()
    async with pool.acquire() as conn:
        o = await conn.fetchrow("SELECT user_id, pack FROM fk_orders WHERE order_id=$1", _oid)
    if not o:
        return False, "Заказ не найден"
    uid = o["user_id"]
    pack = o["pack"] or ""
    if not pack.startswith("shop:"):
        return False, "Не магазинный заказ"
    _parts = pack.split(":")
    _svc = _parts[1] if len(_parts) > 1 else ""
    _idx = int(_parts[2]) if len(_parts) > 2 and _parts[2].isdigit() else 0
    if _svc == "claude":
        # Кнопка «Отправить повторно» под «Истекло окно активации Claude».
        return await claude_resend_activation(_oid)
    if _svc == "perplexity":
        return await perplexity_resend_activation(_oid)
    if _svc != "chatgpt":
        return False, "Эта кнопка только для ChatGPT, Claude и Perplexity"
    _cat = SHOP_CATALOG.get(_svc, {}) or {}
    _plans = _cat.get("plans", [])
    _plan_name = (_plan_by_order(_svc, _idx, _pack_plan_name(pack))[1].get("name")
                  or _pack_plan_name(pack) or "Plus")
    _plan_key = plan_name_to_key(_plan_name)

    # Код, уже закреплённый за заказом, переиспользуем: иначе на один заказ
    # уйдёт второй код. Новый берём, только если прежнего не осталось.
    _pend = await get_pending_activation(uid)
    # Только резерв ЭТОГО заказа: см. выше, резерв адресуется по клиенту.
    if (_pend and _pend.get("code")
            and str(_pend.get("order_id") or "") == str(_oid)):
        _code = _pend["code"]
        _prov = _pend.get("provider") or "bpa"
        _reused = True
    else:
        _code, _prov = await _gpt_pick_code(_plan_key)
        _reused = False
        if not _code:
            return False, f"Нет свободных кодов ChatGPT ({_plan_key})"
    await save_pending_activation(uid, _code, _oid, _plan_key, _plan_name, _prov)

    from aiogram.types import WebAppInfo as _WAI
    _url = webapp_url("/webapp/chatgpt", plan=_plan_name, code=_code)
    try:
        await bot.send_message(
            uid,
            f"🔔 <b>Активация подписки ChatGPT</b>\n\n"
            f"📦 {_cat.get('name','ChatGPT')} {_plan_name}\n"
            f"🎟 Код: <code>{_code}</code>\n\n"
            f"Нажми кнопку ниже, чтобы активировать 👇",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(text="✨ Активировать подписку", web_app=_WAI(url=_url))],
                [InlineKeyboardButton(text="❓ Нужна помощь", callback_data="gpt_need_help")],
            ]))
    except Exception as _se:
        return False, f"Не удалось отправить клиенту: {_se}"
    try:
        await set_setting(f"order_done:{_oid}", "0")
    except Exception:
        pass
    logging.info(f"gpt_resend_activation: order={_oid} uid={uid} code={_code} "
                 f"{'прежний' if _reused else 'новый'}")
    return True, (f"Кнопка отправлена клиенту.\n🎟 Код: <code>{_code}</code>"
                  + ("\n<i>Это тот же код, что был закреплён за заказом.</i>"
                     if _reused else "\n<i>Прежнего кода не было — выдан новый.</i>"))


async def gpt_reconcile_orphans(only_code: str = "") -> dict:
    """Подбирает активации, оборванные рестартом бота.

    Активация через bypriceactivate — это до 5 минут опроса статуса. Если в этот
    момент бот перезапустился (деплой, падение), задача умирает: сайт спокойно
    доводит активацию до конца и выдаёт клиенту подписку, а записать результат
    некому. Код остаётся used_by IS NULL, выглядит свободным и позже уходит
    ДРУГОМУ клиенту — так 11.09.2026 один код ушёл двоим.

    Здесь спрашиваем у сайта судьбу таких кодов и дописываем то, что не успел
    упавший процесс: отмечаем код использованным (это и есть запись подписки —
    профиль читает её из gpt_codes), закрываем pending, сообщаем клиенту и
    админу. Коды, по которым активации НЕ было, не трогаем: клиент ещё может
    активировать сам.
    """
    from chatgpt_activation import (bpa_query_codes, BPA_USED_STATUSES,
                                    _email_from_session, _same_email, same_org,
                                    _org_norm)
    pool = await get_pool()
    _oc = (only_code or "").strip().upper()
    # Сроки нужны, чтобы АВТОМАТИКА не приняла идущую активацию за брошенную.
    # Когда проверку запускает человек (кнопка под сообщением о неудаче или
    # /gpt_check), ждать эти минуты незачем: он уже видит, что активация
    # кончилась, и хочет ответ сейчас. Поэтому по коду — без порогов.
    _where = ("provider='bpa' AND UPPER(code)=$1" if _oc else
              "provider='bpa' AND ("
              # (1) задача оборвалась на полуслове: метка «активация идёт»
              #     пережила рестарт, значит снять её было некому
              "      (activating_at IS NOT NULL "
              "       AND activating_at < NOW() - INTERVAL '10 minutes')"
              # (2) задача ЗАВЕРШИЛАСЬ неудачей (метка снята), но сайт мог
              #     довести активацию уже после того, как бот сдался:
              #     11.09.2026 бот сообщил о неудаче в 12:48, а сайт проставил
              #     fulfilled в 13:01. Такой код оставался закреплён за
              #     клиентом и через 2 часа уходил в пул.
              # Было 15 минут — и это, а не интервал цикла, определяло, как
              # быстро бот замечает. Сама активация опрашивает сайт максимум
              # 5 минут, значит через 7 минут после создания строки задача
              # заведомо завершилась. Запас в 2 минуты оставлен намеренно.
              "   OR (activating_at IS NULL "
              "       AND created_at < NOW() - INTERVAL '7 minutes')"
              ")")
    _sql = ("SELECT user_id, code, order_id, plan, plan_name, session_raw, "
            "activating_at FROM gpt_pending_activations WHERE " + _where)
    async with pool.acquire() as conn:
        rows = (await conn.fetch(_sql, _oc)) if _oc else (await conn.fetch(_sql))
    if not rows:
        return {"ok": True, "checked": 0, "fixed": []}

    _st = await bpa_query_codes([r["code"] for r in rows])
    if not _st:
        # Раньше это была ТИХАЯ остановка: в лог строчка, в чат ничего. Сверка
        # могла не работать сутками, а выглядело бы это как «просто нечего
        # находить» — ровно то, чего мы боимся: закрытая стена. Говорим вслух,
        # но не чаще раза в полчаса, иначе при лежащем сайте будет спам.
        logging.warning("gpt_reconcile_orphans: сайт не ответил — ничего не трогаем")
        try:
            _last_q = await get_setting("recon_site_down_at", "0")
            import time as _t_rq
            if _t_rq.time() - float(_last_q or 0) > 1800:
                await set_setting("recon_site_down_at", str(_t_rq.time()))
                await bot.send_message(
                    ADMIN_ID,
                    "⚠️ <b>Сверка активаций не работает</b>\n\n"
                    f"Сайт проверки не ответил, а в очереди <b>{len(rows)}</b> "
                    f"незакрытых активаций.\n"
                    "Пока он молчит, бот НЕ узнает о прошедших активациях и "
                    "ничего не допишет сам. Проверю снова через 5 минут.",
                    parse_mode="HTML")
        except Exception:
            pass
        return {"ok": False, "checked": 0, "fixed": [],
                "error": "Сайт проверки не ответил."}

    _fixed, _unsure, _inprog = [], [], []
    for r in rows:
        _info = _st.get((r["code"] or "").strip().upper()) or {}
        _v = _info.get("status", "")
        if _v not in BPA_USED_STATUSES:
            continue                      # активации не было — pending оставляем
        _uid, _code = int(r["user_id"]), r["code"]
        # ── «claimed» — это НЕ результат, это середина активации ─────────
        # Код привязан к аккаунту, подписки ЕЩЁ НЕТ. Дальше он станет либо
        # fulfilled (подписка выдана), либо unused (не прошло, нужна
        # повторная активация тем же кодом). Записывать подписку сейчас —
        # значит соврать и клиенту, и в карточке заказа.
        # Поэтому: ничего не записываем, резерв НЕ сносим, клиенту НЕ
        # пишем. Ставим код на слежение — раз в минуту переспрашиваем сайт.
        # Александр 01.10.2026, код GPTP-XU3F-P2M2-BMVI.
        if _v == "claimed":
            try:
                _k_cl = f"gptclaim:{str(_code).strip().upper()}"
                if not (await get_setting(_k_cl, "") or "").strip():
                    import time as _t_cl
                    await set_setting(
                        _k_cl, f"{_uid}|{r['order_id'] or ''}|{int(_t_cl.time())}|")
                    # Из первой очереди выдачи код убираем: он занят. Пометка
                    # обратимая, в пул код сам не вернётся и не сгорит.
                    async with pool.acquire() as _c_cl:
                        # Пометку «ждём освобождения:…» НЕ затираем: по ней
                        # работает gpt_dead_order_release_loop, и если сейчас
                        # её переписать, то после закрытия резерва код выпал бы
                        # из той петли и не вернулся бы в пул никогда.
                        await _c_cl.execute(
                            "UPDATE gpt_codes SET check_status='error', "
                            "last_checked_at=NOW(), flagged_reason = CASE "
                            "  WHEN COALESCE(flagged_reason,'') LIKE 'ждём освобождения:%' "
                            "  THEN flagged_reason ELSE $2 END "
                            "WHERE code=$1",
                            _code, "активация идёт: сайт держит claimed")
            except Exception as _e_cl:
                logging.warning(f"reconcile: метка слежения {_code}: {_e_cl}")
            _inprog.append({"user_id": _uid, "code": _code,
                            "order_id": r["order_id"] or "",
                            "plan_name": r["plan_name"], "status": _v})
            continue
        _email = ""
        try:
            _email = _email_from_session(r["session_raw"] or "")
        except Exception:
            pass
        if not _email:
            # session_raw в эту таблицу никто никогда не писал, поэтому раньше
            # почта тут была пуста ВСЕГДА — и сверка ни одной активации не
            # подтверждала, всё уходило в «проверь вручную». Берём сохранённую.
            try:
                async with pool.acquire() as _c_em2:
                    _email = await _c_em2.fetchval(
                        "SELECT gpt_email FROM users WHERE user_id=$1", _uid) or ""
                    if not _email:
                        _email = await _c_em2.fetchval(
                            "SELECT email FROM gpt_codes WHERE used_by=$1 "
                            "AND COALESCE(email,'')<>'' ORDER BY used_at DESC LIMIT 1",
                            _uid) or ""
            except Exception as _e_em3:
                logging.warning(f"reconcile: почта клиента {_uid}: {_e_em3}")
        # «Код потрачен» само по себе НЕ значит «потрачен нашим клиентом»:
        # процесс мог умереть на коде, который был израсходован кем-то раньше.
        # Записать тогда подписку этому клиенту — значит соврать ему в профиле.
        # Кредитуем только при совпадении почты; иначе отдаём на проверку.
        _site_mail = _info.get("email") or ""
        _site_org = _info.get("org") or ""
        # Organization ID сверяем ПЕРВЫМ: он точный, а почта на сайте
        # замаскирована; у тарифа Go почты нет вовсе, и раньше такие
        # активации подтвердить было нечем в принципе.
        _org_cl = ""
        try:
            async with pool.acquire() as _c_org:
                _org_cl = await _c_org.fetchval(
                    "SELECT gpt_org FROM users WHERE user_id=$1", _uid) or ""
        except Exception as _e_og:
            logging.warning(f"reconcile: org клиента {_uid}: {_e_og}")
        _om = same_org(_site_org, _org_cl)
        if _om is None and _site_org:
            # Кандидаты из начала присланного текста — только для подтверждения.
            try:
                async with pool.acquire() as _c_h:
                    _hint = await _c_h.fetchval(
                        "SELECT gpt_org_hint FROM users WHERE user_id=$1", _uid) or ""
                # Сравниваем через _org_norm: на сайте идентификатор может
                # прийти с префиксом «gpt:», а у клиента лежать без него.
                if _hint and _org_norm(_site_org) in [
                        _org_norm(x) for x in _hint.split(",") if x.strip()]:
                    _om = True
            except Exception as _e_h:
                logging.warning(f"reconcile: подсказки org {_uid}: {_e_h}")
        if _om is not None:
            _sure = _om
        else:
            _sure = bool(_site_mail) and bool(_email) and _same_email(_site_mail, _email)
        if not _sure:
            # Подписку не записываем — но и молча отпускать код нельзя: он
            # потрачен, и через два часа ушёл бы следующему клиенту как
            # «свободный». Ставим ту же обратимую пометку, что и сверка пула:
            # из первой очереди выдачи уходит, в пул сам не вернётся.
            try:
                async with pool.acquire() as _cflag:
                    await _cflag.execute(
                        "UPDATE gpt_codes SET check_status='error', "
                        "last_checked_at=NOW(), flagged_reason=$2 WHERE code=$1",
                        _code, f"bpa/query: {_v} — потрачен, чей аккаунт не подтверждён")
            except Exception as _e_fl:
                logging.warning(f"gpt_reconcile_orphans флаг {_code}: {_e_fl}")
            _unsure.append({"user_id": _uid, "code": _code, "order_id": r["order_id"],
                            "plan_name": r["plan_name"], "status": _v,
                            "site_email": _site_mail, "client_email": _email,
                            "site_org": _site_org, "client_org": _org_cl})
            continue
        try:
            await mark_gpt_code_used(_code, _uid, r["order_id"], _email)
            # Именно этого заказа: у клиента мог появиться новый резерв по
            # другой оплате, и снос «любого» резерва оставлял его без выдачи.
            await delete_pending_activation(_uid, r["order_id"])
        except Exception as _e_mk:
            logging.error(f"gpt_reconcile_orphans {_code}: {_e_mk}")
            continue
        _fixed.append({"user_id": _uid, "code": _code, "order_id": r["order_id"],
                       "plan_name": r["plan_name"], "email": _email, "status": _v,
                       # Строка ожидания без заказа: подписку клиенту всё равно
                       # записываем (иначе он останется ни с чем), но связать её
                       # с покупкой нечем — карточку заказа не найти, в прибыли
                       # код не сойдётся. Молчать об этом нельзя: снаружи такой
                       # код выглядит как сожжённый зря.
                       "no_order": not (r["order_id"] or "")})
        if not (r["order_id"] or ""):
            logging.warning(
                f"gpt_reconcile_orphans: {_code} записан клиенту {_uid} БЕЗ заказа "
                f"— в строке ожидания order_id пуст")
        # Единый вид успеха + пояснение про задержку. Таймер на старом
        # сообщении активации гасим: иначе он потом позовёт «активировать
        # сейчас» уже выданную подписку. 06.10.2026
        try:
            _mid_rc = await _client_act_msg_take("chatgpt", _uid)
            await client_success_deliver(
                _uid,
                client_success_text(
                    "chatgpt", r["plan_name"] or "", account=_email or "",
                    end=client_end_date(r["plan_name"] or ""),
                    order_line=(await _order_ref_line(r["order_id"])) if r["order_id"] else "",
                    note="Активация прошла, но подтверждение дошло до бота с задержкой — "
                         "поэтому сообщение приходит не сразу. Подписка уже работает 🙌"),
                client_success_kb("chatgpt"), edit_mid=_mid_rc)
        except Exception as _e_rs:
            logging.warning(f"reconcile: успех клиенту {_uid}: {_e_rs}")
        # Карточка заказа у админа — в «активирован». Раньше этот путь её не
        # трогал, и в чате оставалось «оплачен» или «НЕУДАЧА» при выданной
        # подписке.
        try:
            await gpt_order_mark_activated(
                r["order_id"], _uid, _code, _email, _site_org,
                "Активация прошла, бот узнал о ней с задержкой — дописано сверкой.")
        except Exception as _e_om:
            logging.warning(f"reconcile: карточка заказа {r['order_id']}: {_e_om}")
        # Висящее сообщение о неудаче по этому заказу переписываем. Иначе у
        # Александра в чате остаётся «не помог и iOS-маршрут» (или «НЕУДАЧА»)
        # при выданной подписке — он просил 23.09.2026, чтобы такие сообщения
        # обновлялись сами, а не требовали сверять их с реальностью.
        try:
            if r["order_id"]:
                _cm_key = f"gpt_confirm_msg:{r['order_id']}"
                _cm_mid = (await get_setting(_cm_key, "") or "").strip()
                if _cm_mid.isdigit():
                    # Тот же подписанный вид, что и у остальных карточек,
                    # плюс журнал попыток. Александр 04.10.2026.
                    _txt_rc = await gpt_watch_card(
                        _code, _uid, r["order_id"], _v, stage="late",
                        note=("Сообщение о неудаче было преждевременным: сайт "
                              "дозавершил заказ, сверка это подтвердила. "
                              "Делать ничего не нужно."))
                    await bot.edit_message_text(
                        _txt_rc, chat_id=ADMIN_ID, message_id=int(_cm_mid),
                        parse_mode="HTML")
                    await set_setting(_cm_key, "")
                    # Помечаем, что карточка этого заказа УЖЕ обновлена. По этой
                    # метке слежение и отчёт кнопки молчат вместо того, чтобы
                    # рассказывать о том же событии второй и третий раз.
                    # Александр 02.10.2026: пять сообщений на одну активацию.
                    if _fixed:
                        _fixed[-1]["card_updated"] = True
                    logging.warning(f"reconcile: переписал сообщение о неудаче "
                                    f"по заказу {r['order_id']}")
        except Exception as _e_cm:
            logging.info(f"reconcile: правка сообщения о неудаче: {_e_cm}")
        logging.warning(f"gpt_reconcile_orphans: дописал активацию {_code} "
                        f"uid={_uid} order={r['order_id']} статус={_v}")
    return {"ok": True, "checked": len(rows), "fixed": _fixed,
            "unsure": _unsure, "in_progress": _inprog}


# Что проверяем на bypriceactivate: таблица кодов, таблица «в процессе»,
# нужно ли фильтровать по провайдеру (у Perplexity колонки provider нет) и
# по какому условию считать активацию ИДУЩЕЙ ПРЯМО СЕЙЧАС.
#
# Последнее — важное. Раньше из сверки выпадал любой код, у которого есть
# строка в таблице «в процессе». Но после неудачной активации бот эту строку
# НЕ удаляет (код закрепляется за клиентом, чтобы активировать вручную тем же
# кодом) — и такой код становился невидимым для сверки на два часа. Ровно в
# этом промежутке 11.09.2026 код GPTP-ISFG-…-B6ZQ числился «годным», хотя на
# сайте уже стоял fulfilled. Теперь пропускаем только те, что реально в
# работе: у ChatGPT это свежая метка activating_at, у остальных — свежая
# строка «в процессе» (колонки activating_at у них нет).
_AUDIT_SERVICES = {
    "chatgpt":    {"name": "ChatGPT",    "table": "gpt_codes",
                   "pending": "gpt_pending_activations",        "by_provider": True,
                   "inflight": "p.activating_at IS NOT NULL "
                               "AND p.activating_at > NOW() - INTERVAL '15 minutes'"},
    "claude":     {"name": "Claude",     "table": "claude_codes",
                   "pending": "claude_pending_activations",     "by_provider": True,
                   "inflight": "p.created_at > NOW() - INTERVAL '15 minutes'"},
    "perplexity": {"name": "Perplexity", "table": "perplexity_codes",
                   "pending": "perplexity_pending_activations", "by_provider": False,
                   "inflight": "p.created_at > NOW() - INTERVAL '15 minutes'"},
}


async def pool_audit(services=None, include_reserved: bool = True) -> dict:
    """Сверяет пулы кодов с сайтом активации (POST /query, без активации).

    Код мог быть реально потрачен, а бот этого не зафиксировал (упал,
    перезапустился, счёл неудачей). Тогда он выглядит свободным и уходит
    следующему клиенту — так 11.09.2026 один код ушёл двум клиентам.

    Коды всех сервисов уходят ОДНИМ запросом: сайт принимает их вперемешку и
    различает сам по префиксу.

    Ничего не гасит и не удаляет: ставит обратимую пометку и возвращает сводку.
    Если сайт не ответил или ответил не тем — пулы не меняются вовсе.
    """
    from chatgpt_activation import (bpa_query_codes, BPA_USED_STATUSES,
                                    BPA_FREE_STATUSES)
    _svcs = [x for x in (services or list(_AUDIT_SERVICES)) if x in _AUDIT_SERVICES]
    pool = await get_pool()

    _all, _by_code = [], {}
    _pool_n = {_sv: 0 for _sv in _svcs}          # сколько кодов в пуле сервиса
    _sql_err = {}                                # сервис → почему не смогли выбрать
    _skipped = {}                                # сервис → пропущено (активация идёт)
    async with pool.acquire() as conn:
        for _sv in _svcs:
            _cfg = _AUDIT_SERVICES[_sv]
            if include_reserved:
                _where = ["(is_used=FALSE OR (is_used=TRUE AND used_by IS NULL))"]
            else:
                _where = ["is_used=FALSE"]
            if _cfg["by_provider"]:
                _where.append("provider='bpa'")
            # Код, который активируют ПРЯМО СЕЙЧАС, не трогаем: сайт может уже
            # показывать fulfilled, хотя это законная активация в процессе, —
            # пометили бы её как «похоже, потрачен» и зря подняли тревогу.
            # Но именно СЕЙЧАС, а не «когда-то была строка»: см. _AUDIT_SERVICES.
            _where.append(f"NOT EXISTS (SELECT 1 FROM {_cfg['pending']} p "
                          f"WHERE p.code = {_cfg['table']}.code "
                          f"  AND ({_cfg['inflight']}))")
            # Сколько кодов мы ПРОПУСКАЕМ из-за идущей активации — считаем
            # отдельно и показываем в отчёте. Без этого «годных: 47» читалось
            # как «всё чисто», хотя пропущенный код мог быть уже потрачен:
            # 15.09.2026 так и вышло — проверка через 11 минут после неудачи
            # не увидела код, который на сайте уже значился fulfilled.
            try:
                _skipped[_sv] = await conn.fetchval(
                    f"SELECT COUNT(*) FROM {_cfg['table']} WHERE "
                    + " AND ".join(_where[:-1])
                    + f" AND EXISTS (SELECT 1 FROM {_cfg['pending']} p "
                      f"WHERE p.code = {_cfg['table']}.code "
                      f"  AND ({_cfg['inflight']}))") or 0
            except Exception:
                _skipped[_sv] = 0
            try:
                _rows = await conn.fetch(
                    f"SELECT code FROM {_cfg['table']} WHERE " + " AND ".join(_where))
            except Exception as _e_sel:
                # Молчать нельзя: в отчёте сервис выглядел бы как «пул пуст»,
                # то есть проверка соврала бы, что всё в порядке.
                logging.error(f"pool_audit {_sv}: не смог выбрать коды: {_e_sel}")
                _sql_err[_sv] = str(_e_sel)[:200]
                continue
            for _r in _rows:
                _all.append(_r["code"])
                _by_code[(_r["code"] or "").strip().upper()] = _sv
                _pool_n[_sv] = _pool_n.get(_sv, 0) + 1

    def _blank(_extra=None):
        """Пустая разбивка по сервисам — чтобы отчёт всегда показывал ВСЕ сервисы,
        даже когда проверять было нечего или сайт не ответил."""
        _b = {}
        for _sv in _svcs:
            _b[_sv] = {"pool": _pool_n.get(_sv, 0), "checked": 0, "free": 0,
                       "spent": [], "odd": [], "noanswer": 0, "unknown": False,
                       "error": _sql_err.get(_sv, "")}
            if _extra == "noanswer":
                _b[_sv]["noanswer"] = _pool_n.get(_sv, 0)
        return _b

    if not _all:
        return {"ok": True, "checked": 0, "spent": [], "free": 0, "odd": [],
                "services": _svcs, "unknown": [], "by_service": _blank()}

    _st = await bpa_query_codes(_all)
    if not _st:
        logging.warning("pool_audit: сайт не ответил — пулы не трогаем")
        return {"ok": False, "checked": 0, "spent": [], "free": 0, "odd": [],
                "services": _svcs, "unknown": [],
                "by_service": _blank("noanswer"),
                "error": "Сайт проверки не ответил — пулы не меняли."}

    # Сначала раскладываем ответ по полочкам В ПАМЯТИ и только потом пишем в базу.
    # Причина: страница /query сделана под ChatGPT, и не факт, что она вообще
    # знает коды Claude/Perplexity. Если не знает — она ответит на них
    # not_in_db, и построчная запись пометила бы ВЕСЬ пул сервиса как спорный.
    # Поэтому сервис, у которого ВСЕ ответы — not_in_db, считаем непокрытым
    # проверкой и не трогаем вовсе.
    _plan = []                       # (код, статус, сервис, что_делать)
    _ans, _nid = {}, {}              # сколько ответов и сколько not_in_db по сервисам
    _noans = {_sv: 0 for _sv in _svcs}   # коды, про которые сайт промолчал
    for _c in _all:
        _key = (_c or "").strip().upper()
        _v = (_st.get(_key) or {}).get("status", "")
        _sv = _by_code.get(_key, "chatgpt")
        if not _v:
            # Сайт про этот код не ответил вовсе. Не молчим об этом: если таких
            # много у одного сервиса — значит проверка его толком не покрывает.
            _noans[_sv] = _noans.get(_sv, 0) + 1
            continue
        _ans[_sv] = _ans.get(_sv, 0) + 1
        if _v == "not_in_db":
            _nid[_sv] = _nid.get(_sv, 0) + 1
        if _v in BPA_USED_STATUSES:
            _plan.append((_c, _v, _sv, "spent"))
        elif _v in BPA_FREE_STATUSES:
            _plan.append((_c, _v, _sv, "free"))
        else:
            _plan.append((_c, _v, _sv, "odd"))

    _unknown = sorted(_sv for _sv, _n in _ans.items()
                      if _n >= 3 and _nid.get(_sv, 0) == _n)
    if _unknown:
        logging.warning("pool_audit: сайт не знает коды сервисов "
                        + ", ".join(_unknown) + " — их не трогаем")

    _spent, _odd, _free = [], [], 0
    async with pool.acquire() as conn:
        for _c, _v, _sv, _what in _plan:
            if _sv in _unknown:
                continue                      # сервис не покрыт проверкой
            _tbl = _AUDIT_SERVICES[_sv]["table"]
            if _what == "spent":
                # Сайт говорит, что код потрачен. НЕ гасим и не удаляем: проверка
                # могла ошибиться, а решение о судьбе товара — за Александром.
                # Пометка обратима и убирает код из первой очереди на выдачу.
                await conn.execute(
                    f"UPDATE {_tbl} SET check_status='error', last_checked_at=NOW(), "
                    f"flagged_reason=$2 WHERE code=$1",
                    _c, f"bpa/query: {_v} — похоже, уже потрачен")
                _spent.append((_c, _v, _sv))
            elif _what == "free":
                await conn.execute(
                    f"UPDATE {_tbl} SET check_status='ok', last_checked_at=NOW(), "
                    f"flagged_reason=NULL WHERE code=$1", _c)
                _free += 1
            else:
                # failed / zoom_* / not_in_db — состояние неясное. Не жжём и не
                # объявляем годным: помечаем и показываем админу.
                await conn.execute(
                    f"UPDATE {_tbl} SET check_status='error', last_checked_at=NOW(), "
                    f"flagged_reason=$2 WHERE code=$1", _c, f"bpa/query: {_v}")
                _odd.append((_c, _v, _sv))
    _checked = sum(1 for _c, _v, _sv, _w in _plan if _sv not in _unknown)

    # Разбивка по сервисам — её показывает отчёт. Считаем по _svcs, а не по
    # найденному, чтобы сервис с пустым пулом тоже попал в отчёт отдельной
    # строкой: «проверять нечего» — это тоже ответ.
    _by = {}
    for _sv in _svcs:
        _u = _sv in _unknown
        _by[_sv] = {
            "pool": _pool_n.get(_sv, 0),
            "checked": 0 if _u else sum(1 for _c, _v, _s, _w in _plan if _s == _sv),
            "free": 0 if _u else sum(1 for _c, _v, _s, _w in _plan
                                     if _s == _sv and _w == "free"),
            "spent": [(_c, _v) for _c, _v, _s in _spent if _s == _sv],
            "odd": [(_c, _v) for _c, _v, _s in _odd if _s == _sv],
            "noanswer": _noans.get(_sv, 0),
            "unknown": _u,
            "error": _sql_err.get(_sv, ""),
        }
    logging.info(f"pool_audit: проверено {_checked}, подозрительных {len(_spent)}, "
                 f"годных {_free}, спорных {len(_odd)}, непокрытых сервисов "
                 f"{len(_unknown)} — ничего не гасили")
    for _sv, _d in _by.items():
        logging.info(f"pool_audit/{_sv}: пул {_d['pool']}, проверено {_d['checked']}, "
                     f"годных {_d['free']}, потрачено {len(_d['spent'])}, "
                     f"спорных {len(_d['odd'])}, без ответа {_d['noanswer']}")
    return {"ok": True, "checked": _checked, "spent": _spent, "free": _free,
            "odd": _odd, "services": _svcs, "unknown": _unknown, "by_service": _by,
            "skipped": {k: int(v) for k, v in _skipped.items() if v}}


def _gw_int(v, default: int) -> int:
    """int() с защитой от нуля.

    Писать int(x or 2) нельзя: ноль — ложное значение, и «0 друзей» молча
    превратилось бы в 2. Тогда при настройке «приглашать никого не нужно»
    условия не выполнил бы никто, и понять почему было бы невозможно.
    """
    if v is None or v == "":
        return default
    try:
        return int(v)
    except Exception:
        return default


_GW_REFRESH_RUNNING = set()      # какие розыгрыши сейчас пересчитываются


async def giveaway_refresh(gid: int) -> dict:
    """Пересчитывает участников розыгрыша: подписка, приглашённые, подозрения.

    Работает в фоне и складывает результат прямо в giveaway_comments. Панель
    потом читает готовое: опрос Telegram по каждому участнику и каждому его
    другу — это сотни запросов, держать на них открытый HTTP от мини-аппа
    нельзя, оно отвалится по таймауту.
    """
    from handlers_giveaway import giveaway_is_subscribed
    from db import giveaway_get, giveaway_commenters, giveaway_refs
    if gid in _GW_REFRESH_RUNNING:
        return {"ok": False, "busy": True}
    _GW_REFRESH_RUNNING.add(gid)
    try:
        _gw = await giveaway_get(gid)
        if not _gw:
            return {"ok": False, "error": "Розыгрыш не найден"}
        _need = _gw_int(_gw.get("need_refs"), 2)
        _since = _gw["starts_at"]
        _people = await giveaway_commenters(gid)
        _sub_cache = {}

        async def _sub(uid):
            """True/False/None. None — спросить не удалось, см. giveaway_is_subscribed."""
            if uid not in _sub_cache:
                _sub_cache[uid] = await giveaway_is_subscribed(uid)
                # Telegram не любит больше ~30 запросов в секунду — идём
                # спокойно, торопиться тут некуда.
                await asyncio.sleep(0.05)
            return _sub_cache[uid]

        pool = await get_pool()
        _done = 0
        _unknown = 0
        for _p in _people:
            _uid = int(_p["user_id"])
            _ok_sub = await _sub(_uid)
            _refs = await giveaway_refs(_uid, _since)
            # ПРАВИЛО ЗАЧЁТА. Друг считается, если пришёл по ссылке и запустил
            # бота после старта розыгрыша (referred_by проставляется только
            # новым, так что повторно одного человека не засчитать).
            #
            # Подписка ДРУГА на канал на зачёт не влияет. Раньше влияла — и
            # это расходилось с условиями конкурса, где сказано только
            # «пригласить 2 друзей в бота». 20.09.2026 человек с тремя
            # приглашёнными видел «1 из 2» и не понимал, за что.
            _cnt = len(_refs)
            _murky = (_ok_sub is None)
            # Подписку друзей всё равно считаем, но ТОЛЬКО для показа в панели:
            # так видно, кого стоит попросить подписаться. На вердикт это не
            # влияет, и молчание Telegram про друга больше не оставляет
            # участника непроверенным — раньше оставляло и блокировало розыгрыш.
            _subbed = 0
            for _r in _refs[:20]:
                if await _sub(int(_r["user_id"])) is True:
                    _subbed += 1
            _flags = _gw_suspicion(_refs)
            if _murky:
                # Про кого-то не удалось спросить. Пишем что есть, но НЕ
                # ставим checked_at: участник останется «не проверен», и
                # розыгрыш не запустится, пока не прогонишь ещё раз. Молча
                # засчитать неполную проверку — это лотерея с чужими призами.
                _unknown += 1
                async with pool.acquire() as conn:
                    await conn.execute(
                        "UPDATE giveaway_comments SET subscribed=$3, refs_ok=$4, "
                        "refs_total=$5, suspicious=$6, refs_sub=$7, checked_at=NULL "
                        "WHERE giveaway_id=$1 AND user_id=$2",
                        gid, _uid, (_ok_sub if _ok_sub is not None else None),
                        _cnt, len(_refs), _flags, _subbed)
            else:
                async with pool.acquire() as conn:
                    await conn.execute(
                        "UPDATE giveaway_comments SET subscribed=$3, refs_ok=$4, "
                        "refs_total=$5, suspicious=$6, refs_sub=$7, checked_at=NOW() "
                        "WHERE giveaway_id=$1 AND user_id=$2",
                        gid, _uid, bool(_ok_sub), _cnt, len(_refs), _flags, _subbed)
            _done += 1
        await set_setting(f"gw_checked:{gid}", str(int(_time_module.time())))
        if _unknown:
            logging.warning(f"giveaway_refresh #{gid}: по {_unknown} участникам "
                            f"Telegram не ответил — они остались непроверенными")
        logging.info(f"giveaway_refresh #{gid}: проверено {_done} участников")
        return {"ok": True, "checked": _done, "unknown": _unknown}
    except Exception as _e:
        logging.error(f"giveaway_refresh #{gid}: {_e}", exc_info=True)
        return {"ok": False, "error": str(_e)[:200]}
    finally:
        _GW_REFRESH_RUNNING.discard(gid)


def _gw_suspicion(refs: list) -> str:
    """Признаки накрутки. НЕ приговор — бот никого не исключает сам.

    Смысл в том, чтобы Александр посмотрел на десяток подозрительных, а не на
    весь список. Telegram не даёт боту ни возраст аккаунта, ни устройство,
    поэтому судим по тому немногому, что видно.

    Одного слабого признака мало: двое друзей, зашедших в бота подряд, — это
    совершенно обычное дело (позвал в общем чате, оба нажали). Поэтому
    помечаем либо по сильному признаку, либо когда слабых набралось два.
    """
    if not refs:
        return ""
    _strong, _weak = [], []
    _noname = sum(1 for r in refs if not (r.get("username") or "").strip())
    if len(refs) >= 2 and _noname == len(refs):
        _strong.append("все приглашённые без юзернейма")
    elif _noname >= 2:
        _weak.append(f"без юзернейма: {_noname}")
    # Регистрации впритык друг к другу. Само по себе — не улика.
    try:
        _ts = sorted(r["created_at"] for r in refs if r.get("created_at"))
        _fast = sum(1 for _i in range(1, len(_ts))
                    if (_ts[_i] - _ts[_i - 1]).total_seconds() < 120)
        if _fast:
            _weak.append("регистрации подряд (<2 мин)")
    except Exception:
        pass
    # Имена вида «Иван1», «Иван2» — типичная заготовка аккаунтов.
    try:
        import re as _re_gw
        _stems = [_re_gw.sub(r"\d+$", "", (r.get("username") or "").lower())
                  for r in refs if (r.get("username") or "").strip()]
        _stems = [x for x in _stems if len(x) >= 3]
        if len(_stems) >= 2 and len(set(_stems)) == 1:
            _strong.append("юзернеймы отличаются только цифрой")
    except Exception:
        pass
    if _strong:
        return "; ".join(_strong + _weak)
    return "; ".join(_weak) if len(_weak) >= 2 else ""


async def giveaway_sync_button() -> str:
    """Ставит или убирает кнопку розыгрыша в главном меню.

    Кнопка появляется, только когда розыгрыш активен И указана ссылка на пост:
    кнопка, ведущая в никуда, хуже, чем её отсутствие.
    """
    from db import giveaway_active
    from keyboards import set_giveaway_button
    try:
        _gw = await giveaway_active()
        _url = (_gw.get("post_url") or "") if _gw else ""
        if _url and not _url.lower().startswith(("http://", "https://")):
            _url = ""
        set_giveaway_button(_url, (_gw.get("btn_text") or "") if _gw else "")
        logging.info(f"giveaway button: {'показана' if _url else 'скрыта'}")
        return _url
    except Exception as _e:
        logging.warning(f"giveaway_sync_button: {_e}")
        return ""


async def giveaway_participants(gid: int) -> list:
    """Участники с результатом последней проверки — то, что видит панель."""
    pool = await get_pool()
    async with pool.acquire() as conn:
        rows = await conn.fetch(
            "SELECT c.user_id, "
            "       COALESCE(NULLIF(c.username,''), u.username, '') AS username, "
            "       COALESCE(NULLIF(c.full_name,''), u.full_name, '') AS full_name, "
            "       c.created_at, c.subscribed, c.refs_ok, c.refs_total, "
            "       COALESCE(c.refs_sub,0) AS refs_sub, "
            "       c.suspicious, c.excluded, c.checked_at "
            "FROM giveaway_comments c LEFT JOIN users u ON u.user_id=c.user_id "
            "WHERE c.giveaway_id=$1 ORDER BY c.created_at", gid)
    return [dict(r) for r in rows]


# По каким розыгрышам напоминание идёт прямо сейчас: {gid: когда начали}.
# Не множество, а время старта — чтобы зависший замок (падение процесса,
# неожиданное исключение) отпускался сам через два часа, а не держал
# напоминание заблокированным до перезапуска бота.
_GW_REMIND_RUNNING = {}


async def giveaway_remind(gid: int, dry: bool = False) -> dict:
    """Напоминание участникам конкурса — каждому про ЕГО недостающее.

    Просьба Александра 17.09.2026: «нужна рассылка всем участникам с
    напоминанием о конкурсе и о том, сколько ещё людей нужно привести».

    Общий текст тут бесполезен: человеку нужно знать, чего не хватает ИМЕННО
    ему. Поэтому письмо собирается по его строке проверки — подписка, друзья,
    комментарий — и заканчивается его личной ссылкой.

    dry=True — ничего не отправляет, только считает. Так панель показывает
    «получат N человек» ДО подтверждения, а не после.
    """
    from db import giveaway_get
    from aiogram.exceptions import TelegramRetryAfter, TelegramForbiddenError
    _gw = await giveaway_get(gid) or {}
    _need = _gw_int(_gw.get("need_refs"), 2)
    _title = strip_surrogates(str(_gw.get("title") or "Розыгрыш"))
    _post = (_gw.get("post_url") or "").strip()
    _pp = [p for p in await giveaway_participants(gid) if not p.get("excluded")]
    # Тем, кто уже всё выполнил, напоминание не нужно: «ты в списке» они и так
    # видят в /giveaway, а лишнее сообщение от бота раздражает.
    _todo = [p for p in _pp
             if not (p.get("subscribed") and int(p.get("refs_ok") or 0) >= _need)]
    if dry:
        return {"ok": True, "total": len(_pp), "todo": len(_todo)}

    # ── Одно напоминание за раз ─────────────────────────────────────────
    # 20.09.2026: клиенту и его подруге напоминание пришло ТРИ раза. Причина
    # не в тексте и не в списке — в том, что рассылка шла прямо внутри
    # HTTP-запроса и занимала минуты. Мини-апп столько не ждёт: запрос
    # отваливался по таймауту, Александр видел «ничего не произошло» и жал
    # ещё раз. Защита «не чаще раза в 6 часов» при этом не срабатывала:
    # отметку времени ставили в САМОМ КОНЦЕ, и второй запуск читал ещё
    # старое значение.
    import time as _t_lock
    _since = _GW_REMIND_RUNNING.get(gid, 0)
    if _since and _t_lock.time() - _since < 7200:
        logging.warning(f"giveaway_remind {gid}: уже идёт — второй запуск отклонён")
        return {"ok": False, "busy": True,
                "msg": "Напоминание уже отправляется. Дождись отчёта в боте."}
    _GW_REMIND_RUNNING[gid] = _t_lock.time()
    # Метку ставим СРАЗУ: она и есть защита от повторного запуска.
    try:
        import time as _t_gr0
        await set_setting(f"gwremind_at:{gid}", str(int(_t_gr0.time())))
    except Exception as _e_gr0:
        logging.warning(f"giveaway_remind {gid}: метка времени не записалась: {_e_gr0}")

    _un = ""
    try:
        _un = (await bot.get_me()).username or ""
    except Exception:
        _un = ""

    _sent = _blocked = _failed = 0
    for _p in _todo:
        _uid = int(_p["user_id"])
        _have = int(_p.get("refs_ok") or 0)
        _left = max(0, _need - _have)
        _lines = [f"🎁 <b>{_title}</b>\n", "Напоминаю, чего не хватает для участия:\n"]
        _lines.append(("✅" if _p.get("subscribed") else "⬜️") + " подписка на канал")
        _lines.append(("✅" if _have >= _need else "⬜️")
                      + f" друзей: <b>{_have}</b> из {_need}")
        _lines.append("✅ комментарий под постом")
        if _left:
            _lines.append(f"\nОсталось привести <b>{_left}</b> "
                          + ("друга" if _left == 1 else "друзей") + ".")
        if _un:
            _lines.append(f"\n🔗 Твоя ссылка:\n<code>https://t.me/{_un}?start=ref_{_uid}</code>")
        _lines.append("\nПроверить себя: /giveaway")
        _kb = None
        if _post.lower().startswith(("http://", "https://")):
            _kb = InlineKeyboardMarkup(inline_keyboard=[[
                InlineKeyboardButton(text="📢 Открыть пост", url=_post)]])
        for _try in (1, 2):
            try:
                await bot.send_message(_uid, "\n".join(_lines), parse_mode="HTML",
                                       disable_web_page_preview=True, reply_markup=_kb)
                _sent += 1
                break
            except TelegramRetryAfter as _e_fl:
                _w = min(int(getattr(_e_fl, "retry_after", 5)) + 1, 60)
                logging.warning(f"giveaway_remind: флуд-лимит, жду {_w} с")
                await asyncio.sleep(_w)
                continue
            except TelegramForbiddenError:
                _blocked += 1
                break
            except Exception as _e_s:
                logging.warning(f"giveaway_remind {_uid}: {_e_s}")
                _failed += 1
                break
        await asyncio.sleep(0.05)
    _GW_REMIND_RUNNING.pop(gid, None)
    logging.warning(f"giveaway_remind {gid}: отправлено {_sent}, "
                    f"заблокировали {_blocked}, ошибок {_failed}")
    # Отчёт уходит в бот, а не только в мини-апп: рассылка идёт фоном, и
    # к её концу панель может быть уже закрыта.
    try:
        await bot.send_message(
            ADMIN_ID,
            f"\U0001f4e3 <b>Напоминание участникам отправлено</b>\n\n"
            f"\u2705 Доставлено: <b>{_sent}</b> из {len(_todo)}\n"
            f"\U0001f6ab Заблокировали бота: {_blocked}\n"
            f"\u274c Ошибки: {_failed}\n\n"
            f"<i>Всего участников: {len(_pp)}. Тем, у кого всё закрыто, "
            f"напоминание не слалось.</i>",
            parse_mode="HTML")
    except Exception:
        pass
    return {"ok": True, "sent": _sent, "blocked": _blocked, "failed": _failed,
            "total": len(_pp), "todo": len(_todo)}


async def giveaway_eligible(gid: int) -> list:
    """Кто выполнил ВСЕ условия — из них и тянем победителей."""
    from db import giveaway_get
    _gw = await giveaway_get(gid)
    _need = _gw_int((_gw or {}).get("need_refs"), 2)
    _out = []
    for _p in await giveaway_participants(gid):
        if _p.get("excluded"):
            continue
        if not _p.get("subscribed"):
            continue
        if int(_p.get("refs_ok") or 0) < _need:
            continue
        _out.append(_p)
    return _out


async def giveaway_draw(gid: int) -> dict:
    """Случайный выбор победителей среди выполнивших условия.

    Берём system random (os.urandom), а не обычный псевдослучайный генератор:
    у того результат зависит от внутреннего состояния, и «а ты не перезапускал?»
    имело бы под собой основание.
    """
    from db import giveaway_get, giveaway_set_winners
    import secrets as _secrets
    _gw = await giveaway_get(gid)
    if not _gw:
        return {"ok": False, "error": "Розыгрыш не найден"}
    _pool_people = await giveaway_eligible(gid)
    if not _pool_people:
        return {"ok": False, "error": "Никто пока не выполнил все условия."}
    _wn = _gw_int(_gw.get("winners_count"), 10)
    _rn = _gw_int(_gw.get("reserve_count"), 0)
    _ids = [int(p["user_id"]) for p in _pool_people]
    _shuffled = list(_ids)
    # Перемешивание Фишера–Йетса на криптостойком источнике.
    for _i in range(len(_shuffled) - 1, 0, -1):
        _j = _secrets.randbelow(_i + 1)
        _shuffled[_i], _shuffled[_j] = _shuffled[_j], _shuffled[_i]
    _winners = _shuffled[:_wn]
    _reserves = _shuffled[_wn:_wn + _rn]
    await giveaway_set_winners(gid, _winners, _reserves)
    return {"ok": True, "winners": _winners, "reserves": _reserves,
            "pool": len(_ids)}


def giveaway_post_text(gw: dict, winners: list) -> str:
    """Готовый текст итогов для канала — чтобы не собирать его руками."""
    _w = [x for x in winners if not x.get("is_reserve")]
    _r = [x for x in winners if x.get("is_reserve")]

    def _name(x):
        return ("@" + x["username"]) if x.get("username") else (
            tg_name(x.get("full_name")) or f"id{x['user_id']}")

    _t = (f"🏆 <b>Итоги розыгрыша</b>\n"
          f"{gw.get('title') or ''}\n\n"
          f"Победители ({len(_w)}):\n"
          + "\n".join(f"{_i}. {_name(x)}" for _i, x in enumerate(_w, 1)))
    if _r:
        _t += ("\n\nРезервный список:\n"
               + "\n".join(f"{_i}. {_name(x)}" for _i, x in enumerate(_r, 1)))
    _t += ("\n\nПобедителям — написать в поддержку через бота в течение 7 дней. "
           "Невостребованные призы уходят в резерв.\n\nСпасибо всем за участие! 🍀")
    return _t


def tg_chunks(text: str, limit: int = 3800) -> list:
    """Режет длинный текст на сообщения по границам строк.

    Telegram не принимает сообщения длиннее 4096 символов. Раньше списки
    кодов просто обрезались («…и ещё 20»), и половина пула оставалась
    невидимой — а смотреть их нужно все. Теперь вместо обрезки —
    несколько сообщений подряд.
    """
    _t = text or ""
    if len(_t) <= limit:
        return [_t]
    _out, _cur = [], ""
    for _line in _t.split("\n"):
        # Одна строка длиннее лимита — режем её саму, иначе цикл встанет.
        while len(_line) > limit:
            if _cur:
                _out.append(_cur); _cur = ""
            _out.append(_line[:limit]); _line = _line[limit:]
        if len(_cur) + len(_line) + 1 > limit:
            _out.append(_cur); _cur = _line
        else:
            _cur = (_cur + "\n" + _line) if _cur else _line
    if _cur:
        _out.append(_cur)
    # Подписываем части: иначе непонятно, это весь список или он оборвался.
    if len(_out) > 1:
        _n = len(_out)
        _out = [f"{_p}\n\n<i>— часть {_i + 1} из {_n} —</i>"
                for _i, _p in enumerate(_out)]
    return _out


async def gpt_order_mark_activated(order_id: str, user_id: int, code: str,
                                   email: str = "", org: str = "",
                                   note: str = "") -> bool:
    """Переводит ИСХОДНОЕ сообщение заказа у админа в «активирован».

    Одно место на все пути, которыми бот узнаёт об успехе: обычная активация,
    сверка оборванных, сверка потерянных, ручное подтверждение. Раньше каждый
    путь решал сам, и получалось вразнобой: обычная активация сообщение
    правила, сверка оборванных — нет (слала отдельное), а при пропуске
    использованных кодов даже успех уходил НОВЫМ сообщением. В чате оставалась
    карточка «заказ оплачен» или «НЕУДАЧА», хотя подписка давно выдана.

    Возвращает True, если сообщение действительно поправлено.
    """
    if not order_id:
        return False
    try:
        _ord = await fk_get_order(order_id)
    except Exception as _e:
        logging.warning(f"order_mark: не прочитал заказ {order_id}: {_e}")
        return False
    _amid = (_ord or {}).get("admin_msg_id")
    if not _amid:
        return False
    # Ник печатался ДВАЖДЫ: сначала «@ник», следом _who_user(), который сам
    # возвращает «@ник (id)». В чат уходило «@Ruslik81 (@Ruslik81 (116211210))».
    # Нашёл по скриншоту Александра 04.10.2026.
    import html as _h_om
    _un = _fn = ""
    try:
        _u = await get_user(user_id)
        _un = ((_u or {}).get("username") or "").strip()
        _fn = ((_u or {}).get("full_name") or "").strip()
    except Exception:
        pass
    _nick = ("@" + _un) if _un else (_h_om.escape(strip_surrogates(_fn)) or f"id{user_id}")
    # Тариф и оплата — из заказа: в этой карточке их не было вовсе.
    _plan_om = _pay_om = _promo_om = ""
    try:
        _o_om = await fk_get_order(order_id) or {}
        _amt_om = _o_om.get("amount_rub")
        _pm_om = {"sbp": "СБП", "card": "карта"}.get(
            (_o_om.get("payment_method") or "").strip().lower(), "")
        _bits_om = []
        if _amt_om:
            _bits_om.append(f"<b>{int(_amt_om)} \u20bd</b>")
        if _pm_om:
            _bits_om.append(_pm_om)
        if _o_om.get("paid_at"):
            try:
                _bits_om.append(_o_om["paid_at"].astimezone(_BOT_TZ).strftime("%d.%m %H:%M"))
            except Exception:
                pass
        _pay_om = " \u00b7 ".join(_bits_om)
        _promo_om = (_o_om.get("promo_code") or "").strip()
    except Exception as _e_om:
        logging.warning(f"order_mark: заказ {order_id}: {_e_om}")
    try:
        _pl_om = await _gpt_plan_of_code(code)
    except Exception:
        _pl_om = ""
    _att_om = await gpt_attempts_block(order_id)
    _txt = (f"✅ <b>Заказ активирован</b>\n\n"
            f"👤 Клиент: <b>{_nick}</b>  (<code>{user_id}</code>)\n"
            + (f"📦 Тариф: <b>{_h_om.escape(_pl_om)}</b>\n" if _pl_om else "")
            + (f"💳 Оплата: {_pay_om}\n" if _pay_om else "")
            + (f"🎟 Промокод: <b>{_h_om.escape(_promo_om)}</b>\n" if _promo_om else "")
            + f"🔑 Код: <code>{code}</code>\n"
            + (f"📧 Email: <b>{_h_om.escape(str(email))}</b>\n" if email else "")
            + (f"🏢 Organization: <code>{_h_om.escape(str(org))}</code>\n" if org else "")
            + f"🆔 Order: <code>{order_id}</code>\n"
            + f"{await _fk_num_line(order_id)}"
            + (f"\n{_att_om}\n" if _att_om else "")
            + (f"\n<i>{note}</i>" if note else ""))
    try:
        await bot.edit_message_text(_txt, chat_id=ADMIN_ID, message_id=_amid,
                                    parse_mode="HTML")
        return True
    except Exception as _e2:
        # «message is not modified» — тоже успех: карточка уже в нужном виде.
        if "not modified" in str(_e2).lower():
            return True
        logging.warning(f"order_mark: не поправил сообщение {order_id}: {_e2}")
        return False


async def gpt_lost_activations_scan(hours: int = 48, only_new: bool = True) -> list:
    """Ищет активации, которые ПРОШЛИ, а бот записал их как неудачу.

    Откуда берётся этот случай. Перебор «код уже использован» помечает код
    использованным без order_id и без почты, а строку ожидания затирает
    следующий код. Из-за этого фоновый сверщик оборванных активаций
    (gpt_reconcile_orphans) такие коды не видит вовсе: он смотрит только
    gpt_pending_activations. А на сайте код при этом значится fulfilled, с
    почтой клиента и временем в минуту от нашей попытки — то есть подписка
    клиенту УШЛА, просто бот об этом не узнал (15.09.2026, три заказа подряд).

    Сам ничего не пишет и ничего не возвращает в пул: отдаёт находки, решение
    за человеком. Это то же правило, что и с кодами, — бот не распоряжается
    ими молча.
    """
    from chatgpt_activation import (bpa_query_codes, BPA_USED_STATUSES,
                                    _email_from_session, _same_email, same_org,
                                    _org_norm)
    _h = max(1, min(int(hours or 48), 24 * 30))
    pool = await get_pool()
    async with pool.acquire() as conn:
        rows = await conn.fetch(
            "SELECT c.code, c.used_by, c.used_at, COALESCE(u.username,'') AS username "
            "FROM gpt_codes c LEFT JOIN users u ON u.user_id=c.used_by "
            "WHERE c.provider='bpa' AND c.is_used=TRUE AND c.used_by IS NOT NULL "
            "  AND (c.order_id IS NULL OR c.order_id='') "
            "  AND c.used_at >= NOW() - make_interval(hours => $1) "
            # Код, который прямо сейчас активируют, не трогаем.
            "  AND NOT EXISTS (SELECT 1 FROM gpt_pending_activations p "
            "                  WHERE p.code = c.code) "
            "ORDER BY c.used_at DESC LIMIT 200", _h)
    if not rows:
        return []
    _st = await bpa_query_codes([r["code"] for r in rows])
    if not _st:
        logging.warning("gpt_lost_activations: сайт не ответил — ничего не решаем")
        return []

    # Пометки забираем ОДНИМ запросом, а не по одной на строку: цикл теперь
    # ходит каждые 5 минут, и 200 отдельных SELECT'ов за проход — это 2400
    # запросов в час на пустом месте.
    _seen_keys = set()
    if only_new:
        try:
            async with pool.acquire() as _c_seen:
                _seen_keys = {x["key"] for x in await _c_seen.fetch(
                    "SELECT key FROM settings WHERE key LIKE 'lostact:%' AND value='1'")}
        except Exception as _e_sk:
            logging.warning(f"lostact: не прочитал пометки: {_e_sk}")

    out, _arm = [], []
    # Одно соединение на весь проход. Раньше каждая строка брала своё —
    # при 200 находках это 200 захватов пула подряд.
    async with pool.acquire() as conn2:
        for r in rows:
            _info = _st.get((r["code"] or "").strip().upper()) or {}
            _v = (_info.get("status") or "").lower()
            if _v not in BPA_USED_STATUSES:
                continue                      # цел или неизвестен — это другой разговор
            _uid = int(r["used_by"])
            # Уже показывали — второй раз не дёргаем. НО только когда нас зовёт
            # фоновый цикл: он помечает находку показанной сразу после отправки
            # сообщения, и если бы этот фильтр действовал всегда, кнопка под тем
            # самым сообщением НИКОГДА бы не сработала — проверка при нажатии
            # просто не нашла бы код и ответила «условия изменились».
            # В ключ входит и КЛИЕНТ. Иначе так: код пометили, потом вернули в пул
            # (сайт сказал «цел»), он ушёл другому клиенту и снова сгорел — а
            # пометка старая, и находка молча не придёт. Пометка, которая глушит
            # будущие потери, хуже её отсутствия.
            if only_new and f"lostact:{r['code']}:{_uid}" in _seen_keys:
                continue
            # Почта клиента: сперва из его текущей сессии, иначе из его же прошлой
            # удачной активации. Без почты решать НЕЛЬЗЯ: «код потрачен» само по
            # себе не значит «потрачен нашим клиентом».
            _mine = ""
            _pr = await conn2.fetchrow(
                "SELECT session_raw FROM gpt_pending_activations WHERE user_id=$1", _uid)
            if _pr and _pr["session_raw"]:
                try:
                    _mine = _email_from_session(_pr["session_raw"]) or ""
                except Exception:
                    _mine = ""
            if not _mine:
                # Основной источник: почта, сохранённая в момент активации.
                _mine = await conn2.fetchval(
                    "SELECT gpt_email FROM users WHERE user_id=$1", _uid) or ""
            _mine_org = await conn2.fetchval(
                    "SELECT gpt_org FROM users WHERE user_id=$1", _uid) or ""
            _hint_org = await conn2.fetchval(
                    "SELECT gpt_org_hint FROM users WHERE user_id=$1", _uid) or ""
            if not _mine:
                _mine = await conn2.fetchval(
                    "SELECT email FROM gpt_codes WHERE used_by=$1 AND COALESCE(email,'')<>'' "
                    "ORDER BY used_at DESC LIMIT 1", _uid) or ""
            # Заказ, к которому это относится: ближайшая оплата ChatGPT
            # этого клиента до момента сжигания.
            # Берём БЛИЖАЙШИЙ заказ, к которому ещё не привязан ни один код.
            # Иначе код прицепился бы к заказу, который давно закрыт другим
            # кодом, и в разбивке прибыли появилось бы «ушло несколько кодов»
            # там, где ушёл один.
            _ord = await conn2.fetchrow(
                "SELECT f.order_id FROM fk_orders f "
                "WHERE f.user_id=$1 AND f.status='paid' "
                "  AND f.pack LIKE 'shop:chatgpt:%' "
                "  AND f.paid_at <= $2::timestamptz + INTERVAL '10 minutes' "
                "  AND NOT EXISTS (SELECT 1 FROM gpt_codes g "
                "                  WHERE g.order_id = f.order_id) "
                "ORDER BY f.paid_at DESC LIMIT 1", _uid, r["used_at"])
            _site_mail = _info.get("email") or ""
            _site_org = _info.get("org") or ""
            # Organization ID — сильнее почты: он точный, а почта на сайте
            # замаскирована. И у тарифа Go почты нет вовсе, сверять можно
            # ТОЛЬКО по нему. Поэтому сначала он, потом почта.
            _match = same_org(_site_org, _mine_org)
            _by = "org" if _match is not None else ""
            # Кандидаты из начала токена: совпал — значит наш, это факт.
            # Не совпал — НЕ доказательство: среди них может быть id сессии.
            # Поэтому здесь только True, а False отсюда не бывает.
            if _match is None and _site_org and _hint_org:
                if _org_norm(_site_org) in [
                        _org_norm(x) for x in _hint_org.split(",") if x.strip()]:
                    _match, _by = True, "org"
            if _match is None and _site_mail and _mine:
                _match = bool(_same_email(_site_mail, _mine))
                _by = "email"
            # «claimed» — активация ещё идёт, подписки нет. Предлагать её
            # записать нельзя: кнопка «Записать активацию» сделала бы ровно
            # ту ошибку, из-за которой всё это и правится. Аудит 01.10.2026.
            _ip_row = (_v == "claimed")
            if _ip_row:
                _match = None
            out.append({
                "code": r["code"], "user_id": _uid,
                "user": ("@" + r["username"]) if r["username"] else f"id{_uid}",
                "status": _v, "site_email": _site_mail, "client_email": _mine,
                "in_progress": _ip_row,
                "match": _match,                  # True / False / None (не с чем сверить)
                "by": _by,                        # по чему сверили: org | email | ''
                "site_org": _site_org, "client_org": _mine_org,
                "burned_at": r["used_at"],
                "site_when": _info.get("when", ""),
                "order_id": (_ord or {}).get("order_id") or "",
            })
            if _ip_row:
                _arm.append((r["code"], _uid, (_ord or {}).get("order_id") or ""))
    # Слежение заводим ПОСЛЕ выхода из блока с conn2: брать вторую коннекцию,
    # держа первую, — прямой путь к исчерпанию пула (см. log_event).
    # Без этого обещание «слежу за ним каждую минуту» было бы ложью: у кодов
    # из этого разбора строки ожидания НЕТ (её затёр следующий код), поэтому
    # сверка их не видит и слежение само не заводится.
    for _c_arm, _u_arm, _o_arm in _arm:
        try:
            _k_arm = f"gptclaim:{str(_c_arm).strip().upper()}"
            if not (await get_setting(_k_arm, "") or "").strip():
                import time as _t_arm
                await set_setting(_k_arm, f"{_u_arm}|{_o_arm}|{int(_t_arm.time())}|")
        except Exception as _e_arm:
            logging.warning(f"lostscan: слежение за {_c_arm}: {_e_arm}")
    return out


async def _gpt_apply_from_pending(code: str, force: bool = False):
    """Записывает активацию по ЖИВОЙ строке ожидания — только по команде человека.

    Зачем отдельный путь. gpt_lost_activations_scan по построению ищет коды
    БЕЗ строки ожидания (её затирает следующий код) — поэтому коды, у которых
    строка жива, он не возвращает вовсе. А слежение за «claimed» создаёт ровно
    такой случай: код дозрел до fulfilled, сверка личность подтвердить не
    смогла (у тарифа Go сайт не показывает ни почту, ни Organization ID),
    строку ожидания она НЕ удаляет — и кнопка «Записать активацию» под её
    сообщением вела в тупик «Условия изменились: на сайте сейчас fulfilled».
    Поймал Александр 01.10.2026 на GPTGO-1FP6-KSLN-21BI.

    Возвращает None, если строки ожидания нет (тогда работает обычный путь).
    Бот сам сюда не заходит: только кнопка или /gpt_lost_ok.
    """
    from chatgpt_activation import (bpa_query_codes, BPA_DONE_STATUSES,
                                    _same_email, same_org, _org_norm)
    pool = await get_pool()
    async with pool.acquire() as conn:
        _p = await conn.fetchrow(
            "SELECT user_id, order_id, plan_name FROM gpt_pending_activations "
            "WHERE UPPER(code)=$1", code.strip().upper())
    if not _p:
        return None
    _q = await bpa_query_codes([code])
    if not _q:
        return {"ok": False, "msg": "Сайт не ответил — попробуй позже."}
    _info = _q.get(code.strip().upper()) or {}
    _v = str(_info.get("status") or "").strip().lower()
    if _v not in BPA_DONE_STATUSES:
        _tail = ("\n\nСайт отпустил код — активация не прошла. Нужна повторная "
                 "активация ЭТИМ ЖЕ кодом; сам я её не запускаю."
                 if _v == "unused" else
                 f"\n\nРазбор: <code>/gpt_why {code}</code>")
        return {"ok": False,
                "msg": f"На сайте сейчас «{_v or '?'}» — подписка ещё не выдана. "
                       f"Записывать нечего." + _tail}
    _uid = int(_p["user_id"])
    _oid = (_p["order_id"] or "").strip()
    if not _oid:
        return {"ok": False,
                "msg": "В строке ожидания нет номера заказа — записывать не к чему."}
    _site_mail = _info.get("email") or ""
    _site_org = _info.get("org") or ""
    async with pool.acquire() as conn:
        _u = await conn.fetchrow(
            "SELECT gpt_email, gpt_org, gpt_org_hint FROM users WHERE user_id=$1", _uid)
    _cl_mail = ((_u["gpt_email"] if _u else "") or "")
    _cl_org = ((_u["gpt_org"] if _u else "") or "")
    _hint = ((_u["gpt_org_hint"] if _u else "") or "")
    # Тот же порядок, что в сверке: сперва Organization ID, потом почта.
    _m = same_org(_site_org, _cl_org)
    if _m is None and _site_org and _hint:
        if _org_norm(_site_org) in [_org_norm(x) for x in _hint.split(",") if x.strip()]:
            _m = True
    if _m is None and _site_mail and _cl_mail:
        _m = bool(_same_email(_site_mail, _cl_mail))
    if _m is False:
        return {"ok": False,
                "msg": "Аккаунт на сайте и аккаунт клиента РАЗНЫЕ — записывать "
                       "активацию этому клиенту нельзя."}
    if _m is None and not force:
        return {"ok": False,
                "msg": ("Подписка на сайте выдана, но ЧЕЙ это аккаунт — "
                        "подтвердить нечем: сайт не показал ни почту, ни "
                        "Organization ID. Для тарифа Go это обычное дело.\n\n"
                        f"Если проверил сам: <code>/gpt_lost_ok {code}</code>")}
    await mark_gpt_code_used(code, _uid, _oid, _site_mail or _cl_mail)
    # Именно ЭТОГО заказа: у клиента мог появиться резерв по другой оплате.
    try:
        await delete_pending_activation(_uid, _oid)
    except Exception as _e_dp:
        logging.warning(f"apply_from_pending: не закрыл строку ожидания {code}: {_e_dp}")
    try:
        await gpt_order_mark_activated(
            _oid, _uid, code, _site_mail or _cl_mail, _site_org,
            "Подписка на сайте выдана; записано по твоему подтверждению.")
    except Exception as _e_oc:
        logging.warning(f"apply_from_pending: карточка заказа {_oid}: {_e_oc}")
    try:
        await bot.send_message(
            _uid,
            "✅ <b>Подписка всё-таки активна</b>\n\n"
            "Мы перепроверили: активация прошла, хотя бот сообщил об ошибке. "
            "Загляни в ChatGPT — подписка уже должна быть на месте.\n\n"
            "Извини за путаницу 🙌",
            parse_mode="HTML")
    except Exception as _e_cl:
        logging.info(f"apply_from_pending: клиенту {_uid} не написалось: {_e_cl}")
    logging.warning(f"apply_from_pending: записал активацию {code} → uid={_uid} "
                    f"заказ={_oid} (статус сайта {_v})")
    return {"ok": True, "user_id": _uid, "order_id": _oid,
            "email": _site_mail or _cl_mail}


async def gpt_lost_activation_apply(code: str, force: bool = False) -> dict:
    """Записывает найденную активацию — ТОЛЬКО по команде человека.

    Перед записью сайт спрашивается ЗАНОВО: сообщение могло пролежать в чате
    час, и за это время всё могло измениться.

    force=True — человек проверил сам и берёт ответственность на себя. Нужен
    для старых случаев, где почты клиента в базе просто нет (её начали
    сохранять только теперь), — иначе такие находки были бы тупиком: бот не
    может подтвердить, а у Александра нет способа сказать «я проверил».
    Разные почты force НЕ переопределяет: там ошибка стоила бы клиенту чужой
    подписки в профиле. Дальше — то же, что сделал бы
    удачный проход: код получает заказ и почту (именно это и есть запись
    подписки, профиль читает её отсюда), сообщение заказа у админа правится
    на «активировано», клиенту уходит короткое «подписка всё-таки активна».
    """
    from chatgpt_activation import bpa_query_codes, BPA_USED_STATUSES, _same_email
    code = (code or "").strip()
    if not code:
        return {"ok": False, "msg": "Пустой код"}
    # Сообщение с кнопкой могло пролежать в чате час. Спрашиваем сайт ЗАНОВО
    # именно про claimed: записывать активацию, которой ещё нет, нельзя ни по
    # кнопке, ни по команде. Аудит 01.10.2026.
    try:
        _v_now = str(((await bpa_query_codes([code])).get(code.upper())
                      or {}).get("status") or "").strip().lower()
        if _v_now == "claimed":
            return {"ok": False,
                    "msg": ("Сайт держит код в «claimed» — это значит, что код "
                            "привязан к аккаунту, а подписка ещё НЕ выдана. "
                            "Записывать нечего.\n\nСлежу за ним каждую минуту и "
                            "напишу, когда станет fulfilled (подписка выдана) или "
                            "unused (не прошло, нужна повторная активация тем же "
                            "кодом).")}
    except Exception as _e_cq:
        logging.warning(f"gpt_lost_activation_apply: /query {code}: {_e_cq}")
    _found = None
    for _f in await gpt_lost_activations_scan(hours=24 * 30, only_new=False):
        if _f["code"].upper() == code.upper():
            _found = _f
            break
    if not _found:
        # Сначала пробуем ЖИВУЮ строку ожидания: разбор потерянных активаций
        # такие коды не возвращает вовсе, и без этой ветки кнопка «Записать
        # активацию» под сообщением слежения вела в тупик.
        _by_pending = await _gpt_apply_from_pending(code, force=force)
        if _by_pending is not None:
            return _by_pending
        # Код УЖЕ записан — самый частый случай второго нажатия. Раньше он
        # сваливался в «условия изменились», и выглядело это как сбой, хотя
        # всё в порядке. Проверка матрицей «точка входа × состояние кода»,
        # 01.10.2026.
        try:
            _pool_al = await get_pool()
            async with _pool_al.acquire() as _c_al:
                _al = await _c_al.fetchrow(
                    "SELECT order_id, used_by, email FROM gpt_codes "
                    "WHERE UPPER(code)=$1", code.strip().upper())
            if _al and (_al["order_id"] or "").strip():
                return {"ok": False,
                        "msg": (f"Эта активация уже записана: код привязан к "
                                f"заказу <code>{_al['order_id']}</code>"
                                + (f", почта <code>{_al['email']}</code>" if _al["email"] else "")
                                + ".\n\nДелать ничего не нужно. Разбор: "
                                  f"<code>/gpt_why {code}</code>")}
        except Exception as _e_al:
            logging.warning(f"gpt_lost_activation_apply: проверка записи {code}: {_e_al}")
        # Мог быть возвращён в пул или сайт передумал.
        _st = await bpa_query_codes([code])
        if not _st:
            return {"ok": False, "msg": "Сайт не ответил — попробуй позже."}
        _v = ((_st.get(code.upper()) or {}).get("status") or "").lower()
        return {"ok": False,
                "msg": f"Условия изменились: на сайте сейчас «{_v or '?'}». "
                       f"Ничего не записал."}
    if _found["match"] is False:
        return {"ok": False,
                "msg": "Почта клиента и почта на сайте РАЗНЫЕ — "
                       "записывать активацию этому клиенту нельзя."}
    if _found["match"] is None and not force:
        return {"ok": False,
                "msg": "Сверить почту не с чем — бот подтвердить не может.\n"
                       f"Если проверил сам: <code>/gpt_lost_ok {code}</code>"}
    _uid = _found["user_id"]
    _oid = _found["order_id"]
    if not _oid:
        return {"ok": False, "msg": "Не нашёл оплаченный заказ ChatGPT у этого клиента."}
    await mark_gpt_code_used(code, _uid, _oid, _found["site_email"])
    await set_setting(f"lostact:{code}:{_uid}", "1")
    # Строку ожидания, если она ещё висит на этом клиенте, закрываем.
    try:
        pool = await get_pool()
        async with pool.acquire() as conn:
            await conn.execute(
                "DELETE FROM gpt_pending_activations WHERE user_id=$1 AND code=$2",
                _uid, code)
    except Exception as _e_p:
        logging.warning(f"lostact: не закрыл pending {code}: {_e_p}")
    # Карточка заказа — тем же помощником, что и все остальные пути.
    try:
        await gpt_order_mark_activated(
            _oid, _uid, code, _found["site_email"], _found.get("site_org") or "",
            "Активация прошла на сайте, но бот её не записал — "
            "дописано по твоему подтверждению.")
    except Exception as _e_m:
        logging.warning(f"lostact: карточка заказа {_oid}: {_e_m}")
    # И клиенту — он получил «не получилось» и, скорее всего, ждёт.
    try:
        await bot.send_message(
            _uid,
            "✅ <b>Подписка всё-таки активна</b>\n\n"
            "Мы перепроверили: активация прошла, хотя бот сообщил об ошибке. "
            "Загляни в ChatGPT — Plus уже должен быть на месте.\n\n"
            "Извини за путаницу 🙌",
            parse_mode="HTML")
    except Exception as _e_c:
        logging.info(f"lostact: клиенту {_uid} не написалось: {_e_c}")
    logging.warning(f"lostact: записал активацию {code} → uid={_uid} заказ={_oid}")
    return {"ok": True, "user_id": _uid, "order_id": _oid,
            "email": _found["site_email"]}


async def balance_report(user_id: int) -> str:
    """Откуда у клиента кредиты и монетки и куда они делись.

    18.09.2026 клиент написал: «монетки-кэшбэк насыпались, а потом куда-то
    пропали, и кредиты пропадают». Ответить было нечем: движения монеток
    пишутся только в лог Railway, а он ротируется. Классическая закрытая
    стена — цифра есть, объяснить её нечем.

    Что здесь восстанавливается по базе:
      • кредиты — целиком: партии хранят источник, срок и остаток, и по ним
        видно, что именно сгорело и когда;
      • монетки — частично: сколько потрачено, видно по заказам (в каждом
        записано coins_spent). Сколько было НАЧИСЛЕНО, задним числом взять
        неоткуда — с этого дня пишем в события.
    """
    pool = await get_pool()
    _uid = int(user_id)
    async with pool.acquire() as conn:
        _u = await conn.fetchrow(
            "SELECT username, full_name, credits, COALESCE(coins,0) AS coins "
            "FROM users WHERE user_id=$1", _uid)
        if not _u:
            return f"Клиент <code>{_uid}</code> в базе не найден."
        _b = await conn.fetch(
            "SELECT credits_init, credits_left, source, expires_at, created_at "
            "FROM credit_batches WHERE user_id=$1 ORDER BY created_at", _uid)
        _sp = await conn.fetch(
            "SELECT order_id, coins_spent, amount_rub, paid_at, status "
            "FROM fk_orders WHERE user_id=$1 AND COALESCE(coins_spent,0)>0 "
            "ORDER BY created_at", _uid)
        _ev = await conn.fetch(
            "SELECT kind, data, created_at FROM events "
            "WHERE user_id=$1 AND kind IN ('coins','batch_expired') "
            "ORDER BY created_at DESC LIMIT 20", _uid)

    _tag = ("@" + _u["username"]) if _u["username"] else (_u["full_name"] or "без ника")
    import html as _h_b
    _L = [f"💰 <b>Баланс клиента</b>\n"
          f"👤 {_h_b.escape(str(_tag))} ({await _who_user(_uid)})\n"
          f"💵 Кредитов сейчас: <b>{int(_u['credits'] or 0)}</b>\n"
          f"🪙 Монеток сейчас: <b>{float(_u['coins'] or 0):.0f} ₽</b>"]

    # ── Кредиты по партиям
    _L.append("\n<b>Кредиты — откуда и куда:</b>")
    if not _b:
        _L.append("  партий нет (кредиты начислялись до появления партий "
                  "или напрямую).")
    else:
        _SRC = {"purchase": "покупка", "referral": "за друга", "promo": "промокод",
                "free": "бонус", "admin_manual": "начислено вручную",
                "admin": "начислено вручную"}
        _burned = 0
        import datetime as _dt_b
        _now = _dt_b.datetime.now()
        for r in _b:
            _src = _SRC.get((r["source"] or "").strip(), r["source"] or "—")
            _when = r["created_at"].strftime("%d.%m.%Y") if r["created_at"] else "—"
            _init, _left = int(r["credits_init"] or 0), int(r["credits_left"] or 0)
            _exp = r["expires_at"]
            if _exp is None:
                _tail = "не сгорает"
            elif _exp <= _now:
                _lost = _init - _left if _left == 0 else 0
                _burned += max(0, _init - _left) if _left == 0 else 0
                _tail = f"<b>сгорела {_exp.strftime('%d.%m.%Y')}</b>"
            else:
                _tail = f"сгорит {_exp.strftime('%d.%m.%Y')}"
            _L.append(f"  • {_when} · {_src} · {_init} кр"
                      + (f" (осталось {_left})" if _left != _init else "")
                      + f" — {_tail}")
        if _burned:
            _L.append(f"  <b>Сгорело всего: {_burned} кр.</b> Бонусные кредиты "
                      f"(за друга, промокод) живут 30 дней. Купленные и "
                      f"начисленные вручную не сгорают никогда.")

    # ── Монетки
    _L.append("\n<b>Монетки — куда потрачены:</b>")
    if not _sp:
        _L.append("  ни в одном заказе монетки не списывались.")
    else:
        _tot = 0
        for r in _sp:
            _when = r["paid_at"].strftime("%d.%m.%Y") if r["paid_at"] else "—"
            _cs = int(r["coins_spent"] or 0)
            _tot += _cs if (r["status"] or "") == "paid" else 0
            _L.append(f"  • {_when} · заказ <code>{_h_b.escape(str(r['order_id']))}</code>"
                      f" · −{_cs} ₽"
                      + ("" if (r["status"] or "") == "paid" else " <i>(не оплачен — возвращены)</i>"))
        _L.append(f"  <b>Списано по оплаченным заказам: {_tot} ₽</b>")
    _L.append("  <i>Монетки НЕ сгорают: их можно только потратить при оплате. "
              "Если заказ не оплачен, они возвращаются через сутки.</i>")

    # ── Движения, записанные с 18.09.2026
    if _ev:
        _L.append("\n<b>Последние движения:</b>")
        for r in _ev:
            _when = r["created_at"].strftime("%d.%m %H:%M") if r["created_at"] else "—"
            _L.append(f"  {_when} · {_h_b.escape(str(r['data'] or r['kind']))}")
    else:
        _L.append("\n<i>Подробных движений пока нет — их начали записывать "
                  "18.09.2026. За более ранние периоды выше только то, что "
                  "восстанавливается по заказам и партиям.</i>")
    return "\n".join(_L)


async def gpt_recheck_report(code: str = "") -> str:
    """Проверить активации ПРЯМО СЕЙЧАС и сказать, чем кончилось.

    Александр 17.09.2026: «нужно чтобы я сам мог запускать проверку, чтобы не
    ждать по несколько минут». Сверка и так ходит раз в пять минут, но когда
    сообщение о неудаче уже пришло и на сайте видно, что активация прошла,
    ждать эти минуты нечего.

    С кодом — проверяем только его и без порогов по времени. Без кода —
    прогоняем обычную сверку целиком.
    """
    try:
        _r = await gpt_reconcile_orphans(only_code=(code or "").strip())
    except Exception as _e_rr:
        logging.warning(f"gpt_recheck_report: {_e_rr}")
        return f"⚠️ Не смог проверить: {_e_rr}"
    if not _r.get("ok") and _r.get("error"):
        return f"⚠️ {_r['error']}"
    _fx, _un = _r.get("fixed") or [], _r.get("unsure") or []
    _ip = _r.get("in_progress") or []
    if not _fx and not _un and not _ip:
        return ("🔍 Проверил — закрывать нечего.\n\n"
                "<i>Либо сайт ещё не считает код потраченным, либо строки "
                "ожидания по нему нет. Подробности: /gpt_why КОД</i>")
    # Если сверка ПЕРЕПИСАЛА карточку заказа, повторять то же самое отдельным
    # сообщением незачем: кнопка «Проверить сейчас» висит на самой карточке,
    # и она обновляется прямо под пальцем. Александр 02.10.2026.
    _fx = [_f for _f in _fx if not _f.get("card_updated")]
    if not _fx and not _un and not _ip:
        return ""        # вызывающий не отправляет ничего
    _L = []
    # Про «активация идёт» Александру сейчас расскажет ЭТОТ отчёт — значит
    # петля слежения об этом уже не пишет. Ставим ей флаг «объявлено» сами:
    # иначе через минуту придёт второе сообщение ровно о том же.
    # Александр 02.10.2026.
    for _p in _ip:
        try:
            _k_ann = f"gptclaim:{str(_p['code']).strip().upper()}"
            _v_ann = (await get_setting(_k_ann, "") or "").strip()
            if _v_ann:
                _pp = _v_ann.split("|")
                while len(_pp) < 4:
                    _pp.append("")
                if "a" not in _pp[3]:
                    _pp[3] += "a"
                    await set_setting(_k_ann, "|".join(_pp[:4]))
        except Exception as _e_ann:
            logging.warning(f"recheck: флаг объявления {_p.get('code')}: {_e_ann}")
    for _p in _ip:
        _L.append(f"⏳ <b>Активация ИДЁТ — подписки ещё нет</b>\n"
                  f"👤 {await _who_user(_p['user_id'])} · {_p.get('plan_name') or '—'}\n"
                  f"🔑 <code>{_p['code']}</code> · сайт: <b>claimed</b>\n"
                  + (f"🆔 <code>{_p['order_id']}</code>\n" if _p.get("order_id") else "")
                  + "\n«claimed» значит, что код привязан к аккаунту, а подписка "
                    "ещё не выдана. Ничего не записываю и резерв не трогаю.\n"
                    "Слежу за кодом каждую минуту и напишу, когда станет "
                    "<b>fulfilled</b> (подписка выдана) или <b>unused</b> "
                    "(не прошло — понадобится повторная активация этим же кодом).")
    for _f in _fx:
        _L.append(f"✅ <b>Активация записана</b>\n"
                  f"👤 {await _who_user(_f['user_id'])} · {_f.get('plan_name') or '—'}\n"
                  f"🔑 <code>{_f['code']}</code>\n"
                  + (f"📧 {_f['email']}\n" if _f.get("email") else "")
                  + f"🆔 <code>{_f.get('order_id') or '—'}</code>\n"
                  + "Карточка заказа поправлена, клиенту сообщил.")
    for _u in _un:
        _L.append(f"❓ <b>Подтвердить не могу</b>\n"
                  f"👤 {await _who_user(_u['user_id'])}\n"
                  f"🔑 <code>{_u['code']}</code> — сайт: {_u.get('status') or '—'}\n"
                  f"📧 на сайте: <code>{_u.get('site_email') or '—'}</code>\n"
                  f"📧 у клиента: <code>{_u.get('client_email') or '—'}</code>\n"
                  f"Подписку НЕ записывал. Если проверил сам — "
                  f"<code>/gpt_lost_ok {_u['code']}</code>")
    return "\n\n".join(_L)


async def gpt_why(code: str) -> str:
    """Отчёт: что бот видит по КОНКРЕТНОМУ коду и почему бездействует.

    Появилась после 17.09.2026. Код GPTGO-…-9E8N: сайт показывал fulfilled и
    Organization ID, а бот за десять минут не дописал активацию и ничего не
    сообщил. Проверить это было нечем: все звенья цепочки — строка ожидания,
    сроки, ответ сайта, сохранённый id клиента — живут в разных местах, и
    единственным способом разобраться была археология по коду.

    Здесь бот отвечает сам: что лежит в базе, что говорит сайт, совпадают ли
    личности, попадает ли код под сроки сверки и чем всё кончится. Ничего не
    меняет — только показывает.
    """
    from chatgpt_activation import (bpa_query_codes, BPA_USED_STATUSES,
                                    BPA_FREE_STATUSES, same_org, _same_email,
                                    _org_norm, _org_kind)
    code = (code or "").strip().upper()
    if not code:
        return "Пустой код."

    # Всё, что пришло СНАРУЖИ — от сайта проверки, из имени клиента, из
    # пометки кода — экранируем. Один символ «<» в ответе сайта превратил бы
    # отчёт в сообщение, которое Telegram откажется отправить, и вместо
    # разбора я бы получил пустоту — ровно там, где разбираюсь с пустотой.
    import html as _h_w
    def _e(v):
        return _h_w.escape(str(v if v is not None else ""))

    _L = [f"🔎 <b>Разбор кода</b>\n<code>{_e(code)}</code>\n"]
    pool = await get_pool()

    # ── 1. Что знает наша база
    async with pool.acquire() as conn:
        _c = await conn.fetchrow(
            "SELECT code, provider, is_used, used_by, used_at, order_id, email, "
            "check_status, flagged_reason FROM gpt_codes WHERE UPPER(code)=$1", code)
        _p = await conn.fetchrow(
            "SELECT user_id, order_id, plan_name, provider, created_at, activating_at, "
            "EXTRACT(EPOCH FROM (NOW()-created_at))/60 AS age_min, "
            "EXTRACT(EPOCH FROM (NOW()-activating_at))/60 AS act_min "
            "FROM gpt_pending_activations WHERE UPPER(code)=$1", code)
    # Раньше на отсутствии кода в пуле отчёт ЗАКАНЧИВАЛСЯ — «такого кода нет»
    # и всё. А кода в пуле может не быть по совершенно обычным причинам: его
    # удалили вручную, почистили пул, он пришёл не оттуда. При этом строка
    # ожидания, ответ сайта и вердикт — то, ради чего команду и зовут — никуда
    # не делись. Обрывать разбор на первом же пустом месте значит оставлять
    # человека ровно с тем вопросом, с которым он пришёл.
    _uid = (_c["used_by"] if _c else None) or (_p["user_id"] if _p else None)
    _L.append("<b>В пуле:</b>")
    if not _c:
        _L.append("  такого кода нет — мог быть удалён вручную или вычищен.")
        _L.append("  <i>На разбор ниже это не влияет: сверка смотрит строку "
                  "ожидания и сайт, а не пул.</i>")
    else:
        _L.append(f"  сожжён: {'да' if _c['is_used'] else 'нет'}"
                  + (f", за клиентом <code>{_c['used_by']}</code>" if _c["used_by"] else ""))
        _L.append(f"  заказ у кода: <code>{_e(_c['order_id'] or '—')}</code>")
        if _c["check_status"]:
            _L.append(f"  пометка: <b>{_e(_c['check_status'])}</b> — "
                      f"{_e(_c['flagged_reason'] or '')}")

    # ── 2. Строка ожидания — именно её смотрит сверка оборванных активаций
    _L.append("\n<b>Строка ожидания:</b>")
    if not _p:
        _L.append("  ❗ её НЕТ — сверка оборванных активаций этот код не увидит.")
        _L.append("  <i>Её удаляют при успехе и при уходе в ручной режим.</i>")
    else:
        _L.append(f"  клиент <code>{_p['user_id']}</code> · {_e(_p['plan_name'] or '—')}"
                  f" · сайт {_e(_p['provider'] or '—')}")
        # Заказ ИЗ СТРОКИ ОЖИДАНИЯ — именно его сверка пропишет коду. Без него
        # запись пройдёт «в пустоту»: код останется без заказа, а карточку
        # заказа будет нечего править. Раньше отчёт это поле не показывал —
        # и на вопрос «почему у кода нет заказа» ответить было нечем.
        _L.append(f"  заказ: <code>{_e(_p['order_id'] or '—')}</code>"
                  + ("" if (_p["order_id"] or "")
                     else "  ⚠️ пусто — записывать активацию не к чему"))
        _L.append(f"  создана {float(_p['age_min'] or 0):.0f} мин назад")
        if _p["activating_at"] is None:
            _L.append("  метка «активация идёт»: снята")
        else:
            _L.append(f"  метка «активация идёт»: стоит {float(_p['act_min'] or 0):.0f} мин")

    # ── 3. Что говорит сайт
    _L.append("\n<b>Сайт:</b>")
    _site_st = _site_org = _site_mail = ""
    try:
        _q = await bpa_query_codes([code])
        _i = _q.get(code) or {}
        if not _q:
            _L.append("  ⛔ не ответил. Пока он молчит, сверка не работает вовсе.")
        elif not _i:
            _L.append("  кода у сайта нет.")
        else:
            _site_st = _i.get("status", "")
            _site_org = _i.get("org", "") or ""
            _site_mail = _i.get("email", "") or ""
            _L.append(f"  статус: <b>{_e(_site_st or '—')}</b>"
                      + ("  (считается использованным)" if _site_st in BPA_USED_STATUSES
                         else "  (считается свободным)" if _site_st in BPA_FREE_STATUSES
                         else "  (статус незнакомый)"))
            # Одна и та же колонка сайта содержит разное: у iOS — настоящий
            # Organization ID, у филиппинских — номер заказа на самом сайте.
            # Называем то, что видим, иначе отчёт вводит в заблуждение ровно
            # там, где в нём больше всего нуждаются.
            if _org_kind(_site_org) == "siteorder":
                _L.append(f"  🧾 номер заказа на сайте: <code>{_e(_site_org)}</code>")
                _L.append("  <i>Это НЕ Organization ID аккаунта — сверять "
                          "личность по нему нельзя, решает почта.</i>")
            else:
                _L.append(f"  org: <code>{_e(_site_org or '—')}</code>")
            _L.append(f"  почта: <code>{_e(_site_mail or '—')}</code>")
            if _i.get("when"):
                _L.append(f"  время: {_e(_i['when'])}")
    except Exception as _e_s:
        _L.append(f"  ⛔ ошибка запроса: {_e(_e_s)}")

    # ── 4. Что мы знаем о клиенте
    _cl_org = _cl_mail = _hint = ""
    if _uid:
        async with pool.acquire() as conn:
            _u = await conn.fetchrow(
                "SELECT username, gpt_email, gpt_org, gpt_org_hint FROM users WHERE user_id=$1", _uid)
        if _u:
            _cl_org = _u["gpt_org"] or ""
            _cl_mail = _u["gpt_email"] or ""
            _hint = _u["gpt_org_hint"] or ""
        _L.append("\n<b>Клиент:</b>")
        _L.append(f"  <code>{_uid}</code>"
                  + (f" @{_e(_u['username'])}" if _u and _u["username"] else ""))
        _L.append(f"  org: <code>{_e(_cl_org or '—')}</code>")
        _L.append(f"  почта: <code>{_e(_cl_mail or '—')}</code>")
        if _hint:
            _L.append(f"  кандидаты в org: <code>{_e(_hint[:120])}</code>")

    # ── 5. Вердикт — тот же порядок, что в самой сверке
    _L.append("\n<b>Сверка личности:</b>")
    _om = same_org(_site_org, _cl_org)
    if _om is True:
        _L.append("  ✅ Organization ID совпал — этого достаточно.")
    elif _om is False:
        _L.append("  ⛔ Organization ID РАЗНЫЕ — записывать нельзя ни при каких условиях.")
    else:
        _ks, _kc = _org_kind(_site_org), _org_kind(_cl_org)
        if _ks == "siteorder":
            # Филиппинский маршрут: в колонке org у сайта лежит номер его
            # СОБСТВЕННОГО заказа. Сверять по нему нечего — и это не пробел,
            # а нормальный порядок вещей для этого маршрута.
            _L.append("  ❔ сайт показал номер своего заказа, а не Organization "
                      "ID аккаунта — так он помечает филиппинские коды. "
                      "Личность сверяем по почте.")
        elif _site_org and _cl_org and _ks != _kc:
            _L.append("  ❔ по org сказать нечего: на сайте и у клиента "
                      f"идентификаторы разного вида ({_ks or 'неопознан'} и "
                      f"{_kc or 'неопознан'}). Решает почта.")
        else:
            _why = ("у клиента org не сохранён" if _site_org and not _cl_org
                    else "сайт org не показал" if _cl_org and not _site_org
                    else "org нет ни там, ни там")
            _L.append(f"  ❔ по org сказать нечего: {_why}.")
        if _site_org and _hint and _org_norm(_site_org) in [
                _org_norm(x) for x in _hint.split(",") if x.strip()]:
            _L.append("  ✅ но org с сайта есть среди кандидатов клиента — этого хватит.")
            _om = True
        elif _site_mail and _cl_mail:
            _ok_m = bool(_same_email(_site_mail, _cl_mail))
            _L.append(("  ✅ почты сходятся." if _ok_m else "  ⛔ почты РАЗНЫЕ."))
            _om = _ok_m
        else:
            _L.append("  ❔ и по почте сверить нечем"
                      + (" (сайт почту не показывает — обычное дело для Go)."
                         if not _site_mail else " (у клиента почта не сохранена)."))

    # ── 6. Что бот сделает
    _L.append("\n<b>Что будет:</b>")
    _burned_for_nothing = bool(
        _c and _c["is_used"] and not (_c["order_id"] or "")
        and _site_st and _site_st in BPA_FREE_STATUSES)
    if _burned_for_nothing:
        # Код помечен использованным, заказа за ним нет, а САЙТ говорит, что
        # он цел. Это сожжённый зря код — потерянный товар, лежащий мёртвым
        # грузом. Прежняя версия отчёта писала тут «трогать нечего» и была
        # формально права (сверка его действительно не тронет), но по сути
        # врала: делать надо, и есть чем.
        _L.append("  ⚠️ Код помечен использованным, но заказа за ним нет, "
                  "а сайт говорит, что код ЦЕЛ.")
        _L.append("  Похоже, он сгорел зря — при переборе или на оборванной "
                  "активации. В пуле его нет, продать нельзя.")
        _L.append("  Вернуть в пул: <code>/gpt_codes_recover</code>")
        if not _c["used_by"]:
            _L.append("  <i>За кодом не закреплён никто — значит это не чужая "
                      "активация, а именно потеря.</i>")
    elif _site_st and _site_st not in BPA_USED_STATUSES:
        _L.append("  Сайт не считает код потраченным — трогать нечего.")
    elif not _p and _c and _c["is_used"] and _c["used_by"] and not (_c["order_id"] or ""):
        _L.append("  Это случай для второго прохода (потерянные активации):")
        _L.append("  " + ("⏳ активация ИДЁТ (claimed) — покажу как «идёт», "
                          "кнопки записи не будет." if _site_st == "claimed"
                          else "пришлю с кнопкой «Записать активацию»." if _om is True
                          else "пришлю как «проверь вручную», сам не запишу."))
    elif _p:
        _age = float(_p["age_min"] or 0)
        _act = _p["activating_at"]
        _ready = (_act is not None and float(_p["act_min"] or 0) >= 10) or (_act is None and _age >= 7)
        if not _ready:
            _wait = (10 - float(_p["act_min"] or 0)) if _act is not None else (7 - _age)
            _L.append(f"  Ещё рано — сверка возьмёт его через ~{max(0, _wait):.0f} мин.")
        elif _site_st == "claimed":
            # Диагностика обязана говорить правду. После 01.10.2026 сверка на
            # claimed НИЧЕГО не дописывает: это середина активации, подписки
            # ещё нет. Прежний текст обещал «допишет сам» и расходился с
            # поведением — хуже, чем молчание.
            _L.append("  ⏳ Сайт держит код в «claimed» — активация ИДЁТ, "
                      "подписки ещё нет.")
            _L.append("  Сверка тут ничего не запишет и резерв не тронет.")
            _L.append("  Код под слежением: проверяю раз в минуту и сообщу, "
                      "когда станет fulfilled (подписка выдана) или unused "
                      "(не прошло — нужна повторная активация этим же кодом).")
        elif _om is True:
            _L.append("  Допишет активацию сам и поправит карточку заказа.")
            if _c and not (_c["order_id"] or ""):
                # Отвечает на вопрос «почему у кода не написан заказ»: его
                # пишет не активация, а именно сверка — на ближайшем проходе.
                _L.append(f"  Тогда же коду пропишется заказ "
                          f"<code>{_e(_p['order_id'] or '—')}</code> — сейчас "
                          f"его нет потому, что код сожгло перебором, а "
                          f"перебор заказ не пишет.")
        else:
            _L.append("  Сам НЕ запишет. Пришлёт «проверь вручную».")
            _L.append(f"  Подтвердить руками: <code>/gpt_lost_ok {code}</code>")
    elif _c and _c["is_used"] and _c["used_by"] and (_c["order_id"] or ""):
        # Здоровый закрытый случай. Раньше он попадал в общий «ни строки
        # ожидания, ни признаков» и читался как тупик — хотя это ровно то,
        # чем всё должно заканчиваться.
        _L.append("  ✅ Здесь всё закрыто: код закреплён за клиентом и "
                  "привязан к заказу, подписка записана.")
        _L.append("  Делать нечего — и это правильный конец.")
        if (_c["check_status"] or "") == "error":
            _L.append("  <i>Пометка error осталась с момента неудачи — на "
                      "выдачу она уже не влияет, код не свободен.</i>")
    else:
        _L.append("  Ни строки ожидания, ни признаков потерянной активации.")

    # ── 7. Когда сверка вообще последний раз работала
    try:
        import time as _t_w
        _ra = float(await get_setting("recon_last_at", "0") or 0)
        _rm = float(await get_setting("recon_last_ms", "0") or 0)
        _L.append("\n<b>Сверка:</b>")
        if not _ra:
            _L.append("  ⚠️ ни одного прохода с последнего запуска бота.")
        else:
            _ago = (_t_w.time() - _ra) / 60.0
            _L.append(f"  последний проход {_ago:.0f} мин назад, занял {_rm/1000:.0f} с")
            if _ago > 12:
                _L.append("  ⚠️ это дольше, чем должно быть (норма — раз в 5 минут).")
        _la = float(await get_setting("lostscan_last_at", "0") or 0)
        if _la:
            _L.append(f"  тяжёлый проход {(_t_w.time()-_la)/60.0:.0f} мин назад "
                      f"(идёт раз в ~15 мин)")
    except Exception:
        pass

    # ── 8. Не заглушено ли уже отправленным сообщением
    if _uid:
        try:
            _f1 = await get_setting(f"unsure:{code}:{_uid}", "")
            _f2 = await get_setting(f"lostact:{code}:{_uid}", "")
            if _f1 == "1" or _f2 == "1":
                _L.append("\n⚠️ Об этом коде я уже присылал сообщение — "
                          "повторно оно не придёт (защита от спама).")
        except Exception:
            pass
    return "\n".join(_L)


async def gpt_codes_recover(days: int = 3, apply: bool = False) -> dict:
    """Ищет коды, сожжённые перебором зря, и (по команде) возвращает их в пул.

    Настоящая активация пишет коду order_id и почту. Перебор «код уже
    использован» помечает код использованным БЕЗ них. Если такой код на сайте
    до сих пор числится unused — значит он не потрачен, и его сожгли впустую:
    12.09.2026 так ушло 8 кодов за две минуты.

    Сам ничего не возвращает: apply=False только показывает список. Возврат —
    отдельной командой с подтверждением, как договаривались про пул.
    """
    from chatgpt_activation import bpa_query_codes, BPA_FREE_STATUSES
    pool = await get_pool()
    # Окно до года: раньше молча резали до 30 дней, и «проверил за 100 дней»
    # было неправдой. Про любую обрезку отчёт теперь говорит прямо.
    _want = int(days or 3)
    _d = max(1, min(365, _want))
    async with pool.acquire() as conn:
        rows = await conn.fetch(
            "SELECT c.code, c.used_by, c.used_at, u.username "
            "FROM gpt_codes c LEFT JOIN users u ON u.user_id=c.used_by "
            # Только коды bypriceactivate: спрашивать его про коды старых
            # сайтов (999uu, kkqq, redeem — префиксы ALEXANDR…, bbtus…)
            # бессмысленно, он честно отвечает not_in_db, а в отчёте они
            # выглядели как «реально потрачены». Это исторические коды,
            # возвращать там нечего.
            "WHERE c.provider='bpa' AND c.is_used=TRUE AND c.used_by IS NOT NULL "
            "  AND (c.order_id IS NULL OR c.order_id='') "
            "  AND c.used_at >= NOW() - make_interval(days => $1) "
            "  AND NOT EXISTS (SELECT 1 FROM gpt_pending_activations p "
            "                  WHERE p.code = c.code) "
            "ORDER BY c.used_at DESC LIMIT 1001", _d)
    # Больше 1000 за раз не тянем, но молчать об обрезке нельзя:
    # иначе «всё проверено» будет неправдой.
    _cut = len(rows) > 1000
    if _cut:
        rows = rows[:1000]
    if not rows:
        return {"ok": True, "checked": 0, "free": [], "spent": [], "applied": 0,
                "days": _d, "want": _want, "cut": False}

    _st = await bpa_query_codes([r["code"] for r in rows])
    if not _st:
        return {"ok": False, "days": _d,
                "error": "Сайт проверки не ответил — ничего не трогал."}

    _free, _spent, _unknown = [], [], []
    for r in rows:
        _v = (_st.get((r["code"] or "").strip().upper()) or {}).get("status", "")
        if not _v:
            continue                       # сайт промолчал — гадать не будем
        _who = ("@" + r["username"]) if r["username"] else f"id{r['used_by']}"
        if _v in BPA_FREE_STATUSES:
            _free.append((r["code"], _who))
        elif _v == "not_in_db":
            # Сайт про код не знает — это НЕ «потрачен». Отдельной кучкой,
            # иначе такие коды читаются как потери, которых не было.
            _unknown.append((r["code"], _who))
        else:
            # Для потраченных берём почту и Organization ID с сайта: по ним
            # сразу видно, ушла подписка нашему клиенту или постороннему.
            _inf = _st.get((r["code"] or "").strip().upper()) or {}
            _spent.append((r["code"], _v, _who,
                           _inf.get("email", ""), _inf.get("org", ""),
                           _inf.get("cells", []), _inf.get("when", ""),
                           r["used_at"], _inf.get("when_ts", 0),
                           bool(_inf.get("when_exact"))))

    _applied = 0
    if apply and _free:
        async with pool.acquire() as conn:
            for _c, _w in _free:
                try:
                    # Возвращаем в пул и снимаем пометку: сайт подтвердил, что
                    # код не потрачен, — это его ответ, а не наша догадка.
                    await conn.execute(
                        "UPDATE gpt_codes SET is_used=FALSE, used_by=NULL, used_at=NULL, "
                        "order_id=NULL, reserved_at=NULL, check_status='ok', "
                        "last_checked_at=NOW(), flagged_reason=NULL WHERE code=$1", _c)
                    _applied += 1
                except Exception as _e_up:
                    logging.error(f"gpt_codes_recover {_c}: {_e_up}")
        logging.warning(f"gpt_codes_recover: вернул в пул {_applied} кодов")
    # Часовой пояс сайта отличается от нашего, и в строках вида «11.09.2026,
    # 13:01:41» он не указан. Сдвиг задаётся настройкой (по умолчанию 2 часа)
    # и применяется ТОЛЬКО к таким строкам — там, где сайт отдал unix, время
    # и так абсолютное.
    try:
        _shift = float(await get_setting("bpa_tz_shift", "2") or 2)
    except Exception:
        _shift = 2.0
    return {"ok": True, "checked": len(_st), "free": _free, "spent": _spent,
            "applied": _applied, "days": _d, "shift": _shift,
            "want": _want, "cut": _cut, "unknown": _unknown}


def gpt_codes_recover_report(r: dict, applied: bool = False) -> str:
    """Отчёт по кодам, сожжённым перебором зря."""
    if not r.get("ok"):
        return "❌ " + (r.get("error") or "Не получилось.")
    _f, _s = r.get("free") or [], r.get("spent") or []
    _nk = r.get("unknown") or []
    _shift = r.get("shift", 2.0)
    if not _f and not _s and not _nk:
        _w = ""
        if r.get("want") and r["want"] > r.get("days", 0):
            _w = f" (просил {r['want']}, смотрю максимум {r.get('days')})"
        return (f"✅ За {r.get('days')} дн.{_w} зря сожжённых кодов не нашёл — "
                f"пул чистый.")
    _t = (f"\U0001f527 <b>Коды, сожжённые перебором</b> (за {r.get('days')} дн.)\n"
          f"Проверено: <b>{r.get('checked')}</b>\n")
    if r.get("want") and r["want"] > r.get("days", 0):
        _t += f"⚠️ Просил {r['want']} дн. — смотрю максимум {r.get('days')}.\n"
    if r.get("cut"):
        _t += ("⚠️ Кодов больше 1000 — показаны первые 1000. "
               "Прогони ещё раз после возврата.\n")
    _t += "\n"
    if _f:
        _t += (f"♻️ <b>Целы на сайте — можно вернуть ({len(_f)}):</b>\n"
               + "\n".join(f"• <code>{c}</code> — жёгся на {w}" for c, w in _f)
               + "\n\n")
    if _s:
        # Время нужно, чтобы отличить две разные беды: код пришёл в пул уже
        # потраченным (сайт активировал его ЗАДОЛГО до нашей выдачи — вопрос
        # к поставщику) или его потратила наша же несохранённая активация
        # (время близко к нашему). Без времени это неразличимо.
        def _srow(_x):
            c, v, w = _x[0], _x[1], _x[2]
            m = _x[3] if len(_x) > 3 else ""
            g = _x[4] if len(_x) > 4 else ""
            cells = _x[5] if len(_x) > 5 else []
            if m:
                _tail = f" → 📧 <code>{m}</code>"
            elif g:
                # Почты сайт не дал — показываем Organization ID: по нему тоже
                # видно, на какой аккаунт лёг код.
                _tail = f" → 🆔 <code>{g}</code>"
            elif cells:
                # Не нашли ни того, ни другого — показываем, что сайт вообще
                # вернул по этой строке. Лучше сырые данные, чем пустота:
                # по ним сразу видно, изменилась ли разметка страницы.
                _raw = " | ".join(str(_x2) for _x2 in cells)[:160]
                _tail = f"\n   <i>ответ сайта:</i> <code>{_raw}</code>"
            else:
                _tail = " → <i>сайт не показал ни почту, ни ID</i>"
            _when = _x[6] if len(_x) > 6 else ""
            _burn = _x[7] if len(_x) > 7 else None
            _wts = _x[8] if len(_x) > 8 else 0
            _exact = _x[9] if len(_x) > 9 else False
            _time = ""
            if _when:
                _time = f"\n   🕒 сайт: <b>{_when}</b>"
                if _burn is not None:
                    try:
                        _time += (f" · мы сожгли: "
                                  f"{_burn.astimezone(_BOT_TZ).strftime('%d.%m.%Y %H:%M')}")
                    except Exception:
                        pass
                # Разницу считаем сами — глазами её по двум строкам не свести,
                # тем более с чужим часовым поясом.
                if _wts and _burn is not None:
                    try:
                        _site = _wts if _exact else (_wts - _shift * 3600)
                        _dh = (_site - _burn.timestamp()) / 3600.0
                        _ab = abs(_dh)
                        _hum = (f"{int(round(_ab * 60))} мин" if _ab < 1
                                else (f"{_ab:.1f} ч" if _ab < 48
                                      else f"{_ab / 24:.1f} сут"))
                        if _dh > 0.25:
                            _time += (f"\n   ➡️ потрачен <b>ПОЗЖЕ</b> нашего сжигания "
                                      f"на {_hum} — значит код кто-то активировал "
                                      f"после (скорее всего ты вручную)")
                        elif _dh < -3:
                            _time += (f"\n   ⬅️ потрачен <b>РАНЬШЕ</b> нашего сжигания "
                                      f"на {_hum} — код попал в пул уже "
                                      f"использованным (вопрос к поставщику)")
                        elif _dh < -0.25:
                            # Полчаса-два до сжигания — это почти наверняка НЕ
                            # поставщик, а наша же активация другому клиенту,
                            # прошедшая и не записанная: код остался в пуле и
                            # тут же ушёл следующему. Разница в минутах такого
                            # вывода не выдерживает, поэтому не настаиваем.
                            _time += (f"\n   ⬅️ потрачен незадолго <b>ДО</b> нашего "
                                      f"сжигания ({_hum}) — скорее всего наша же "
                                      f"активация другому клиенту прошла и не "
                                      f"записалась, а код остался в пуле")
                        else:
                            _time += (f"\n   ⏱ потрачен одновременно с нашей активацией "
                                      f"(разница {_hum}) — это наша активация прошла, "
                                      f"а бот её не записал")
                    except Exception:
                        pass
            return f"• <code>{c}</code> — {v}\n   {w}{_tail}{_time}"
        _t += (f"\U0001f525 <b>Реально потрачены ({len(_s)}):</b>\n"
               + "\n".join(_srow(_x) for _x in _s)
               + f"\n<i>Время сайта сдвинуто на {_shift:g} ч относительно нашего "
                 f"(поменять: /gpt_tz N). «Позже нашего сжигания» = код не пропал, "
                 f"его активировали потом. «Раньше» = пришёл в пул уже "
                 f"использованным.</i>\n\n")
    if _nk:
        _t += (f"❔ <b>Сайт про эти коды не знает ({len(_nk)}):</b>\n"
               + "\n".join(f"• <code>{c}</code> — жёгся на {w}" for c, w in _nk)
               + "\n<i>Не потери: bypriceactivate их и не должен знать. "
                 "Проверь формат — обычно это коды старых сайтов или мусор, "
                 "попавший в пул при заливке.</i>\n\n")
    if applied:
        _t += f"✅ Вернул в пул: <b>{r.get('applied')}</b>."
    elif _f:
        _t += ("Вернуть целые в пул: <code>/gpt_codes_recover да</code>\n"
               "<i>Возвращаю только те, про которые сайт сказал «не использован».</i>")
    return _t


def pool_audit_report(r: dict) -> str:
    """Отчёт по сверке пулов: отдельный блок на КАЖДЫЙ сервис.

    Общая цифра «проверено 89» ничего не говорит о том, дошла ли проверка до
    Claude и Perplexity вообще. Поэтому каждый сервис показываем своей строкой
    с собственными числами — даже когда у него всё чисто или пул пуст, — а
    каждый проблемный код пишем отдельной строкой под своим сервисом.
    """
    if not r.get("ok"):
        _t = ("❌ <b>Сайт проверки не ответил</b>\n"
              + (r.get("error") or "")
              + "\n\nПулы не тронуты. Если повторяется — возможно, сайт не "
                "принимает запросы с сервера; тогда нужен их JSON-эндпоинт.")
        _bs = r.get("by_service") or {}
        if _bs:
            _t += "\n\nНе сверялись:\n" + "\n".join(
                f"• <b>{(_AUDIT_SERVICES.get(_sv) or {}).get('name', _sv)}</b>"
                f" — {_d.get('pool', 0)} код(ов) в пуле"
                for _sv, _d in _bs.items())
        return _t

    _by = r.get("by_service") or {}
    if not _by:
        # Совместимость: старый вызов без разбивки — отдаём общий итог.
        return (f"🔎 <b>Сверка пулов</b>\nПроверено кодов: <b>{r.get('checked')}</b>\n"
                f"✅ Годных: <b>{r.get('free')}</b>")

    _t = (f"🔎 <b>Сверка пулов</b>\n"
          f"Итого проверено: <b>{r.get('checked')}</b> · "
          f"✅ годных: <b>{r.get('free')}</b>\n")
    # Пропущенные — ОБЯЗАТЕЛЬНО отдельной строкой. Без неё «годных: 47»
    # читается как «всё чисто», хотя пропущенный код мог быть уже потрачен:
    # 15.09.2026 проверка через 11 минут после неудачи не увидела код, который
    # на сайте уже значился fulfilled, и выглядело это как ошибка бота.
    _sk = r.get("skipped") or {}
    _sk_n = sum(int(v or 0) for v in _sk.values())
    if _sk_n:
        _t += (f"⏳ Пропущено: <b>{_sk_n}</b> — по ним прямо сейчас идёт "
               f"активация, сайт мог бы показать их потраченными зря. "
               f"Проверь ещё раз минут через 15.\n")

    def _codes(_rows, _title, _icon):
        if not _rows:
            return ""
        _out = f"{_icon} <b>{_title} ({len(_rows)}):</b>\n"
        # Показываем ВСЕ коды. Обрезка «…и ещё N» прятала ровно те строки,
        # ради которых сводку и смотрят; длину разложит tg_chunks.
        _out += "\n".join(f"   • <code>{_c}</code> — {_v}" for _c, _v in _rows)
        return _out + "\n"

    for _sv, _d in _by.items():
        _nm = (_AUDIT_SERVICES.get(_sv) or {}).get("name", _sv)
        _t += f"\n━━━━━━━━━━\n<b>{_nm}</b>\n"
        if _d.get("error"):
            _t += (f"❌ Не смог проверить — ошибка запроса к базе:\n"
                   f"<code>{_d['error']}</code>\n")
            continue
        if _d.get("unknown"):
            _t += (f"ℹ️ Страница проверки не знает эти коды "
                   f"({_d.get('pool', 0)} шт.) — пул не сверялся и не помечался.\n")
            continue
        if not _d.get("pool"):
            _t += "Пул пуст — проверять нечего.\n"
            continue
        _t += (f"Проверено: <b>{_d.get('checked', 0)}</b> из "
               f"{_d.get('pool', 0)} · ✅ годных: <b>{_d.get('free', 0)}</b>\n")
        _t += _codes(_d.get("spent") or [], "Похоже, потрачены", "⚠️")
        _t += _codes(_d.get("odd") or [], "Непонятный статус", "❔")
        if _d.get("noanswer"):
            _t += (f"🔇 Сайт не ответил по {_d['noanswer']} код(ам) — "
                   f"их не трогали.\n")
        if not _d.get("spent") and not _d.get("odd") and not _d.get("noanswer"):
            _t += "Всё чисто.\n"

    if r.get("spent") or r.get("odd"):
        _t += ("\n<i>Ничего не гасил и не удалял — только пометил. Помеченные "
               "не возвращаются в пул автоматически и выдаются последними. "
               "Удалить — в админ-панели.</i>")
    # Длину не режем: отправитель разложит текст на несколько сообщений
    # через tg_chunks. Обрезка прятала ровно те коды, ради которых всё это.
    return _t


async def gpt_pool_audit(include_reserved: bool = True) -> dict:
    """Сверка только пула ChatGPT — её зовёт возврат кодов в пул.

    Отдаёт пары (код, статус) без имени сервиса: так ждут прежние вызывающие.
    """
    _r = await pool_audit(["chatgpt"], include_reserved=include_reserved)
    _r["spent"] = [(c, v) for c, v, _s in _r.get("spent", [])]
    _r["odd"] = [(c, v) for c, v, _s in _r.get("odd", [])]
    return _r


async def _gpt_pick_code(plan: str):
    """Берёт CDK-код из пула активного сайта ChatGPT; при пустом пуле и включённом
    фолбэке пробует остальные. Возвращает (code, provider) либо (None, None).

    Резерв происходит сразу после оплаты, когда план аккаунта клиента ещё
    неизвестен, поэтому маршрут здесь выбираем только там, где он предрешён
    тарифом: Go активируется всегда через iOS. Для Plus маршрут уточняется
    позже, в момент активации, когда придёт session (см. подмену маршрута).
    """
    order = await _gpt_provider_order()
    if not order:
        # Все сайты на паузе — раньше здесь падало IndexError на order[0].
        logging.warning("_gpt_pick_code: нет доступных сайтов (все на паузе)")
        return None, None
    active = order[0]
    # Go активируется только через iOS. Всем остальным тарифам сперва ищем
    # ФИЛИППИНСКИЙ код и лишь потом любой: резерв происходит сразу после
    # оплаты, когда план аккаунта ещё неизвестен, и брать в этот момент iOS
    # значит тратить дорогой код там, где хватило бы дешёвого. Маршрут при
    # необходимости уточнится в момент активации, когда придёт session.
    _route = "ios" if plan == "go" else "ph"
    for prov in order:
        if prov == "bpa":
            code = await get_next_gpt_code(plan, prov, _route)
            if not code and _route == "ph":
                # Филиппинских не осталось — берём любой, иначе клиент
                # останется без кода при полном пуле iOS.
                code = await get_next_gpt_code(plan, prov)
        else:
            code = await get_next_gpt_code(plan, prov)
        if code:
            if prov != active:
                try:
                    await bot.send_message(
                        ADMIN_ID,
                        f"🔀 <b>ChatGPT — авто-переключение сайта</b>\n"
                        f"У <b>{gpt_provider_name(active)}</b> закончились коды ({plan}).\n"
                        f"Активация ушла на <b>{gpt_provider_name(prov)}</b>.\n"
                        f"Пополни коды на {gpt_provider_name(active)}.",
                        parse_mode="HTML")
                except Exception:
                    pass
            return code, prov
    return None, None


async def _send_claude_webapp_to_user(
    user_id: int, code: str, order_id: str,
    plan: str, plan_name: str, delayed_note: str = "", provider: str = "bpa"
) -> bool:
    """Сохраняет pending и отправляет клиенту кнопку WebApp."""
    import urllib.parse as _up
    from aiogram.types import WebAppInfo as _WAI

    await save_claude_pending_activation(user_id, code, order_id, plan, plan_name, provider)

    from config import webapp_url as _wa_url
    webapp_url = _wa_url("/webapp/claude", plan=plan_name, code=code)
    try:
        import datetime as _dt_cl
        _oref_cl = await _order_ref_line(order_id)
        _base_cl = (
            f"🎉 <b>Оплата прошла!</b>\n\n"
            f"📦 <b>Claude {plan_name}</b>\n"
            f"{_oref_cl}\n\n"
            f"Осталось активировать подписку — нажми кнопку ниже, "
            f"введи Organization ID из настроек Claude, и подписка "
            f"активируется автоматически (обычно за 1–2 минуты, иногда до 5) 👇\n\n"
            f"🎟 Код активации: <code>{code}</code>"
            f"{delayed_note}"
        )
        _kb_cl_active = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="⚡ Активировать Claude", style="success", web_app=_WAI(url=webapp_url))],
            [InlineKeyboardButton(text="❓ Нужна помощь", style="primary", callback_data="claude_need_help")],
        ])
        # После окна кнопка активации ОСТАЁТСЯ — код живёт до 12 ч, клиент может активировать сам
        _kb_cl_expired = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="⚡ Активировать Claude", style="success", web_app=_WAI(url=webapp_url))],
            [InlineKeyboardButton(text="❓ Нужна помощь", style="primary", callback_data="claude_need_help")],
        ])
        _dl_cl = _dt_cl.datetime.now(_BOT_TZ) + _dt_cl.timedelta(minutes=ACTIVATION_WINDOW_MIN)
        _exp_cl = (
            f"📦 <b>Claude {plan_name}</b> — оплата сохранена ✅\n"
            f"{_oref_cl}\n\n"
            f"Если ещё не активировал — можно сделать это <b>сейчас</b>: нажми кнопку ниже, "
            f"введи Organization ID.\n"
            f"🎟 Код: <code>{code}</code>\n\n"
            f"Не получается — напиши Александру, активирует вручную 🙌"
        )
        # СНАЧАЛА инструкция…
        try:
            await bot.send_message(
                user_id,
                "📋 <b>Инструкция по активации Claude</b>\n\n"
                "1️⃣ Зайди на <b>claude.ai</b> и авторизуйся (в Chrome или Safari).\n"
                "2️⃣ Открой настройки аккаунта:\n"
                "<code>claude.ai/settings/account</code>\n"
                "3️⃣ Прокрути до «Organization ID» и скопируй UUID.\n"
                "4️⃣ Вернись в мини-приложение (кнопка «Активировать Claude»), "
                "вставь Organization ID — подписка активируется автоматически за 1–5 минут.\n\n"
                f"🎟 Код активации: <code>{code}</code>\n"
                "⚠️ Аккаунт Claude должен быть на Free-плане. "
                "Если есть платная подписка — сначала отмени её на claude.ai/settings/billing.",
                parse_mode="HTML")
        except Exception:
            pass
        # …ПОТОМ сообщение с кнопкой активации (его id отслеживаем для таймера/успеха)
        _m_act_cl = await bot.send_message(
            user_id, _base_cl + _activation_timer_line(_dl_cl),
            parse_mode="HTML", reply_markup=_kb_cl_active)
        _claude_act_msg[user_id] = _m_act_cl.message_id
        asyncio.create_task(_activation_timer_job(
            user_id, _m_act_cl.message_id, _base_cl, _kb_cl_active,
            _dl_cl, _exp_cl, _kb_cl_expired, _claude_act_msg))
        await log_event(user_id, "claude_webapp_sent",
                        f"code={code} plan={plan_name} order={order_id}")
        return True
    except Exception as _e:
        logging.error(f"_send_claude_webapp_to_user uid={user_id}: {_e}")
        return False


