async def _take_claude_bpa_screenshot(bpa_order_id: int, provider: str = "bpa") -> bytes | None:
    """Делает скриншот статуса активации на сайте-провайдере (только для bpa-типа)."""
    if CLAUDE_PROVIDERS.get(provider, {}).get("api", "bpa") != "bpa":
        return None  # у partner-API нет публичной страницы статуса
    try:
        from playwright.async_api import async_playwright
        _base = claude_provider_base(provider)
        async with async_playwright() as _p:
            _br = await _p.chromium.launch(
                headless=True,
                args=["--no-sandbox","--disable-dev-shm-usage","--disable-gpu","--single-process"]
            )
            _pg = await _br.new_page(viewport={"width": 900, "height": 500})
            await _pg.goto(
                f"{_base}/api/activate/{bpa_order_id}",
                timeout=20000, wait_until="networkidle"
            )
            _ss = await _pg.screenshot(full_page=True)
            await _br.close()
            return _ss
    except Exception as _se:
        logging.warning(f"Claude BPA screenshot failed: {_se}")
        return None


async def _claude_activation_polling_job(
    bpa_order_id: int, code: str, user_id: int,
    order_id: str, plan_name: str, org_id: str, provider: str = "bpa", _tried=None
):
    """
    Опрашивает сайт-провайдер каждые 5 сек.
    При done — помечает код, уведомляет тебя и клиента.
    При failed — АВТО-переключает активацию на код другого сайта (если есть), иначе пишет обоим.
    _tried — множество уже пробованных сайтов (для авто-фолбэка без зацикливания).
    """
    _claude_job_results[bpa_order_id] = {"status": "queued"}
    _tried_set = set(_tried or ()) | {provider}
    _replaced_code = None  # авто-замена кода отключена; ветка elif оставлена мёртвой
    _cfg = CLAUDE_PROVIDERS.get(provider, {})
    _api = _cfg.get("api", "bpa")
    _base = _cfg.get("base", "")
    logging.info(f"Claude polling ref={bpa_order_id} user={user_id} code={code} via={provider} api={_api}")

    for attempt in range(120):          # макс 10 минут (120 × 5 сек)
        await asyncio.sleep(5)
        try:
            if _api == "partner":
                # partner-API: GET /api/partner/v1/redemptions/{order_no} (Bearer)
                _hdr = {"Authorization": f"Bearer {_cfg.get('key','')}"}
                async with aiohttp.ClientSession(
                    timeout=aiohttp.ClientTimeout(total=15)
                ) as _s:
                    async with _s.get(
                        f"{_base}/api/partner/v1/redemptions/{bpa_order_id}", headers=_hdr
                    ) as _r:
                        if _r.status != 200:
                            continue
                        _d = await _r.json()
                _pst = str((_d.get("data") or {}).get("status") or "")
                # нормализуем статусы partner в словарь первого сайта
                if _pst == "succeeded":
                    status = "done"
                elif _pst in ("failed", "review"):
                    status = "failed"
                    _d = {"status": "failed", "error": _pst}
                else:
                    status = _pst   # pending / processing — просто ждём дальше
            elif _api == "order":
                # ipiap order-API: POST /api/order/query (подпись MD5), orderStatus 0/1/2/3
                _q = await _claude_order_query(_cfg, str(bpa_order_id))
                if _q["status"] == "success":
                    status = "done"
                elif _q["status"] == "failed":
                    status = "failed"
                    _d = {"status": "failed", "error": _q.get("reason") or "failed"}
                else:
                    status = "pending"   # 0/1 — ждём дальше
            elif _api == "agent":
                # vip666 agent-API: GET /api/agent/v1/redeem/{idempotency_key}
                _q = await _claude_agent_query(_cfg, str(bpa_order_id))
                if _q["status"] == "success":
                    status = "done"
                elif _q["status"] == "failed":
                    status = "failed"
                    _d = {"status": "failed", "error": _q.get("reason") or "failed"}
                else:
                    status = "pending"
            else:
                async with aiohttp.ClientSession(
                    timeout=aiohttp.ClientTimeout(total=15)
                ) as _s:
                    async with _s.get(
                        f"{_base}/api/activate/{bpa_order_id}"
                    ) as _r:
                        if _r.status != 200:
                            continue
                        _d = await _r.json()
                status = _d.get("status")

            _claude_job_results[bpa_order_id] = {"status": status}

            # ── Успех ──────────────────────────────────────────
            if status == "done":
                await mark_claude_code_used(code, user_id, order_id, org_id)
                await delete_claude_pending_activation(user_id, order_id)
                _claude_job_results[bpa_order_id] = {"status": "done", "success": True}

                import datetime as _dt2
                _ts = _dt2.datetime.now(_BOT_TZ).strftime("%d.%m.%Y %H:%M")
                try:
                    _pool2 = await get_pool()
                    async with _pool2.acquire() as _c2:
                        _ur = await _c2.fetchrow(
                            "SELECT username, full_name FROM users WHERE user_id=$1",
                            user_id
                        )
                    _un = (_ur["username"] if _ur else "") or ""
                    _fn = (_ur["full_name"] if _ur else "") or ""
                except Exception:
                    _un = _fn = ""
                _tg = (f"@{_un}" if _un else tg_name(_fn)) or f"id{user_id}"

                # Заменяем сообщение клиента на поздравление, убираем «Нужна помощь»
                import datetime as _dt_end_cl
                _end_cl = (_dt_end_cl.datetime.now(_BOT_TZ) + _dt_end_cl.timedelta(days=_subscription_days(plan_name))).strftime("%d.%m.%Y")
                _prof_kw_cl = ({"icon_custom_emoji_id": UI_EMOJI_IDS["menu_profile"]}
                               if UI_EMOJI_IDS.get("menu_profile") else {})
                _congrats_cl = (
                    "🎉 <b>Подписка Claude активирована!</b>\n\n"
                    f"📦 Тариф: <b>{plan_name}</b>\n"
                    f"🏢 Organization ID: <code>{org_id}</code>\n"
                    f"🔑 Ключ: <code>{code}</code>\n"
                    f"📅 Действует до: <b>{_end_cl}</b>\n\n"
                    "Подписка появится в Claude в течение 5–10 минут. Спасибо за покупку! 🙌"
                )
                _kb_cl = InlineKeyboardMarkup(inline_keyboard=[
                    [InlineKeyboardButton(text="Открыть Claude ↗", url="https://claude.ai")],
                    [InlineKeyboardButton(text="Мой профиль", callback_data="menu_profile", **_prof_kw_cl)],
                    [_eib("Главное меню", "back_main")],
                ])
                _mid_cl = _claude_act_msg.pop(user_id, None)
                _edited_cl = False
                if _mid_cl:
                    try:
                        await bot.edit_message_text(_congrats_cl, chat_id=user_id, message_id=_mid_cl,
                                                    parse_mode="HTML", reply_markup=_kb_cl)
                        _edited_cl = True
                    except Exception as _ee_cl:
                        logging.warning(f"edit claude activation msg failed: {_ee_cl}")
                if not _edited_cl:
                    try:
                        await bot.send_message(user_id, _congrats_cl, parse_mode="HTML", reply_markup=_kb_cl)
                    except Exception:
                        pass

                try:
                    _caption_ok = (
                        f"✅ <b>Claude авто-активация OK</b>\n\n"
                        f"👤 <b>{_tg}</b>  (<code>{user_id}</code>)\n"
                        f"🔑 Код: <code>{code}</code>\n"
                        f"📦 Тариф: <b>{plan_name}</b>\n"
                        f"🆔 Org ID: <code>{org_id}</code>\n"
                        f"🔢 BPA: <code>{bpa_order_id}</code>\n"
                        f"⏱ {_ts}"
                    )
                    try:
                        _ord_ok = await fk_get_order(order_id)
                        _amid_ok = (_ord_ok or {}).get("admin_msg_id")
                    except Exception:
                        _amid_ok = None
                    if _amid_ok:
                        try:
                            await bot.edit_message_text(_caption_ok, chat_id=ADMIN_ID, message_id=_amid_ok, parse_mode="HTML")
                        except Exception:
                            await bot.send_message(ADMIN_ID, _caption_ok, parse_mode="HTML")
                    else:
                        await bot.send_message(ADMIN_ID, _caption_ok, parse_mode="HTML")
                except Exception:
                    pass
                _fail_clear("claude", user_id)
                await log_event(user_id, "claude_activation_ok",
                                f"code={code} bpa={bpa_order_id} plan={plan_name}")
                return

            # ── Ошибка ─────────────────────────────────────────
            elif status == "failed":
                _err = _d.get("error") or "Ошибка активации"
                _claude_job_results[bpa_order_id] = {
                    "status": "done", "success": False, "error": _err
                }
                # Сбрасываем bpa_order_id в pending, чтобы «Попробовать снова» создал НОВЫЙ BPA-заказ
                try:
                    _pool_rb = await get_pool()
                    async with _pool_rb.acquire() as _c_rb:
                        await _c_rb.execute(
                            "UPDATE claude_pending_activations SET bpa_order_id=NULL WHERE user_id=$1", user_id)
                except Exception:
                    pass

                # ── АВТО-ФОЛБЭК: активация провалилась → пробуем код ДРУГОГО сайта ──
                # (у каждого сайта свои коды; берём код ещё не пробованного сайта и повторяем там)
                try:
                    _pk_oos = plan_name_to_key(plan_name)
                    for _np in await _claude_provider_order():
                        if _np in _tried_set:
                            continue
                        _nc = await get_next_claude_code(_pk_oos, _np)
                        if not _nc:
                            continue
                        _res2 = await _claude_redeem_via(_np, _nc, org_id, order_id)
                        if not _res2.get("ok"):
                            continue   # код этого сайта не принят — пробуем следующий
                        _ref2 = _res2["ref"]
                        _is_bpa2 = CLAUDE_PROVIDERS.get(_np, {}).get("api", "bpa") == "bpa"
                        _pool_fo = await get_pool()
                        async with _pool_fo.acquire() as _c_fo:
                            if _is_bpa2:
                                await _c_fo.execute(
                                    "UPDATE claude_pending_activations SET code=$1, provider=$2, bpa_order_id=$3 WHERE user_id=$4",
                                    _nc, _np, int(_ref2), user_id)
                            else:
                                await _c_fo.execute(
                                    "UPDATE claude_pending_activations SET code=$1, provider=$2, bpa_order_id=NULL WHERE user_id=$3",
                                    _nc, _np, user_id)
                        try:
                            await bot.send_message(
                                ADMIN_ID,
                                f"🔀 <b>Claude — авто-переключение сайта после неудачи</b>\n"
                                f"👤 {await _who_user(user_id)} ({plan_name})\n"
                                f"Прежний сайт не активировал — ушли на <b>{claude_provider_name(_np)}</b>.",
                                parse_mode="HTML")
                        except Exception:
                            pass
                        _claude_job_results[_ref2] = {"status": "queued"}
                        asyncio.create_task(_claude_activation_polling_job(
                            _ref2, _nc, user_id, order_id, plan_name, org_id, _np, _tried_set))
                        logging.info(f"Claude auto-failover after fail: user={user_id} -> {_np} ref={_ref2}")
                        return   # активация переехала на другой сайт — клиента не тревожим
                except Exception as _fo_e:
                    logging.error(f"Claude failover after fail: {_fo_e}")

                _is_stock = ("out of stock" in _err.lower() or "out-of-stock" in _err.lower())
                if _is_stock:
                    # провайдер временно без стока — код клиента ОСТАЁТСЯ валидным.
                    # НЕ возвращаем в пул и НЕ удаляем pending: клиент сам повторит, когда пополнят.
                    _fail_note = "Временно нет мест у провайдера — код сохранён за клиентом, можно повторить."
                else:
                    # Сбой обычно временный (провайдер: payment/timeout). Код НЕ сжигаем и НЕ ротируем —
                    # оставляем закреплённым за клиентом: можно повторить тем же кодом или активировать вручную.
                    _fail_note = "Код сохранён — повтори тем же кодом позже или активируй вручную."

                # ── алерт админу (не чаще 1 раза в 15 мин на клиента) ──
                if _fail_should_alert("claude", user_id):
                    try:
                        _caption_fail = (
                            f"❌ <b>Claude FAILED</b>\n"
                            f"👤 {await _who_user(user_id)}  📦 {plan_name}\n"
                            f"🔑 <code>{code}</code>  🔢 BPA: <code>{bpa_order_id}</code>\n"
                            f"❌ {_err[:300]}"
                            + f"\n♻️ {_fail_note}"
                        )
                        _ss_fail = await _take_claude_bpa_screenshot(bpa_order_id, provider)
                        if _ss_fail:
                            await bot.send_photo(
                                ADMIN_ID,
                                BufferedInputFile(_ss_fail, "claude_fail.png"),
                                caption=_caption_fail, parse_mode="HTML"
                            )
                        else:
                            await bot.send_message(ADMIN_ID, _caption_fail, parse_mode="HTML")
                    except Exception:
                        pass

                # ── сообщение клиенту ──
                try:
                    if _is_stock:
                        await bot.send_message(
                            user_id,
                            "⏳ <b>Временно нет мест у провайдера</b>\n\n"
                            "Твой код сохранён и остаётся действительным. Провайдер пополняет запас — "
                            "попробуй активировать снова через 5–10 минут 👇",
                            parse_mode="HTML",
                            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                                [InlineKeyboardButton(
                                    text="🔁 Попробовать снова",
                                    callback_data="claude_reopen_webapp"
                                )],
                                [InlineKeyboardButton(
                                    text="❓ Нужна помощь", style="primary",
                                    callback_data="claude_need_help"
                                )],
                            ])
                        )
                    elif _replaced_code:
                        await bot.send_message(
                            user_id,
                            "😔 <b>Первый код не сработал</b>\n\n"
                            "Мы автоматически выдали новый код. "
                            "Нажми «🔁 Попробовать снова» — активируем заново 👇",
                            parse_mode="HTML",
                            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                                [InlineKeyboardButton(
                                    text="🔁 Попробовать снова",
                                    callback_data="claude_reopen_webapp"
                                )],
                                [InlineKeyboardButton(
                                    text="❓ Нужна помощь", style="primary",
                                    callback_data="claude_need_help"
                                )],
                            ])
                        )
                    else:
                        await bot.send_message(
                            user_id,
                            f"😔 <b>Активация Claude не прошла</b>\n\n"
                            f"{_err[:300]}\n\n"
                            f"Напиши Александру — активирую вручную за 15–30 мин!",
                            parse_mode="HTML",
                            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                                [InlineKeyboardButton(
                                    text="✅ Активировали тариф вручную",
                                    callback_data="claude_manual_activated"
                                )],
                                [InlineKeyboardButton(
                                    text="❓ Нужна помощь", style="primary",
                                    callback_data="claude_need_help"
                                )],
                            ])
                        )
                except Exception:
                    pass
                await log_event(user_id, "claude_activation_fail",
                                f"code={code} bpa={bpa_order_id} replaced={_replaced_code or '-'} err={_err[:120]}")
                return

        except Exception as _e:
            logging.error(f"Claude poll #{attempt} bpa={bpa_order_id}: {_e}")

    # ── Таймаут ────────────────────────────────────────────────
    # Код и pending НЕ трогаем — чтобы клиент мог нажать «активировали вручную»,
    # а Александр активировал тем же кодом. Освободится сам через ~2ч (cleanup-loop).
    _claude_job_results[bpa_order_id] = {
        "status": "done", "success": False,
        "error": "Активация затянулась. Напиши Александру — он поможет!"
    }
    try:
        await bot.send_message(
            user_id,
            f"⏰ <b>Активация Claude затянулась</b>\n\n"
            f"Мы не получили подтверждение от сервиса активации.\n"
            f"Напиши Александру — разберёмся и активируем вручную!",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(
                    text="✅ Активировали тариф вручную",
                    callback_data="claude_manual_activated"
                )],
                [InlineKeyboardButton(
                    text="❓ Нужна помощь", style="primary",
                    callback_data="claude_need_help"
                )],
            ])
        )
    except Exception:
        pass
    try:
        await bot.send_message(
            ADMIN_ID,
            f"⏰ <b>Claude TIMEOUT</b>\n"
            f"👤 {await _who_user(user_id)}  🔢 BPA: <code>{bpa_order_id}</code>\n"
            f"🔑 Код: <code>{code}</code>\n"
            f"10 минут — проверь вручную на bypriceactivate.pro\n"
            f"Код зарезервирован за клиентом — активируй вручную им же.",
            parse_mode="HTML"
        )
    except Exception:
        pass


# ─── Веб-хэндлеры ────────────────────────────────────────────────────────────

async def webapp_claude_handler(request: web.Request) -> web.Response:
    """GET /webapp/claude — отдаёт claude_webapp.html.
    БЕЗ КЭША: Telegram агрессивно кэширует WebApp, из-за чего после деплоя у клиента
    оставался старый JS (напр. не отрабатывал экран подтверждения активации)."""
    try:
        with open(_CLAUDE_WEBAPP_HTML_PATH, "r", encoding="utf-8") as _f:
            _html = _f.read()
        _html = await _inject_recs(_html, exclude_key="claude")
        _html = await _apply_act_media(_html, "claude")
        return web.Response(text=_html, content_type="text/html", charset="utf-8",
                            headers=_NO_CACHE_HEADERS)
    except FileNotFoundError:
        return web.Response(text="Claude Mini App not found", status=404)


async def _run_claude_browser_job(ref, code, org_id, user_id, order_id, plan_name, plan_key, provider):
    """Фоновая активация Claude через браузерный сайт (6661231.xyz, Playwright).
    Обновляет _claude_job_results[ref]; клиент опрашивает /api/activate-claude-status/{ref}."""
    _claude_job_results[ref] = {"status": "queued"}
    try:
        from chatgpt_activation import activate_claude_aipro
        result = await activate_claude_aipro(code, org_id, plan_key)

        # код уже использован на сайте → следующий код этого же сайта, один ретрай
        if not result.get("success") and result.get("code_already_used"):
            try:
                _pool2 = await get_pool()
                async with _pool2.acquire() as _c2:
                    await _c2.execute(
                        "UPDATE claude_codes SET is_used=TRUE, used_by=$1, used_at=NOW() WHERE code=$2",
                        user_id, code)
            except Exception:
                pass
            _nc = await get_next_claude_code(plan_key, provider)
            if _nc:
                code = _nc
                await save_claude_pending_activation(user_id, code, order_id, plan_key, plan_name, provider)
                try:
                    await bot.send_message(user_id, "🔄 Первый код занят — выдаю следующий, подожди немного...", parse_mode="HTML")
                except Exception:
                    pass
                result = await activate_claude_aipro(code, org_id, plan_key)

        # ── Успех ──
        if result.get("success"):
            await mark_claude_code_used(code, user_id, order_id, org_id)
            await delete_claude_pending_activation(user_id, order_id)
            _claude_job_results[ref] = {"status": "done", "success": True}

            import datetime as _dt2
            _ts = _dt2.datetime.now(_BOT_TZ).strftime("%d.%m.%Y %H:%M")
            try:
                _pool2 = await get_pool()
                async with _pool2.acquire() as _c2:
                    _ur = await _c2.fetchrow("SELECT username, full_name FROM users WHERE user_id=$1", user_id)
                _un = (_ur["username"] if _ur else "") or ""
                _fn = (_ur["full_name"] if _ur else "") or ""
            except Exception:
                _un = _fn = ""
            _tg = (f"@{_un}" if _un else tg_name(_fn)) or f"id{user_id}"

            _end_cl = (_dt2.datetime.now(_BOT_TZ) + _dt2.timedelta(days=_subscription_days(plan_name))).strftime("%d.%m.%Y")
            _prof_kw = ({"icon_custom_emoji_id": UI_EMOJI_IDS["menu_profile"]} if UI_EMOJI_IDS.get("menu_profile") else {})
            _congrats = (
                "🎉 <b>Подписка Claude активирована!</b>\n\n"
                f"📦 Тариф: <b>{plan_name}</b>\n"
                f"🏢 Organization ID: <code>{org_id}</code>\n"
                f"🔑 Ключ: <code>{code}</code>\n"
                f"📅 Действует до: <b>{_end_cl}</b>\n\n"
                "Подписка появится в Claude в течение 5–10 минут. Спасибо за покупку! 🙌"
            )
            _kb = InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(text="Открыть Claude ↗", url="https://claude.ai")],
                [InlineKeyboardButton(text="Мой профиль", callback_data="menu_profile", **_prof_kw)],
                [_eib("Главное меню", "back_main")],
            ])
            _mid = _claude_act_msg.pop(user_id, None)
            _edited = False
            if _mid:
                try:
                    await bot.edit_message_text(_congrats, chat_id=user_id, message_id=_mid, parse_mode="HTML", reply_markup=_kb)
                    _edited = True
                except Exception:
                    pass
            if not _edited:
                try:
                    await bot.send_message(user_id, _congrats, parse_mode="HTML", reply_markup=_kb)
                except Exception:
                    pass

            try:
                _caption = (
                    f"✅ <b>Claude авто-активация OK</b> (6661231.xyz)\n\n"
                    f"👤 <b>{_tg}</b>  (<code>{user_id}</code>)\n"
                    f"🔑 Код: <code>{code}</code>\n"
                    f"📦 Тариф: <b>{plan_name}</b>\n"
                    f"🆔 Org ID: <code>{org_id}</code>\n"
                    f"⏱ {_ts}"
                )
                try:
                    _ord_ok = await fk_get_order(order_id)
                    _amid = (_ord_ok or {}).get("admin_msg_id")
                except Exception:
                    _amid = None
                if _amid:
                    try:
                        await bot.edit_message_text(_caption, chat_id=ADMIN_ID, message_id=_amid, parse_mode="HTML")
                    except Exception:
                        await bot.send_message(ADMIN_ID, _caption, parse_mode="HTML")
                else:
                    await bot.send_message(ADMIN_ID, _caption, parse_mode="HTML")
            except Exception:
                pass
            _fail_clear("claude", user_id)
            await log_event(user_id, "claude_activation_ok", f"code={code} browser={provider} plan={plan_name}")
            return

        # ── Неуспех ──
        _err = result.get("error") or "Не удалось активировать."
        _claude_job_results[ref] = {"status": "done", "success": False, "error": _err}
        try:
            await bot.send_message(
                ADMIN_ID,
                f"❌ <b>Claude (6661231.xyz) — активация не прошла</b>\n"
                f"👤 {await _who_user(user_id)} · {plan_name}\n"
                f"🔑 <code>{code}</code>\n"
                f"🧩 <code>{org_id}</code>\n"
                f"⚠️ {(_err)[:300]}",
                parse_mode="HTML")
        except Exception:
            pass
    except Exception as _e:
        logging.error(f"claude browser job {ref}: {_e}", exc_info=True)
        _claude_job_results[ref] = {"status": "done", "success": False,
                                    "error": "Ошибка активации. Напиши Александру."}


async def _claude_query_once(provider: str, ref) -> str:
    """ОДИН запрос статуса активации на API-сайте.

    'success' | 'failed' | 'review' | 'pending' | 'unknown' (сайт не ответил /
    у сайта нет API статуса). Нужен и ожиданию в цепочке, и кнопке
    «Проверить на сайте сейчас», и фоновому слежению. 08.10.2026
    """
    cfg = CLAUDE_PROVIDERS.get(provider, {})
    api = cfg.get("api", "bpa")
    base = cfg.get("base", "")
    if api == "browser" or not ref:
        return "unknown"
    try:
        if api == "partner":
            _hdr = {"Authorization": f"Bearer {cfg.get('key','')}"}
            async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=15)) as _s:
                async with _s.get(f"{base}/api/partner/v1/redemptions/{ref}", headers=_hdr) as _r:
                    if _r.status != 200:
                        return "unknown"
                    _d = await _r.json()
            _st = str((_d.get("data") or {}).get("status") or "")
            if _st == "succeeded":
                return "success"
            if _st == "failed":
                return "failed"
            # «review» — сайт отправил активацию на ручную проверку. Это НЕ отказ:
            # раньше бот считал его отказом и шёл на следующий сайт со вторым
            # кодом — пройди проверка, у клиента было бы две подписки. 08.10.2026
            if _st == "review":
                return "review"
            return "pending" if _st else "unknown"
        if api == "order":
            _q = await _claude_order_query(cfg, str(ref))
        elif api == "agent":
            _q = await _claude_agent_query(cfg, str(ref))
        else:  # bpa
            async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=15)) as _s:
                async with _s.get(f"{base}/api/activate/{ref}") as _r:
                    if _r.status != 200:
                        return "unknown"
                    _d = await _r.json()
            _q = {"status": {"done": "success", "failed": "failed"}.get(
                str(_d.get("status") or ""), "pending")}
        _qs = str((_q or {}).get("status") or "")
        if _qs in ("success", "failed"):
            return _qs
        return "pending" if _qs else "unknown"
    except Exception as _e_q1:
        logging.warning(f"claude query {provider} {ref}: {_e_q1}")
        return "unknown"


async def _claude_wait_result(provider: str, ref) -> str:
    """Ждёт итог активации на API-сайте: 'success' | 'failed' | 'review' | 'timeout'.
    Без уведомлений и фолбэка — только результат ОДНОГО сайта (фолбэком рулит цепочка)."""
    cfg = CLAUDE_PROVIDERS.get(provider, {})
    api = cfg.get("api", "bpa")
    # bpa сам ретраит внутри заказа (status=running, пока идут повторы; failed — только когда
    # попытки исчерпаны). Ему даём больше времени — иначе обрываем активацию, которая бы прошла.
    _iters = 84 if api == "bpa" else 36      # bpa ≈7 мин, остальные ≈3 мин
    for _ in range(_iters):
        await asyncio.sleep(5)
        _st = await _claude_query_once(provider, ref)
        if _st in ("success", "failed", "review"):
            return _st
    return "timeout"


# ─── Claude: неясный исход активации ──────────────────────────────────────
# Когда сайт принял код, а подтверждения нет (needs_check у браузерных сайтов,
# таймаут у API-сайтов), код мог быть уже активирован. Раньше цепочка просто
# завершалась, её finally снимал оба замка, и следующее нажатие клиента
# НАЧИНАЛОСЬ с возврата этого кода в пул и брало второй: две подписки за один
# заказ плюс пустой код следующему покупателю. А кнопки решения хранили
# контекст только в памяти и после деплоя отвечали «Контекст устарел».
# Теперь: метка в settings (переживает деплой), цепочка по такому коду НЕ
# стартует, решение — только за Александром. 06.10.2026.
#
# 08.10.2026: в метке хранится всё, чтобы закрыть заказ без участия цепочки —
# сайт, номер активации на сайте, Organization ID, тариф. По ним фоновое
# слежение само спрашивает API-сайт и, если он ответил «успех», закрывает заказ.

def _cl_s(v) -> str:
    return str(v if v is not None else "").replace("|", "/").replace("\n", " ").strip()


_CLAUDE_CHECK_FIELDS = ("uid", "order", "ts", "site", "prov", "ref", "org", "plan_name", "plan_key")


async def _claude_check_mark(code: str, user_id: int, order_id: str, site: str = "",
                             prov: str = "", ref: str = "", org: str = "",
                             plan_name: str = "", plan_key: str = "") -> None:
    import time as _t_cm
    try:
        await set_setting(
            f"claudecheck:{str(code).strip().upper()}",
            "|".join([str(int(user_id)), _cl_s(order_id), str(int(_t_cm.time())),
                      _cl_s(site), _cl_s(prov), _cl_s(ref), _cl_s(org),
                      _cl_s(plan_name), _cl_s(plan_key)]))
    except Exception as _e_cm:
        logging.error(f"claudecheck mark {code}: {_e_cm}")


def _claude_check_parse(raw: str) -> dict:
    """Разбирает метку claudecheck. Старые метки (4 поля) тоже читаются."""
    _p = str(raw or "").split("|")
    return {k: (_p[i].strip() if i < len(_p) else "") for i, k in enumerate(_CLAUDE_CHECK_FIELDS)}


async def _claude_check_get(code: str) -> str:
    try:
        return (await get_setting(f"claudecheck:{str(code).strip().upper()}", "") or "").strip()
    except Exception as _e_cg:
        logging.warning(f"claudecheck get {code}: {_e_cg}")
        # Не смогли прочитать — считаем, что метка ЕСТЬ: безопаснее не
        # запускать вторую активацию, чем отдать потраченный код в пул.
        return "?"


async def _claude_check_clear(code: str) -> None:
    try:
        _pool_cc = await get_pool()
        async with _pool_cc.acquire() as _c_cc:
            await _c_cc.execute("DELETE FROM settings WHERE key=$1",
                                f"claudecheck:{str(code).strip().upper()}")
    except Exception as _e_cc:
        logging.warning(f"claudecheck clear {code}: {_e_cc}")


async def _claude_nc_save(tok: str, ctx: dict) -> None:
    """Контекст кнопок «активирована / не активировалась» — и в память, и в базу."""
    import json as _j_ns
    _claude_needcheck[tok] = ctx
    try:
        await set_setting(f"claudenc:{tok}", _j_ns.dumps(ctx, ensure_ascii=False, default=str))
    except Exception as _e_ns:
        logging.warning(f"claudenc save {tok}: {_e_ns}")


async def _claude_nc_peek(tok: str):
    """Читает контекст кнопки, НЕ удаляя его (для проверок до решения)."""
    import json as _j_np
    _ctx = _claude_needcheck.get(tok)
    if _ctx is not None:
        return _ctx
    try:
        _raw = (await get_setting(f"claudenc:{tok}", "") or "").strip()
        return _j_np.loads(_raw) if _raw else None
    except Exception as _e_np:
        logging.warning(f"claudenc peek {tok}: {_e_np}")
        return None


async def _claude_nc_load(tok: str):
    """Достаёт и УДАЛЯЕТ контекст кнопки. Память — потом база (после деплоя)."""
    import json as _j_nl
    _ctx = _claude_needcheck.pop(tok, None)
    _raw = ""
    try:
        _raw = (await get_setting(f"claudenc:{tok}", "") or "").strip()
        _pool_nl = await get_pool()
        async with _pool_nl.acquire() as _c_nl:
            await _c_nl.execute("DELETE FROM settings WHERE key=$1", f"claudenc:{tok}")
    except Exception as _e_nl:
        logging.warning(f"claudenc load {tok}: {_e_nl}")
    if _ctx is None and _raw:
        try:
            _ctx = _j_nl.loads(_raw)
        except Exception:
            _ctx = None
    return _ctx


async def _claude_decision_taken(code: str) -> None:
    """Решение по коду принято — гасим ВСЕ остальные кнопки по нему.

    По одному коду бывает несколько сообщений с кнопками (исходное и
    напоминание после повторного нажатия клиента). Нажал «активирована» в
    одном — второе оставалось живым, и «не активировалась — другой сайт» в нём
    запускало новую цепочку по уже выданной подписке: вторая активация.
    Самопроверка 06.10.2026.
    """
    _c = str(code or "").strip()
    if not _c:
        return
    for _k in [k for k, v in list(_claude_needcheck.items())
               if str((v or {}).get("code") or "").strip() == _c]:
        _claude_needcheck.pop(_k, None)
    try:
        _pool_dt = await get_pool()
        async with _pool_dt.acquire() as _c_dt:
            await _c_dt.execute(
                "DELETE FROM settings WHERE key LIKE 'claudenc:%' AND value LIKE $1",
                f'%"code": "{_c}"%')
    except Exception as _e_dt:
        logging.warning(f"claude decision cleanup {_c}: {_e_dt}")


# ─── Claude: журнал попыток, контекст заказа, сообщения (08.10.2026) ──────
# Всё, что у ChatGPT уже было: журнал «с какой попытки и каким кодом прошло»,
# полный контекст заказа в каждом сообщении Александру, подсказка клиенту по
# каждой ошибке, и сообщения о сбоях, которые сами переписываются в «прошла»,
# когда активация в итоге удалась.

async def _claude_log_attempt(order_id: str, code: str, site: str, outcome: str) -> None:
    """Строка журнала на КАЖДУЮ попытку (settings claudelog:{заказ}).
    outcome='ok' — успех. Повтор той же строки подряд — счётчик ×N."""
    _oid = str(order_id or "").strip()
    if not _oid:
        return
    try:
        _out = _cl_s(outcome or "сайт не назвал причину")[:140]
        _base = f"{_cl_s(code).upper()}|{_cl_s(site)}|{_out}"
        _key = f"claudelog:{_oid}"
        _rows = [r for r in (await get_setting(_key, "") or "").split("\n") if r.strip()]
        if _rows:
            _lp = _rows[-1].split("|")
            if "|".join(_lp[:3]) == _base:
                _cnt = int(_lp[3]) if len(_lp) > 3 and _lp[3].isdigit() else 1
                _rows[-1] = f"{_base}|{_cnt + 1}"
                await set_setting(_key, "\n".join(_rows[-14:]))
                return
        _rows.append(f"{_base}|1")
        await set_setting(_key, "\n".join(_rows[-14:]))
    except Exception as _e_la:
        logging.warning(f"_claude_log_attempt {_oid}: {_e_la}")


async def claude_attempts_block(order_id: str) -> str:
    """«С какой попытки прошло, каким кодом и что мешало» — одним блоком.
    Сводит журнал с тем, что записано на самом деле (claude_codes)."""
    import html as _h_a
    _oid = str(order_id or "").strip()
    if not _oid:
        return ""
    try:
        _raw = (await get_setting(f"claudelog:{_oid}", "") or "").strip()
    except Exception as _e_a:
        logging.warning(f"claude_attempts_block {_oid}: {_e_a}")
        return ""
    _rows = [r for r in _raw.split("\n") if r.strip()]
    if not _rows:
        return ""
    _recorded = []
    try:
        _pool_a = await get_pool()
        async with _pool_a.acquire() as _c_a:
            _rec = await _c_a.fetch(
                "SELECT UPPER(code) AS c FROM claude_codes WHERE order_id=$1 "
                "AND used_by IS NOT NULL ORDER BY used_at NULLS LAST", _oid)
        _recorded = [r["c"] for r in _rec]
    except Exception as _e_a2:
        logging.warning(f"claude_attempts_block запись {_oid}: {_e_a2}")
    _lines, _win, _seen, _acc = [], 0, set(), 0
    for _i, _r in enumerate(_rows, 1):
        _p = _r.split("|")
        _c = (_p[0] if _p else "").strip().upper()
        _s = _p[1].strip() if len(_p) > 1 else ""
        _o = _p[2].strip() if len(_p) > 2 else ""
        _n = int(_p[3]) if len(_p) > 3 and _p[3].strip().isdigit() else 1
        _seen.add(_c)
        _acc += _n
        if _o == "ok":
            _o = "успех"
            _win = _acc
        elif _c in _recorded and _i == max(
                [j for j, rr in enumerate(_rows, 1)
                 if rr.split("|")[0].strip().upper() == _c] or [0]):
            _o = f"{_o} → позже подтвердилась, подписка выдана"
            _win = _acc
        _lines.append(f"  {_i}. <code>{_h_a.escape(_c)}</code>"
                      + (f" · {_h_a.escape(_s)}" if _s else "")
                      + (f" — {_h_a.escape(_o)}" if _o else "")
                      + (f" <b>×{_n}</b>" if _n > 1 else ""))
    for _c in _recorded:
        if _c not in _seen:
            _lines.append(f"  • <code>{_h_a.escape(_c)}</code> — записан без "
                          f"попытки бота (вручную)")
    _head = f"\U0001f9ed Попытки: <b>{_acc}</b>"
    if _win:
        _head += f" · удалась <b>{_win}-я</b>"
    elif _recorded:
        _head += " · итог записан вне попыток бота"
    else:
        _head += " · <b>успешной нет</b>"
    return _head + "\n" + "\n".join(_lines)


async def _adm_claude_ctx(order_id: str = "", code: str = "", site: str = "",
                          org_id: str = "", plan_name: str = "", uid=None) -> str:
    """Контекст для сообщений Александру по Claude — каждая строка, если есть:
      👤 Клиент · 📦 Тариф · 🧾 Заказ #N · FreeKassa · 💳 оплата · 🆔 Order ·
      🌐 Сайт · 🔑 Код · 🏢 Organization ID
    Раньше в части сообщений были только uid и код — заказ искали руками."""
    import html as _h_cc
    _L = []
    if uid:
        try:
            _L.append(f"\U0001f464 Клиент: {await _who_user(uid)}")
        except Exception:
            _L.append(f"\U0001f464 Клиент: <code>{uid}</code>")
    if plan_name:
        _L.append(f"\U0001f4e6 Тариф: <b>Claude {_h_cc.escape(str(plan_name))}</b>")
    if order_id:
        try:
            _oc = (await _adm_gpt_ctx(order_id, show_site=False, show_route=False) or "").rstrip("\n")
        except Exception:
            _oc = ""
        if _oc:
            _L.append(_oc)
        _L.append(f"\U0001f194 Order: <code>{_h_cc.escape(str(order_id))}</code>")
    if site:
        _L.append(f"\U0001f310 Сайт: <b>{_h_cc.escape(str(site))}</b>")
    if code:
        _L.append(f"\U0001f511 Код: <code>{_h_cc.escape(str(code))}</code>")
    if org_id:
        _L.append(f"\U0001f3e2 Organization ID: <code>{_h_cc.escape(str(org_id))}</code>")
    return "\n".join(_L)


async def _claude_admin_msg_add(order_id: str, mid) -> None:
    """Запоминает сообщение о ходе активации по заказу — чтобы при успехе
    переписать его в «активация прошла», а не оставить висеть неправдой."""
    if not order_id or not mid:
        return
    try:
        _k = f"claude_admin_msgs:{order_id}"
        _ids = [x for x in (await get_setting(_k, "") or "").split(",") if x.strip().isdigit()]
        if str(int(mid)) not in _ids:
            _ids.append(str(int(mid)))
        await set_setting(_k, ",".join(_ids[-10:]))
    except Exception as _e_ma:
        logging.warning(f"claude admin msg add {order_id}: {_e_ma}")


async def _claude_admin_send(text: str, kb=None, shot=None, order_id: str = ""):
    """Сообщение Александру (+ скриншот сайта отдельно). Возвращает message_id
    текста и запоминает его по заказу. Отказ отправки — в лог, не молча."""
    _mid = None
    for _pm in ("HTML", None):
        try:
            _t = text if _pm else re.sub(r"<[^>]+>", "", text)
            _m = await bot.send_message(ADMIN_ID, _t[:4096], parse_mode=_pm, reply_markup=kb,
                                        disable_web_page_preview=True)
            _mid = getattr(_m, "message_id", None)
            break
        except Exception as _e_as:
            logging.error(f"claude admin send ({_pm}): {_e_as}")
    if _mid and order_id:
        await _claude_admin_msg_add(order_id, _mid)
    if shot:
        try:
            from aiogram.types import BufferedInputFile as _BIF_as
            await bot.send_photo(ADMIN_ID, _BIF_as(shot, filename="claude_site.png"),
                                 caption="📸 Экран сайта активации Claude")
        except Exception as _e_sh:
            logging.warning(f"claude admin shot: {_e_sh}")
    return _mid


async def _claude_admin_msgs_close(order_id: str, text: str) -> int:
    """Переписывает все запомненные сообщения по заказу в итоговое и убирает
    с них кнопки. Возвращает, сколько сообщений поправлено."""
    if not order_id:
        return 0
    _keys = (f"claude_admin_msgs:{order_id}", f"claude_confirm_msg:{order_id}")
    _ids = []
    for _k in _keys:
        try:
            for _x in (await get_setting(_k, "") or "").split(","):
                if _x.strip().isdigit() and _x.strip() not in _ids:
                    _ids.append(_x.strip())
        except Exception as _e_mc:
            logging.warning(f"claude admin msgs read {_k}: {_e_mc}")
    _n = 0
    for _mid in _ids:
        try:
            await bot.edit_message_text(text, chat_id=ADMIN_ID, message_id=int(_mid),
                                        parse_mode="HTML", disable_web_page_preview=True)
            _n += 1
        except Exception as _e_ed:
            if "not modified" in str(_e_ed).lower():
                _n += 1
            else:
                logging.info(f"claude admin msg {_mid} edit: {_e_ed}")
    for _k in _keys:
        try:
            await set_setting(_k, "")
        except Exception:
            pass
    return _n


