def _pack_label(pack: str) -> str:
    """Человекочитаемое название заказа по значению pack в fk_orders."""
    pack = pack or ""
    try:
        if pack.startswith("shop:"):
            _p = pack.split(":")
            _k = _p[1] if len(_p) > 1 else ""
            _idx = int(_p[2]) if len(_p) > 2 and _p[2].isdigit() else 0
            _s = SHOP_CATALOG.get(_k, {}) or {}
            _nm = _s.get("name", _k)
            _pl = _s.get("plans", [])
            _plname = _pl[_idx]["name"] if 0 <= _idx < len(_pl) else ""
            return (_nm + (f" {_plname}" if _plname else "")).strip() or "Заказ"
        if pack.startswith("nsg:"):
            return "iCloud / App Store"
        if pack.startswith("credits:") or pack.startswith("pack"):
            return "Пополнение кредитов"
    except Exception:
        pass
    return "Заказ"


_GENIMG_CACHE = {}  # token -> (bytes, mime, ts) — временная отдача для скачивания
def _genimg_put(_b: bytes, _mime: str) -> str:
    import time as _t, secrets as _sec
    _tok = _sec.token_urlsafe(10)
    _GENIMG_CACHE[_tok] = (_b, _mime, _t.time())
    if len(_GENIMG_CACHE) > 300:
        _now = _t.time()
        for _k in list(_GENIMG_CACHE.keys()):
            if _now - _GENIMG_CACHE[_k][2] > 3600:
                _GENIMG_CACHE.pop(_k, None)
    return _tok


async def tg_file_proxy_url(file_id: str, mime: str = "image/jpeg") -> str:
    """Публичная одноразовая ссылка на файл Telegram — БЕЗ токена бота в URL.

    Раньше Motion Control отдавал EvoLink ссылку вида
    https://api.telegram.org/file/bot<BOT_TOKEN>/... — то есть отправлял третьей
    стороне полный токен бота (он же и есть доступ к боту: рассылка по всей базе,
    перехват апдейтов). Теперь мы сами скачиваем файл и отдаём его со своего
    домена по случайному токену, который живёт ~1 час.
    """
    if not WEBAPP_BASE_URL:
        raise Exception(
            "Не задан WEBAPP_BASE_URL — Motion Control временно недоступен. "
            "Добавь переменную в Railway Variables."
        )
    _f = await bot.get_file(file_id)
    _buf = await bot.download_file(_f.file_path)
    _data = _buf.read() if hasattr(_buf, "read") else _buf
    _tok = _genimg_put(_data, mime)
    return f"{WEBAPP_BASE_URL.rstrip('/')}/genimg?t={_tok}"


def _bytes_response(data: bytes, mime: str, filename: str, request: web.Request) -> web.Response:
    """Отдача байтов с поддержкой Range (нужно для inline-видео на iOS)."""
    total = len(data)
    _base_h = {"Accept-Ranges": "bytes", "Content-Disposition": 'inline; filename="' + filename + '"'}
    rng = request.headers.get("Range", "")
    if rng.startswith("bytes="):
        try:
            _se = rng.split("=", 1)[1].split("-")
            _start = int(_se[0]) if _se[0] else 0
            _end = int(_se[1]) if len(_se) > 1 and _se[1] else total - 1
            _end = min(_end, total - 1)
            if _start > _end or _start >= total:
                raise ValueError("bad range")
            _h = dict(_base_h)
            _h["Content-Range"] = f"bytes {_start}-{_end}/{total}"
            return web.Response(status=206, body=data[_start:_end + 1], content_type=mime, headers=_h)
        except Exception:
            pass
    return web.Response(body=data, content_type=mime, headers=_base_h)


async def genimg_handler(request: web.Request) -> web.Response:
    """Отдаёт сгенерированную картинку/видео по токену (просмотр/скачивание)."""
    _it = _GENIMG_CACHE.get(request.query.get("t", ""))
    if not _it:
        return web.Response(status=404, text="not found")
    _mime = _it[1]
    _fn = "video.mp4" if "video" in _mime else ("image.jpg" if "jpeg" in _mime else "image.png")
    return _bytes_response(_it[0], _mime, _fn, request)


_GENVIDF_CACHE = {}  # file_id -> (bytes, ts) кэш скачанных из Telegram видео


async def genvidf_handler(request: web.Request) -> web.Response:
    """Постоянное воспроизведение видео из истории по telegram file_id."""
    _fid = request.query.get("fid", "")
    if not _fid:
        return web.Response(status=404, text="not found")
    try:
        import time as _t
        _c = _GENVIDF_CACHE.get(_fid)
        if _c and (_t.time() - _c[1] < 3600):
            _data = _c[0]
        else:
            _f = await bot.get_file(_fid)
            _buf = await bot.download_file(_f.file_path)
            _data = _buf.read() if hasattr(_buf, "read") else _buf
            _GENVIDF_CACHE[_fid] = (_data, _t.time())
            if len(_GENVIDF_CACHE) > 60:
                for _k in list(_GENVIDF_CACHE.keys()):
                    if _t.time() - _GENVIDF_CACHE[_k][1] > 3600:
                        _GENVIDF_CACHE.pop(_k, None)
        return _bytes_response(_data, "video/mp4", "video.mp4", request)
    except Exception as _e:
        logging.error(f"genvidf: {_e}")
        return web.Response(status=404, text="not found")


async def api_gen_image_handler(request: web.Request) -> web.Response:
    """Генерация изображения из мини-аппки. Списывает кредиты, при ошибке возвращает."""
    try:
        try:
            body = await request.json()
        except Exception:
            body = {}
        _idata = (body.get("initData") if isinstance(body, dict) else None) or ""
        uid = _verify_tg_init_data(_idata)
        if not uid:
            return web.json_response({"ok": False, "error": "auth:" + _initdata_reason(_idata)}, status=403)
        from config import IMAGE_MODELS
        _key = str(body.get("model", "")).strip()
        _prompt = str(body.get("prompt", "")).strip()
        _aspect = str(body.get("aspect", "1:1")).strip() or "1:1"
        m = IMAGE_MODELS.get(_key)
        if not m:
            return web.json_response({"ok": False, "error": "model"}, status=400)
        if len(_prompt) < 2:
            return web.json_response({"ok": False, "error": "prompt"}, status=400)
        _cost = int(m.get("credits", 0))
        from db import deduct as _deduct, add_credits as _add_cr, get_credits as _get_cr, log_gen as _log_gen
        _cr = await _get_cr(int(uid))
        if _cr < _cost:
            return web.json_response({"ok": False, "error": "credits", "need": _cost, "have": _cr})
        _g_ok, _g_err, _g_ck = await _webgen_guard(int(uid), "photo")
        if not _g_ok:
            return _webgen_err_resp(_g_err)
        try:
            if not await _deduct(int(uid), _cost):
                await _webgen_done(int(uid), _g_ck)
                return web.json_response({"ok": False, "error": "credits", "have": _cr})
        except Exception:
            await _webgen_done(int(uid), _g_ck)
            raise
        # Оплаченная генерация попадает в долговечный журнал ДО обращения к
        # поставщику: если процесс остановят прямо сейчас, кредиты вернёт
        # разбор потерянных задач, а не «никто». Аудит 29.09.2026, №11.
        _wjob = _new_webgen_id()
        await webgen_job_start(_wjob, int(uid), "photo", _key, _cost,
                               params=_prompt[:200], worker=_WORKER_ID)
        try:
            from generation_api import api_generate_image as _gen
            _img = await _gen(_prompt, m["model_id"], _aspect, m.get("api", "imagen"),
                              quality=m.get("quality", "medium"))
        except Exception as _ge:
            # Закрытие задачи и возврат кредитов — одной транзакцией.
            await webgen_job_finish_refund(_wjob, str(_ge)[:200], int(uid), _cost)
            await _webgen_done(int(uid), _g_ck)
            logging.error(f"api_gen_image gen: {_ge}")
            return web.json_response({"ok": False, "error": "gen_failed"})
        await _webgen_done(int(uid), _g_ck)
        if not _img:
            await webgen_job_finish_refund(_wjob, "пустой ответ поставщика",
                                           int(uid), _cost)
            return web.json_response({"ok": False, "error": "empty"})
        await webgen_job_finish(_wjob, "done")
        try:
            await _log_gen(int(uid), "image", _key, _cost)
        except Exception:
            pass
        try:
            await bot.send_photo(int(uid), BufferedInputFile(_img, "image.png"),
                                 caption=f"🎨 {m.get('name','')} · −{_cost} кр")
        except Exception:
            pass
        _mime = "image/jpeg" if (len(_img) > 2 and _img[0] == 0xFF and _img[1] == 0xD8) else "image/png"
        import base64 as _b64
        _uri = "data:" + _mime + ";base64," + _b64.b64encode(_img).decode()
        _tok = _genimg_put(_img, _mime)
        return web.json_response({"ok": True, "img": _uri, "token": _tok, "credits": await _get_cr(int(uid))})
    except Exception as _e:
        logging.error(f"api_gen_image: {_e}")
        return web.json_response({"ok": False, "error": "server"}, status=500)


_GENVID_JOBS = {}  # job_id -> {status, token, url, err, credits, size_mb, ts}

def _genvid_gc():
    import time as _t
    _now = _t.time()
    if len(_GENVID_JOBS) > 200:
        for _k in list(_GENVID_JOBS.keys()):
            if _now - _GENVID_JOBS[_k].get("ts", 0) > 3600:
                _GENVID_JOBS.pop(_k, None)


async def _run_video_job(job_id, uid, key, m, prompt, aspect, duration, cost):
    """Фоновая генерация видео: результат в чат бота + токен на скачивание."""
    from db import add_credits as _add_cr, get_credits as _get_cr, log_gen as _log_gen
    try:
        from generation_api import api_generate_video as _gv
        try:
            from generation_api import upload_large_file as _upl
        except Exception:
            _upl = None
        vid = await _gv(prompt, m["model_id"], aspect, m.get("api", "veo"), duration)
        if not vid or len(vid) < 1000:
            raise Exception("empty")
        size_mb = len(vid) / 1024 / 1024
        try:
            await _log_gen(int(uid), "video", key, cost)
        except Exception:
            pass
        _cap = f"🎬 {m.get('name','')} · {duration}с · −{cost} кр"
        _url = None
        _tok = None
        _fid = None
        if size_mb > 48:
            _url = await _upl(vid, f"video_{key}.mp4") if _upl else None
            if not _url:
                raise Exception("upload_failed")
            try:
                await bot.send_message(int(uid), f"{_cap}\nСкачать (ссылка 24ч): {_url}",
                                       disable_web_page_preview=True)
            except Exception:
                pass
        else:
            try:
                _sent = await bot.send_video(int(uid), BufferedInputFile(vid, "video.mp4"),
                                             caption=_cap, supports_streaming=True)
                try:
                    _fid = _sent.video.file_id if _sent and _sent.video else None
                except Exception:
                    _fid = None
            except Exception as _se:
                logging.error(f"video job send: {_se}")
            _tok = _genimg_put(vid, "video/mp4")
        _GENVID_JOBS[job_id].update({"status": "done", "token": _tok, "url": _url, "fid": _fid,
                                     "size_mb": round(size_mb, 1), "credits": await _get_cr(int(uid))})
        if not await webgen_job_finish(job_id, "done"):
            # Задачу уже успели разобрать как потерянную и вернуть кредиты —
            # результат всё равно отдаём, но след в логе оставляем.
            logging.warning(f"webgen job {job_id}: результат пришёл ПОСЛЕ возврата кредитов")
    except Exception as _e:
        # Кредиты возвращаем, только если запись журнала ещё за нами: если
        # задачу уже разобрали как потерянную и вернули за неё деньги, второй
        # возврат был бы подарком. Аудит 29.09.2026, пункт №11.
        # Закрытие задачи и возврат — одной транзакцией: раньше отметка
        # refunded=1 коммитилась ДО начисления, и сбой между ними прятал
        # задачу от фоновой компенсации навсегда. Аудит 30.09.2026, №11.
        await webgen_job_finish_refund(job_id, str(_e)[:200], int(uid), cost)
        logging.error(f"video job {job_id}: {_e}")
        _cr = 0
        try:
            _cr = await _get_cr(int(uid))
        except Exception:
            pass
        _GENVID_JOBS[job_id].update({"status": "error", "err": "gen_failed", "credits": _cr})
    finally:
        # Снимаем «идёт генерация»: иначе счётчик параллельных генераций
        # оставался занятым до автоочистки через 30 минут и блокировал клиента.
        try:
            await unmark_generation_active(int(uid))
        except Exception as _e_um:
            logging.warning(f"unmark after video job uid={uid}: {_e_um}")


async def api_gen_video_handler(request: web.Request) -> web.Response:
    """Старт генерации видео из мини-аппки. Списывает кредиты, запускает фоновый job."""
    try:
        try:
            body = await request.json()
        except Exception:
            body = {}
        _idata = (body.get("initData") if isinstance(body, dict) else None) or ""
        uid = _verify_tg_init_data(_idata)
        if not uid:
            return web.json_response({"ok": False, "error": "auth:" + _initdata_reason(_idata)}, status=403)
        from config import VIDEO_MODELS
        _key = str(body.get("model", "")).strip()
        _prompt = str(body.get("prompt", "")).strip()
        _aspect = str(body.get("aspect", "16:9")).strip() or "16:9"
        if _aspect not in ("16:9", "9:16", "1:1"):
            _aspect = "16:9"
        m = VIDEO_MODELS.get(_key)
        if not m:
            return web.json_response({"ok": False, "error": "model"}, status=400)
        if len(_prompt) < 2:
            return web.json_response({"ok": False, "error": "prompt"}, status=400)
        _durs = m.get("durations")
        try:
            _dur = int(body.get("duration", 0))
        except Exception:
            _dur = 0
        if _durs:
            if _dur not in _durs:
                _dur = sorted(_durs.keys())[0]
            _cost = int(_durs[_dur][0])
        else:
            _dur = 8
            _cost = int(m.get("credits", 0))
        from db import deduct as _deduct, get_credits as _get_cr
        _cr = await _get_cr(int(uid))
        if _cr < _cost:
            return web.json_response({"ok": False, "error": "credits", "need": _cost, "have": _cr})
        _g_ok, _g_err, _g_ck = await _webgen_guard(int(uid), "video")
        if not _g_ok:
            return _webgen_err_resp(_g_err)
        try:
            if not await _deduct(int(uid), _cost):
                await _webgen_done(int(uid), _g_ck)
                return web.json_response({"ok": False, "error": "credits", "have": _cr})
        except Exception:
            await _webgen_done(int(uid), _g_ck)
            raise
        import time as _t, secrets as _sec
        _job = _sec.token_urlsafe(10)
        _genvid_gc()
        _GENVID_JOBS[_job] = {"status": "pending", "ts": _t.time()}
        await webgen_job_start(_job, int(uid), "video", _key, _cost,
                               params=f"{_prompt[:160]} | {_aspect} | {_dur}с",
                               worker=_WORKER_ID)
        asyncio.create_task(_run_video_job(_job, int(uid), _key, m, _prompt, _aspect, _dur, _cost))
        return web.json_response({"ok": True, "job": _job, "cost": _cost, "credits": await _get_cr(int(uid))})
    except Exception as _e:
        logging.error(f"api_gen_video: {_e}")
        return web.json_response({"ok": False, "error": "server"}, status=500)


