def _decode_data_uri_image(_uri: str):
    """data:image/...;base64,XXX -> (bytes, mime) или (None, None)."""
    try:
        if not _uri.startswith("data:image/"):
            return None, None
        _head, _b64 = _uri.split(",", 1)
        _mime = _head.split(";")[0][5:] or "image/jpeg"
        import base64 as _b
        _raw = _b.b64decode(_b64)
        if len(_raw) < 100 or len(_raw) > 12 * 1024 * 1024:
            return None, None
        return _raw, _mime
    except Exception:
        return None, None


async def api_gen_edit_handler(request: web.Request) -> web.Response:
    """Редактирование фото по описанию (Nano Banana). Фото приходит data-URI от клиента."""
    try:
        try:
            body = await request.json()
        except Exception:
            body = {}
        _idata = (body.get("initData") if isinstance(body, dict) else None) or ""
        uid = _verify_tg_init_data(_idata)
        if not uid:
            return web.json_response({"ok": False, "error": "auth:" + _initdata_reason(_idata)}, status=403)
        from config import EDIT_MODELS
        _key = str(body.get("model", "")).strip() or "edit_gemini"
        m = EDIT_MODELS.get(_key)
        if not m:
            _key = "edit_gemini"
            m = EDIT_MODELS.get("edit_gemini") or {"name": "Nano Banana", "credits": 10, "api": "gemini"}
        _prompt = str(body.get("prompt", "")).strip()
        if len(_prompt) < 2:
            return web.json_response({"ok": False, "error": "prompt"}, status=400)
        _img_in, _ = _decode_data_uri_image(str(body.get("image", "")))
        if not _img_in:
            return web.json_response({"ok": False, "error": "image"}, status=400)
        _cost = int(m.get("credits", 10))
        from db import deduct as _deduct, add_credits as _add_cr, get_credits as _get_cr, log_gen as _log_gen
        _cr = await _get_cr(int(uid))
        if _cr < _cost:
            return web.json_response({"ok": False, "error": "credits", "need": _cost, "have": _cr})
        _g_ok, _g_err, _g_ck = await _webgen_guard(int(uid), "photo")
        if not _g_ok:
            return _webgen_err_resp(_g_err)
        try:
            if not await _deduct(int(uid), _cost):
                await _webgen_done(int(uid), _g_ck)
                return web.json_response({"ok": False, "error": "credits", "have": _cr})
        except Exception:
            await _webgen_done(int(uid), _g_ck)
            raise
        _wjob = _new_webgen_id()
        await webgen_job_start(_wjob, int(uid), "edit", _key, _cost,
                               params=_prompt[:200], worker=_WORKER_ID)
        try:
            if (m.get("api") or "gemini") == "fal" and m.get("model_id"):
                from generation_api import api_fal_edit_image as _fedit
                _out = await _fedit(_img_in, _prompt, m["model_id"])
            else:
                from generation_api import api_edit_image as _edit
                _out = await _edit(_img_in, _prompt)
        except Exception as _ge:
            # Закрытие задачи и возврат кредитов — одной транзакцией.
            await webgen_job_finish_refund(_wjob, str(_ge)[:200], int(uid), _cost)
            await _webgen_done(int(uid), _g_ck)
            logging.error(f"api_gen_edit gen: {_ge}")
            return web.json_response({"ok": False, "error": "gen_failed"})
        await _webgen_done(int(uid), _g_ck)
        if not _out:
            await webgen_job_finish_refund(_wjob, "пустой ответ поставщика",
                                           int(uid), _cost)
            return web.json_response({"ok": False, "error": "empty"})
        await webgen_job_finish(_wjob, "done")
        try:
            await _log_gen(int(uid), "edit", _key, _cost)
        except Exception:
            pass
        try:
            await bot.send_photo(int(uid), BufferedInputFile(_out, "edited.png"),
                                 caption=f"🖌 {m.get('name','')} · −{_cost} кр")
        except Exception:
            pass
        _mime = "image/jpeg" if (len(_out) > 2 and _out[0] == 0xFF and _out[1] == 0xD8) else "image/png"
        import base64 as _b64
        _uri = "data:" + _mime + ";base64," + _b64.b64encode(_out).decode()
        _tok = _genimg_put(_out, _mime)
        return web.json_response({"ok": True, "img": _uri, "token": _tok, "credits": await _get_cr(int(uid))})
    except Exception as _e:
        logging.error(f"api_gen_edit: {_e}")
        return web.json_response({"ok": False, "error": "server"}, status=500)


async def _run_anim_job(job_id, uid, key, m, prompt, img_bytes, aspect, cost):
    """Фоновая анимация фото (Veo или fal image-to-video)."""
    from db import add_credits as _add_cr, get_credits as _get_cr, log_gen as _log_gen
    try:
        if (m.get("api") or "veo_anim") == "fal" and m.get("model_id"):
            from generation_api import api_fal_animate_image as _fanim
            vid = await _fanim(img_bytes, prompt, m["model_id"], int(m.get("duration", 5)), aspect)
        else:
            from generation_api import api_animate_image as _anim
            vid = await _anim(img_bytes, prompt, aspect)
        if not vid or len(vid) < 1000:
            raise Exception("empty")
        size_mb = len(vid) / 1024 / 1024
        try:
            await _log_gen(int(uid), "anim", key, cost)
        except Exception:
            pass
        _cap = f"🎞 {m.get('name','Анимация')} · −{cost} кр"
        _url = None
        _tok = None
        _fid = None
        if size_mb > 48:
            try:
                from generation_api import upload_large_file as _upl
                _url = await _upl(vid, "anim.mp4")
            except Exception:
                _url = None
            if not _url:
                raise Exception("upload_failed")
            try:
                await bot.send_message(int(uid), f"{_cap}\nСкачать (ссылка 24ч): {_url}",
                                       disable_web_page_preview=True)
            except Exception:
                pass
        else:
            try:
                _sent = await bot.send_video(int(uid), BufferedInputFile(vid, "anim.mp4"),
                                             caption=_cap, supports_streaming=True)
                try:
                    _fid = _sent.video.file_id if _sent and _sent.video else None
                except Exception:
                    _fid = None
            except Exception as _se:
                logging.error(f"anim job send: {_se}")
            _tok = _genimg_put(vid, "video/mp4")
        _GENVID_JOBS[job_id].update({"status": "done", "token": _tok, "url": _url, "fid": _fid,
                                     "size_mb": round(size_mb, 1), "credits": await _get_cr(int(uid))})
        if not await webgen_job_finish(job_id, "done"):
            # Задачу уже успели разобрать как потерянную и вернуть кредиты —
            # результат всё равно отдаём, но след в логе оставляем.
            logging.warning(f"webgen job {job_id}: результат пришёл ПОСЛЕ возврата кредитов")
    except Exception as _e:
        # Закрытие задачи и возврат — одной транзакцией: раньше отметка
        # refunded=1 коммитилась ДО начисления, и сбой между ними прятал
        # задачу от фоновой компенсации навсегда. Аудит 30.09.2026, №11.
        await webgen_job_finish_refund(job_id, str(_e)[:200], int(uid), cost)
        logging.error(f"anim job {job_id}: {_e}")
        _cr = 0
        try:
            _cr = await _get_cr(int(uid))
        except Exception:
            pass
        _GENVID_JOBS[job_id].update({"status": "error", "err": "gen_failed", "credits": _cr})
    finally:
        # Снимаем «идёт генерация»: иначе счётчик параллельных генераций
        # оставался занятым до автоочистки через 30 минут и блокировал клиента.
        try:
            await unmark_generation_active(int(uid))
        except Exception as _e_um:
            logging.warning(f"unmark after anim job uid={uid}: {_e_um}")


