#  ВАЖНО: зарегистрируй ЭТО ДО существующего @dp.callback_query(F.data.startswith("shop_svc:"))
#  Если вставляешь в конец файла — переименуй callback_data в меню на "nsg_start"
#  (см. ниже menu_shop_nsg_override — он заменит стандартную кнопку appstore)
# ──────────────────────────────────────────────────────────────────────────────

def _nsg_pins_from(resp) -> list:
    """Вытаскивает пин-коды из ответа поставщика, как бы он их ни завернул."""
    if not isinstance(resp, dict):
        return []
    for _k in ("pins", "codes", "keys"):
        _v = resp.get(_k)
        if isinstance(_v, list) and _v:
            return [str(_x) for _x in _v]
    for _k in ("order", "data", "result"):
        _inner = resp.get(_k)
        if isinstance(_inner, dict):
            _v = _nsg_pins_from(_inner)
            if _v:
                return _v
    return []


async def nsgifts_send_pins(fk_order_id: str, user_id: int, service_name: str, pins: list):
    """Отправляет клиенту готовые коды и отмечает факт доставки.

    Вынесено отдельно, чтобы тем же текстом пользовалась и обычная выдача, и
    восстановление застрявшего заказа. Отметка delivered_at ставится ТОЛЬКО
    после успешной отправки: по ней разбор отличает «код куплен и отдан» от
    «куплен, сохранён, но клиент его не видел».
    Повторный внешний аудит 29.09.2026, пункт №18.
    """
    pins_text = "\n".join(f"<code>{p}</code>" for p in pins)
    _oref_ns = await _order_ref_line(fk_order_id)
    await bot.send_message(
        user_id,
        f"🎉 <b>Вот твой код!</b>\n\n"
        f"📦 <b>{service_name}</b>\n"
        f"{_oref_ns}\n\n"
        f"🔑 <b>Код активации:</b>\n{pins_text}\n\n"
        f"📲 <b>Как активировать:</b>\n"
        f"1. Открой <b>App Store</b> на iPhone/iPad\n"
        f"2. Нажми на свой <b>аватар</b> (вверху справа)\n"
        f"3. Выбери <b>«Погасить подарочную карту или код»</b>\n"
        f"4. Нажми <b>«Ввести код вручную»</b> и вставь код выше\n"
        f"5. Готово — баланс пополнится 🎉\n\n"
        f"⚠️ <b>Важно:</b> код работает только на Apple ID того же региона, "
        f"что и карта (например, код 🇺🇸 USA — только на американском Apple ID).\n\n"
        f"Если код не активируется — пиши @{PERSONAL_USERNAME} 🙌",
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="🌍 Как сменить регион Apple ID",
                                  callback_data="nsg_region_help")]
        ])
    )
    # Сообщение ушло — только теперь заказ считается доставленным.
    # Код у клиента — зовём в канал (не чаще раза в 30 дней, подписчиков не
    # трогаем). Ничего не ждёт и не мешает отметкам ниже. 06.10.2026
    client_channel_invite(user_id)
    try:
        _p_dl = await get_pool()
        async with _p_dl.acquire() as _c_dl:
            await _c_dl.execute(
                "UPDATE nsgifts_orders SET delivered_at=NOW() WHERE fk_order_id=$1",
                fk_order_id)
    except Exception as _e_dl:
        logging.warning(f"nsgifts delivered_at {fk_order_id}: {_e_dl}")
    # И отметка в САМОМ ЗАКАЗЕ. Без неё заказ App Store, оплаченный монетками,
    # навсегда оставался с пустым fulfilled_at — и моя же почасовая сводка
    # через 15 минут присылала «🚨 Оплачено, но выдачи не было… выдай из
    # админки» по заказу, код которого клиент уже получил. Послушавшись,
    # Александр закупил бы ВТОРОЙ код в убыток. Ставим здесь, а не в каждом
    # обработчике оплаты: сюда сходятся все пути — монетки, СБП и вебхук.
    # Широкий разбор 02.10.2026.
    try:
        await _mark_order_fulfilled(fk_order_id)
    except Exception as _e_mf:
        logging.warning(f"nsgifts fulfilled_at {fk_order_id}: {_e_mf}")


async def nsgifts_recover_stuck(fk_order_id: str) -> str:
    """Разбирает заказ App Store, застрявший в 'processing'.

    Захват заказа делает статус 'processing', и повторная выдача его уже не
    принимает — это защита от покупки второго кода. Но если процесс упал или
    Railway перезапустил бота посреди выдачи, заказ оставался в 'processing'
    НАВСЕГДА: вебхук больше ничего не делал, кнопка отвечала «уже выполнен»,
    а деньги у поставщика могли быть уже списаны.
    Внешний аудит 29.09.2026, пункт №18.

    Правило то же, что и везде: сами вслепую НИЧЕГО не докупаем. Спрашиваем у
    поставщика про УЖЕ созданный заказ и действуем только по его ответу.
    Возвращает короткий код исхода — для логов и отчёта.
    """
    pool = await get_pool()
    async with pool.acquire() as conn:
        row = await conn.fetchrow(
            "SELECT * FROM nsgifts_orders WHERE fk_order_id=$1", fk_order_id)
    # Берём не только 'processing'. Второе окно: код КУПЛЕН, пины сохранены,
    # статус уже 'fulfilled' — и на этом процесс убили, до отправки клиенту.
    # Такой заказ не подбирал никто: петля смотрела только на 'processing', а
    # кнопка клиента отвечала «код выше в чате», хотя кода он не видел.
    # Повторный внешний аудит 29.09.2026, пункт №18.
    if not row:
        return "not_stuck"
    _undelivered = (row["status"] == "fulfilled"
                    and (row["pins_json"] or "").strip()
                    and row["delivered_at"] is None)
    if row["status"] != "processing" and not _undelivered:
        return "not_stuck"

    _uid = int(row["user_id"])
    _name = row["service_name"]
    _custom = (row["ns_custom_id"] or "").strip()

    async def _alert(text):
        try:
            await bot.send_message(
                ADMIN_ID,
                f"🧯 <b>App Store: зависший заказ</b>\n\n"
                f"👤 {await _who_user(_uid)}\n"
                f"📦 {_name}\n"
                f"🆔 FK: <code>{fk_order_id}</code>\n"
                f"🆔 NS: <code>{_custom or '—'}</code>\n\n" + text,
                parse_mode="HTML")
        except Exception as _e_a:
            logging.warning(f"NSGifts recover: алерт {fk_order_id}: {_e_a}")

    async def _deliver(pins, source):
        import json as _json
        async with pool.acquire() as conn:
            await conn.execute(
                "UPDATE nsgifts_orders SET status='fulfilled', pins_json=$1, "
                "error_msg=$2 WHERE fk_order_id=$3",
                _json.dumps(pins), f"восстановлен ({source})", fk_order_id)
        _sent = False
        try:
            await nsgifts_send_pins(fk_order_id, _uid, _name, pins)
            _sent = True
            await _alert(f"✅ Код нашёлся ({source}) и отправлен клиенту:\n"
                         f"<code>{', '.join(pins)}</code>")
        except Exception as _e_s:
            await _alert(f"✅ Код нашёлся ({source}), но отправить клиенту не вышло "
                         f"(<code>{str(_e_s)[:150]}</code>). Перешли вручную:\n"
                         f"<code>{', '.join(pins)}</code>")
        await log_event(_uid, "nsgifts_recovered", f"fk={fk_order_id} src={source}")
        # Важно вернуть РАЗНОЕ: если клиент заблокировал бота, отправка будет
        # падать всегда, delivered_at так и останется пустым — и петля брала
        # бы этот заказ каждые пять минут и слала алерт снова и снова.
        # Разный исход включает счётчик попыток в петле.
        return _sent

    # 1. Коды уже лежат у нас — упала только доставка.
    _local = (row["pins_json"] or "").strip()
    if _local:
        try:
            import json as _json2
            _pins = _json2.loads(_local)
        except Exception:
            _pins = []
        if _pins:
            _ok_d = await _deliver([str(p) for p in _pins], "из нашей базы")
            return "delivered_local" if _ok_d else "delivered_not_sent"

    # 2. Заказ у поставщика создан — спрашиваем, чем кончилось.
    if _custom and rt.nsgifts_client:
        try:
            info = await rt.nsgifts_client.order_info(_custom)
        except Exception as _e_i:
            logging.warning(f"NSGifts recover: order_info {_custom}: {_e_i}")
            return "api_error"
        _pins = _nsg_pins_from(info)
        if _pins:
            _ok_d2 = await _deliver(_pins, "у поставщика")
            return "delivered_remote" if _ok_d2 else "delivered_not_sent"
        _st = str((info or {}).get("status") or "").lower()
        if _st in ("refunded", "insufficient", "canceled", "cancelled", "failed"):
            # Покупка НЕ состоялась — заказ можно снова сделать выдаваемым.
            # Сами при этом ничего не покупаем: следующую попытку запускает
            # вебхук или кнопка клиента.
            async with pool.acquire() as conn:
                await conn.execute(
                    "UPDATE nsgifts_orders SET status='pending', error_msg=$1 "
                    "WHERE fk_order_id=$2 AND status='processing'",
                    f"поставщик: {_st} — покупка не состоялась", fk_order_id)
            await _alert(f"↩️ У поставщика заказ в статусе <code>{_st}</code> — "
                         f"покупка не состоялась, код НЕ куплен.\n"
                         f"Заказ снова готов к выдаче, второй код не тратится.")
            return "reopened"
        await _alert(f"⏳ У поставщика заказ в статусе <code>{_st or '—'}</code>, "
                     f"кодов пока нет.\n"
                     f"Деньги у поставщика МОГЛИ быть списаны — проверь в кабинете "
                     f"wholesale.ns.gifts по номеру NS выше, прежде чем покупать ещё раз.")
        return "unknown_remote"

    # 3. Заказа у поставщика нет (упали до create_order — или после, но не
    #    успели записать номер). Вслепую не покупаем: решает владелец.
    await _alert("❓ Номера заказа у поставщика нет — мы упали в самом начале "
                 "выдачи.\nСкорее всего ничего не куплено, но проверь кабинет "
                 "по времени заказа. Если покупки не было — нажми «Выдать» "
                 "в админке или попроси клиента нажать «Проверить оплату».")
    return "no_custom_id"


async def nsgifts_fulfill_after_payment(fk_order_id: str, user_id: int):
    """
    Вызывается из fk_credit_paid_order когда order_id начинается с 'nsg_'.
    1. Ищем запись в nsgifts_orders
    2. Создаём заказ в NS Gifts
    3. Оплачиваем → получаем пин-коды
    4. Отправляем пользователю
    """
    if not rt.nsgifts_client:
        logging.error("NSGifts: client not initialized, cannot fulfill")
        await bot.send_message(
            user_id,
            "⚠️ Оплата получена, но автодоставка временно недоступна.\n"
            "Напиши @neirosetkaalex — код пришлю вручную в течение 15 минут.",
        )
        await bot.send_message(
            ADMIN_ID,
            f"🚨 <b>NSGifts: client not init</b>\n"
            f"fk_order={fk_order_id}  uid={user_id}\nАктивируй вручную!",
            parse_mode="HTML"
        )
        return

    pool = await get_pool()

    # 1. Получаем информацию о заказе
    async with pool.acquire() as conn:
        row = await conn.fetchrow(
            "SELECT * FROM nsgifts_orders WHERE fk_order_id=$1", fk_order_id
        )

    if not row:
        logging.error(f"NSGifts: order not found for fk_order={fk_order_id}")
        await bot.send_message(
            ADMIN_ID,
            f"🚨 <b>NSGifts: запись не найдена</b>\n"
            f"fk_order={fk_order_id}  uid={user_id}",
            parse_mode="HTML"
        )
        return

    if row["status"] == "fulfilled":
        logging.info(f"NSGifts: order {fk_order_id} already fulfilled")
        return   # идемпотентность — уже выполнен

    # АТОМАРНЫЙ ЗАХВАТ заказа. Без него два пути выдачи (вебхук FreeKassa и кнопка
    # «Проверить оплату») могли стартовать одновременно, оба увидеть status='pending'
    # и купить у поставщика ДВА кода — клиент оплатил один, второй в убыток.
    async with pool.acquire() as conn:
        _claim = await conn.execute(
            "UPDATE nsgifts_orders SET status='processing' "
            "WHERE fk_order_id=$1 AND status IN ('pending', 'paying')",
            fk_order_id
        )
    if str(_claim).split()[-1] != "1":
        logging.info(f"NSGifts: order {fk_order_id} уже обрабатывается другим путём — выходим")
        return

    service_id   = row["service_id"]
    service_name = row["service_name"]
    price_rub    = row["price_rub"]

    # Уведомляем что обрабатываем
    try:
        await bot.send_message(
            user_id,
            f"✅ <b>Оплата получена!</b>\n"
            f"🆔 Заказ: <code>{fk_order_id}</code>\n\n"
            f"Получаем код — займёт пару секунд… ⏳",
            parse_mode="HTML"
        )
    except Exception:
        pass

    try:
        # 2. Создаём заказ
        create_resp = await rt.nsgifts_client.create_order(service_id, quantity=1)
        custom_id   = create_resp.get("custom_id") or create_resp.get("_custom_id")

        if not custom_id:
            raise RuntimeError(f"create_order: no custom_id in response: {create_resp}")

        # Сохраняем custom_id. Статус НЕ трогаем: он остаётся 'processing',
        # иначе заказ снова становится «захватываемым» и его может подхватить
        # второй путь выдачи.
        async with pool.acquire() as conn:
            await conn.execute(
                "UPDATE nsgifts_orders SET ns_custom_id=$1 WHERE fk_order_id=$2",
                custom_id, fk_order_id
            )

        # 3. Оплачиваем
        pay_resp = await rt.nsgifts_client.pay_order(custom_id)
        status   = pay_resp.get("status", "")
        pins     = pay_resp.get("pins") or []

        if status == "insufficient":
            raise RuntimeError("Insufficient balance on NS Gifts account")

        if not pins:
            raise RuntimeError(f"pay_order returned no pins: {pay_resp}")

        # 4. Сохраняем и отправляем
        import json as _json
        async with pool.acquire() as conn:
            await conn.execute(
                "UPDATE nsgifts_orders SET status='fulfilled', "
                "ns_custom_id=$1, pins_json=$2 WHERE fk_order_id=$3",
                custom_id, _json.dumps(pins), fk_order_id
            )

        # Текст выдачи — один на все пути (обычная выдача и восстановление
        # зависшего заказа), чтобы они не разъезжались со временем.
        await nsgifts_send_pins(fk_order_id, user_id, service_name, pins)

        # ── Код клиенту УЖЕ ушёл. Дальше только служебное ────────────────
        # Раньше это лежало внутри общего try, и обычный таймаут при запросе
        # баланса у поставщика бросал клиенту вдогонку «при выдаче кода
        # возникла ошибка» — человек с рабочим кодом на руках шёл в поддержку.
        # Внешний аудит 29.09.2026, пункт №25.
        try:
            balance = await rt.nsgifts_client.check_balance()
            threshold = await _nsg_threshold()
            balance_warn = f"\n⚠️ <b>Баланс NS Gifts: ${balance:.2f}</b> — пора пополнить!" \
                           if balance < threshold else f"\nБаланс NS Gifts: ${balance:.2f}"
        except Exception as _e_bal:
            logging.warning(f"NSGifts: баланс после выдачи {fk_order_id}: {_e_bal}")
            balance_warn = "\n⚠️ Баланс NS Gifts узнать не удалось — посмотри в кабинете."
        try:
            await bot.send_message(
                ADMIN_ID,
                f"✅ <b>Apple Gift Card продан</b>\n\n"
                f"👤 {await _who_user(user_id)}\n"
                f"📦 {service_name}\n"
                f"💵 {price_rub} ₽\n"
                f"🔑 {', '.join(pins)}"
                f"{balance_warn}",
                parse_mode="HTML"
            )
        except Exception as _e_adm:
            logging.warning(f"NSGifts: алерт о продаже {fk_order_id}: {_e_adm}")
        try:
            await log_event(user_id, "nsgifts_fulfilled",
                            f"fk={fk_order_id} ns={custom_id} pins={len(pins)}")
        except Exception:
            pass
        return

    except Exception as e:
        logging.error(f"NSGifts fulfill failed for {fk_order_id}: {e}", exc_info=True)

        # Если код УЖЕ куплен (pins_json заполнен), а упала только доставка —
        # не помечаем заказ как 'failed', иначе админ по алерту купит второй код.
        async with pool.acquire() as conn:
            _has_pins = await conn.fetchval(
                "SELECT (pins_json IS NOT NULL AND pins_json <> '') FROM nsgifts_orders "
                "WHERE fk_order_id=$1", fk_order_id)
            await conn.execute(
                "UPDATE nsgifts_orders SET status=$1, error_msg=$2 WHERE fk_order_id=$3",
                ("fulfilled" if _has_pins else "failed"), str(e)[:500], fk_order_id
            )

        # Сообщение пользователю — по фактическому этапу сбоя, а не одно на всё.
        try:
            await bot.send_message(
                user_id,
                ("😔 Оплата прошла, код куплен, но отправить его не получилось.\n\n"
                 if _has_pins else
                 "😔 Оплата прошла, но при выдаче кода возникла ошибка.\n\n")
                + f"Напиши @{PERSONAL_USERNAME} — код пришлю вручную в течение 15 минут! 🙏"
            )
        except Exception as _e_cl:
            logging.warning(f"NSGifts: сообщение клиенту о сбое {fk_order_id}: {_e_cl}")

        # Алерт администратору с деталями.
        # Если код уже куплен — НЕ покупать повторно, а переслать имеющийся.
        _pins_note = ""
        if _has_pins:
            try:
                async with pool.acquire() as conn:
                    _pj = await conn.fetchval(
                        "SELECT pins_json FROM nsgifts_orders WHERE fk_order_id=$1", fk_order_id)
                _pins_note = (
                    f"\n\n✅ <b>КОД УЖЕ КУПЛЕН — повторно НЕ покупать!</b>\n"
                    f"Упала только доставка. Перешли клиенту:\n<code>{_pj}</code>"
                )
            except Exception:
                _pins_note = "\n\n✅ Код уже куплен — проверь pins_json в заказе, повторно НЕ покупай."
        await bot.send_message(
            ADMIN_ID,
            f"🚨 <b>NSGifts ОШИБКА выдачи</b>\n\n"
            f"👤 {await _who_user(user_id)}\n"
            f"📦 {service_name}  (service_id={service_id})\n"
            f"💵 {price_rub} ₽\n"
            f"🆔 FK: <code>{fk_order_id}</code>\n\n"
            f"❌ Ошибка: <code>{str(e)[:300]}</code>"
            + (_pins_note if _has_pins else
               "\n\nАктивируй вручную через кабинет wholesale.ns.gifts"),
            parse_mode="HTML"
        )
        await log_event(user_id, "nsgifts_failed",
                        f"fk={fk_order_id} error={str(e)[:300]}")


# ──────────────────────────────────────────────────────────────────────────────
#  Фоновый цикл: алерт на низкий баланс NS Gifts
# ──────────────────────────────────────────────────────────────────────────────


# ══════════════════════════════════════════════════════════
#  PERPLEXITY — авто-активация (копия Claude, идентификатор = Perplexity User ID)
# ══════════════════════════════════════════════════════════

async def _send_perplexity_webapp_to_user(
    user_id: int, code: str, order_id: str,
    plan: str, plan_name: str, delayed_note: str = ""
) -> bool:
    """Сохраняет pending и отправляет клиенту кнопку WebApp."""
    import urllib.parse as _up
    from aiogram.types import WebAppInfo as _WAI

    from config import webapp_url as _wa_url
    webapp_url = _wa_url("/webapp/perplexity", plan=plan_name, code=code)
    try:
        await save_perplexity_pending_activation(user_id, code, order_id, plan, plan_name)
        import datetime as _dt_cl
        _oref_px = await _order_ref_line(order_id)
        _base_cl = (
            f"🎉 <b>Оплата прошла!</b>\n\n"
            f"📦 <b>Perplexity {plan_name}</b>\n"
            f"{_oref_px}\n\n"
            f"Осталось активировать подписку — нажми кнопку ниже, "
            f"введи Perplexity User ID (perplexity.ai/api/auth/session), и подписка "
            f"активируется автоматически за 1–2 минуты 👇\n\n"
            f"🎟 Код активации: <code>{code}</code>"
            f"{delayed_note}"
        )
        _kb_cl_active = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="⚡ Активировать Perplexity", style="success", web_app=_WAI(url=webapp_url))],
            [InlineKeyboardButton(text="❓ Нужна помощь", style="primary", callback_data="perplexity_need_help")],
        ])
        _kb_cl_expired = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="❓ Нужна помощь", style="primary", callback_data="perplexity_need_help")],
        ])
        _dl_cl = _dt_cl.datetime.now(_BOT_TZ) + _dt_cl.timedelta(minutes=ACTIVATION_WINDOW_MIN)
        _exp_cl = (
            f"⏰ <b>Время самостоятельной активации истекло</b>\n\n"
            f"📦 <b>Perplexity {plan_name}</b> — оплата сохранена.\n"
            f"{_oref_px}\n"
            f"Напиши Александру — активирую вручную 🙌"
        )
        _m_act_cl = await bot.send_message(
            user_id, _base_cl + _activation_timer_line(_dl_cl),
            parse_mode="HTML", reply_markup=_kb_cl_active)
        _perplexity_act_msg[user_id] = _m_act_cl.message_id
        asyncio.create_task(_activation_timer_job(
            user_id, _m_act_cl.message_id, _base_cl, _kb_cl_active,
            _dl_cl, _exp_cl, _kb_cl_expired, _perplexity_act_msg))
        try:
            await bot.send_message(
                user_id,
                "📋 <b>Инструкция по активации Perplexity</b>\n\n"
                "1️⃣ Зайди на <b>perplexity.ai</b> и авторизуйся (в Chrome или Safari).\n"
                "2️⃣ Открой страницу сессии:\n"
                "<code>perplexity.ai/api/auth/session</code>\n"
                "3️⃣ Скопируй значение поля «id» (UUID).\n"
                "4️⃣ Вернись в мини-приложение (кнопка «Активировать Perplexity»), "
                "вставь User ID — подписка активируется автоматически за 1–2 минуты.\n\n"
                f"🎟 Код активации: <code>{code}</code>\n"
                "⚠️ Убедись, что вошёл именно в нужный аккаунт Perplexity.",
                parse_mode="HTML")
        except Exception:
            pass
        await log_event(user_id, "perplexity_webapp_sent",
                        f"code={code} plan={plan_name} order={order_id}")
        return True
    except Exception as _e:
        logging.error(f"_send_perplexity_webapp_to_user uid={user_id}: {_e}")
        return False


# ─── Фоновый polling job ──────────────────────────────────────────────────────


async def _perplexity_test_activation_job(fake_bpa: int, user_id: int, plan_name: str):
    """Симулирует успешную активацию для тестового кода TEST-."""
    await asyncio.sleep(4)  # имитируем задержку как в реальном сценарии
    _perplexity_job_results[fake_bpa] = {"status": "done", "success": True}
    try:
        await bot.send_message(
            ADMIN_ID,
            f"🧪 <b>Perplexity тест завершён</b>\n"
            f"👤 {await _who_user(user_id)}  📦 {plan_name}\n"
            f"Это фейковая активация — реальный код не потрачен.",
            parse_mode="HTML"
        )
    except Exception:
        pass


async def _perplexity_activation_polling_job(
    bpa_order_id: int, code: str, user_id: int,
    order_id: str, plan_name: str, org_id: str
):
    """
    Опрашивает bypriceactivate.pro каждые 5 сек.
    При done — помечает код, уведомляет тебя и клиента.
    При failed — возвращает код, пишет обоим.
    """
    _perplexity_job_results[bpa_order_id] = {"status": "queued"}
    _replaced_code = None  # авто-замена кода отключена; ветка elif оставлена мёртвой
    logging.info(f"Perplexity polling bpa={bpa_order_id} user={user_id} code={code}")

    for attempt in range(120):          # макс 10 минут (120 × 5 сек)
        await asyncio.sleep(5)
        try:
            async with aiohttp.ClientSession(
                timeout=aiohttp.ClientTimeout(total=15)
            ) as _s:
                async with _s.get(
                    f"https://bypriceactivate.pro/api/activate/{bpa_order_id}"
                ) as _r:
                    if _r.status != 200:
                        continue
                    _d = await _r.json()

            status = _d.get("status")
            _perplexity_job_results[bpa_order_id] = {"status": status}

            # ── Успех ──────────────────────────────────────────
            if status == "done":
                await mark_perplexity_code_used(code, user_id, order_id, org_id)
                await delete_perplexity_pending_activation(user_id, order_id)
                _perplexity_job_results[bpa_order_id] = {"status": "done", "success": True}

                import datetime as _dt2
                _ts = _dt2.datetime.now(_BOT_TZ).strftime("%d.%m.%Y %H:%M")
                try:
                    _pool2 = await get_pool()
                    async with _pool2.acquire() as _c2:
                        _ur = await _c2.fetchrow(
                            "SELECT username, full_name FROM users WHERE user_id=$1",
                            user_id
                        )
                    _un = (_ur["username"] if _ur else "") or ""
                    _fn = (_ur["full_name"] if _ur else "") or ""
                except Exception:
                    _un = _fn = ""
                _tg = (f"@{_un}" if _un else tg_name(_fn)) or f"id{user_id}"

                # Заменяем сообщение клиента на поздравление, убираем «Нужна помощь»
                import datetime as _dt_end_cl
                _end_cl = (_dt_end_cl.datetime.now(_BOT_TZ) + _dt_end_cl.timedelta(days=_subscription_days(plan_name))).strftime("%d.%m.%Y")
                _prof_kw_cl = ({"icon_custom_emoji_id": UI_EMOJI_IDS["menu_profile"]}
                               if UI_EMOJI_IDS.get("menu_profile") else {})
                _oref_px2 = await _order_ref_line(order_id)
                _congrats_cl = (
                    "🎉 <b>Подписка Perplexity активирована!</b>\n\n"
                    f"📦 Тариф: <b>{plan_name}</b>\n"
                    f"🏢 Perplexity User ID: <code>{org_id}</code>\n"
                    f"🔑 Ключ: <code>{code}</code>\n"
                    f"{_oref_px2}\n"
                    f"📅 Действует до: <b>{_end_cl}</b>\n\n"
                    "Подписка появится в Perplexity в течение 5–10 минут. Спасибо за покупку! 🙌"
                )
                _kb_cl = InlineKeyboardMarkup(inline_keyboard=[
                    [InlineKeyboardButton(text="Открыть Perplexity ↗", url="https://perplexity.ai")],
                    [InlineKeyboardButton(text="Мой профиль", callback_data="menu_profile", **_prof_kw_cl)],
                    [_eib("Главное меню", "back_main")],
                ])
                _mid_cl = _perplexity_act_msg.pop(user_id, None)
                _edited_cl = False
                if _mid_cl:
                    try:
                        await bot.edit_message_text(_congrats_cl, chat_id=user_id, message_id=_mid_cl,
                                                    parse_mode="HTML", reply_markup=_kb_cl)
                        _edited_cl = True
                    except Exception as _ee_cl:
                        logging.warning(f"edit perplexity activation msg failed: {_ee_cl}")
                if not _edited_cl:
                    try:
                        await bot.send_message(user_id, _congrats_cl, parse_mode="HTML", reply_markup=_kb_cl)
                    except Exception:
                        pass

                try:
                    _caption_ok = (
                        f"✅ <b>Perplexity авто-активация OK</b>\n\n"
                        f"👤 <b>{_tg}</b>  (<code>{user_id}</code>)\n"
                        f"🔑 Код: <code>{code}</code>\n"
                        f"📦 Тариф: <b>{plan_name}</b>\n"
                        f"🆔 Org ID: <code>{org_id}</code>\n"
                        f"🔢 BPA: <code>{bpa_order_id}</code>\n"
                        f"⏱ {_ts}"
                    )
                    try:
                        _ord_ok = await fk_get_order(order_id)
                        _amid_ok = (_ord_ok or {}).get("admin_msg_id")
                    except Exception:
                        _amid_ok = None
                    if _amid_ok:
                        try:
                            await bot.edit_message_text(_caption_ok, chat_id=ADMIN_ID, message_id=_amid_ok, parse_mode="HTML")
                        except Exception:
                            await bot.send_message(ADMIN_ID, _caption_ok, parse_mode="HTML")
                    else:
                        await bot.send_message(ADMIN_ID, _caption_ok, parse_mode="HTML")
                except Exception:
                    pass
                _fail_clear("perplexity", user_id)
                await log_event(user_id, "perplexity_activation_ok",
                                f"code={code} bpa={bpa_order_id} plan={plan_name}")
                return

            # ── Ошибка ─────────────────────────────────────────
            elif status == "failed":
                _err = _d.get("error") or "Ошибка активации"
                _perplexity_job_results[bpa_order_id] = {
                    "status": "done", "success": False, "error": _err
                }
                # Сбрасываем bpa_order_id в pending, чтобы «Попробовать снова» создал НОВЫЙ BPA-заказ
                try:
                    _pool_rb = await get_pool()
                    async with _pool_rb.acquire() as _c_rb:
                        await _c_rb.execute(
                            "UPDATE perplexity_pending_activations SET bpa_order_id=NULL WHERE user_id=$1", user_id)
                except Exception:
                    pass
                _is_stock = ("out of stock" in _err.lower() or "out-of-stock" in _err.lower())
                if _is_stock:
                    # провайдер временно без стока — код клиента ОСТАЁТСЯ валидным.
                    # НЕ возвращаем в пул и НЕ удаляем pending: клиент сам повторит, когда пополнят.
                    _fail_note = "Временно нет мест у провайдера — код сохранён за клиентом, можно повторить."
                else:
                    # Сбой обычно временный (провайдер: payment/timeout). Код НЕ сжигаем и НЕ ротируем —
                    # оставляем закреплённым за клиентом: можно повторить тем же кодом или активировать вручную.
                    _fail_note = "Код сохранён — повтори тем же кодом позже или активируй вручную."

                # ── алерт админу (не чаще 1 раза в 15 мин на клиента) ──
                if _fail_should_alert("perplexity", user_id):
                    try:
                        _caption_fail = (
                            f"❌ <b>Perplexity FAILED</b>\n"
                            f"👤 {await _who_user(user_id)}  📦 {plan_name}\n"
                            f"🔑 <code>{code}</code>  🔢 BPA: <code>{bpa_order_id}</code>\n"
                            f"❌ {_err[:300]}"
                            + f"\n♻️ {_fail_note}"
                        )
                        _ss_fail = await _take_claude_bpa_screenshot(bpa_order_id)
                        if _ss_fail:
                            await bot.send_photo(
                                ADMIN_ID,
                                BufferedInputFile(_ss_fail, "perplexity_fail.png"),
                                caption=_caption_fail, parse_mode="HTML"
                            )
                        else:
                            await bot.send_message(ADMIN_ID, _caption_fail, parse_mode="HTML")
                    except Exception:
                        pass

                # ── сообщение клиенту ──
                try:
                    if _is_stock:
                        await bot.send_message(
                            user_id,
                            "⏳ <b>Временно нет мест у провайдера</b>\n\n"
                            "Твой код сохранён и остаётся действительным. Провайдер пополняет запас — "
                            "попробуй активировать снова через 5–10 минут 👇",
                            parse_mode="HTML",
                            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                                [InlineKeyboardButton(
                                    text="🔁 Попробовать снова",
                                    callback_data="perplexity_reopen_webapp"
                                )],
                                [InlineKeyboardButton(
                                    text="❓ Нужна помощь", style="primary",
                                    callback_data="perplexity_need_help"
                                )],
                            ])
                        )
                    elif _replaced_code:
                        await bot.send_message(
                            user_id,
                            "😔 <b>Первый код не сработал</b>\n\n"
                            "Мы автоматически выдали новый код. "
                            "Нажми «🔁 Попробовать снова» — активируем заново 👇",
                            parse_mode="HTML",
                            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                                [InlineKeyboardButton(
                                    text="🔁 Попробовать снова",
                                    callback_data="perplexity_reopen_webapp"
                                )],
                                [InlineKeyboardButton(
                                    text="❓ Нужна помощь", style="primary",
                                    callback_data="perplexity_need_help"
                                )],
                            ])
                        )
                    else:
                        await bot.send_message(
                            user_id,
                            f"😔 <b>Активация Perplexity не прошла</b>\n\n"
                            f"{_err[:300]}\n\n"
                            f"Напиши Александру — активирую вручную за 15–30 мин!",
                            parse_mode="HTML",
                            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                                [InlineKeyboardButton(
                                    text="✅ Активировали тариф вручную",
                                    callback_data="perplexity_manual_activated"
                                )],
                                [InlineKeyboardButton(
                                    text="❓ Нужна помощь", style="primary",
                                    callback_data="perplexity_need_help"
                                )],
                            ])
                        )
                except Exception:
                    pass
                await log_event(user_id, "perplexity_activation_fail",
                                f"code={code} bpa={bpa_order_id} replaced={_replaced_code or '-'} err={_err[:120]}")
                return

        except Exception as _e:
            logging.error(f"Perplexity poll #{attempt} bpa={bpa_order_id}: {_e}")

    # ── Таймаут ────────────────────────────────────────────────
    # Код и pending НЕ трогаем — чтобы клиент мог нажать «активировали вручную»,
    # а Александр активировал тем же кодом. Освободится сам через ~2ч (cleanup-loop).
    _perplexity_job_results[bpa_order_id] = {
        "status": "done", "success": False,
        "error": "Активация затянулась. Напиши Александру — он поможет!"
    }
    try:
        await bot.send_message(
            user_id,
            f"⏰ <b>Активация Perplexity затянулась</b>\n\n"
            f"Мы не получили подтверждение от сервиса активации.\n"
            f"Напиши Александру — разберёмся и активируем вручную!",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(
                    text="✅ Активировали тариф вручную",
                    callback_data="perplexity_manual_activated"
                )],
                [InlineKeyboardButton(
                    text="❓ Нужна помощь", style="primary",
                    callback_data="perplexity_need_help"
                )],
            ])
        )
    except Exception:
        pass
    try:
        await bot.send_message(
            ADMIN_ID,
            f"⏰ <b>Perplexity TIMEOUT</b>\n"
            f"👤 {await _who_user(user_id)}  🔢 BPA: <code>{bpa_order_id}</code>\n"
            f"🔑 Код: <code>{code}</code>\n"
            f"10 минут — проверь вручную на bypriceactivate.pro\n"
            f"Код зарезервирован за клиентом — активируй вручную им же.",
            parse_mode="HTML"
        )
    except Exception:
        pass


# ─── Веб-хэндлеры ────────────────────────────────────────────────────────────


async def webapp_perplexity_handler(request: web.Request) -> web.Response:
    """GET /webapp/perplexity — отдаёт perplexity_webapp.html"""
    try:
        with open(_PERPLEXITY_WEBAPP_HTML_PATH, "r", encoding="utf-8") as _f:
            _html = _f.read()
        _html = await _apply_act_media(_html, "perplexity")
        return web.Response(text=_html, content_type="text/html", charset="utf-8",
                            headers=_NO_CACHE_HEADERS)
    except FileNotFoundError:
        return web.Response(text="Perplexity Mini App not found", status=404)


async def _perplexity_notify_success(code, user_id, order_id, plan_name, org_id):
    """Уведомления после УСПЕШНОЙ синхронной активации Perplexity (клиент + админ)."""
    import datetime as _dt2
    _ts = _dt2.datetime.now(_BOT_TZ).strftime("%d.%m.%Y %H:%M")
    try:
        _pool2 = await get_pool()
        async with _pool2.acquire() as _c2:
            _ur = await _c2.fetchrow("SELECT username, full_name FROM users WHERE user_id=$1", user_id)
        _un = (_ur["username"] if _ur else "") or ""
        _fn = (_ur["full_name"] if _ur else "") or ""
    except Exception:
        _un = _fn = ""
    _tg = (f"@{_un}" if _un else tg_name(_fn)) or f"id{user_id}"
    _end_cl = (_dt2.datetime.now(_BOT_TZ) + _dt2.timedelta(days=_subscription_days(plan_name))).strftime("%d.%m.%Y")
    _oref_px2 = await _order_ref_line(order_id)
    # Единый вид успеха + приглашение в канал. 06.10.2026
    _mid_cl = _perplexity_act_msg.pop(user_id, None)
    await client_success_deliver(
        user_id,
        client_success_text("perplexity", plan_name, account_label="🆔 Аккаунт Perplexity",
                            account=org_id or "", end=client_end_date(plan_name),
                            order_line=_oref_px2),
        client_success_kb("perplexity"), edit_mid=_mid_cl)
    try:
        _caption_ok = (
            f"✅ <b>Perplexity авто-активация OK</b>\n\n"
            f"👤 <b>{_tg}</b>  (<code>{user_id}</code>)\n"
            f"🔑 Код: <code>{code}</code>\n"
            f"📦 Тариф: <b>{plan_name}</b>\n"
            f"🆔 User ID: <code>{org_id}</code>\n"
            f"⏱ {_ts}"
        )
        try:
            _ord_ok = await fk_get_order(order_id)
            _amid_ok = (_ord_ok or {}).get("admin_msg_id")
        except Exception:
            _amid_ok = None
        if _amid_ok:
            try:
                await bot.edit_message_text(_caption_ok, chat_id=ADMIN_ID, message_id=_amid_ok, parse_mode="HTML")
            except Exception:
                await bot.send_message(ADMIN_ID, _caption_ok, parse_mode="HTML")
        else:
            await bot.send_message(ADMIN_ID, _caption_ok, parse_mode="HTML")
    except Exception:
        pass


# ─── Perplexity: защита от повторной отправки кода поставщику ─────────────
# Отметка org_id в строке ожидания ставится ДО отправки кода и снимается
# только когда поставщик ЯВНО сказал «кода не касался». Но ставилась она
# безусловно — и двойной тап, и повтор после таймаута отправляли код
# поставщику снова. Теперь отметка атомарная: выигрывает только первый
# запрос, а при неясном исходе решает Александр. 06.10.2026.
_px_inflight: dict = {}       # user_id → время отправки (запрос ещё идёт)


async def _px_ask_admin_unclear(user_id: int, code: str, order_id: str,
                                org_id: str, why: str) -> None:
    """Сообщение Александру: исход неясен, код помечен, решать ему."""
    try:
        if await activation_cooldown(f"pxunclear:{user_id}", seconds=1800):
            return
    except Exception as _e_pc:
        logging.warning(f"pxunclear cooldown {user_id}: {_e_pc}")
    try:
        await bot.send_message(
            ADMIN_ID,
            f"⚠️ <b>Perplexity — исход активации неясен</b>\n\n"
            f"👤 Клиент: {await _who_user(user_id)}\n"
            f"🔑 Код: <code>{code}</code>\n"
            f"🆔 Аккаунт Perplexity: <code>{org_id or '—'}</code>\n"
            + (f"🧾 Order: <code>{order_id}</code>\n" if order_id else "")
            + f"{await _fk_num_line(order_id) if order_id else ''}"
            + f"\n{why}\n\n"
            f"Код ушёл поставщику, а ответа «успех» или «отказ» нет — он мог "
            f"быть потрачен. Повторно код бот НЕ отправит.\n\n"
            f"Проверь у поставщика. Если код цел — разреши клиенту повторить:",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
                InlineKeyboardButton(text="🔄 Код цел — разрешить повтор",
                                     callback_data=f"pxallow:{int(user_id)}")]]))
    except Exception as _e_pa:
        logging.error(f"pxunclear notify {user_id}: {_e_pa}")


@dp.callback_query(F.data.startswith("pxallow:"))
async def px_allow_ask(cb: CallbackQuery):
    """Первый шаг: точно разрешить повтор? Повтор отправит код поставщику снова."""
    if cb.from_user.id != ADMIN_ID:
        await cb.answer("❌", show_alert=True); return
    _uid = cb.data.split(":", 1)[1]
    await cb.message.answer(
        "🔄 <b>Разрешить клиенту повторить активацию Perplexity?</b>\n\n"
        f"👤 {await _who_user(int(_uid))}\n\n"
        "Повтор отправит ТОТ ЖЕ код поставщику ещё раз. Делай это, только если "
        "проверил у поставщика, что код не потрачен.",
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="✅ Да, код цел — разрешить",
                                  callback_data=f"pxallow2:{_uid}")],
            [InlineKeyboardButton(text="↩️ Отмена", callback_data="noop")]]))
    await cb.answer()


@dp.callback_query(F.data.startswith("pxallow2:"))
async def px_allow_do(cb: CallbackQuery):
    if cb.from_user.id != ADMIN_ID:
        await cb.answer("❌", show_alert=True); return
    try:
        _uid = int(cb.data.split(":", 1)[1])
    except Exception:
        await cb.answer("Не разобрал клиента", show_alert=True); return
    _n = 0
    try:
        _p_al = await get_pool()
        async with _p_al.acquire() as _c_al:
            _r_al = await _c_al.execute(
                "UPDATE perplexity_pending_activations SET org_id='' WHERE user_id=$1", _uid)
        _n = int(str(_r_al).split()[-1]) if str(_r_al).split()[-1].isdigit() else 0
    except Exception as _e_al:
        logging.error(f"pxallow {_uid}: {_e_al}")
    _px_inflight.pop(_uid, None)
    if not _n:
        await cb.answer("Резерва клиента нет — разрешать нечего.", show_alert=True)
        return
    logging.warning(f"pxallow: Александр разрешил повтор Perplexity uid={_uid}")
    try:
        await bot.send_message(
            _uid,
            "✅ Можно повторить активацию Perplexity — открой мини-приложение "
            "кнопкой активации выше и нажми «Активировать» ещё раз.")
    except Exception:
        pass
    try:
        await cb.message.edit_text("✅ Повтор разрешён, клиенту написал.")
    except Exception:
        pass
    await cb.answer("Готово")


async def api_activate_perplexity_handler(request: web.Request) -> web.Response:
    """POST /api/activate-perplexity"""
    import json as _j, re as _re

    def _resp(data, status=200):
        return web.Response(
            text=_j.dumps(data, ensure_ascii=False),
            content_type="application/json", status=status
        )

    if not rt.perplexity_webapp_enabled:
        return _resp({"error": f"Временно недоступно. Напиши @{PERSONAL_USERNAME}"}, 503)

    try:
        body = await request.json()
    except Exception:
        return _resp({"error": "Неверный формат запроса"}, 400)

    org_id    = (body.get("org_id") or "").strip().lower()
    init_data = (body.get("init_data") or "").strip()
    _fb_code  = (body.get("code") or "").strip()

    user_id = _verify_tg_init_data(init_data)
    if not user_id and _fb_code:
        _fb = await get_perplexity_pending_activation_by_code(_fb_code)
        if _fb:
            user_id = _fb.get("user_id")
    if not user_id:
        try:
            await bot.send_message(
                ADMIN_ID,
                f"⚠️ <b>Mini-app: не прошла авторизация</b>\n"
                f"initData len=<b>{len(init_data)}</b> · "
                f"hash={'hash=' in init_data} · signature={'signature=' in init_data}",
                parse_mode="HTML")
        except Exception:
            pass
        return _resp({"error": "Ошибка авторизации. Перезапусти мини-приложение."}, 403)

    # Выдача уже оплаченного: режим техработ тут не применяем (деньги
    # получены), а вот заблокированному клиенту код не отдаём — и сразу
    # говорим об этом владельцу, чтобы отказ не остался незамеченным.
    _den, _den_msg = await _web_access_denied(user_id, check_maintenance=False)
    if _den:
        try:
            await bot.send_message(
                ADMIN_ID,
                f"\U0001f6ab <b>Заблокированный клиент пытался активировать Perplexity</b>\n"
                f"\U0001f464 {await _who_user(user_id)}",
                parse_mode="HTML")
        except Exception:
            pass
        return _resp({"error": _den_msg}, 403)

    if not _re.match(
        r'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$', org_id
    ):
        return _resp({"error": "Неверный формат Perplexity User ID. Должен быть UUID."})

    pending = await get_perplexity_pending_activation(user_id)
    if not pending:
        # Как у ChatGPT и Claude: Александру — кнопка повторной выдачи. 08.10.2026
        if await _notify_perplexity_pending_expired(user_id):
            return _resp({"error": (
                "Время на самостоятельную активацию истекло. Оплата сохранена — "
                "Александр уже получил уведомление и пришлёт новую кнопку активации "
                "в чат бота. Ничего делать не нужно.")})
        return _resp({"error": (
            "Активная активация не найдена. Если подписка уже активирована — всё в "
            f"порядке. Если нет — напиши @{PERSONAL_USERNAME}, поможет.")})

    code      = pending["code"]
    order_id  = pending["order_id"]
    plan_name = pending["plan_name"]

    # ТЕСТ: если код фейковый (TEST-) — симулируем успех без реального запроса
    if code.startswith("TEST-"):
        import random as _rand
        fake_bpa = _rand.randint(9000000, 9999999)
        _perplexity_job_results[fake_bpa] = {"status": "queued"}
        asyncio.create_task(_perplexity_test_activation_job(fake_bpa, user_id, plan_name))
        await delete_perplexity_pending_activation(user_id)
        logging.info(f"Perplexity TEST activation: fake_bpa={fake_bpa} user={user_id}")
        return _resp({"order_id": fake_bpa, "status": "queued"})

    # БАГ 3 FIX: если job уже запущен — не делаем новый POST, просто возвращаем существующий order_id
    existing_bpa = pending.get("bpa_order_id")
    if existing_bpa:
        _prev = _perplexity_job_results.get(existing_bpa)
        _prev_failed = bool(_prev and _prev.get("status") == "done" and _prev.get("success") is False)
        if not _prev_failed:
            # Polling job уже работает/завершился успехом — возвращаем тот же order_id
            logging.info(f"Perplexity reuse bpa={existing_bpa} user={user_id}")
            return _resp({"order_id": existing_bpa, "status": "queued"})
        logging.info(f"Perplexity prev bpa={existing_bpa} failed — делаем новый POST")

    # Guard: повторная активация Perplexity за 29 дней — предупреждаем, повторное
    # нажатие «Попробовать снова» активирует принудительно (на другой аккаунт).
    try:
        _pool_dbl = await get_pool()
        async with _pool_dbl.acquire() as _c_dbl:
            _recent = await _c_dbl.fetchrow(
                "SELECT code, plan, used_at FROM perplexity_codes"
                " WHERE used_by=$1 AND used_at > NOW() - INTERVAL '29 days'"
                " AND used_by IS NOT NULL ORDER BY used_at DESC LIMIT 1",
                user_id
            )
        if _recent:
            _us = _recent["used_at"].strftime("%d.%m.%Y %H:%M") if _recent["used_at"] else "-"
            _u = await get_user(user_id)
            if _u and _u.get("username"):
                _uname = "@" + _u["username"]
            elif _u and _u.get("full_name"):
                _uname = _u["full_name"].replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
            else:
                _uname = "без ника"
            if user_id not in _perplexity_double_warned:
                _perplexity_double_warned.add(user_id)
                logging.warning(f'Perplexity repeat activation: warned user={user_id} code={_recent["code"]}')
                try:
                    await bot.send_message(
                        ADMIN_ID,
                        "⚠️ <b>Повторная активация Perplexity</b> (клиент предупреждён)\n\n"
                        f"👤 {_uname} ({await _who_user(user_id)})\n"
                        f"🔑 Уже активирован: <code>{_recent['code']}</code>\n"
                        f"📦 Тариф: <b>{_recent['plan']}</b>\n"
                        f"⏱ Дата: <b>{_us}</b>\n\n"
                        "Если клиент нажмёт «Попробовать снова» — активирует на другой аккаунт.",
                        parse_mode="HTML"
                    )
                except Exception:
                    pass
                return _resp({"error": (
                    "⚠️ На твой аккаунт уже активирована подписка Perplexity.\n\n"
                    "Если оформляешь на ДРУГОЙ аккаунт (например, для друга) — "
                    "нажми «Попробовать снова», и активация пройдёт.\n\n"
                    "Если это случайно — напиши Александру."
                )})
            else:
                _perplexity_double_warned.discard(user_id)
                logging.info(f"Perplexity forced re-activation user={user_id}")
                try:
                    await bot.send_message(
                        ADMIN_ID,
                        "✅ <b>Повторная активация Perplexity — подтверждена</b>\n\n"
                        f"👤 {_uname} ({await _who_user(user_id)}) активирует ещё раз (другой аккаунт).",
                        parse_mode="HTML"
                    )
                except Exception:
                    pass
    except Exception as _dbl_e:
        logging.error(f"perplexity double-activation check: {_dbl_e}")

    async def _px_unmark():
        """Снять отметку начала активации.

        Зовём только там, где поставщик ЯВНО сказал, что кода не касался:
        неверный UUID клиента, нет стока, код у него не найден. Тогда резерв
        снова обычный, и по истечении окна код сам вернётся в пул, как было.
        Во всех неясных случаях (сеть, таймаут, 5xx, исключение) отметку
        ОСТАВЛЯЕМ: там поставщик мог код потратить, и решать должен Александр.
        """
        try:
            _p_un = await get_pool()
            async with _p_un.acquire() as _c_un:
                await _c_un.execute(
                    "UPDATE perplexity_pending_activations SET org_id='' WHERE user_id=$1",
                    user_id)
        except Exception as _e_un:
            logging.warning(f"perplexity unmark uid={user_id}: {_e_un}")

    # ОТМЕЧАЕМ НАЧАЛО АКТИВАЦИИ ДО запроса к поставщику.
    # Без этой отметки резерв Perplexity выглядел как «активацию даже не
    # пробовали»: org_id у него не заполнялся НИКОГДА, а bpa_order_id у
    # синхронного эндпоинта не бывает по определению. Поэтому фоновая чистка
    # удаляла такой резерв и возвращала код в пул — хотя поставщик мог его
    # уже потратить. Код уходил следующему клиенту пустым.
    # У Claude та же отметка стоит с самого начала, Perplexity под неё не
    # подвели. Повторный внешний аудит 29.09.2026, пункт №15.
    # Отметка ОБЯЗАТЕЛЬНА. Раньше её ошибка только писалась в лог, и запрос
    # к поставщику уходил всё равно — то есть код мог быть потрачен, а следа
    # об этом не оставалось, и фоновая чистка возвращала его в пул пустым.
    # Считаем и UPDATE 0 строк: резерв мог исчезнуть, пока клиент заполнял
    # форму. Повторный внешний аудит 30.09.2026, пункт №15.
    _px_marked = False
    try:
        _pool_px_mark = await get_pool()
        async with _pool_px_mark.acquire() as _c_px_mark:
            # ТОЛЬКО если отметки ещё нет. Раньше UPDATE был безусловным: двойной
            # тап и повтор после таймаута отправляли код поставщику второй раз.
            _r_px_mark = await _c_px_mark.execute(
                "UPDATE perplexity_pending_activations SET org_id=$1 "
                "WHERE user_id=$2 AND COALESCE(org_id,'')=''",
                org_id, user_id)
            _px_marked = str(_r_px_mark).split()[-1] != "0"
            _px_prev_org = ""
            if not _px_marked:
                _px_prev_org = (await _c_px_mark.fetchval(
                    "SELECT COALESCE(org_id,'') FROM perplexity_pending_activations "
                    "WHERE user_id=$1", user_id)) or ""
    except Exception as _e_px_mark:
        logging.error(f"perplexity: не отметил начало активации uid={user_id}: {_e_px_mark}")
        _px_prev_org = ""
    if not _px_marked and _px_prev_org:
        # Код уже отправлялся поставщику. Либо запрос идёт прямо сейчас (двойной
        # тап), либо прошлый закончился неясно. В обоих случаях второй раз НЕ шлём.
        import time as _t_pxi
        if _t_pxi.time() - _px_inflight.get(user_id, 0) < 75:
            logging.info(f"perplexity: запрос uid={user_id} уже идёт — второй не шлю")
            return _resp({"processing": True,
                          "error": "Активация уже выполняется — подожди минуту, "
                                   "результат придёт в чат."})
        logging.warning(f"perplexity: по коду {code} uid={user_id} исход прошлой "
                        f"попытки неясен — повторно код НЕ отправляю")
        await _px_ask_admin_unclear(
            user_id, code, order_id, _px_prev_org,
            "Клиент нажал «Активировать» снова, а прошлая отправка этого кода "
            "так и не получила ответа.")
        return _resp({"processing": True,
                      "error": "Активация обрабатывается. Александр проверяет её — "
                               "повторять ничего не нужно, сообщение придёт в чат."})
    if not _px_marked:
        # Код НЕ отправляем: непотраченный код дороже одной неудачной попытки.
        try:
            await bot.send_message(
                ADMIN_ID,
                f"🚨 <b>Perplexity: активация остановлена ДО отправки кода</b>\n\n"
                f"👤 {await _who_user(user_id)}\n"
                f"🆔 <code>{order_id}</code>\n\n"
                f"Не удалось отметить начало активации в базе (сбой БД либо "
                f"резерв уже исчез). Код поставщику НЕ отправлен и не "
                f"потрачен. Нужна ручная выдача.",
                parse_mode="HTML")
        except Exception:
            pass
        return _resp({"error": "Не получилось начать активацию. "
                               f"Напиши @{PERSONAL_USERNAME} — активирует вручную."})

    import time as _t_pxs
    _px_inflight[user_id] = _t_pxs.time()
    try:
        async with aiohttp.ClientSession(
            timeout=aiohttp.ClientTimeout(total=30)
        ) as _s:
            # Perplexity у bypriceactivate.pro — ОТДЕЛЬНЫЙ СИНХРОННЫЙ эндпоинт:
            # {code, user_id (UUID)} → сразу итог (без order_id/поллинга).
            async with _s.post(
                "https://bypriceactivate.pro/api/perplexity/activate",
                json={"code": code, "user_id": org_id},
                headers={"Content-Type": "application/json"},
            ) as _r:
                try:
                    _rd = await _r.json()
                except Exception:
                    _rd = {}

                if _r.status == 200 and _rd.get("ok"):
                    # Успех — оформляем сразу (синхронно)
                    _px_marked_used = False
                    try:
                        await mark_perplexity_code_used(code, user_id, order_id, org_id)
                        _px_marked_used = True
                    except Exception as _e_pxm:
                        logging.error(f"perplexity: НЕ отметил код {code} "
                                      f"использованным uid={user_id}: {_e_pxm}")
                    # Резерв сносим ТОЛЬКО если отметка прошла. Иначе код
                    # оставался is_used=TRUE с пустым used_by и без резерва —
                    # а фоновая чистка через полчаса считает такой код
                    # свободным и отдаёт ВТОРОМУ клиенту. Подписка по нему уже
                    # выдана: второй платит за мёртвый код.
                    # Широкий разбор 02.10.2026.
                    if _px_marked_used:
                        await delete_perplexity_pending_activation(user_id, order_id)
                    else:
                        try:
                            await bot.send_message(
                                ADMIN_ID,
                                f"🚨 <b>Perplexity: подписка выдана, но код не "
                                f"отмечен</b>\n\n"
                                f"👤 {await _who_user(user_id)}\n"
                                f"🔑 <code>{code}</code>\n"
                                f"🆔 <code>{order_id}</code>\n\n"
                                f"Поставщик активацию подтвердил, а записать это "
                                f"в базу не вышло (сбой БД). Резерв НЕ снимаю — "
                                f"иначе код ушёл бы второму клиенту пустым. "
                                f"Отметь выдачу вручную.",
                                parse_mode="HTML")
                        except Exception:
                            pass
                    _perplexity_double_warned.discard(user_id)
                    import random as _rnd_px
                    _ref = _rnd_px.randint(9000000, 9999999)
                    _perplexity_job_results[_ref] = {"status": "done", "success": True}
                    try:
                        await _perplexity_notify_success(code, user_id, order_id, plan_name, org_id)
                    except Exception as _ne:
                        logging.warning(f"perplexity notify success: {_ne}")
                    try:
                        _fail_clear("perplexity", user_id)
                    except Exception:
                        pass
                    await log_event(user_id, "perplexity_activation_ok", f"code={code} plan={plan_name}")
                    logging.info(f"Perplexity SYNC activation OK: user={user_id} code={code} tx={_rd.get('transaction_id')}")
                    return _resp({"order_id": _ref, "status": "queued"})

                elif _r.status == 409:
                    _detail = (_rd.get("detail") or "").lower()
                    if "fulfilled" in _detail or "already" in _detail or "уже" in _detail or "claimed" in _detail:
                        return _resp({"error": "Код уже активирован. Напиши Александру."})
                    if ("стоке" in _detail or "out of stock" in _detail or "нет свободных" in _detail
                            or "receipt" in _detail or "no stock" in _detail):
                        try:
                            await bot.send_message(
                                ADMIN_ID,
                                f"🚨 <b>Perplexity — нет стока!</b>\n"
                                f"👤 {await _who_user(user_id)} ({plan_name})\n"
                                f"Пополни receipt'ы Perplexity на bypriceactivate.pro",
                                parse_mode="HTML"
                            )
                        except Exception:
                            pass
                        await _px_unmark()   # стока нет — код не тронут
                        return _resp({"error": "Временно нет активаций. Александр активирует вручную."})
                    return _resp({"error": _rd.get("detail") or "Ошибка кода."})

                elif _r.status == 404:
                    await _px_unmark()   # поставщик такого кода не знает — не тратил
                    return _resp({"error": "Код не найден. Напиши Александру."})

                elif _r.status == 400:
                    # Запрос отвергнут на входе — до кода дело не дошло.
                    await _px_unmark()
                    _det4 = (_rd.get("detail") or "").lower()
                    if "user_id" in _det4 or "uuid" in _det4:
                        return _resp({"error": "Неверный Perplexity User ID — нужен UUID со страницы perplexity.ai/api/auth/session (поле id)."})
                    return _resp({"error": _rd.get("detail") or "Ошибка запроса."})

                else:
                    # 5xx и прочее: поставщик мог код принять. Отметка остаётся,
                    # повтор бот не допустит — значит и «попробуй ещё раз» писать
                    # нельзя. Решает Александр. 06.10.2026
                    logging.error(f"bypriceactivate.pro perplexity HTTP {_r.status}: {str(_rd)[:200]}")
                    _px_inflight.pop(user_id, None)
                    await _px_ask_admin_unclear(
                        user_id, code, order_id, org_id,
                        f"Поставщик ответил HTTP {_r.status}: "
                        f"{str(_rd.get('detail') or '')[:150] or 'без пояснения'}.")
                    return _resp({"processing": True,
                                  "error": "Активация обрабатывается. Александр проверяет её — "
                                           "повторять ничего не нужно, сообщение придёт в чат."})

    except aiohttp.ClientError as _e:
        # Обрыв сети или таймаут 30 с: код мог дойти до поставщика. Раньше
        # клиенту писали «попробуй ещё раз» — и повтор отправлял код снова.
        logging.error(f"Perplexity activate network: {_e}")
        _px_inflight.pop(user_id, None)
        await _px_ask_admin_unclear(
            user_id, code, order_id, org_id,
            f"Связь с поставщиком оборвалась или он не ответил за 30 секунд "
            f"({type(_e).__name__}).")
        return _resp({"processing": True,
                      "error": "Активация обрабатывается. Александр проверяет её — "
                               "повторять ничего не нужно, сообщение придёт в чат."})
    except Exception as _e:
        logging.error(f"Perplexity activate error: {_e}", exc_info=True)
        try:
            await bot.send_message(
                ADMIN_ID,
                f"⚠️ <b>Perplexity activate exception</b>\n"
                f"user=<code>{user_id}</code> code=<code>{code}</code>\n"
                f"{type(_e).__name__}: {str(_e)[:300]}",
                parse_mode="HTML")
        except Exception:
            pass
        _px_inflight.pop(user_id, None)
        return _resp({"processing": True,
                      "error": "Активация обрабатывается. Александр проверяет её — "
                               "повторять ничего не нужно, сообщение придёт в чат."})


async def api_activate_perplexity_status_handler(request: web.Request) -> web.Response:
    """GET /api/activate-perplexity-status/{order_id}"""
    import json as _j2
    try:
        bpa_order_id = int(request.match_info.get("order_id", ""))
    except ValueError:
        return web.Response(
            text=_j2.dumps({"status": "not_found"}),
            content_type="application/json", status=400
        )
    result = _perplexity_job_results.get(bpa_order_id)
    if result is None:
        return web.Response(
            text=_j2.dumps({"status": "not_found"}),
            content_type="application/json", status=404
        )
    return web.Response(
        text=_j2.dumps(result, ensure_ascii=False),
        content_type="application/json"
    )


