async def _is_manual_plan(shop_key, plan_idx, plan: dict = None) -> bool:
    """Выдавать этот заказ вручную?

    plan — тариф, НАЙДЕННЫЙ ПО ИМЕНИ из заказа. Раньше функция принимала
    только номер позиции в каталоге, и решение расходилось с товаром:
    тариф брали по имени, а «автомат или вручную» считали по номеру.
    Достаточно было удалить один тариф в админке — номера схлопывались, и
    дорогой Pro 20× мог уйти в автоматическую выдачу по коду от Plus.
    Повторный внешний аудит 29.09.2026, пункт №9.
    """
    _all = (SHOP_CATALOG.get(shop_key, {}) or {}).get("plans", []) or []
    # Настоящий номер тарифа в текущем каталоге — по имени. Переключатель
    # «Ручная выдача» в админке хранится по номеру, и без этого он
    # относился бы к соседнему тарифу.
    _idx = plan_idx
    if isinstance(plan, dict) and plan.get("name"):
        _nm_p = str(plan.get("name", "")).strip()
        for _i, _pp in enumerate(_all):
            if str(_pp.get("name", "")).strip() == _nm_p:
                _idx = _i
                break
    _p = plan if isinstance(plan, dict) and plan else (
        _all[_idx] if 0 <= _idx < len(_all) else {})
    # Тариф из заказа в каталоге не найден — сами не выдаём, решает Александр.
    if not _p:
        return True
    # 1) Явный переключатель «Ручная выдача» в админке
    try:
        if (await get_setting(f"manual:{shop_key}:{_idx}", "0") or "0") == "1":
            return True
    except Exception:
        pass
    # 1a) ChatGPT: автоматически активируются только тарифы из GPT_AUTO_PLANS
    #     (Plus и Go). Pro 5× / Pro 20× Александр активирует сам — правило зашито
    #     здесь, а не только переключателем в админке, чтобы забытый тумблер не
    #     привёл к резерву кода под тариф, который бот всё равно не активирует.
    try:
        if shop_key == "chatgpt":
            if plan_name_to_key(_p.get("name", "")) not in GPT_AUTO_PLANS:
                return True
    except Exception as _e_ap:
        logging.warning(f"_is_manual_plan auto-plans: {_e_ap}")
    # 2) Недельные тарифы всегда выдаём вручную (авто-активация — только для месячных).
    #    Коды в пуле — месячные; недельную подписку оформляет Александр сам.
    try:
        _nm = (_p.get("name", "") or "").lower()
        if "недел" in _nm or "week" in _nm:
            return True
    except Exception:
        pass
    return False


def _strip_tg_html(s: str) -> str:
    """Убирает HTML/премиум-эмодзи из строки для подстановки в ?text= (t.me).
    <tg-emoji ...>⚡</tg-emoji> → ⚡, прочие теги вырезаются. В ?text= HTML не рендерится."""
    import re as _re_st
    s = _re_st.sub(r"<tg-emoji[^>]*>(.*?)</tg-emoji>", r"\1", s or "")
    s = _re_st.sub(r"<[^>]+>", "", s)
    return _re_st.sub(r"\s{2,}", " ", s).strip()


async def _send_manual_order(user_id, shop_key, service_name, plan_name,
                             order_id, amount_rub, delayed_note=""):
    """Тариф с ручной выдачей: создаём заказ, уведомляем клиента и админа (с кнопками)."""
    try:
        try:
            _pool = await get_pool()
            async with _pool.acquire() as _c:
                _u = await _c.fetchrow("SELECT username FROM users WHERE user_id=$1", user_id)
            _uname = (_u["username"] if _u else "") or ""
        except Exception:
            _uname = ""
        await create_linkpay_order(user_id, _uname, order_id, shop_key,
                                   service_name, plan_name, amount_rub,
                                   kind="manual", status="awaiting_payment")
        # Номер платежа в FreeKassa — чтобы клиент и админ сверялись по ОДНОМУ номеру
        _fk_no_cl = ""
        _num_h = None
        try:
            _dbo_cl = await fk_get_order(order_id)
            _fk_no_cl = (_dbo_cl or {}).get("fk_intid") or ""
            _num_h = (_dbo_cl or {}).get("num")
        except Exception:
            pass
        _onum_h = f"#{_num_h}" if _num_h else (_fk_no_cl or order_id)
        _num_line = (f"\U0001f9fe Номер заказа: <code>{_onum_h}</code>\n\n"
                     if (_num_h or _fk_no_cl) else f"\U0001f194 Номер заказа: <code>{order_id}</code>\n\n")
        import urllib.parse as _uq_manual
        _msg_to_alex = _uq_manual.quote(
            f"Приветствую! Оплатил заказ {_onum_h}\nСервис: {_strip_tg_html(service_name)}\n"
            f"Номер заказа: {_fk_no_cl or order_id}")
        await bot.send_message(
            user_id,
            f"🎉 <b>Оплата прошла!</b>\n\n📦 <b>{service_name}</b>\n\n"
            f"{_num_line}"
            f"❗️ <b>Отправьте Александру чек об оплате и номер вашего заказа</b> 👇"
            f"{delayed_note}",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(text="✍️ Написать Александру",
                                      url=f"https://t.me/{PERSONAL_USERNAME}?text={_msg_to_alex}")],
            ]))
        # Сообщение админу формирует section 4 (единое изменяющееся сообщение заказа)
        await log_event(user_id, "manual_order", f"order={order_id} svc={shop_key}")
    except Exception as e:
        logging.error(f"_send_manual_order uid={user_id}: {e}")
